(function(g){g.__QURAN_DATA=g.__QURAN_DATA||{};g.__QURAN_DATA["tamil-040"]={"sura":40,"name_ar":"غافر","name_en":"Ghafir","verses":85,"source":"https://www.tamililquran.com/tafsiribnkathir.php","count":85,"missing":[],"data":{"1":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=40&ayah=3\" class=\"link\">40:3</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 40:3 ஐ பார்க்கவும்"},"2":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=40&ayah=3\" class=\"link\">40:3</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 40:3 ஐ பார்க்கவும்"},"3":{"html":"<strong>ஹா மீம் என்று தொடங்கும் சூராக்களின் சிறப்புகள்</strong><br />\r\n<br />\r\nஇப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்: \"ஒவ்வொரு பொருளுக்கும் ஒரு சாரம் உண்டு. குர்ஆனின் சாரம் 'ஹா மீம்' குடும்பமாகும் (அல்லது 'ஹா மீம்கள்' என்று கூறினார்கள்).\" மிஸ்அர் பின் கிதாம் அவர்கள், \"இவை 'மணப்பெண்கள்' என்று அழைக்கப்பட்டன\" என்று கூறினார்கள். இவை அனைத்தையும் இமாமும் பெரும் அறிஞருமான அபூ உபைத் அல்-காசிம் பின் ஸல்லாம் (ரஹ்) அவர்கள் தனது 'ஃபழாயில் அல்-குர்ஆன்' நூலில் பதிவு செய்துள்ளார்கள். ஹுமைத் பின் ஸன்ஜூயாஹ் அவர்கள் அறிவிக்கிறார்கள்: அப்துல்லாஹ் (இப்னு மஸ்ஊத்) (ரழி) அவர்கள் கூறினார்கள், \"குர்ஆனுக்கு உவமை, ஒரு மனிதன் தன் குடும்பம் தங்குவதற்கு ஓரிடத்தைத் தேடிப் புறப்படுவதைப் போன்றது. அவன் மழை பெய்ததற்கான தடயங்கள் உள்ள ஒரு இடத்திற்கு வருகிறான். அவன் அதை வியப்புடன் பார்த்துக் கொண்டு நடக்கும்போது, திடீரென்று அழகான தோட்டங்களைக் காண்கிறான். அப்போது அவன், 'மழையின் முதல் தடயங்களையே நான் பெரிதும் விரும்பினேன், ஆனால் இதுவோ அதைவிட மிகச் சிறந்தது' என்று கூறுகிறான். அவனிடம், 'அந்த முதல் இடம் குர்ஆனைப் போன்றது; இந்த அழகான தோட்டங்கள், குர்ஆனின் மற்ற பகுதிகளோடு ஒப்பிடும்போது 'ஹா மீம்' குடும்பத்தின் சிறப்பைப் போன்றது' என்று கூறப்பட்டது.\" இதனை அல்-பகவீ பதிவு செய்துள்ளார்கள். இப்னு மஸ்ஊத் (ரழி) அவர்கள் கூறினார்கள்: \"நான் 'ஹா மீம்' குடும்பத்தை அடையும்போது, ஒரு அழகான தோட்டத்தை அடைந்தது போல் உணர்கிறேன்; எனவே நான் அங்கேயே (அவற்றை ஓதி மகிழ்வதில்) அதிக நேரம் செலவிடுகிறேன்.\"<br />\r\n<br />\r\nஇமாம் அபூதாவூத் (ரஹ்) அவர்கள் அல்-முஹல்லப் பின் அபீ ஸுஃப்ரா (ரழி) அவர்கள் வாயிலாகப் பதிவு செய்துள்ளார்கள்: நபி (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِنْ</span> <span class=\"quran-arabic-font text-success\">بُيِّتُّمُ</span> <span class=\"quran-arabic-font text-success\">اللَّيْلَةَ</span> <span class=\"quran-arabic-font text-success\">فَقُولُوا</span>: <span class=\"quran-arabic-font text-success\">حم</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">يُنْصَرُون</span>»<br />\r\n<br />\r\n(இன்றிரவு நீங்கள் (எதிரிகளால்) தாக்கப்பட்டால், 'ஹா மீம், லா யுன்ஸரூன்' என்று கூறுங்கள்.)\" இதன் அறிவிப்பாளர் தொடர் ஸஹீஹ் (ஆதாரப்பூர்வமானது) ஆகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">بِسْمِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">الرَّحْمَـنِ</span> <span class=\"quran-arabic-font text-success\">الرَّحِيمِ</span><br />\r\n<br />\r\nஅளவற்ற அருளாளனும், நிகரற்ற அன்புடையோனுமாகிய அல்லாஹ்வின் பெயரால்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">حم</span> <span class=\"quran-arabic-font text-success\">تَنزِيلُ</span> <span class=\"quran-arabic-font text-success\">الْكِتَابِ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">الْعَزِيزِ</span> <span class=\"quran-arabic-font text-success\">الْعَلِيمِ</span><br />\r\n<br />\r\n(ஹா மீம்.) (இவ்வேதத்தின் வஹீ (இறைச்செய்தி), யாவரையும் மிகைத்தவனும், யாவற்றையும் அறிந்தவனுமாகிய அல்லாஹ்விடமிருந்து அருளப்பட்டது.) இதன் பொருள், இந்த வேதம் - குர்ஆன் - வல்லமையும் ஞானமும் மிக்க அல்லாஹ்விடமிருந்து வந்துள்ளது. அவனையாரும் வெல்ல முடியாது; அவனிடமிருந்து எதுவும் மறைந்துவிடாது, பல அடுக்குகளுக்குக் கீழே மறைந்திருக்கும் ஒரு சிறிய எறும்பு கூட அவனுக்குத் தெரியும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">غَافِرِ</span> <span class=\"quran-arabic-font text-success\">الذَّنبِ</span> <span class=\"quran-arabic-font text-success\">وَقَابِلِ</span> <span class=\"quran-arabic-font text-success\">التَّوْبِ</span><br />\r\n<br />\r\n(பாவத்தை மன்னிப்பவனும், தவ்பாவை (பாவமன்னிப்பை) ஏற்றுக்கொள்பவனும்,) அதாவது, அவன் கடந்த காலத்தில் செய்த பாவங்களை மன்னிக்கிறான்; மேலும் எதிர்காலத்தில் செய்யப்படக்கூடிய பாவங்களுக்கு, தவ்பா செய்து அவனிடம் சரணடைபவர்களின் மன்னிப்பை அவன் ஏற்றுக்கொள்கிறான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">شَدِيدِ</span> <span class=\"quran-arabic-font text-success\">الْعِقَابِ</span><br />\r\n<br />\r\n(தண்டனை வழங்குவதில் கடுமையானவன்,) அதாவது, வரம்பு மீறுவதில் பிடிவாதமாக இருந்து, இவ்வுலக வாழ்க்கையை விரும்பி, அல்லாஹ்வின் கட்டளைகளைப் புறக்கணித்துப் பாவம் செய்பவர்களுக்கு அவன் கடுமையானவன். இது பின்வரும் ஆயத்தைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">نَبِّىءْ</span> <span class=\"quran-arabic-font text-success\">عِبَادِى</span> <span class=\"quran-arabic-font text-success\">أَنِّى</span> <span class=\"quran-arabic-font text-success\">أَنَا</span> <span class=\"quran-arabic-font text-success\">الْغَفُورُ</span> <span class=\"quran-arabic-font text-success\">الرَّحِيمُ</span> - <span class=\"quran-arabic-font text-success\">وَأَنَّ</span> <span class=\"quran-arabic-font text-success\">عَذَابِى</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">ٱلْعَذَابُ</span> <span class=\"quran-arabic-font text-success\">ٱلْأَلِيمُ</span><br />\r\n<br />\r\n(என் அடியார்களுக்கு அறிவிப்பீராக: நிச்சயமாக நான் மிக்க மன்னிப்பவன், மிக்க கருணையாளன். மேலும், நிச்சயமாக எனது வேதனைதான் மிகத் துன்பகரமான வேதனையாகும்.) (<a href=\"qurandisp.php?sura=15&ayah=49\" class=\"link\">15:49</a>-50). மக்கள் நம்பிக்கையுடனும் அச்சமுடனும் இருக்க வேண்டும் என்பதற்காக, குர்ஆனில் இந்த இரு பண்புகளும் (கருணை மற்றும் தண்டனை) பெரும்பாலும் இணைத்தே குறிப்பிடப்படுகின்றன.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">ذِى</span> <span class=\"quran-arabic-font text-success\">الطَّوْلِ</span><br />\r\n<br />\r\n(பெருங்கொடையாளன்.) இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்: \"இதன் பொருள் அவன் தாராளமானவனும், தன்னிறைவு பெற்றவனும் (எவரிடத்தும் தேவையற்ற செல்வந்தனும்) ஆவான்.\" அதாவது அவன் தன் அடியார்களுக்கு மிகவும் தாராளமாக அருள்புரிகிறான்; அவர்கள் ஒருபோதும் முழுமையாக நன்றி செலுத்த முடியாத அளவு தொடர்ச்சியான அருட்கொடைகளை அவன் வழங்குகிறான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَإِن</span> <span class=\"quran-arabic-font text-success\">تَعُدُّواْ</span> <span class=\"quran-arabic-font text-success\">نِعْمَةَ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">تُحْصُوهَا</span><br />\r\n<br />\r\n(அல்லாஹ்வின் அருட்கொடைகளை நீங்கள் எண்ணிப்பார்த்தால், அவற்றை உங்களால் கணக்கிட முடியாது...) (<a href=\"qurandisp.php?sura=16&ayah=18\" class=\"link\">16:18</a>).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">إِلَـهَ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span><br />\r\n<br />\r\n(லா இலாஹ இல்லா ஹுவ) இதன் பொருள், அவனது பண்புகளில் அவனுக்கு நிகரானவர் எவருமில்லை; அவனைத் தவிர வேறு வணக்கத்திற்குரிய இறைவனோ இரட்சகனோ இல்லை.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِلَيْهِ</span> <span class=\"quran-arabic-font text-success\">الْمَصِيرُ</span><br />\r\n<br />\r\n(அவனிடமே இறுதித் திரும்புதல் உள்ளது.) அதாவது, அனைத்தும் அவனிடமே திரும்பிச் செல்லும்; அவன் ஒவ்வொருவருக்கும் அவரவர் செயல்களுக்கு ஏற்ப நற்கூலியோ அல்லது தண்டனையோ வழங்குவான்.<br />\r\n<br />","text":"ஹா மீம் என்று தொடங்கும் சூராக்களின் சிறப்புகள்\n\r\n\n\r\nஇப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்: \"ஒவ்வொரு பொருளுக்கும் ஒரு சாரம் உண்டு. குர்ஆனின் சாரம் 'ஹா மீம்' குடும்பமாகும் (அல்லது 'ஹா மீம்கள்' என்று கூறினார்கள்).\" மிஸ்அர் பின் கிதாம் அவர்கள், \"இவை 'மணப்பெண்கள்' என்று அழைக்கப்பட்டன\" என்று கூறினார்கள். இவை அனைத்தையும் இமாமும் பெரும் அறிஞருமான அபூ உபைத் அல்-காசிம் பின் ஸல்லாம் (ரஹ்) அவர்கள் தனது 'ஃபழாயில் அல்-குர்ஆன்' நூலில் பதிவு செய்துள்ளார்கள். ஹுமைத் பின் ஸன்ஜூயாஹ் அவர்கள் அறிவிக்கிறார்கள்: அப்துல்லாஹ் (இப்னு மஸ்ஊத்) (ரழி) அவர்கள் கூறினார்கள், \"குர்ஆனுக்கு உவமை, ஒரு மனிதன் தன் குடும்பம் தங்குவதற்கு ஓரிடத்தைத் தேடிப் புறப்படுவதைப் போன்றது. அவன் மழை பெய்ததற்கான தடயங்கள் உள்ள ஒரு இடத்திற்கு வருகிறான். அவன் அதை வியப்புடன் பார்த்துக் கொண்டு நடக்கும்போது, திடீரென்று அழகான தோட்டங்களைக் காண்கிறான். அப்போது அவன், 'மழையின் முதல் தடயங்களையே நான் பெரிதும் விரும்பினேன், ஆனால் இதுவோ அதைவிட மிகச் சிறந்தது' என்று கூறுகிறான். அவனிடம், 'அந்த முதல் இடம் குர்ஆனைப் போன்றது; இந்த அழகான தோட்டங்கள், குர்ஆனின் மற்ற பகுதிகளோடு ஒப்பிடும்போது 'ஹா மீம்' குடும்பத்தின் சிறப்பைப் போன்றது' என்று கூறப்பட்டது.\" இதனை அல்-பகவீ பதிவு செய்துள்ளார்கள். இப்னு மஸ்ஊத் (ரழி) அவர்கள் கூறினார்கள்: \"நான் 'ஹா மீம்' குடும்பத்தை அடையும்போது, ஒரு அழகான தோட்டத்தை அடைந்தது போல் உணர்கிறேன்; எனவே நான் அங்கேயே (அவற்றை ஓதி மகிழ்வதில்) அதிக நேரம் செலவிடுகிறேன்.\"\n\r\n\n\r\nஇமாம் அபூதாவூத் (ரஹ்) அவர்கள் அல்-முஹல்லப் பின் அபீ ஸுஃப்ரா (ரழி) அவர்கள் வாயிலாகப் பதிவு செய்துள்ளார்கள்: நபி (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«إِنْ بُيِّتُّمُ اللَّيْلَةَ فَقُولُوا: حم لَا يُنْصَرُون»\n\r\n\n\r\n(இன்றிரவு நீங்கள் (எதிரிகளால்) தாக்கப்பட்டால், 'ஹா மீம், லா யுன்ஸரூன்' என்று கூறுங்கள்.)\" இதன் அறிவிப்பாளர் தொடர் ஸஹீஹ் (ஆதாரப்பூர்வமானது) ஆகும்.\n\r\n\n\r\nبِسْمِ اللَّهِ الرَّحْمَـنِ الرَّحِيمِ\n\r\n\n\r\nஅளவற்ற அருளாளனும், நிகரற்ற அன்புடையோனுமாகிய அல்லாஹ்வின் பெயரால்.\n\r\n\n\r\nحم تَنزِيلُ الْكِتَابِ مِنَ اللَّهِ الْعَزِيزِ الْعَلِيمِ\n\r\n\n\r\n(ஹா மீம்.) (இவ்வேதத்தின் வஹீ (இறைச்செய்தி), யாவரையும் மிகைத்தவனும், யாவற்றையும் அறிந்தவனுமாகிய அல்லாஹ்விடமிருந்து அருளப்பட்டது.) இதன் பொருள், இந்த வேதம் - குர்ஆன் - வல்லமையும் ஞானமும் மிக்க அல்லாஹ்விடமிருந்து வந்துள்ளது. அவனையாரும் வெல்ல முடியாது; அவனிடமிருந்து எதுவும் மறைந்துவிடாது, பல அடுக்குகளுக்குக் கீழே மறைந்திருக்கும் ஒரு சிறிய எறும்பு கூட அவனுக்குத் தெரியும்.\n\r\n\n\r\nغَافِرِ الذَّنبِ وَقَابِلِ التَّوْبِ\n\r\n\n\r\n(பாவத்தை மன்னிப்பவனும், தவ்பாவை (பாவமன்னிப்பை) ஏற்றுக்கொள்பவனும்,) அதாவது, அவன் கடந்த காலத்தில் செய்த பாவங்களை மன்னிக்கிறான்; மேலும் எதிர்காலத்தில் செய்யப்படக்கூடிய பாவங்களுக்கு, தவ்பா செய்து அவனிடம் சரணடைபவர்களின் மன்னிப்பை அவன் ஏற்றுக்கொள்கிறான்.\n\r\n\n\r\nشَدِيدِ الْعِقَابِ\n\r\n\n\r\n(தண்டனை வழங்குவதில் கடுமையானவன்,) அதாவது, வரம்பு மீறுவதில் பிடிவாதமாக இருந்து, இவ்வுலக வாழ்க்கையை விரும்பி, அல்லாஹ்வின் கட்டளைகளைப் புறக்கணித்துப் பாவம் செய்பவர்களுக்கு அவன் கடுமையானவன். இது பின்வரும் ஆயத்தைப் போன்றது:\n\r\n\n\r\nنَبِّىءْ عِبَادِى أَنِّى أَنَا الْغَفُورُ الرَّحِيمُ - وَأَنَّ عَذَابِى هُوَ ٱلْعَذَابُ ٱلْأَلِيمُ\n\r\n\n\r\n(என் அடியார்களுக்கு அறிவிப்பீராக: நிச்சயமாக நான் மிக்க மன்னிப்பவன், மிக்க கருணையாளன். மேலும், நிச்சயமாக எனது வேதனைதான் மிகத் துன்பகரமான வேதனையாகும்.) (15:49-50). மக்கள் நம்பிக்கையுடனும் அச்சமுடனும் இருக்க வேண்டும் என்பதற்காக, குர்ஆனில் இந்த இரு பண்புகளும் (கருணை மற்றும் தண்டனை) பெரும்பாலும் இணைத்தே குறிப்பிடப்படுகின்றன.\n\r\n\n\r\nذِى الطَّوْلِ\n\r\n\n\r\n(பெருங்கொடையாளன்.) இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்: \"இதன் பொருள் அவன் தாராளமானவனும், தன்னிறைவு பெற்றவனும் (எவரிடத்தும் தேவையற்ற செல்வந்தனும்) ஆவான்.\" அதாவது அவன் தன் அடியார்களுக்கு மிகவும் தாராளமாக அருள்புரிகிறான்; அவர்கள் ஒருபோதும் முழுமையாக நன்றி செலுத்த முடியாத அளவு தொடர்ச்சியான அருட்கொடைகளை அவன் வழங்குகிறான்.\n\r\n\n\r\nوَإِن تَعُدُّواْ نِعْمَةَ اللَّهِ لاَ تُحْصُوهَا\n\r\n\n\r\n(அல்லாஹ்வின் அருட்கொடைகளை நீங்கள் எண்ணிப்பார்த்தால், அவற்றை உங்களால் கணக்கிட முடியாது...) (16:18).\n\r\n\n\r\nلاَ إِلَـهَ إِلاَّ هُوَ\n\r\n\n\r\n(லா இலாஹ இல்லா ஹுவ) இதன் பொருள், அவனது பண்புகளில் அவனுக்கு நிகரானவர் எவருமில்லை; அவனைத் தவிர வேறு வணக்கத்திற்குரிய இறைவனோ இரட்சகனோ இல்லை.\n\r\n\n\r\nإِلَيْهِ الْمَصِيرُ\n\r\n\n\r\n(அவனிடமே இறுதித் திரும்புதல் உள்ளது.) அதாவது, அனைத்தும் அவனிடமே திரும்பிச் செல்லும்; அவன் ஒவ்வொருவருக்கும் அவரவர் செயல்களுக்கு ஏற்ப நற்கூலியோ அல்லது தண்டனையோ வழங்குவான்."},"4":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=40&ayah=6\" class=\"link\">40:6</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 40:6 ஐ பார்க்கவும்"},"5":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=40&ayah=6\" class=\"link\">40:6</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 40:6 ஐ பார்க்கவும்"},"6":{"html":"<strong>நிராகரிப்பாளர்களின் பண்புகளில் ஒன்று அல்லாஹ்வின் ஆயத்துகள் குறித்து அவர்கள் தர்க்கம் செய்வதாகும் -- அதன் விளைவுகள்</strong><br />\r\nதெளிவான ஆதாரங்கள் வந்த பிறகும் அல்லாஹ்வின் அத்தாட்சிகளை எவரும் மறுப்பதோ அல்லது தர்க்கம் செய்வதோ இல்லை என்று அல்லாஹ் கூறுகிறான்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">يُجَادِلُ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">ءَايَـتِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">كَفَرُواْ</span><br />\r\n(நிராகரிப்பவர்களைத் தவிர), அதாவது அல்லாஹ்வின் அத்தாட்சிகளையும் அவனது ஆதாரங்களையும் சான்றுகளையும் மறுப்பவர்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَلاَ</span> <span class=\"quran-arabic-font text-success\">يَغْرُرْكَ</span> <span class=\"quran-arabic-font text-success\">تَقَلُّبُهُمْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْبِلاَدِ</span><br />\r\n(எனவே, பல்வேறு ஊர்களில் அவர்கள் (சுகமாக) நடமாடித் திரிவது உம்மை ஏமாற்றிவிட வேண்டாம்!) என்பது அவர்களின் செல்வத்தையும் ஆடம்பர வாழ்வையும் குறிக்கிறது. இது இந்த வசனத்தைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَغُرَّنَّكَ</span> <span class=\"quran-arabic-font text-success\">تَقَلُّبُ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">كَفَرُواْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْبِلَـدِ</span> - <span class=\"quran-arabic-font text-success\">مَتَـعٌ</span> <span class=\"quran-arabic-font text-success\">قَلِيلٌ</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">مَأْوَاهُمْ</span> <span class=\"quran-arabic-font text-success\">جَهَنَّمُ</span> <span class=\"quran-arabic-font text-success\">وَبِئْسَ</span> <span class=\"quran-arabic-font text-success\">الْمِهَادُ</span><br />\r\n(நகரங்களில் நிராகரிப்பவர்கள் (சுகமாக) நடமாடித் திரிவது உம்மை ஏமாற்றிவிட வேண்டாம். (இது) சொற்ப சுகமே; பின்னர் அவர்களின் தங்குமிடம் நரகமாகும்; தங்குமிடங்களில் அது மிகவும் கெட்டது.) (<a href=\"qurandisp.php?sura=3&ayah=196\" class=\"link\">3:196</a>-197)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">نُمَتِّعُهُمْ</span> <span class=\"quran-arabic-font text-success\">قَلِيلاً</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">نَضْطَرُّهُمْ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">عَذَابٍ</span> <span class=\"quran-arabic-font text-success\">غَلِيظٍ</span><br />\r\n(நாம் அவர்களைச் சிறிது காலம் சுகமனுபவிக்க விடுவோம்; பின்னர் அவர்களைக் கடுமையான வேதனைக்கு உள்ளாக்குவோம்.) (<a href=\"qurandisp.php?sura=31&ayah=24\" class=\"link\">31:24</a>). பிறகு அல்லாஹ் தனது தூதர் முஹம்மது (ஸல்) அவர்களை, அவருடைய மக்கள் அவரைப் பொய்யாக்கியதற்காகத் தேற்றுகிறான். அவருக்கு முன் வந்த நபிமார்களிடம் (அவர்கள் அனைவர் மீதும் அல்லாஹ்வின் சாந்தியும் அருளும் உண்டாவதாக) அவருக்கு ஒரு முன்மாதிரி இருக்கிறது என்று அவன் கூறுகிறான். ஏனெனில் முந்தைய சமுதாயங்களும் அவர்களைப் பொய்யாக்கின, எதிர்த்தன; அவர்களில் ஒரு சிலரே ஈமான் கொண்டார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">كَذَّبَتْ</span> <span class=\"quran-arabic-font text-success\">قَبْلَهُمْ</span> <span class=\"quran-arabic-font text-success\">قَوْمُ</span> <span class=\"quran-arabic-font text-success\">نُوحٍ</span><br />\r\n(இவர்களுக்கு முன்னரே நூஹுடைய சமுதாயத்தினர் (தங்கள் தூதரைப்) பொய்யாக்கினர்;) சிலை வழிபாட்டைக் கண்டிப்பதற்கும் அதைத் தடுப்பதற்கும் அல்லாஹ் அனுப்பிய முதல் தூதர் நூஹ் (அலை) அவர்கள் ஆவார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالْأَحْزَابُ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">بَعْدِهِمْ</span><br />\r\n(மேலும் அவர்களுக்குப் பின் வந்த இதர கூட்டத்தினரும்) என்பது ஒவ்வொரு சமுதாயத்திலிருந்தும் வந்தவர்களைக் குறிக்கிறது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَهَمَّتْ</span> <span class=\"quran-arabic-font text-success\">كُـلُّ</span> <span class=\"quran-arabic-font text-success\">أُمَّةٍ</span> <span class=\"quran-arabic-font text-success\">بِرَسُولِهِمْ</span> <span class=\"quran-arabic-font text-success\">لِيَأْخُذُوهُ</span><br />\r\n(மேலும் ஒவ்வொரு சமுதாயமும் தங்கள் தூதரைப் பிடிப்பதற்காகச் சதி செய்தது,) என்பது அவர்கள் அவரை எப்படியாவது கொலை செய்ய விரும்பினார்கள் என்பதைக் குறிக்கிறது. அவர்களில் சிலர் தங்கள் தூதரைக் கொலை செய்தும் இருக்கிறார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَجَادَلُوا</span> <span class=\"quran-arabic-font text-success\">بِالْبَـطِلِ</span> <span class=\"quran-arabic-font text-success\">لِيُدْحِضُواْ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">الْحَقَّ</span><br />\r\n(மேலும் சத்தியத்தை அழிப்பதற்காகப் பொய்யைக் கொண்டு தர்க்கம் செய்தார்கள்.) அதாவது மிகவும் தெளிவாக இருந்த சத்தியத்தை மறுப்பதற்காக அவர்கள் வீணான வாதங்களைக் கொண்டு வந்தார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَأَخَذْتُهُمْ</span><br />\r\n(ஆகவே, நான் அவர்களைப் பிடித்துக் கொண்டேன்) என்பது, \"அவர்கள் செய்த பாவங்களின் காரணமாக நான் அவர்களை அழித்தேன்\" என்று பொருள்படும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَكَيْفَ</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">عِقَابِ</span><br />\r\n(மேலும் எனது தண்டனை எவ்வாறு இருந்தது!) என்பது, \"எனது தண்டனையும் பழிவாங்கலும் எவ்வளவு கடுமையானதாகவும் வேதனையானதாகவும் இருந்தது என்பதைப் பற்றி நீங்கள் கேள்விப்பட்டிருக்கிறீர்களா?\" என்று பொருள்படும். கதாதா (ரஹ்) கூறினார்கள்: \"அல்லாஹ்வின் மீது சத்தியமாக, அது மிகக் கொடூரமானதாக இருந்தது.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَكَذَلِكَ</span> <span class=\"quran-arabic-font text-success\">حَقَّتْ</span> <span class=\"quran-arabic-font text-success\">كَلِمَتُ</span> <span class=\"quran-arabic-font text-success\">رَبِّكَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">كَفَرُواْ</span> <span class=\"quran-arabic-font text-success\">أَنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">أَصْحَـبُ</span> <span class=\"quran-arabic-font text-success\">النَّارِ</span><br />\r\n(இவ்வாறே, நிராகரிப்பாளர்கள் நரகவாசிகள் என்று உமது இறைவனின் வாக்கு அவர்கள் மீது உறுதியாகிவிட்டது.) இதன் பொருள், \"முந்தைய சமுதாயங்களில் நிராகரித்தவர்கள் மீது தண்டனை குறித்த வாக்கு எவ்வாறு உறுதியானதோ, அவ்வாறே உம்மைப் பொய்யாக்கி உமக்கு எதிராகச் செயல்படும் இந்த நிராகரிப்பாளர்கள் மீதும் அது உறுதியாகிவிட்டது முஹம்மது (ஸல்) அவர்களே! இவர்கள் உம்மையே நிராகரிக்கும்போது, வேறு எந்த நபியையும் நம்புவார்கள் என்பதற்கு எந்த உறுதியும் இல்லை என்பதால் இவர்களுக்கு எதிராக இது இன்னும் அதிகமாகப் பொருந்தும்.\" மேலும் அல்லாஹ்வே மிக அறிந்தவன்.<br />\r\n<br />\r\n<br />\r\n<br />","text":"நிராகரிப்பாளர்களின் பண்புகளில் ஒன்று அல்லாஹ்வின் ஆயத்துகள் குறித்து அவர்கள் தர்க்கம் செய்வதாகும் -- அதன் விளைவுகள்\n\r\nதெளிவான ஆதாரங்கள் வந்த பிறகும் அல்லாஹ்வின் அத்தாட்சிகளை எவரும் மறுப்பதோ அல்லது தர்க்கம் செய்வதோ இல்லை என்று அல்லாஹ் கூறுகிறான்,\n\r\n\n\r\nمَا يُجَادِلُ فِى ءَايَـتِ اللَّهِ إِلاَّ الَّذِينَ كَفَرُواْ\n\r\n(நிராகரிப்பவர்களைத் தவிர), அதாவது அல்லாஹ்வின் அத்தாட்சிகளையும் அவனது ஆதாரங்களையும் சான்றுகளையும் மறுப்பவர்கள்.\n\r\n\n\r\nفَلاَ يَغْرُرْكَ تَقَلُّبُهُمْ فِى الْبِلاَدِ\n\r\n(எனவே, பல்வேறு ஊர்களில் அவர்கள் (சுகமாக) நடமாடித் திரிவது உம்மை ஏமாற்றிவிட வேண்டாம்!) என்பது அவர்களின் செல்வத்தையும் ஆடம்பர வாழ்வையும் குறிக்கிறது. இது இந்த வசனத்தைப் போன்றது:\n\r\n\n\r\nلاَ يَغُرَّنَّكَ تَقَلُّبُ الَّذِينَ كَفَرُواْ فِى الْبِلَـدِ - مَتَـعٌ قَلِيلٌ ثُمَّ مَأْوَاهُمْ جَهَنَّمُ وَبِئْسَ الْمِهَادُ\n\r\n(நகரங்களில் நிராகரிப்பவர்கள் (சுகமாக) நடமாடித் திரிவது உம்மை ஏமாற்றிவிட வேண்டாம். (இது) சொற்ப சுகமே; பின்னர் அவர்களின் தங்குமிடம் நரகமாகும்; தங்குமிடங்களில் அது மிகவும் கெட்டது.) (3:196-197)\n\r\n\n\r\nنُمَتِّعُهُمْ قَلِيلاً ثُمَّ نَضْطَرُّهُمْ إِلَى عَذَابٍ غَلِيظٍ\n\r\n(நாம் அவர்களைச் சிறிது காலம் சுகமனுபவிக்க விடுவோம்; பின்னர் அவர்களைக் கடுமையான வேதனைக்கு உள்ளாக்குவோம்.) (31:24). பிறகு அல்லாஹ் தனது தூதர் முஹம்மது (ஸல்) அவர்களை, அவருடைய மக்கள் அவரைப் பொய்யாக்கியதற்காகத் தேற்றுகிறான். அவருக்கு முன் வந்த நபிமார்களிடம் (அவர்கள் அனைவர் மீதும் அல்லாஹ்வின் சாந்தியும் அருளும் உண்டாவதாக) அவருக்கு ஒரு முன்மாதிரி இருக்கிறது என்று அவன் கூறுகிறான். ஏனெனில் முந்தைய சமுதாயங்களும் அவர்களைப் பொய்யாக்கின, எதிர்த்தன; அவர்களில் ஒரு சிலரே ஈமான் கொண்டார்கள்.\n\r\n\n\r\nكَذَّبَتْ قَبْلَهُمْ قَوْمُ نُوحٍ\n\r\n(இவர்களுக்கு முன்னரே நூஹுடைய சமுதாயத்தினர் (தங்கள் தூதரைப்) பொய்யாக்கினர்;) சிலை வழிபாட்டைக் கண்டிப்பதற்கும் அதைத் தடுப்பதற்கும் அல்லாஹ் அனுப்பிய முதல் தூதர் நூஹ் (அலை) அவர்கள் ஆவார்கள்.\n\r\n\n\r\nوَالْأَحْزَابُ مِن بَعْدِهِمْ\n\r\n(மேலும் அவர்களுக்குப் பின் வந்த இதர கூட்டத்தினரும்) என்பது ஒவ்வொரு சமுதாயத்திலிருந்தும் வந்தவர்களைக் குறிக்கிறது.\n\r\n\n\r\nوَهَمَّتْ كُـلُّ أُمَّةٍ بِرَسُولِهِمْ لِيَأْخُذُوهُ\n\r\n(மேலும் ஒவ்வொரு சமுதாயமும் தங்கள் தூதரைப் பிடிப்பதற்காகச் சதி செய்தது,) என்பது அவர்கள் அவரை எப்படியாவது கொலை செய்ய விரும்பினார்கள் என்பதைக் குறிக்கிறது. அவர்களில் சிலர் தங்கள் தூதரைக் கொலை செய்தும் இருக்கிறார்கள்.\n\r\n\n\r\nوَجَادَلُوا بِالْبَـطِلِ لِيُدْحِضُواْ بِهِ الْحَقَّ\n\r\n(மேலும் சத்தியத்தை அழிப்பதற்காகப் பொய்யைக் கொண்டு தர்க்கம் செய்தார்கள்.) அதாவது மிகவும் தெளிவாக இருந்த சத்தியத்தை மறுப்பதற்காக அவர்கள் வீணான வாதங்களைக் கொண்டு வந்தார்கள்.\n\r\n\n\r\nفَأَخَذْتُهُمْ\n\r\n(ஆகவே, நான் அவர்களைப் பிடித்துக் கொண்டேன்) என்பது, \"அவர்கள் செய்த பாவங்களின் காரணமாக நான் அவர்களை அழித்தேன்\" என்று பொருள்படும்.\n\r\n\n\r\nفَكَيْفَ كَانَ عِقَابِ\n\r\n(மேலும் எனது தண்டனை எவ்வாறு இருந்தது!) என்பது, \"எனது தண்டனையும் பழிவாங்கலும் எவ்வளவு கடுமையானதாகவும் வேதனையானதாகவும் இருந்தது என்பதைப் பற்றி நீங்கள் கேள்விப்பட்டிருக்கிறீர்களா?\" என்று பொருள்படும். கதாதா (ரஹ்) கூறினார்கள்: \"அல்லாஹ்வின் மீது சத்தியமாக, அது மிகக் கொடூரமானதாக இருந்தது.\"\n\r\n\n\r\nوَكَذَلِكَ حَقَّتْ كَلِمَتُ رَبِّكَ عَلَى الَّذِينَ كَفَرُواْ أَنَّهُمْ أَصْحَـبُ النَّارِ\n\r\n(இவ்வாறே, நிராகரிப்பாளர்கள் நரகவாசிகள் என்று உமது இறைவனின் வாக்கு அவர்கள் மீது உறுதியாகிவிட்டது.) இதன் பொருள், \"முந்தைய சமுதாயங்களில் நிராகரித்தவர்கள் மீது தண்டனை குறித்த வாக்கு எவ்வாறு உறுதியானதோ, அவ்வாறே உம்மைப் பொய்யாக்கி உமக்கு எதிராகச் செயல்படும் இந்த நிராகரிப்பாளர்கள் மீதும் அது உறுதியாகிவிட்டது முஹம்மது (ஸல்) அவர்களே! இவர்கள் உம்மையே நிராகரிக்கும்போது, வேறு எந்த நபியையும் நம்புவார்கள் என்பதற்கு எந்த உறுதியும் இல்லை என்பதால் இவர்களுக்கு எதிராக இது இன்னும் அதிகமாகப் பொருந்தும்.\" மேலும் அல்லாஹ்வே மிக அறிந்தவன்."},"7":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=40&ayah=9\" class=\"link\">40:9</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 40:9 ஐ பார்க்கவும்"},"8":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=40&ayah=9\" class=\"link\">40:9</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 40:9 ஐ பார்க்கவும்"},"9":{"html":"<strong>அர்ஷைச் சுமப்பவர்கள் அல்லாஹ்வைப் புகழ்ந்து, விசுவாசிகளுக்காகப் பாவமன்னிப்புக் கோருதல்</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">يَحْمِلُونَ</span> <span class=\"quran-arabic-font text-success\">الْعَرْشَ</span> <span class=\"quran-arabic-font text-success\">وَمَنْ</span> <span class=\"quran-arabic-font text-success\">حَوْلَهُ</span> <span class=\"quran-arabic-font text-success\">يُسَبِّحُونَ</span> <span class=\"quran-arabic-font text-success\">بِحَمْدِ</span> <span class=\"quran-arabic-font text-success\">رَبِّهِمْ﴿</span><br />\r\n<br />\r\nதனக்கு மிக நெருக்கமான வானவர்களும், அர்ஷைச் சுமப்பவர்களும், அதைச் சுற்றியுள்ள வானவர்களும் - அனைவரும் தங்கள் இறைவனின் புகழைக் கூறி அவனைத் துதிக்கின்றனர் என்று அல்லாஹ் கூறுகிறான். அவர்கள், அல்லாஹ் குறைகளற்றவன் என்பதைக் குறிக்கும் 'தஸ்பீஹ்' (துதித்தல்) மற்றும் புகழுக்கான 'தஹ்மீத்' (புகழுரை) ஆகியவற்றை இணைத்துக் கூறுகின்றனர். <span class=\"quran-arabic-font text-success\">﴾وَيُؤْمِنُونَ</span> <span class=\"quran-arabic-font text-success\">بِهِ﴿</span><br />\r\n<br />\r\n(மேலும் அவனையே நம்பிக்கை கொள்கின்றனர்) என்பதன் பொருள், அவர்கள் பணிவுடன் அவனிடம் தங்களை ஒப்படைக்கிறார்கள் என்பதாகும். <span class=\"quran-arabic-font text-success\">﴾وَيَسْتَغْفِرُونَ</span> <span class=\"quran-arabic-font text-success\">لِلَّذِينَ</span> <span class=\"quran-arabic-font text-success\">ءَامَنُواْ﴿</span><br />\r\n<br />\r\n(மேலும் நம்பிக்கை கொண்டவர்களுக்காகப் பாவமன்னிப்புக் கோருகின்றனர்) இதன் பொருள், பூமியில் வசிக்கும் மக்களில் மறைவானவற்றை (ஈமான்) நம்பிக்கை கொண்டவர்களுக்காக அவர்கள் பிரார்த்திக்கின்றனர் என்பதாகும். தனக்கு நெருக்கமான வானவர்கள், இறைவிசுவாசிகள் இல்லாதபோது அவர்களுக்காகப் பிரார்த்தனை செய்ய வேண்டும் என்று அல்லாஹ் கட்டளையிட்டான். எனவே, ஒரு விசுவாசி தன் சகோதரனுக்காக அவர் இல்லாதபோது பிரார்த்திக்கும்போது, வானவர்கள் 'ஆமீன்' என்று கூறுவது அவர்களின் இயற்கையான பண்பாகும். ஸஹீஹ் முஸ்லிமில் இவ்வாறு கூறப்பட்டுள்ளது: <span class=\"quran-arabic-font text-success\">﴾</span>«<span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">دَعَا</span> <span class=\"quran-arabic-font text-success\">الْمُسْلِمُ</span> <span class=\"quran-arabic-font text-success\">لِأَخِيهِ</span> <span class=\"quran-arabic-font text-success\">بِظَهْرِ</span> <span class=\"quran-arabic-font text-success\">الْغَيْبِ</span> <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">الْمَلَكُ</span>: <span class=\"quran-arabic-font text-success\">آمِينَ</span> <span class=\"quran-arabic-font text-success\">وَلَكَ</span> <span class=\"quran-arabic-font text-success\">بِمِثْلِه</span>»<span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(ஒரு முஸ்லிம் தன் சகோதரனுக்காக அவர் இல்லாதபோது பிரார்த்தித்தால், அந்த வானவர், 'ஆமீன், உனக்கும் அதுபோன்றே கிடைக்கட்டும்' என்று கூறுகிறார்.)\" ஷஹ்ர் பின் ஹவ்ஷப் (ரஹ்) அவர்கள் கூறினார்கள்: \"அர்ஷைச் சுமப்பவர்கள் எட்டு பேர்; அவர்களில் நால்வர், 'யா அல்லாஹ், நீ தூய்மையானவன், உனக்கே எல்லாப் புகழும். உனது அறிவுக்குப் பிறகும் நீ காட்டும் சகிப்புத்தன்மைக்காக உனக்கே புகழ் அனைத்தும்' என்று கூறுகின்றனர். மற்ற நால்வர், 'யா அல்லாஹ், நீ தூய்மையானவன், உனக்கே எல்லாப் புகழும். உனது ஆற்றலுக்குப் பிறகும் நீ காட்டும் மன்னிப்புக்காக உனக்கே புகழ் அனைத்தும்' என்று கூறுகின்றனர். அவர்கள் நம்பிக்கை கொண்டவர்களுக்காகப் பாவமன்னிப்புக் கோரும்போது இவ்வாறு கூறுகின்றனர்: <span class=\"quran-arabic-font text-success\">﴾رَبَّنَا</span> <span class=\"quran-arabic-font text-success\">وَسِعْتَ</span> <span class=\"quran-arabic-font text-success\">كُلَّ</span> <span class=\"quran-arabic-font text-success\">شَىْءٍ</span> <span class=\"quran-arabic-font text-success\">رَّحْمَةً</span> <span class=\"quran-arabic-font text-success\">وَعِلْماً﴿</span><br />\r\n<br />\r\n(எங்கள் இறைவனே! நீ உனது அருளாலும் அறிவாலும் அனைத்துப் பொருட்களையும் சூழ்ந்துள்ளாய்.) இதன் பொருள், 'உனது அருள் அவர்களின் பாவங்களை விடவும் விரிவானது; உனது அறிவு அவர்களின் அனைத்துச் செயல்களையும், சொற்களையும், நடவடிக்கைகளையும் சூழ்ந்துள்ளது' என்பதாகும். <span class=\"quran-arabic-font text-success\">﴾فَاغْفِرْ</span> <span class=\"quran-arabic-font text-success\">لِلَّذِينَ</span> <span class=\"quran-arabic-font text-success\">تَابُواْ</span> <span class=\"quran-arabic-font text-success\">وَاتَّبَعُواْ</span> <span class=\"quran-arabic-font text-success\">سَبِيلَكَ﴿</span><br />\r\n<br />\r\n(ஆகவே, பாவமன்னிப்புக் கோரி உனது வழியைப் பின்பற்றியவர்களை மன்னிப்பாயாக.)\" அதாவது, 'பாவிகள் உன்னிடம் தவ்பா (பாவமன்னிப்பு) செய்து, உன்பக்கம் திரும்பி, தங்கள் பழைய தீய வழிகளைக் கைவிட்டு, நன்மையைச் செய்யவும் தீமையிலிருந்து விலகவும் உனது கட்டளைகளைப் பின்பற்றும் போது அவர்களை மன்னிப்பாயாக.' <span class=\"quran-arabic-font text-success\">﴾وَقِهِمْ</span> <span class=\"quran-arabic-font text-success\">عَذَابَ</span> <span class=\"quran-arabic-font text-success\">الْجَحِيمِ﴿</span><br />\r\n<br />\r\n(மேலும் கொழுந்து விட்டெரியும் நரக நெருப்பின் வேதனையிலிருந்து அவர்களைக் காப்பாற்றுவாயாக!) இதன் பொருள், 'வலிமிகுந்த, கடுமையான தண்டனையான நரக வேதனையிலிருந்து அவர்களைக் காத்தருள்வாயாக' என்பதாகும். <span class=\"quran-arabic-font text-success\">﴾رَبَّنَا</span> <span class=\"quran-arabic-font text-success\">وَأَدْخِلْهُمْ</span> <span class=\"quran-arabic-font text-success\">جَنَّاتِ</span> <span class=\"quran-arabic-font text-success\">عَدْنٍ</span> <span class=\"quran-arabic-font text-success\">الَّتِى</span> <span class=\"quran-arabic-font text-success\">وَعَدْتَّهُمْ</span> <span class=\"quran-arabic-font text-success\">وَمَن</span> <span class=\"quran-arabic-font text-success\">صَـلَحَ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">ءَابَآئِهِمْ</span> <span class=\"quran-arabic-font text-success\">وَأَزْوَجِهِمْ</span> <span class=\"quran-arabic-font text-success\">وَذُرِّيَّـتِهِمْ﴿</span><br />\r\n<br />\r\n(எங்கள் இறைவனே! நீ அவர்களுக்கு வாக்களித்த 'அத்ன்' எனும் நிலையான சுவனங்களில் அவர்களையும், அவர்களது மூதாதையர், அவர்களது மனைவியர், அவர்களது சந்ததியினரில் நற்செயல் புரிந்தவர்களையும் நுழையச் செய்வாயாக!) இதன் பொருள், 'அவர்கள் அருகருகே உள்ள வசிப்பிடங்களில் ஒருவரையொருவர் கண்டு மகிழும் பொருட்டு அவர்களை ஒன்று சேர்ப்பாயாக' என்பதாகும். இது பின்வரும் வசனத்தைப் போன்றது: <span class=\"quran-arabic-font text-success\">﴾وَالَّذِينَ</span> <span class=\"quran-arabic-font text-success\">ءَامَنُواْ</span> <span class=\"quran-arabic-font text-success\">وَاتَّبَعَتْهُمْ</span> <span class=\"quran-arabic-font text-success\">ذُرِّيَّتُهُم</span> <span class=\"quran-arabic-font text-success\">بِإِيمَانٍ</span> <span class=\"quran-arabic-font text-success\">أَلْحَقْنَا</span> <span class=\"quran-arabic-font text-success\">بِهِمْ</span> <span class=\"quran-arabic-font text-success\">ذُرِّيَّتَهُمْ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">أَلَتْنَاهُم</span> <span class=\"quran-arabic-font text-success\">مِّنْ</span> <span class=\"quran-arabic-font text-success\">عَمَلِهِم</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">شَىْءٍ﴿</span><br />\r\n<br />\r\n(எவர்கள் ஈமான் கொண்டு, அவர்களுடைய சந்ததியினரும் ஈமான் கொள்வதில் அவர்களைப் பின்பற்றுகிறார்களோ, அவர்களுடைய சந்ததியினரை அவர்களுடன் நாம் சேர்த்து வைப்போம்; அவர்களுடைய நற்செயல்களின் கூலியில் எதையும் நாம் குறைக்க மாட்டோம்) (<a href=\"qurandisp.php?sura=52&ayah=21\" class=\"link\">52:21</a>). இதன் பொருள், 'அவர்கள் அனைவரும் அந்தஸ்தில் சமமாக்கப்படுவார்கள். இதன் மூலம் அவர்கள் ஒருவருக்கொருவர் துணையுடன் இன்புறுவார்கள்; உயர்ந்த அந்தஸ்தில் இருப்பவர் தனது அந்தஸ்தில் எதையும் இழக்க மாட்டார். மாறாக, நம்முடைய அருளாகவும் கருணையாகவும் குறைந்த அந்தஸ்தில் உள்ளவரின் நிலையை உயர்த்தி, அவர்கள் சமமாகும்படிச் செய்வோம்' என்பதாகும். ஸயீத் பின் ஜுபைர் (ரஹ்) அவர்கள் கூறினார்கள்: \"ஒரு விசுவாசி சொர்க்கத்தில் நுழையும்போது, தனது தந்தை, மகன் மற்றும் சகோதரர் எங்கே என்று கேட்பார். அப்போது அவரிடம், 'அவர்கள் உங்களைப் போன்ற நற்செயல்களின் உயர் நிலையை அடையவில்லை' என்று கூறப்படும். அதற்கு அவர், 'நான் எனக்காகவும் அவர்களுக்காகவும்தான் நற்செயல்களைச் செய்தேன்' என்பார். பின்னர், அந்த உயர் நிலையில் அவருடன் இணைவதற்காக அவர்கள் கொண்டு வரப்படுவார்கள்.\" பிறகு ஸயீத் பின் ஜுபைர் (ரஹ்) அவர்கள் இந்த வசனத்தை ஓதினார்கள்: <span class=\"quran-arabic-font text-success\">﴾رَبَّنَا</span> <span class=\"quran-arabic-font text-success\">وَأَدْخِلْهُمْ</span> <span class=\"quran-arabic-font text-success\">جَنَّاتِ</span> <span class=\"quran-arabic-font text-success\">عَدْنٍ</span> <span class=\"quran-arabic-font text-success\">الَّتِى</span> <span class=\"quran-arabic-font text-success\">وَعَدْتَّهُمْ</span> <span class=\"quran-arabic-font text-success\">وَمَن</span> <span class=\"quran-arabic-font text-success\">صَـلَحَ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">ءَابَآئِهِمْ</span> <span class=\"quran-arabic-font text-success\">وَأَزْوَجِهِمْ</span> <span class=\"quran-arabic-font text-success\">وَذُرِّيَّـتِهِمْ</span> <span class=\"quran-arabic-font text-success\">إِنَّكَ</span> <span class=\"quran-arabic-font text-success\">أَنتَ</span> <span class=\"quran-arabic-font text-success\">الْعَزِيزُ</span> <span class=\"quran-arabic-font text-success\">الْحَكِيمُ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(எங்கள் இறைவனே! நீ அவர்களுக்கு வாக்களித்த 'அத்ன்' எனும் நிலையான சுவனங்களில் அவர்களையும், அவர்களது மூதாதையர், அவர்களது மனைவியர், அவர்களது சந்ததியினரில் நற்செயல் புரிந்தவர்களையும் நுழையச் செய்வாயாக! நிச்சயமாக நீயே மிகைத்தவனும் ஞானம் மிக்கவனுமாவாய்.) முதர்ரிஃப் பின் அப்துல்லாஹ் பின் அஷ்-ஷிக்கீர் (ரஹ்) அவர்கள் கூறினார்கள்: \"விசுவாசிகளின் மீது அல்லாஹ்வின் அடியார்களில் மிகவும் அக்கறை கொண்டவர்கள் வானவர்களே.\" பின்னர் அவர் இந்த வசனத்தை ஓதினார்: <span class=\"quran-arabic-font text-success\">﴾رَبَّنَا</span> <span class=\"quran-arabic-font text-success\">وَأَدْخِلْهُمْ</span> <span class=\"quran-arabic-font text-success\">جَنَّاتِ</span> <span class=\"quran-arabic-font text-success\">عَدْنٍ</span> <span class=\"quran-arabic-font text-success\">الَّتِى</span> <span class=\"quran-arabic-font text-success\">وَعَدْتَّهُمْ﴿</span><br />\r\n<br />\r\n(எங்கள் இறைவனே! நீ அவர்களுக்கு வாக்களித்த 'அத்ன்' எனும் நிலையான சுவனங்களில் அவர்களை நுழையச் செய்வாயாக.) பிறகு அவர், \"விசுவாசிகளுக்கு மிகவும் துரோகம் செய்யக்கூடியவர்கள் ஷைத்தான்களே\" என்று கூறினார். <span class=\"quran-arabic-font text-success\">﴾إِنَّكَ</span> <span class=\"quran-arabic-font text-success\">أَنتَ</span> <span class=\"quran-arabic-font text-success\">العَزِيزُ</span> <span class=\"quran-arabic-font text-success\">الحَكِيمُ﴿</span><br />\r\n<br />\r\n(நிச்சயமாக நீயே மிகைத்தவனும் ஞானம் மிக்கவனுமாவாய்.) இதன் பொருள், 'எவராலும் எதிர்க்க முடியாத அல்லது வெல்ல முடியாதவன் அல்லாஹ்; நீ நாடியது மட்டுமே நடக்கும், நீ நாடாதது நடக்காது. நீ சொல்வதிலும் செய்வதிலும், சட்டம் இயற்றுவதிலும் தீர்ப்பளிப்பதிலும் ஞானம் மிக்கவன்' என்பதாகும். <span class=\"quran-arabic-font text-success\">﴾وَقِهِمُ</span> <span class=\"quran-arabic-font text-success\">السَّيِّئَاتِ﴿</span><br />\r\n<br />\r\n(மேலும் அவர்களைத் தீமைகளிலிருந்து காப்பாற்றுவாயாக,) இதன் பொருள், தீய செயல்களிலிருந்தும் அதன் விளைவுகளிலிருந்தும் அவர்களைக் காப்பாயாக என்பதாகும். <span class=\"quran-arabic-font text-success\">﴾وَمَن</span> <span class=\"quran-arabic-font text-success\">تَقِ</span> <span class=\"quran-arabic-font text-success\">السَّيِّئَاتِ</span> <span class=\"quran-arabic-font text-success\">يَوْمَئِذٍ﴿</span><br />\r\n<br />\r\n(மேலும் அந்நாளில் எவரை நீ தீமைகளிலிருந்து காப்பாற்றுகிறாயோ,) இதன் பொருள், மறுமை நாளில் (யாரை நீ காப்பாற்றுகிறாயோ), <span class=\"quran-arabic-font text-success\">﴾فَقَدْ</span> <span class=\"quran-arabic-font text-success\">رَحِمْتَهُ﴿</span><br />\r\n<br />\r\n(அவருக்கு நிச்சயமாக நீ அருள் புரிந்துவிட்டாய்.) இதன் பொருள், 'நீ அவருக்குப் பாதுகாப்பு அளித்து, தண்டனையிலிருந்து அவரைக் காப்பாற்றிவிட்டாய்; மேலும் அவருக்கு நற்கூலியை வழங்கிவிட்டாய்' என்பதாகும். <span class=\"quran-arabic-font text-success\">﴾وَذَلِكَ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">الْفَوْزُ</span> <span class=\"quran-arabic-font text-success\">الْعَظِيمُ﴿</span><br />\r\n<br />\r\n(மேலும் அதுவே மகத்தான வெற்றியாகும்.)<br />\r\n<br />","text":"அர்ஷைச் சுமப்பவர்கள் அல்லாஹ்வைப் புகழ்ந்து, விசுவாசிகளுக்காகப் பாவமன்னிப்புக் கோருதல்\n\r\n\n\r\n﴾الَّذِينَ يَحْمِلُونَ الْعَرْشَ وَمَنْ حَوْلَهُ يُسَبِّحُونَ بِحَمْدِ رَبِّهِمْ﴿\n\r\n\n\r\nதனக்கு மிக நெருக்கமான வானவர்களும், அர்ஷைச் சுமப்பவர்களும், அதைச் சுற்றியுள்ள வானவர்களும் - அனைவரும் தங்கள் இறைவனின் புகழைக் கூறி அவனைத் துதிக்கின்றனர் என்று அல்லாஹ் கூறுகிறான். அவர்கள், அல்லாஹ் குறைகளற்றவன் என்பதைக் குறிக்கும் 'தஸ்பீஹ்' (துதித்தல்) மற்றும் புகழுக்கான 'தஹ்மீத்' (புகழுரை) ஆகியவற்றை இணைத்துக் கூறுகின்றனர். ﴾وَيُؤْمِنُونَ بِهِ﴿\n\r\n\n\r\n(மேலும் அவனையே நம்பிக்கை கொள்கின்றனர்) என்பதன் பொருள், அவர்கள் பணிவுடன் அவனிடம் தங்களை ஒப்படைக்கிறார்கள் என்பதாகும். ﴾وَيَسْتَغْفِرُونَ لِلَّذِينَ ءَامَنُواْ﴿\n\r\n\n\r\n(மேலும் நம்பிக்கை கொண்டவர்களுக்காகப் பாவமன்னிப்புக் கோருகின்றனர்) இதன் பொருள், பூமியில் வசிக்கும் மக்களில் மறைவானவற்றை (ஈமான்) நம்பிக்கை கொண்டவர்களுக்காக அவர்கள் பிரார்த்திக்கின்றனர் என்பதாகும். தனக்கு நெருக்கமான வானவர்கள், இறைவிசுவாசிகள் இல்லாதபோது அவர்களுக்காகப் பிரார்த்தனை செய்ய வேண்டும் என்று அல்லாஹ் கட்டளையிட்டான். எனவே, ஒரு விசுவாசி தன் சகோதரனுக்காக அவர் இல்லாதபோது பிரார்த்திக்கும்போது, வானவர்கள் 'ஆமீன்' என்று கூறுவது அவர்களின் இயற்கையான பண்பாகும். ஸஹீஹ் முஸ்லிமில் இவ்வாறு கூறப்பட்டுள்ளது: ﴾«إِذَا دَعَا الْمُسْلِمُ لِأَخِيهِ بِظَهْرِ الْغَيْبِ قَالَ الْمَلَكُ: آمِينَ وَلَكَ بِمِثْلِه»﴿\n\r\n\n\r\n(ஒரு முஸ்லிம் தன் சகோதரனுக்காக அவர் இல்லாதபோது பிரார்த்தித்தால், அந்த வானவர், 'ஆமீன், உனக்கும் அதுபோன்றே கிடைக்கட்டும்' என்று கூறுகிறார்.)\" ஷஹ்ர் பின் ஹவ்ஷப் (ரஹ்) அவர்கள் கூறினார்கள்: \"அர்ஷைச் சுமப்பவர்கள் எட்டு பேர்; அவர்களில் நால்வர், 'யா அல்லாஹ், நீ தூய்மையானவன், உனக்கே எல்லாப் புகழும். உனது அறிவுக்குப் பிறகும் நீ காட்டும் சகிப்புத்தன்மைக்காக உனக்கே புகழ் அனைத்தும்' என்று கூறுகின்றனர். மற்ற நால்வர், 'யா அல்லாஹ், நீ தூய்மையானவன், உனக்கே எல்லாப் புகழும். உனது ஆற்றலுக்குப் பிறகும் நீ காட்டும் மன்னிப்புக்காக உனக்கே புகழ் அனைத்தும்' என்று கூறுகின்றனர். அவர்கள் நம்பிக்கை கொண்டவர்களுக்காகப் பாவமன்னிப்புக் கோரும்போது இவ்வாறு கூறுகின்றனர்: ﴾رَبَّنَا وَسِعْتَ كُلَّ شَىْءٍ رَّحْمَةً وَعِلْماً﴿\n\r\n\n\r\n(எங்கள் இறைவனே! நீ உனது அருளாலும் அறிவாலும் அனைத்துப் பொருட்களையும் சூழ்ந்துள்ளாய்.) இதன் பொருள், 'உனது அருள் அவர்களின் பாவங்களை விடவும் விரிவானது; உனது அறிவு அவர்களின் அனைத்துச் செயல்களையும், சொற்களையும், நடவடிக்கைகளையும் சூழ்ந்துள்ளது' என்பதாகும். ﴾فَاغْفِرْ لِلَّذِينَ تَابُواْ وَاتَّبَعُواْ سَبِيلَكَ﴿\n\r\n\n\r\n(ஆகவே, பாவமன்னிப்புக் கோரி உனது வழியைப் பின்பற்றியவர்களை மன்னிப்பாயாக.)\" அதாவது, 'பாவிகள் உன்னிடம் தவ்பா (பாவமன்னிப்பு) செய்து, உன்பக்கம் திரும்பி, தங்கள் பழைய தீய வழிகளைக் கைவிட்டு, நன்மையைச் செய்யவும் தீமையிலிருந்து விலகவும் உனது கட்டளைகளைப் பின்பற்றும் போது அவர்களை மன்னிப்பாயாக.' ﴾وَقِهِمْ عَذَابَ الْجَحِيمِ﴿\n\r\n\n\r\n(மேலும் கொழுந்து விட்டெரியும் நரக நெருப்பின் வேதனையிலிருந்து அவர்களைக் காப்பாற்றுவாயாக!) இதன் பொருள், 'வலிமிகுந்த, கடுமையான தண்டனையான நரக வேதனையிலிருந்து அவர்களைக் காத்தருள்வாயாக' என்பதாகும். ﴾رَبَّنَا وَأَدْخِلْهُمْ جَنَّاتِ عَدْنٍ الَّتِى وَعَدْتَّهُمْ وَمَن صَـلَحَ مِنْ ءَابَآئِهِمْ وَأَزْوَجِهِمْ وَذُرِّيَّـتِهِمْ﴿\n\r\n\n\r\n(எங்கள் இறைவனே! நீ அவர்களுக்கு வாக்களித்த 'அத்ன்' எனும் நிலையான சுவனங்களில் அவர்களையும், அவர்களது மூதாதையர், அவர்களது மனைவியர், அவர்களது சந்ததியினரில் நற்செயல் புரிந்தவர்களையும் நுழையச் செய்வாயாக!) இதன் பொருள், 'அவர்கள் அருகருகே உள்ள வசிப்பிடங்களில் ஒருவரையொருவர் கண்டு மகிழும் பொருட்டு அவர்களை ஒன்று சேர்ப்பாயாக' என்பதாகும். இது பின்வரும் வசனத்தைப் போன்றது: ﴾وَالَّذِينَ ءَامَنُواْ وَاتَّبَعَتْهُمْ ذُرِّيَّتُهُم بِإِيمَانٍ أَلْحَقْنَا بِهِمْ ذُرِّيَّتَهُمْ وَمَا أَلَتْنَاهُم مِّنْ عَمَلِهِم مِّن شَىْءٍ﴿\n\r\n\n\r\n(எவர்கள் ஈமான் கொண்டு, அவர்களுடைய சந்ததியினரும் ஈமான் கொள்வதில் அவர்களைப் பின்பற்றுகிறார்களோ, அவர்களுடைய சந்ததியினரை அவர்களுடன் நாம் சேர்த்து வைப்போம்; அவர்களுடைய நற்செயல்களின் கூலியில் எதையும் நாம் குறைக்க மாட்டோம்) (52:21). இதன் பொருள், 'அவர்கள் அனைவரும் அந்தஸ்தில் சமமாக்கப்படுவார்கள். இதன் மூலம் அவர்கள் ஒருவருக்கொருவர் துணையுடன் இன்புறுவார்கள்; உயர்ந்த அந்தஸ்தில் இருப்பவர் தனது அந்தஸ்தில் எதையும் இழக்க மாட்டார். மாறாக, நம்முடைய அருளாகவும் கருணையாகவும் குறைந்த அந்தஸ்தில் உள்ளவரின் நிலையை உயர்த்தி, அவர்கள் சமமாகும்படிச் செய்வோம்' என்பதாகும். ஸயீத் பின் ஜுபைர் (ரஹ்) அவர்கள் கூறினார்கள்: \"ஒரு விசுவாசி சொர்க்கத்தில் நுழையும்போது, தனது தந்தை, மகன் மற்றும் சகோதரர் எங்கே என்று கேட்பார். அப்போது அவரிடம், 'அவர்கள் உங்களைப் போன்ற நற்செயல்களின் உயர் நிலையை அடையவில்லை' என்று கூறப்படும். அதற்கு அவர், 'நான் எனக்காகவும் அவர்களுக்காகவும்தான் நற்செயல்களைச் செய்தேன்' என்பார். பின்னர், அந்த உயர் நிலையில் அவருடன் இணைவதற்காக அவர்கள் கொண்டு வரப்படுவார்கள்.\" பிறகு ஸயீத் பின் ஜுபைர் (ரஹ்) அவர்கள் இந்த வசனத்தை ஓதினார்கள்: ﴾رَبَّنَا وَأَدْخِلْهُمْ جَنَّاتِ عَدْنٍ الَّتِى وَعَدْتَّهُمْ وَمَن صَـلَحَ مِنْ ءَابَآئِهِمْ وَأَزْوَجِهِمْ وَذُرِّيَّـتِهِمْ إِنَّكَ أَنتَ الْعَزِيزُ الْحَكِيمُ ﴿\n\r\n\n\r\n(எங்கள் இறைவனே! நீ அவர்களுக்கு வாக்களித்த 'அத்ன்' எனும் நிலையான சுவனங்களில் அவர்களையும், அவர்களது மூதாதையர், அவர்களது மனைவியர், அவர்களது சந்ததியினரில் நற்செயல் புரிந்தவர்களையும் நுழையச் செய்வாயாக! நிச்சயமாக நீயே மிகைத்தவனும் ஞானம் மிக்கவனுமாவாய்.) முதர்ரிஃப் பின் அப்துல்லாஹ் பின் அஷ்-ஷிக்கீர் (ரஹ்) அவர்கள் கூறினார்கள்: \"விசுவாசிகளின் மீது அல்லாஹ்வின் அடியார்களில் மிகவும் அக்கறை கொண்டவர்கள் வானவர்களே.\" பின்னர் அவர் இந்த வசனத்தை ஓதினார்: ﴾رَبَّنَا وَأَدْخِلْهُمْ جَنَّاتِ عَدْنٍ الَّتِى وَعَدْتَّهُمْ﴿\n\r\n\n\r\n(எங்கள் இறைவனே! நீ அவர்களுக்கு வாக்களித்த 'அத்ன்' எனும் நிலையான சுவனங்களில் அவர்களை நுழையச் செய்வாயாக.) பிறகு அவர், \"விசுவாசிகளுக்கு மிகவும் துரோகம் செய்யக்கூடியவர்கள் ஷைத்தான்களே\" என்று கூறினார். ﴾إِنَّكَ أَنتَ العَزِيزُ الحَكِيمُ﴿\n\r\n\n\r\n(நிச்சயமாக நீயே மிகைத்தவனும் ஞானம் மிக்கவனுமாவாய்.) இதன் பொருள், 'எவராலும் எதிர்க்க முடியாத அல்லது வெல்ல முடியாதவன் அல்லாஹ்; நீ நாடியது மட்டுமே நடக்கும், நீ நாடாதது நடக்காது. நீ சொல்வதிலும் செய்வதிலும், சட்டம் இயற்றுவதிலும் தீர்ப்பளிப்பதிலும் ஞானம் மிக்கவன்' என்பதாகும். ﴾وَقِهِمُ السَّيِّئَاتِ﴿\n\r\n\n\r\n(மேலும் அவர்களைத் தீமைகளிலிருந்து காப்பாற்றுவாயாக,) இதன் பொருள், தீய செயல்களிலிருந்தும் அதன் விளைவுகளிலிருந்தும் அவர்களைக் காப்பாயாக என்பதாகும். ﴾وَمَن تَقِ السَّيِّئَاتِ يَوْمَئِذٍ﴿\n\r\n\n\r\n(மேலும் அந்நாளில் எவரை நீ தீமைகளிலிருந்து காப்பாற்றுகிறாயோ,) இதன் பொருள், மறுமை நாளில் (யாரை நீ காப்பாற்றுகிறாயோ), ﴾فَقَدْ رَحِمْتَهُ﴿\n\r\n\n\r\n(அவருக்கு நிச்சயமாக நீ அருள் புரிந்துவிட்டாய்.) இதன் பொருள், 'நீ அவருக்குப் பாதுகாப்பு அளித்து, தண்டனையிலிருந்து அவரைக் காப்பாற்றிவிட்டாய்; மேலும் அவருக்கு நற்கூலியை வழங்கிவிட்டாய்' என்பதாகும். ﴾وَذَلِكَ هُوَ الْفَوْزُ الْعَظِيمُ﴿\n\r\n\n\r\n(மேலும் அதுவே மகத்தான வெற்றியாகும்.)"},"10":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=40&ayah=14\" class=\"link\">40:14</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 40:14 ஐ பார்க்கவும்"},"11":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=40&ayah=14\" class=\"link\">40:14</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 40:14 ஐ பார்க்கவும்"},"12":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=40&ayah=14\" class=\"link\">40:14</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 40:14 ஐ பார்க்கவும்"},"13":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=40&ayah=14\" class=\"link\">40:14</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 40:14 ஐ பார்க்கவும்"},"14":{"html":"<strong>நரகில் நுழைந்த பிறகு நிராகரிப்பாளர்களின் வருத்தம்</strong><br />\r\n<br />\r\nமறுமை நாளில் நிராகரிப்பாளர்கள் நரகத்தில் நுழைந்து, வேதனைமிக்க நெருப்பின் ஆழத்தில் மூழ்கும்போது வருத்தப்படுவார்கள் என்று அல்லாஹ் கூறுகிறான். அல்லாஹ்வின் தாங்க முடியாத தண்டனையை அவர்கள் அனுபவிக்கும்போது, கடந்த காலத்தில் தாங்கள் செய்த பாவங்களின் காரணமாகத் தங்களையே மிகுந்த அளவில் வெறுப்பார்கள். அந்தப் பாவங்களே அவர்கள் நரகில் நுழைவதற்குக் காரணமாயின. அந்த நேரத்தில், \"இவ்வுலகில் உங்களுக்கு ஈமான் (நம்பிக்கை) வழங்கப்பட்டபோது நீங்கள் அதை நிராகரித்தீர்கள்; அப்போது உங்கள் மீது அல்லாஹ் கொண்டிருந்த வெறுப்பானது, இப்போது உங்கள் மீது நீங்களே கொண்டிருக்கும் வெறுப்பை விடப் பெரியது\" என்று வானவர்கள் உரத்த குரலில் அவர்களிடம் கூறுவார்கள். கதாதா (ரஹ்) அவர்கள் இந்த வசனத்தைப் (ஆயத்) பற்றிக் கூறினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لَمَقْتُ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">أَكْبَرُ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">مَّقْتِكُمْ</span> <span class=\"quran-arabic-font text-success\">أَنفُسَكُـمْ</span> <span class=\"quran-arabic-font text-success\">إِذْ</span> <span class=\"quran-arabic-font text-success\">تُدْعَوْنَ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">الإِيمَـنِ</span> <span class=\"quran-arabic-font text-success\">فَتَكْفُرُونَ</span><br />\r\n(நிச்சயமாக, நீங்கள் ஈமானின் பக்கம் அழைக்கப்பட்டு, அதை நிராகரித்தபோது, உங்கள் மீது நீங்கள் கொண்டிருந்த வெறுப்பை விட அல்லாஹ்வின் வெறுப்பு மிகப் பெரியதாக இருந்தது.) \"வழிகேட்டில் உள்ள மக்கள் இவ்வுலகில் ஈமானின் பக்கம் அழைக்கப்பட்டு, அதை அவர்கள் ஏற்க மறுத்துப் புறக்கணித்தபோது அல்லாஹ் அவர்கள் மீது கொண்டிருந்த வெறுப்பு, மறுமை நாளில் அல்லாஹ்வின் தண்டனையை நேரில் கண்டு அவர்கள் தங்களையே வெறுப்பதை விடப் பெரியது\" (என்று கதாதா (ரஹ்) கூறினார்கள்). இதுவே அல்-ஹஸன் அல்-பஸரி, முஜாஹித், அஸ்-ஸுத்தி, தர்ர் பின் அப்துல்லாஹ் அல்-ஹம்தானி, அப்துர்-ரஹ்மான் பின் ஸைத் பின் அஸ்லம் மற்றும் இப்னு ஜரீர் அத்-தபரி (ரஹ்மதுல்லாஹி அலைஹிம்) ஆகியோரின் கருத்தாகவும் இருந்தது. அல்லாஹ் அவர்கள் அனைவர் மீதும் கருணை புரிவானாக.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قَالُواْ</span> <span class=\"quran-arabic-font text-success\">رَبَّنَآ</span> <span class=\"quran-arabic-font text-success\">أَمَتَّنَا</span> <span class=\"quran-arabic-font text-success\">اثْنَتَيْنِ</span> <span class=\"quran-arabic-font text-success\">وَأَحْيَيْتَنَا</span> <span class=\"quran-arabic-font text-success\">اثْنَتَيْنِ</span><br />\r\n(அவர்கள் கூறுவார்கள்: \"எங்கள் இறைவனே! நீ எங்களுக்கு இரண்டு முறை மரணத்தைத் தந்தாய், எங்களுக்கு இரண்டு முறை வாழ்வையும் தந்தாய்!...\") இப்னு மஸ்ஊத் (ரழி) அவர்களிடமிருந்து அபூ அல்-அஹ்வஸ், அவரிடமிருந்து அபூ இஸ்ஹாக், அவரிடமிருந்து அத்-தவ்ரி ஆகியோர் அறிவிக்கிறார்கள்: \"இந்த வசனம் (ஆயத்) பின்வரும் வசனத்தைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">كَيْفَ</span> <span class=\"quran-arabic-font text-success\">تَكْفُرُونَ</span> <span class=\"quran-arabic-font text-success\">بِاللَّهِ</span> <span class=\"quran-arabic-font text-success\">وَكُنتُمْ</span> <span class=\"quran-arabic-font text-success\">أَمْوَتًا</span> <span class=\"quran-arabic-font text-success\">فَأَحْيَـكُمْ</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">يُمِيتُكُمْ</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">يُحْيِيكُمْ</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">إِلَيْهِ</span> <span class=\"quran-arabic-font text-success\">تُرْجَعُونَ</span><br />\r\n(நீங்கள் உயிரற்றவர்களாக இருந்த நிலையில் அல்லாஹ்வை எப்படி நிராகரிக்கிறீர்கள்? அவன்தான் உங்களுக்கு உயிர் கொடுத்தான். பிறகு அவன் உங்களை மரணிக்கச் செய்வான், பிறகு மீண்டும் உங்களை உயிர்ப்பிப்பான், பிறகு அவனிடமே நீங்கள் திரும்பக் கொண்டுவரப்படுவீர்கள்.)\" (<a href=\"qurandisp.php?sura=2&ayah=28\" class=\"link\">2:28</a>). இது இப்னு அப்பாஸ் (ரழி), அத்-தஹ்ஹாக், கதாதா (ரஹ்) மற்றும் அபூ மாலிக் ஆகியோரின் கருத்தாகவும் இருந்தது. இதுவே சந்தேகத்திற்கு இடமின்றி சரியான கருத்தாகும்.<br />\r\n<br />\r\nஇதன் மூலம் கூறப்படுவது என்னவென்றால், மறுமை நாளில் விசாரணைக்காக அல்லாஹ்வின் முன்னால் நிற்கும்போது, நிராகரிப்பாளர்கள் மீண்டும் உலகிற்குத் திரும்பிச் செல்ல அனுமதி கோருவார்கள். அல்லாஹ் கூறுவது போல:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَوْ</span> <span class=\"quran-arabic-font text-success\">تَرَى</span> <span class=\"quran-arabic-font text-success\">إِذِ</span> <span class=\"quran-arabic-font text-success\">الْمُجْرِمُونَ</span> <span class=\"quran-arabic-font text-success\">نَاكِسُواْ</span> <span class=\"quran-arabic-font text-success\">رُءُوسِهِمْ</span> <span class=\"quran-arabic-font text-success\">عِندَ</span> <span class=\"quran-arabic-font text-success\">رَبِّهِمْ</span> <span class=\"quran-arabic-font text-success\">رَبَّنَآ</span> <span class=\"quran-arabic-font text-success\">أَبْصَرْنَا</span> <span class=\"quran-arabic-font text-success\">وَسَمِعْنَا</span> <span class=\"quran-arabic-font text-success\">فَارْجِعْنَا</span> <span class=\"quran-arabic-font text-success\">نَعْمَلْ</span> <span class=\"quran-arabic-font text-success\">صَـلِحاً</span> <span class=\"quran-arabic-font text-success\">إِنَّا</span> <span class=\"quran-arabic-font text-success\">مُوقِنُونَ</span><br />\r\n(குற்றவாளிகள் தங்கள் இறைவன் முன் தலைகுனிந்து நின்று, \"எங்கள் இறைவனே! நாங்கள் இப்போது பார்த்துவிட்டோம், கேட்டுவிட்டோம். எனவே, எங்களைத் திருப்பி அனுப்புவாயாக, நாங்கள் நற்செயல்களைச் செய்வோம். நிச்சயமாக, நாங்கள் இப்போது உறுதியாக நம்புகிறோம்\" என்று கூறுவதை நீங்கள் கண்டால்!) (<a href=\"qurandisp.php?sura=32&ayah=12\" class=\"link\">32:12</a>). எனினும், அவர்களுக்கு எந்தப் பதிலும் அளிக்கப்படாது. பிறகு அவர்கள் நரக நெருப்பைக் கண்டு, அதன் விளிம்பில் நிறுத்தப்பட்டு, அங்கிருக்கும் தண்டனைகளைப் பார்க்கும்போது, முன்பை விட அதிக ஆவலுடன் உலகிற்குத் திரும்பக் கோருவார்கள். அப்போதும் அவர்களுக்கு எந்தப் பதிலும் கிடைக்காது. அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَوْ</span> <span class=\"quran-arabic-font text-success\">تَرَى</span> <span class=\"quran-arabic-font text-success\">إِذْ</span> <span class=\"quran-arabic-font text-success\">وُقِفُواْ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">النَّارِ</span> <span class=\"quran-arabic-font text-success\">فَقَالُواْ</span> <span class=\"quran-arabic-font text-success\">يلَيْتَنَا</span> <span class=\"quran-arabic-font text-success\">نُرَدُّ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">نُكَذِّبَ</span> <span class=\"quran-arabic-font text-success\">بِـَايَـتِ</span> <span class=\"quran-arabic-font text-success\">رَبِّنَا</span> <span class=\"quran-arabic-font text-success\">وَنَكُونَ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْمُؤْمِنِينَ</span> - <span class=\"quran-arabic-font text-success\">بَلْ</span> <span class=\"quran-arabic-font text-success\">بَدَا</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">مَّا</span> <span class=\"quran-arabic-font text-success\">كَانُواْ</span> <span class=\"quran-arabic-font text-success\">يُخْفُونَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">قَبْلُ</span> <span class=\"quran-arabic-font text-success\">وَلَوْ</span> <span class=\"quran-arabic-font text-success\">رُدُّواْ</span> <span class=\"quran-arabic-font text-success\">لَعَـدُواْ</span> <span class=\"quran-arabic-font text-success\">لِمَا</span> <span class=\"quran-arabic-font text-success\">نُهُواْ</span> <span class=\"quran-arabic-font text-success\">عَنْهُ</span> <span class=\"quran-arabic-font text-success\">وَإِنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">لَكَـذِبُونَ</span><br />\r\n(அவர்கள் (நரக) நெருப்பின் முன் நிறுத்தப்படும்போது நீங்கள் அவர்களைக் கண்டால்! \"நாங்கள் (உலகிற்குத்) திருப்பி அனுப்பப்பட்டால் எவ்வளவு நன்றாக இருக்கும்! அப்போது நாங்கள் எங்கள் இறைவனின் வசனங்களை (ஆயத்துகளை) நிராகரிக்க மாட்டோம், மேலும் நாங்கள் நம்பிக்கையாளர்களில் ஒருவராக இருப்போம்\" என்று அவர்கள் கூறுவார்கள். அவ்வாறல்ல, அவர்கள் முன்பு மறைத்து வைத்திருந்தது அவர்களுக்கு வெளியாகிவிட்டது. அவர்கள் திருப்பி அனுப்பப்பட்டாலும், அவர்கள் எதை விட்டும் தடுக்கப்பட்டார்களோ, அதற்கே மீண்டும் திரும்புவார்கள். நிச்சயமாக அவர்கள் பொய்யர்கள்.) (<a href=\"qurandisp.php?sura=6&ayah=27\" class=\"link\">6:27</a>-28).<br />\r\n<br />\r\nஅவர்கள் உண்மையில் நரகத்தில் நுழைந்து அதன் வெப்பத்தையும், இரும்புக் கொக்கிகளையும், சங்கிலிகளையும் அனுபவிக்கும்போது, உலகிற்குத் திரும்ப வேண்டும் என்ற அவர்களின் வேண்டுகோள் மிகவும் தீவிரமானதாகவும் கதறலாகவும் இருக்கும்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَهُمْ</span> <span class=\"quran-arabic-font text-success\">يَصْطَرِخُونَ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">رَبَّنَآ</span> <span class=\"quran-arabic-font text-success\">أَخْرِجْنَا</span> <span class=\"quran-arabic-font text-success\">نَعْمَلْ</span> <span class=\"quran-arabic-font text-success\">صَـلِحاً</span> <span class=\"quran-arabic-font text-success\">غَيْرَ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">كُـنَّا</span> <span class=\"quran-arabic-font text-success\">نَعْمَلُ</span> <span class=\"quran-arabic-font text-success\">أَوَلَمْ</span> <span class=\"quran-arabic-font text-success\">نُعَمِّرْكُمْ</span> <span class=\"quran-arabic-font text-success\">مَّا</span> <span class=\"quran-arabic-font text-success\">يَتَذَكَّرُ</span> <span class=\"quran-arabic-font text-success\">فِيهِ</span> <span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">تَذَكَّرَ</span> <span class=\"quran-arabic-font text-success\">وَجَآءَكُمُ</span> <span class=\"quran-arabic-font text-success\">النَّذِيرُ</span> <span class=\"quran-arabic-font text-success\">فَذُوقُواْ</span> <span class=\"quran-arabic-font text-success\">فَمَا</span> <span class=\"quran-arabic-font text-success\">لِلظَّـلِمِينَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">نَّصِيرٍ</span><br />\r\n(அதில் அவர்கள் கதறுவார்கள்: \"எங்கள் இறைவனே! எங்களை வெளியேற்றுவாயாக, நாங்கள் முன்பு செய்து கொண்டிருந்த செயல்களுக்கு மாறாக நற்செயல்களைச் செய்வோம்.\" (அதற்கு அல்லாஹ்), \"உசாவுபவர் பாடம் பெறுவதற்குப் போதுமான கால அவகாசத்தை நாம் உங்களுக்கு வழங்கவில்லையா? உங்களிடம் எச்சரிப்பவரும் வந்தாரே! எனவே, வேதனையைச் சுவையுங்கள். அநீதி இழைத்தவர்களுக்கு எந்த உதவியாளரும் இல்லை\" (என்று பதிலளிப்பான்).) (<a href=\"qurandisp.php?sura=35&ayah=37\" class=\"link\">35:37</a>)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">رَبَّنَآ</span> <span class=\"quran-arabic-font text-success\">أَخْرِجْنَا</span> <span class=\"quran-arabic-font text-success\">مِنْهَا</span> <span class=\"quran-arabic-font text-success\">فَإِنْ</span> <span class=\"quran-arabic-font text-success\">عُدْنَا</span> <span class=\"quran-arabic-font text-success\">فَإِنَّا</span> <span class=\"quran-arabic-font text-success\">ظَـلِمُونَ</span> - <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">اخْسَئُواْ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">تُكَلِّمُونِ</span><br />\r\n(\"எங்கள் இறைவனே! எங்களை இதிலிருந்து வெளியேற்றுவாயாக. நாங்கள் மீண்டும் (பாவத்திற்குத்) திரும்பினால், நிச்சயமாக நாங்கள் அநீதியாளர்களாகி விடுவோம்.\" அதற்கு அவன் (அல்லாஹ்), \"இழிவடைந்த நிலையில் அங்கேயே இருங்கள்! என்னிடம் பேசாதீர்கள்\" என்று கூறுவான்.) (<a href=\"qurandisp.php?sura=23&ayah=107\" class=\"link\">23:107</a>-108).<br />\r\n<br />\r\nஇந்த வசனத்தின்படி, அவர்கள் மிகவும் கெஞ்சிக் கூத்தாடி, பின்வரும் வார்த்தைகளுடன் தங்கள் வேண்டுகோளைத் தொடங்குவார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">رَبَّنَآ</span> <span class=\"quran-arabic-font text-success\">أَمَتَّنَا</span> <span class=\"quran-arabic-font text-success\">اثْنَتَيْنِ</span> <span class=\"quran-arabic-font text-success\">وَأَحْيَيْتَنَا</span> <span class=\"quran-arabic-font text-success\">اثْنَتَيْنِ</span> <span class=\"quran-arabic-font text-success\">فَاعْتَرَفْنَا</span> <span class=\"quran-arabic-font text-success\">بِذُنُوبِنَا</span><br />\r\n(எங்கள் இறைவனே! நீ எங்களுக்கு இரண்டு முறை மரணத்தைத் தந்தாய், எங்களுக்கு இரண்டு முறை வாழ்வையும் தந்தாய்! எனவே, நாங்கள் எங்கள் பாவங்களை ஒப்புக்கொள்கிறோம்.) அதாவது, \"உனது பேராற்றலால், நாங்கள் மரணித்திருந்த நிலையில் எங்களுக்கு உயிர் கொடுத்தாய், பிறகு உயிருடன் இருந்த நிலையில் எங்களை மரணிக்கச் செய்தாய்; நீ நாடியதைச் செய்ய ஆற்றலுள்ளவன். நாங்கள் எங்கள் பாவங்களை ஒப்புக்கொள்கிறோம், இவ்வுலகில் எங்களுக்கே அநீதி இழைத்துக் கொண்டோம் என்பதை ஏற்றுக்கொள்கிறோம்\" (என்று கூறுவார்கள்).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَهَلْ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">خُرُوجٍ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">سَبِيلٍ</span><br />\r\n(அப்படியானால், இதிலிருந்து வெளியேற ஏதேனும் வழி உண்டா?) அதாவது, \"எங்களை மீண்டும் உலகிற்குத் திருப்பி அனுப்ப வேண்டும் என்ற எங்கள் வேண்டுதலை ஏற்றுக்கொள்வாயா? நீ அதற்கு ஆற்றலுள்ளவன். உலகிற்குச் சென்றால், முன்பு நாங்கள் செய்த செயல்களுக்குப் பதிலாக நற்செயல்களைச் செய்வோம். மீண்டும் நாங்கள் பழைய வழிகளுக்கே திரும்பினால், நிச்சயமாக நாங்கள் அநீதியாளர்களாவோம்\" (என்று கதறுவார்கள்). அதற்கு, \"நீங்கள் மீண்டும் உலகிற்குச் செல்ல வழியே இல்லை\" என்று பதில் அளிக்கப்படும். பிறகு அதற்கான காரணம் இவ்வாறு கூறப்படும்: \"உங்கள் இயல்பு உண்மையை ஏற்று அதற்குக் கட்டுப்படாது. நீங்கள் அதை நிராகரித்து புறக்கணிப்பீர்கள்.\" அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">ذَلِكُم</span> <span class=\"quran-arabic-font text-success\">بِأَنَّهُ</span> <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">دُعِىَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">وَحْدَهُ</span> <span class=\"quran-arabic-font text-success\">كَـفَرْتُمْ</span> <span class=\"quran-arabic-font text-success\">وَإِن</span> <span class=\"quran-arabic-font text-success\">يُشْرَكْ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">تُؤْمِنُواْ</span><br />\r\n((கூறப்படும்): \"இதற்குக் காரணம், அல்லாஹ் ஒருவன் மட்டுமே (வணக்கத்திற்குரியவனாக) அழைக்கப்பட்டபோது, நீங்கள் அவனை நிராகரித்தீர்கள்; ஆனால் அவனுக்கு இணைகள் கற்பிக்கப்பட்டபோது, நீங்கள் அதை நம்பினீர்கள்!\") அதாவது, \"நீங்கள் மீண்டும் உலகிற்குத் திருப்பி அனுப்பப்பட்டாலும் இப்படியேதான் நடப்பீர்கள்.\" இது பின்வரும் வசனத்தைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَوْ</span> <span class=\"quran-arabic-font text-success\">رُدُّواْ</span> <span class=\"quran-arabic-font text-success\">لَعَـدُواْ</span> <span class=\"quran-arabic-font text-success\">لِمَا</span> <span class=\"quran-arabic-font text-success\">نُهُواْ</span> <span class=\"quran-arabic-font text-success\">عَنْهُ</span> <span class=\"quran-arabic-font text-success\">وَإِنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">لَكَـذِبُونَ</span><br />\r\n(அவர்கள் திருப்பி அனுப்பப்பட்டாலும், அவர்கள் எதை விட்டும் தடுக்கப்பட்டார்களோ, அதற்கே மீண்டும் திரும்புவார்கள். நிச்சயமாக அவர்கள் பொய்யர்கள்.) (<a href=\"qurandisp.php?sura=6&ayah=28\" class=\"link\">6:28</a>).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَالْحُكْمُ</span> <span class=\"quran-arabic-font text-success\">للَّهِ</span> <span class=\"quran-arabic-font text-success\">الْعَلِـىِّ</span> <span class=\"quran-arabic-font text-success\">الْكَبِيرِ</span><br />\r\n(எனவே தீர்ப்பு அல்லாஹ்விடமே உள்ளது, அவன் மிக உயர்ந்தவன், மிகப் பெரியவன்!) அதாவது, அவன் தன் படைப்புகளுக்குத் தீர்ப்பளிப்பவன், ஒருபோதும் அநீதி இழைக்காத நீதியாளன். அவன் நாடியவர்களுக்கு நேர்வழி காட்டுகிறான், நாடியவர்களை வழிகேட்டில் விடுகிறான்; அவன் நாடியவர்களுக்குக் கருணை காட்டுகிறான், நாடியவர்களைத் தண்டிக்கிறான்; அவனைத் தவிர வேறு இறைவன் இல்லை.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">يُرِيكُمْ</span> <span class=\"quran-arabic-font text-success\">ءَايَـتِهِ</span><br />\r\n(அவன்தான் உங்களுக்குத் தன் அடையாளங்களை (ஆயத்துகளை)க் காட்டுகிறான்) அதாவது, அவன் தன் அடியார்களுக்குத் தன் பேராற்றலை உணர்த்துகிறான். அவர்கள் வானத்திலும் பூமியிலும் காணும் மாபெரும் அடையாளங்கள், அவற்றை உருவாக்கியவனின் பரிபூரணத்துவத்தைச் சுட்டிக்காட்டுகின்றன.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَيُنَزِّلُ</span> <span class=\"quran-arabic-font text-success\">لَكُم</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">السَّمَآءِ</span> <span class=\"quran-arabic-font text-success\">رِزْقاً</span><br />\r\n(மேலும் வானத்திலிருந்து உங்களுக்காக வாழ்வாதாரத்தை இறக்குகிறான்.) இது மழையைக் குறிக்கிறது. அதன் மூலம் பல்வேறு நிறங்கள், சுவைகள், நறுமணங்கள் மற்றும் வடிவங்களைக் கொண்ட பயிர்களும் கனிகளும் உருவாகின்றன. இவை அனைத்தும் அந்தப் படைப்பாளனின் அத்தாட்சிகளாகும். பெய்யும் நீர் ஒரே வகையானதுதான், ஆனால் அல்லாஹ் தன் பேராற்றலால் அதன் மூலம் வெவ்வேறு பொருட்களை உருவாக்குகிறான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">يَتَذَكَّرُ</span><br />\r\n(மேலும் யாரும் பாடம் பெறுவதில்லை) அதாவது, எவரும் இதிலிருந்து படிப்பினை பெறுவதில்லை அல்லது இவற்றை படைப்பாளனின் வல்லமைக்கான அத்தாட்சிகளாகக் கருதுவதில்லை,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">يُنِيبُ</span><br />\r\n(முற்றிலும் அவன் பக்கமே திரும்புகிறவர்களைத் தவிர.) அதாவது, சிந்தனைத் தெளிவு பெற்று அல்லாஹ்விடம் மீண்டு வருபவர்களைத் தவிர. அவன் பாக்கியம் மிக்கவன், உயர்ந்தவன்.<br />\r\n<br />\r\n<strong>எந்தச் சூழ்நிலையிலும் அல்லாஹ்வை மட்டுமே வணங்குமாறு இறைநம்பிக்கையாளர்களுக்கு இடப்பட்ட கட்டளை</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَادْعُواْ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">مُخْلِصِينَ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">الدِّينَ</span> <span class=\"quran-arabic-font text-success\">وَلَوْ</span> <span class=\"quran-arabic-font text-success\">كَرِهَ</span> <span class=\"quran-arabic-font text-success\">الْكَـفِرُونَ</span><br />\r\n(எனவே, நிராகரிப்பாளர்கள் எவ்வளவு வெறுத்தாலும், மார்க்கத்தை அவனுக்கே தூய்மையாக்கியவர்களாக அல்லாஹ்வையே அழையுங்கள்.) இதன் பொருள், அல்லாஹ்வை மட்டுமே வணங்குங்கள், அவனிடம் மட்டுமே முழுமையான தூய்மையுடன் பிரார்த்தனை செய்யுங்கள். செயல்பாடுகளிலும் நம்பிக்கைகளிலும் இணைவைப்பவர்களைப் போல் இருக்காதீர்கள். இமாம் அஹ்மத் (ரஹ்) அவர்கள் பதிவு செய்துள்ளார்கள்: ஒவ்வொரு தொழுகையை முடித்த பிறகும், அப்துல்லாஹ் பின் அஸ்-ஸுபைர் (ரழி) அவர்கள் பின்வருமாறு கூறுவார்கள்: \"அல்லாஹ்வைத் தவிர வணக்கத்திற்குரியவன் வேறு யாருமில்லை. அவன் தனித்தவன், அவனுக்கு இணையில்லை. ஆட்சியில் அவனுக்கே அதிகாரம் உண்டு, புகழும் அவனுக்கே உரியது. அவன் அனைத்துப் பொருட்கள் மீதும் பேராற்றல் கொண்டவன். அல்லாஹ்வின் உதவியின்றி யாருக்கும் எந்த ஆற்றலோ சக்தியோ இல்லை. அல்லாஹ்வைத் தவிர வணக்கத்திற்குரியவன் யாருமில்லை. அவனைத் தவிர வேறு எவரையும் நாங்கள் வணங்குவதில்லை. அவனுக்கே அருள்களும் மேன்மைகளும் அழகிய புகழும் உரியன. அல்லாஹ்வைத் தவிர வணக்கத்திற்குரியவன் வேறு யாருமில்லை. நிராகரிப்பாளர்கள் வெறுத்த போதிலும், மார்க்கத்தை அவனுக்கே தூய்மையாக்கியவர்களாக (நாங்கள் அவனை வணங்குகிறோம்).\" \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் ஒவ்வொரு தொழுகைக்குப் பிறகும் இவ்வாறு தஹ்லீல் கூறுவார்கள்\" என்று அவர் கூறினார்கள். இதே போன்ற ஒரு அறிவிப்பு முஸ்லிம், அபூ தாவூத் மற்றும் அந்-நஸாஈ ஆகியோராலும் பதிவு செய்யப்பட்டுள்ளது. ஸஹீஹ் முஸ்லிமில் இப்னு அஸ்-ஸுபைர் (ரழி) அவர்களிடமிருந்து அறிவிக்கப்பட்டிருப்பதாவது: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கடமையான தொழுகைகளை முடித்ததும் பின்வருமாறு கூறுவார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">إِلهَ</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">وَحْدَهُ</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">شَرِيكَ</span> <span class=\"quran-arabic-font text-success\">لَهُ،</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">الْمُلْكُ</span> <span class=\"quran-arabic-font text-success\">وَلَهُ</span> <span class=\"quran-arabic-font text-success\">الْحَمْدُ،</span> <span class=\"quran-arabic-font text-success\">وَهُوَ</span> <span class=\"quran-arabic-font text-success\">عَلى</span> <span class=\"quran-arabic-font text-success\">كُلِّ</span> <span class=\"quran-arabic-font text-success\">شَيْءٍ</span> <span class=\"quran-arabic-font text-success\">قَدِيرٌ،</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">حَوْلَ</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">قُوَّةَ</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">بِاللهِ،</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">إِلهَ</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">اللهُ،</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">نَعْبُدُ</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">إِيَّاهُ،</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">النِّعْمَةُ</span> <span class=\"quran-arabic-font text-success\">وَلَهُ</span> <span class=\"quran-arabic-font text-success\">الْفَضْلُ</span> <span class=\"quran-arabic-font text-success\">وَلَهُ</span> <span class=\"quran-arabic-font text-success\">الثَّــنَاءُ</span> <span class=\"quran-arabic-font text-success\">الْحَسَنُ،</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">إِلهَ</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">مُخْلِصِينَ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">الدِّينَ</span> <span class=\"quran-arabic-font text-success\">وَلَوْ</span> <span class=\"quran-arabic-font text-success\">كَرِهَ</span> <span class=\"quran-arabic-font text-success\">الْكَافِرُون</span>»<br />\r\n(அல்லாஹ்வைத் தவிர வணக்கத்திற்குரியவன் வேறு யாருமில்லை. அவன் தனித்தவன், அவனுக்கு இணையில்லை. ஆட்சி அவனுக்கே உரியது, புகழும் அவனுக்கே உரியது. அவன் அனைத்துப் பொருட்கள் மீதும் பேராற்றல் கொண்டவன். அல்லாஹ்வின் உதவியின்றி எந்த ஆற்றலோ சக்தியோ இல்லை. அல்லாஹ்வைத் தவிர வணக்கத்திற்குரியவன் வேறு யாருமில்லை. அவனைத் தவிர வேறு எவரையும் நாங்கள் வணங்குவதில்லை. அவனுக்கே அருள்களும் மேன்மைகளும் அழகிய புகழும் உரியன. அல்லாஹ்வைத் தவிர வணக்கத்திற்குரியவன் வேறு யாருமில்லை. நிராகரிப்பாளர்கள் வெறுத்த போதிலும், மார்க்கத்தை அவனுக்கே தூய்மையாக்கியவர்களாக நாங்கள் அவனை வணங்குகிறோம்.)<br />\r\n<br />","text":"நரகில் நுழைந்த பிறகு நிராகரிப்பாளர்களின் வருத்தம்\n\r\n\n\r\nமறுமை நாளில் நிராகரிப்பாளர்கள் நரகத்தில் நுழைந்து, வேதனைமிக்க நெருப்பின் ஆழத்தில் மூழ்கும்போது வருத்தப்படுவார்கள் என்று அல்லாஹ் கூறுகிறான். அல்லாஹ்வின் தாங்க முடியாத தண்டனையை அவர்கள் அனுபவிக்கும்போது, கடந்த காலத்தில் தாங்கள் செய்த பாவங்களின் காரணமாகத் தங்களையே மிகுந்த அளவில் வெறுப்பார்கள். அந்தப் பாவங்களே அவர்கள் நரகில் நுழைவதற்குக் காரணமாயின. அந்த நேரத்தில், \"இவ்வுலகில் உங்களுக்கு ஈமான் (நம்பிக்கை) வழங்கப்பட்டபோது நீங்கள் அதை நிராகரித்தீர்கள்; அப்போது உங்கள் மீது அல்லாஹ் கொண்டிருந்த வெறுப்பானது, இப்போது உங்கள் மீது நீங்களே கொண்டிருக்கும் வெறுப்பை விடப் பெரியது\" என்று வானவர்கள் உரத்த குரலில் அவர்களிடம் கூறுவார்கள். கதாதா (ரஹ்) அவர்கள் இந்த வசனத்தைப் (ஆயத்) பற்றிக் கூறினார்கள்:\n\r\n\n\r\nلَمَقْتُ اللَّهِ أَكْبَرُ مِن مَّقْتِكُمْ أَنفُسَكُـمْ إِذْ تُدْعَوْنَ إِلَى الإِيمَـنِ فَتَكْفُرُونَ\n\r\n(நிச்சயமாக, நீங்கள் ஈமானின் பக்கம் அழைக்கப்பட்டு, அதை நிராகரித்தபோது, உங்கள் மீது நீங்கள் கொண்டிருந்த வெறுப்பை விட அல்லாஹ்வின் வெறுப்பு மிகப் பெரியதாக இருந்தது.) \"வழிகேட்டில் உள்ள மக்கள் இவ்வுலகில் ஈமானின் பக்கம் அழைக்கப்பட்டு, அதை அவர்கள் ஏற்க மறுத்துப் புறக்கணித்தபோது அல்லாஹ் அவர்கள் மீது கொண்டிருந்த வெறுப்பு, மறுமை நாளில் அல்லாஹ்வின் தண்டனையை நேரில் கண்டு அவர்கள் தங்களையே வெறுப்பதை விடப் பெரியது\" (என்று கதாதா (ரஹ்) கூறினார்கள்). இதுவே அல்-ஹஸன் அல்-பஸரி, முஜாஹித், அஸ்-ஸுத்தி, தர்ர் பின் அப்துல்லாஹ் அல்-ஹம்தானி, அப்துர்-ரஹ்மான் பின் ஸைத் பின் அஸ்லம் மற்றும் இப்னு ஜரீர் அத்-தபரி (ரஹ்மதுல்லாஹி அலைஹிம்) ஆகியோரின் கருத்தாகவும் இருந்தது. அல்லாஹ் அவர்கள் அனைவர் மீதும் கருணை புரிவானாக.\n\r\n\n\r\nقَالُواْ رَبَّنَآ أَمَتَّنَا اثْنَتَيْنِ وَأَحْيَيْتَنَا اثْنَتَيْنِ\n\r\n(அவர்கள் கூறுவார்கள்: \"எங்கள் இறைவனே! நீ எங்களுக்கு இரண்டு முறை மரணத்தைத் தந்தாய், எங்களுக்கு இரண்டு முறை வாழ்வையும் தந்தாய்!...\") இப்னு மஸ்ஊத் (ரழி) அவர்களிடமிருந்து அபூ அல்-அஹ்வஸ், அவரிடமிருந்து அபூ இஸ்ஹாக், அவரிடமிருந்து அத்-தவ்ரி ஆகியோர் அறிவிக்கிறார்கள்: \"இந்த வசனம் (ஆயத்) பின்வரும் வசனத்தைப் போன்றது:\n\r\n\n\r\nكَيْفَ تَكْفُرُونَ بِاللَّهِ وَكُنتُمْ أَمْوَتًا فَأَحْيَـكُمْ ثُمَّ يُمِيتُكُمْ ثُمَّ يُحْيِيكُمْ ثُمَّ إِلَيْهِ تُرْجَعُونَ\n\r\n(நீங்கள் உயிரற்றவர்களாக இருந்த நிலையில் அல்லாஹ்வை எப்படி நிராகரிக்கிறீர்கள்? அவன்தான் உங்களுக்கு உயிர் கொடுத்தான். பிறகு அவன் உங்களை மரணிக்கச் செய்வான், பிறகு மீண்டும் உங்களை உயிர்ப்பிப்பான், பிறகு அவனிடமே நீங்கள் திரும்பக் கொண்டுவரப்படுவீர்கள்.)\" (2:28). இது இப்னு அப்பாஸ் (ரழி), அத்-தஹ்ஹாக், கதாதா (ரஹ்) மற்றும் அபூ மாலிக் ஆகியோரின் கருத்தாகவும் இருந்தது. இதுவே சந்தேகத்திற்கு இடமின்றி சரியான கருத்தாகும்.\n\r\n\n\r\nஇதன் மூலம் கூறப்படுவது என்னவென்றால், மறுமை நாளில் விசாரணைக்காக அல்லாஹ்வின் முன்னால் நிற்கும்போது, நிராகரிப்பாளர்கள் மீண்டும் உலகிற்குத் திரும்பிச் செல்ல அனுமதி கோருவார்கள். அல்லாஹ் கூறுவது போல:\n\r\n\n\r\nوَلَوْ تَرَى إِذِ الْمُجْرِمُونَ نَاكِسُواْ رُءُوسِهِمْ عِندَ رَبِّهِمْ رَبَّنَآ أَبْصَرْنَا وَسَمِعْنَا فَارْجِعْنَا نَعْمَلْ صَـلِحاً إِنَّا مُوقِنُونَ\n\r\n(குற்றவாளிகள் தங்கள் இறைவன் முன் தலைகுனிந்து நின்று, \"எங்கள் இறைவனே! நாங்கள் இப்போது பார்த்துவிட்டோம், கேட்டுவிட்டோம். எனவே, எங்களைத் திருப்பி அனுப்புவாயாக, நாங்கள் நற்செயல்களைச் செய்வோம். நிச்சயமாக, நாங்கள் இப்போது உறுதியாக நம்புகிறோம்\" என்று கூறுவதை நீங்கள் கண்டால்!) (32:12). எனினும், அவர்களுக்கு எந்தப் பதிலும் அளிக்கப்படாது. பிறகு அவர்கள் நரக நெருப்பைக் கண்டு, அதன் விளிம்பில் நிறுத்தப்பட்டு, அங்கிருக்கும் தண்டனைகளைப் பார்க்கும்போது, முன்பை விட அதிக ஆவலுடன் உலகிற்குத் திரும்பக் கோருவார்கள். அப்போதும் அவர்களுக்கு எந்தப் பதிலும் கிடைக்காது. அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَلَوْ تَرَى إِذْ وُقِفُواْ عَلَى النَّارِ فَقَالُواْ يلَيْتَنَا نُرَدُّ وَلاَ نُكَذِّبَ بِـَايَـتِ رَبِّنَا وَنَكُونَ مِنَ الْمُؤْمِنِينَ - بَلْ بَدَا لَهُمْ مَّا كَانُواْ يُخْفُونَ مِن قَبْلُ وَلَوْ رُدُّواْ لَعَـدُواْ لِمَا نُهُواْ عَنْهُ وَإِنَّهُمْ لَكَـذِبُونَ\n\r\n(அவர்கள் (நரக) நெருப்பின் முன் நிறுத்தப்படும்போது நீங்கள் அவர்களைக் கண்டால்! \"நாங்கள் (உலகிற்குத்) திருப்பி அனுப்பப்பட்டால் எவ்வளவு நன்றாக இருக்கும்! அப்போது நாங்கள் எங்கள் இறைவனின் வசனங்களை (ஆயத்துகளை) நிராகரிக்க மாட்டோம், மேலும் நாங்கள் நம்பிக்கையாளர்களில் ஒருவராக இருப்போம்\" என்று அவர்கள் கூறுவார்கள். அவ்வாறல்ல, அவர்கள் முன்பு மறைத்து வைத்திருந்தது அவர்களுக்கு வெளியாகிவிட்டது. அவர்கள் திருப்பி அனுப்பப்பட்டாலும், அவர்கள் எதை விட்டும் தடுக்கப்பட்டார்களோ, அதற்கே மீண்டும் திரும்புவார்கள். நிச்சயமாக அவர்கள் பொய்யர்கள்.) (6:27-28).\n\r\n\n\r\nஅவர்கள் உண்மையில் நரகத்தில் நுழைந்து அதன் வெப்பத்தையும், இரும்புக் கொக்கிகளையும், சங்கிலிகளையும் அனுபவிக்கும்போது, உலகிற்குத் திரும்ப வேண்டும் என்ற அவர்களின் வேண்டுகோள் மிகவும் தீவிரமானதாகவும் கதறலாகவும் இருக்கும்:\n\r\n\n\r\nوَهُمْ يَصْطَرِخُونَ فِيهَا رَبَّنَآ أَخْرِجْنَا نَعْمَلْ صَـلِحاً غَيْرَ الَّذِى كُـنَّا نَعْمَلُ أَوَلَمْ نُعَمِّرْكُمْ مَّا يَتَذَكَّرُ فِيهِ مَن تَذَكَّرَ وَجَآءَكُمُ النَّذِيرُ فَذُوقُواْ فَمَا لِلظَّـلِمِينَ مِن نَّصِيرٍ\n\r\n(அதில் அவர்கள் கதறுவார்கள்: \"எங்கள் இறைவனே! எங்களை வெளியேற்றுவாயாக, நாங்கள் முன்பு செய்து கொண்டிருந்த செயல்களுக்கு மாறாக நற்செயல்களைச் செய்வோம்.\" (அதற்கு அல்லாஹ்), \"உசாவுபவர் பாடம் பெறுவதற்குப் போதுமான கால அவகாசத்தை நாம் உங்களுக்கு வழங்கவில்லையா? உங்களிடம் எச்சரிப்பவரும் வந்தாரே! எனவே, வேதனையைச் சுவையுங்கள். அநீதி இழைத்தவர்களுக்கு எந்த உதவியாளரும் இல்லை\" (என்று பதிலளிப்பான்).) (35:37)\n\r\n\n\r\nرَبَّنَآ أَخْرِجْنَا مِنْهَا فَإِنْ عُدْنَا فَإِنَّا ظَـلِمُونَ - قَالَ اخْسَئُواْ فِيهَا وَلاَ تُكَلِّمُونِ\n\r\n(\"எங்கள் இறைவனே! எங்களை இதிலிருந்து வெளியேற்றுவாயாக. நாங்கள் மீண்டும் (பாவத்திற்குத்) திரும்பினால், நிச்சயமாக நாங்கள் அநீதியாளர்களாகி விடுவோம்.\" அதற்கு அவன் (அல்லாஹ்), \"இழிவடைந்த நிலையில் அங்கேயே இருங்கள்! என்னிடம் பேசாதீர்கள்\" என்று கூறுவான்.) (23:107-108).\n\r\n\n\r\nஇந்த வசனத்தின்படி, அவர்கள் மிகவும் கெஞ்சிக் கூத்தாடி, பின்வரும் வார்த்தைகளுடன் தங்கள் வேண்டுகோளைத் தொடங்குவார்கள்:\n\r\n\n\r\nرَبَّنَآ أَمَتَّنَا اثْنَتَيْنِ وَأَحْيَيْتَنَا اثْنَتَيْنِ فَاعْتَرَفْنَا بِذُنُوبِنَا\n\r\n(எங்கள் இறைவனே! நீ எங்களுக்கு இரண்டு முறை மரணத்தைத் தந்தாய், எங்களுக்கு இரண்டு முறை வாழ்வையும் தந்தாய்! எனவே, நாங்கள் எங்கள் பாவங்களை ஒப்புக்கொள்கிறோம்.) அதாவது, \"உனது பேராற்றலால், நாங்கள் மரணித்திருந்த நிலையில் எங்களுக்கு உயிர் கொடுத்தாய், பிறகு உயிருடன் இருந்த நிலையில் எங்களை மரணிக்கச் செய்தாய்; நீ நாடியதைச் செய்ய ஆற்றலுள்ளவன். நாங்கள் எங்கள் பாவங்களை ஒப்புக்கொள்கிறோம், இவ்வுலகில் எங்களுக்கே அநீதி இழைத்துக் கொண்டோம் என்பதை ஏற்றுக்கொள்கிறோம்\" (என்று கூறுவார்கள்).\n\r\n\n\r\nفَهَلْ إِلَى خُرُوجٍ مِّن سَبِيلٍ\n\r\n(அப்படியானால், இதிலிருந்து வெளியேற ஏதேனும் வழி உண்டா?) அதாவது, \"எங்களை மீண்டும் உலகிற்குத் திருப்பி அனுப்ப வேண்டும் என்ற எங்கள் வேண்டுதலை ஏற்றுக்கொள்வாயா? நீ அதற்கு ஆற்றலுள்ளவன். உலகிற்குச் சென்றால், முன்பு நாங்கள் செய்த செயல்களுக்குப் பதிலாக நற்செயல்களைச் செய்வோம். மீண்டும் நாங்கள் பழைய வழிகளுக்கே திரும்பினால், நிச்சயமாக நாங்கள் அநீதியாளர்களாவோம்\" (என்று கதறுவார்கள்). அதற்கு, \"நீங்கள் மீண்டும் உலகிற்குச் செல்ல வழியே இல்லை\" என்று பதில் அளிக்கப்படும். பிறகு அதற்கான காரணம் இவ்வாறு கூறப்படும்: \"உங்கள் இயல்பு உண்மையை ஏற்று அதற்குக் கட்டுப்படாது. நீங்கள் அதை நிராகரித்து புறக்கணிப்பீர்கள்.\" அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nذَلِكُم بِأَنَّهُ إِذَا دُعِىَ اللَّهُ وَحْدَهُ كَـفَرْتُمْ وَإِن يُشْرَكْ بِهِ تُؤْمِنُواْ\n\r\n((கூறப்படும்): \"இதற்குக் காரணம், அல்லாஹ் ஒருவன் மட்டுமே (வணக்கத்திற்குரியவனாக) அழைக்கப்பட்டபோது, நீங்கள் அவனை நிராகரித்தீர்கள்; ஆனால் அவனுக்கு இணைகள் கற்பிக்கப்பட்டபோது, நீங்கள் அதை நம்பினீர்கள்!\") அதாவது, \"நீங்கள் மீண்டும் உலகிற்குத் திருப்பி அனுப்பப்பட்டாலும் இப்படியேதான் நடப்பீர்கள்.\" இது பின்வரும் வசனத்தைப் போன்றது:\n\r\n\n\r\nوَلَوْ رُدُّواْ لَعَـدُواْ لِمَا نُهُواْ عَنْهُ وَإِنَّهُمْ لَكَـذِبُونَ\n\r\n(அவர்கள் திருப்பி அனுப்பப்பட்டாலும், அவர்கள் எதை விட்டும் தடுக்கப்பட்டார்களோ, அதற்கே மீண்டும் திரும்புவார்கள். நிச்சயமாக அவர்கள் பொய்யர்கள்.) (6:28).\n\r\n\n\r\nفَالْحُكْمُ للَّهِ الْعَلِـىِّ الْكَبِيرِ\n\r\n(எனவே தீர்ப்பு அல்லாஹ்விடமே உள்ளது, அவன் மிக உயர்ந்தவன், மிகப் பெரியவன்!) அதாவது, அவன் தன் படைப்புகளுக்குத் தீர்ப்பளிப்பவன், ஒருபோதும் அநீதி இழைக்காத நீதியாளன். அவன் நாடியவர்களுக்கு நேர்வழி காட்டுகிறான், நாடியவர்களை வழிகேட்டில் விடுகிறான்; அவன் நாடியவர்களுக்குக் கருணை காட்டுகிறான், நாடியவர்களைத் தண்டிக்கிறான்; அவனைத் தவிர வேறு இறைவன் இல்லை.\n\r\n\n\r\nهُوَ الَّذِى يُرِيكُمْ ءَايَـتِهِ\n\r\n(அவன்தான் உங்களுக்குத் தன் அடையாளங்களை (ஆயத்துகளை)க் காட்டுகிறான்) அதாவது, அவன் தன் அடியார்களுக்குத் தன் பேராற்றலை உணர்த்துகிறான். அவர்கள் வானத்திலும் பூமியிலும் காணும் மாபெரும் அடையாளங்கள், அவற்றை உருவாக்கியவனின் பரிபூரணத்துவத்தைச் சுட்டிக்காட்டுகின்றன.\n\r\n\n\r\nوَيُنَزِّلُ لَكُم مِّنَ السَّمَآءِ رِزْقاً\n\r\n(மேலும் வானத்திலிருந்து உங்களுக்காக வாழ்வாதாரத்தை இறக்குகிறான்.) இது மழையைக் குறிக்கிறது. அதன் மூலம் பல்வேறு நிறங்கள், சுவைகள், நறுமணங்கள் மற்றும் வடிவங்களைக் கொண்ட பயிர்களும் கனிகளும் உருவாகின்றன. இவை அனைத்தும் அந்தப் படைப்பாளனின் அத்தாட்சிகளாகும். பெய்யும் நீர் ஒரே வகையானதுதான், ஆனால் அல்லாஹ் தன் பேராற்றலால் அதன் மூலம் வெவ்வேறு பொருட்களை உருவாக்குகிறான்.\n\r\n\n\r\nوَمَا يَتَذَكَّرُ\n\r\n(மேலும் யாரும் பாடம் பெறுவதில்லை) அதாவது, எவரும் இதிலிருந்து படிப்பினை பெறுவதில்லை அல்லது இவற்றை படைப்பாளனின் வல்லமைக்கான அத்தாட்சிகளாகக் கருதுவதில்லை,\n\r\n\n\r\nإِلاَّ مَن يُنِيبُ\n\r\n(முற்றிலும் அவன் பக்கமே திரும்புகிறவர்களைத் தவிர.) அதாவது, சிந்தனைத் தெளிவு பெற்று அல்லாஹ்விடம் மீண்டு வருபவர்களைத் தவிர. அவன் பாக்கியம் மிக்கவன், உயர்ந்தவன்.\n\r\n\n\r\nஎந்தச் சூழ்நிலையிலும் அல்லாஹ்வை மட்டுமே வணங்குமாறு இறைநம்பிக்கையாளர்களுக்கு இடப்பட்ட கட்டளை\n\r\n\n\r\nفَادْعُواْ اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ وَلَوْ كَرِهَ الْكَـفِرُونَ\n\r\n(எனவே, நிராகரிப்பாளர்கள் எவ்வளவு வெறுத்தாலும், மார்க்கத்தை அவனுக்கே தூய்மையாக்கியவர்களாக அல்லாஹ்வையே அழையுங்கள்.) இதன் பொருள், அல்லாஹ்வை மட்டுமே வணங்குங்கள், அவனிடம் மட்டுமே முழுமையான தூய்மையுடன் பிரார்த்தனை செய்யுங்கள். செயல்பாடுகளிலும் நம்பிக்கைகளிலும் இணைவைப்பவர்களைப் போல் இருக்காதீர்கள். இமாம் அஹ்மத் (ரஹ்) அவர்கள் பதிவு செய்துள்ளார்கள்: ஒவ்வொரு தொழுகையை முடித்த பிறகும், அப்துல்லாஹ் பின் அஸ்-ஸுபைர் (ரழி) அவர்கள் பின்வருமாறு கூறுவார்கள்: \"அல்லாஹ்வைத் தவிர வணக்கத்திற்குரியவன் வேறு யாருமில்லை. அவன் தனித்தவன், அவனுக்கு இணையில்லை. ஆட்சியில் அவனுக்கே அதிகாரம் உண்டு, புகழும் அவனுக்கே உரியது. அவன் அனைத்துப் பொருட்கள் மீதும் பேராற்றல் கொண்டவன். அல்லாஹ்வின் உதவியின்றி யாருக்கும் எந்த ஆற்றலோ சக்தியோ இல்லை. அல்லாஹ்வைத் தவிர வணக்கத்திற்குரியவன் யாருமில்லை. அவனைத் தவிர வேறு எவரையும் நாங்கள் வணங்குவதில்லை. அவனுக்கே அருள்களும் மேன்மைகளும் அழகிய புகழும் உரியன. அல்லாஹ்வைத் தவிர வணக்கத்திற்குரியவன் வேறு யாருமில்லை. நிராகரிப்பாளர்கள் வெறுத்த போதிலும், மார்க்கத்தை அவனுக்கே தூய்மையாக்கியவர்களாக (நாங்கள் அவனை வணங்குகிறோம்).\" \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் ஒவ்வொரு தொழுகைக்குப் பிறகும் இவ்வாறு தஹ்லீல் கூறுவார்கள்\" என்று அவர் கூறினார்கள். இதே போன்ற ஒரு அறிவிப்பு முஸ்லிம், அபூ தாவூத் மற்றும் அந்-நஸாஈ ஆகியோராலும் பதிவு செய்யப்பட்டுள்ளது. ஸஹீஹ் முஸ்லிமில் இப்னு அஸ்-ஸுபைர் (ரழி) அவர்களிடமிருந்து அறிவிக்கப்பட்டிருப்பதாவது: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கடமையான தொழுகைகளை முடித்ததும் பின்வருமாறு கூறுவார்கள்:\n\r\n\n\r\n«لَا إِلهَ إِلَّا اللهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلى كُلِّ شَيْءٍ قَدِيرٌ، لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللهِ، لَا إِلهَ إِلَّا اللهُ، وَلَا نَعْبُدُ إِلَّا إِيَّاهُ، لَهُ النِّعْمَةُ وَلَهُ الْفَضْلُ وَلَهُ الثَّــنَاءُ الْحَسَنُ، لَا إِلهَ إِلَّا اللهُ مُخْلِصِينَ لَهُ الدِّينَ وَلَوْ كَرِهَ الْكَافِرُون»\n\r\n(அல்லாஹ்வைத் தவிர வணக்கத்திற்குரியவன் வேறு யாருமில்லை. அவன் தனித்தவன், அவனுக்கு இணையில்லை. ஆட்சி அவனுக்கே உரியது, புகழும் அவனுக்கே உரியது. அவன் அனைத்துப் பொருட்கள் மீதும் பேராற்றல் கொண்டவன். அல்லாஹ்வின் உதவியின்றி எந்த ஆற்றலோ சக்தியோ இல்லை. அல்லாஹ்வைத் தவிர வணக்கத்திற்குரியவன் வேறு யாருமில்லை. அவனைத் தவிர வேறு எவரையும் நாங்கள் வணங்குவதில்லை. அவனுக்கே அருள்களும் மேன்மைகளும் அழகிய புகழும் உரியன. அல்லாஹ்வைத் தவிர வணக்கத்திற்குரியவன் வேறு யாருமில்லை. நிராகரிப்பாளர்கள் வெறுத்த போதிலும், மார்க்கத்தை அவனுக்கே தூய்மையாக்கியவர்களாக நாங்கள் அவனை வணங்குகிறோம்.)"},"15":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=40&ayah=17\" class=\"link\">40:17</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 40:17 ஐ பார்க்கவும்"},"16":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=40&ayah=17\" class=\"link\">40:17</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 40:17 ஐ பார்க்கவும்"},"17":{"html":"<strong>சந்திப்பு நாளைப் பற்றித் தன் அடியார்களை எச்சரிப்பதற்காக அல்லாஹ் வஹீயை (இறைச்செய்தியை) அனுப்புகிறான்</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">رَفِيعُ</span> <span class=\"quran-arabic-font text-success\">الدَّرَجَاتِ</span> <span class=\"quran-arabic-font text-success\">ذُو</span> <span class=\"quran-arabic-font text-success\">الْعَرْشِ</span><br />\r\n<br />\r\n(அவன்) உயர் பதவிகளை உடையவன்; அர்ஷுக்குச் சொந்தக்காரன்.<br />\r\n<br />\r\nஅல்லாஹ் தனது வல்லமையையும் பெருமையையும் பற்றியும், அவனது மகத்தான அர்ஷ் ஒரு கூரையைப் போல அவனது படைப்புகள் அனைத்திற்கும் மேலாக உயர்த்தப்பட்டுள்ளது என்பதைப் பற்றியும் நமக்குக் கூறுகிறான். இது பின்வரும் வசனத்தைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">ذِي</span> <span class=\"quran-arabic-font text-success\">الْمَعَارِجِ</span> - <span class=\"quran-arabic-font text-success\">تَعْرُجُ</span> <span class=\"quran-arabic-font text-success\">الْمَلَائِكَةُ</span> <span class=\"quran-arabic-font text-success\">وَالرُّوحُ</span> <span class=\"quran-arabic-font text-success\">إِلَيْهِ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">يَوْمٍ</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">مِقْدَارُهُ</span> <span class=\"quran-arabic-font text-success\">خَمْسِينَ</span> <span class=\"quran-arabic-font text-success\">أَلْفَ</span> <span class=\"quran-arabic-font text-success\">سَنَةٍ</span><br />\r\n<br />\r\n(உயர்வழிகளின் உரிமையாளனான அல்லாஹ்விடமிருந்து (அது கிடைக்கிறது). வானவர்களும் ரூஹும் (ஜிப்ரீல் அலை) ஐம்பதாயிரம் ஆண்டுகள் அளவுள்ள ஒரு நாளில் அவன்பால் ஏறிச் செல்வார்கள்.) (<a href=\"qurandisp.php?sura=70&ayah=3\" class=\"link\">70:3</a>-4). அல்லாஹ் நாடினால், அர்ஷுக்கும் ஏழாவது பூமிக்கும் இடைப்பட்ட தூரம் குறித்து முந்தைய மற்றும் பிந்தைய அறிஞர்கள் கூறும் மிகவும் சரியான கருத்து எது என்பதைப் பற்றி கீழே விவாதிப்போம். அர்ஷ் சிவப்பு மாணிக்கங்களால் ஆனது என்று ஒன்றுக்கும் மேற்பட்ட அறிஞர்கள் கூறியுள்ளனர். அதன் இரண்டு மூலைகளுக்கு இடைப்பட்ட அகலம் ஐம்பதாயிரம் ஆண்டு காலப் பயண தூரமாகும்; ஏழாவது பூமிக்கு மேல் அதன் உயரம் ஐம்பதாயிரம் ஆண்டு காலப் பயண தூரமாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يُلْقِى</span> <span class=\"quran-arabic-font text-success\">الرُّوحَ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">أَمْرِهِ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">يَشَآءُ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">عِبَادِهِ</span><br />\r\n<br />\r\n(அவன் தனது அடியார்களில் தான் நாடியவர் மீது தனது கட்டளையின் மூலம் வஹீயை (இறைச்செய்தியை) இறக்குகிறான்.) இது பின்வரும் வசனங்களைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يُنَزِّلُ</span> <span class=\"quran-arabic-font text-success\">الْمَلَائِكَةَ</span> <span class=\"quran-arabic-font text-success\">بِالرُّوحِ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">أَمْرِهِ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">يَشَآءُ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">عِبَادِهِ</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">أَنْذِرُواْ</span> <span class=\"quran-arabic-font text-success\">أَنَّهُ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">إِلَـهَ</span> <span class=\"quran-arabic-font text-success\">إِلاَ</span> <span class=\"quran-arabic-font text-success\">أَنَاْ</span> <span class=\"quran-arabic-font text-success\">فَاتَّقُونِ</span><br />\r\n<br />\r\n(\"என்னைத் தவிர வேறு இறைவனில்லை; எனவே எனக்கே அஞ்சுங்கள் என்று எச்சரிக்கை செய்யுங்கள்\" என்று கூறி, தனது அடியார்களில் தான் நாடியவர் மீது தனது கட்டளையின் மூலம் ரூஹுடன் (வஹீயுடன்) வானவர்களை அவன் இறக்குகிறான்.) (<a href=\"qurandisp.php?sura=16&ayah=2\" class=\"link\">16:2</a>), மேலும்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَإِنَّهُ</span> <span class=\"quran-arabic-font text-success\">لَتَنزِيلُ</span> <span class=\"quran-arabic-font text-success\">رَبِّ</span> <span class=\"quran-arabic-font text-success\">الْعَالَمِينَ</span> - <span class=\"quran-arabic-font text-success\">نَزَلَ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">الرُّوحُ</span> <span class=\"quran-arabic-font text-success\">الْأَمِينُ</span> - <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">قَلْبِكَ</span> <span class=\"quran-arabic-font text-success\">لِتَكُونَ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْمُنْذِرِينَ</span><br />\r\n<br />\r\n(நிச்சயமாக இது அகிலங்களின் இறைவனால் இறக்கப்பட்டதாகும். இதனை நம்பிக்கைக்குரிய ரூஹ் (ஜிப்ரீல் அலை) உம்முடைய இதயத்தில் இறக்கினார்; நீர் எச்சரிப்பவர்களில் ஒருவராக இருப்பதற்காக.) (<a href=\"qurandisp.php?sura=26&ayah=192\" class=\"link\">26:192</a>-194). அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لِيُنذِرَ</span> <span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">التَّلاَقِ</span><br />\r\n<br />\r\n(அவர் (மக்களை) சந்திப்பு நாளைப் பற்றி எச்சரிப்பதற்காக.) 'சந்திப்பு நாள்' (யவ்முத் தலாக்) என்பது மறுமை நாளின் பெயர்களில் ஒன்று என்றும், அதைக் கொண்டே அல்லாஹ் தனது அடியார்களை எச்சரிக்கிறான் என்றும் இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாக அலீ பின் அபீ தல்ஹா (ரழி) அவர்கள் அறிவிக்கிறார்கள். அந்த நாளில்தான் ஒவ்வொருவரும் தங்களது நன்மையான மற்றும் தீமையான செயல்களைப் பற்றித் தெரிந்துகொள்வார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">هُم</span> <span class=\"quran-arabic-font text-success\">بَارِزُونَ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَخْفَى</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">مِنْهُمْ</span> <span class=\"quran-arabic-font text-success\">شَىْءٌ</span><br />\r\n<br />\r\n(அவர்கள் வெளிப்படும் நாளில், அவர்களிடமிருந்து எதுவும் அல்லாஹ்வுக்கு மறைந்திருக்காது.) அதாவது, அவர்களுக்குப் புகலிடமோ, நிழலோ அல்லது மறைப்போ எதுவுமின்றி அவர்கள் அனைவரும் திறந்த வெளியில் தோன்றுவார்கள் என்று பொருள். அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">هُم</span> <span class=\"quran-arabic-font text-success\">بَارِزُونَ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَخْفَى</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">مِنْهُمْ</span> <span class=\"quran-arabic-font text-success\">شَىْءٌ</span><br />\r\n<br />\r\n(அவர்கள் வெளிப்படும் நாளில், அவர்களிடமிருந்து எதுவும் அல்லாஹ்வுக்கு மறைந்திருக்காது.) அதாவது, அனைத்தும் அவனுக்குத் சமமாக (தெளிவாகத்) தெரிந்திருக்கும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لِّمَنِ</span> <span class=\"quran-arabic-font text-success\">الْمُلْكُ</span> <span class=\"quran-arabic-font text-success\">الْيَوْمَ</span> <span class=\"quran-arabic-font text-success\">لِلَّهِ</span> <span class=\"quran-arabic-font text-success\">الْوَاحِدِ</span> <span class=\"quran-arabic-font text-success\">الْقَهَّارِ</span><br />\r\n<br />\r\n(இன்றைய நாளில் ஆட்சி யாருடையது? ஏகனும் அடக்கி ஆள்பவனுமான அல்லாஹ்வுக்கே உரியது!) அல்லாஹ் வானங்களையும் பூமியையும் தனது கையில் சுருட்டிக்கொண்டு:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">أَنَا</span> <span class=\"quran-arabic-font text-success\">الْمَلِكُ،</span> <span class=\"quran-arabic-font text-success\">أَنَا</span> <span class=\"quran-arabic-font text-success\">الْجَبَّارُ،</span> <span class=\"quran-arabic-font text-success\">أَنَا</span> <span class=\"quran-arabic-font text-success\">الْمُتَكَبِّرُ،</span> <span class=\"quran-arabic-font text-success\">أَيْنَ</span> <span class=\"quran-arabic-font text-success\">مُلُوكُ</span> <span class=\"quran-arabic-font text-success\">الْأَرْضِ؟</span> <span class=\"quran-arabic-font text-success\">أَيْنَ</span> <span class=\"quran-arabic-font text-success\">الْجَبَّارُونَ؟</span> <span class=\"quran-arabic-font text-success\">أَيْنَ</span> <span class=\"quran-arabic-font text-success\">الْمُتَكَبِّرُونَ؟</span>»<br />\r\n<br />\r\n(\"நானே அரசன், நானே அடக்குபவன், நானே பெருமைக்குரியவன்; பூமியின் அரசர்கள் எங்கே? அக்கிரமக்காரர்கள் எங்கே? பெருமையடித்தவர்கள் எங்கே?\") என்று கூறுவான் என இப்னு உமர் (ரழி) அவர்கள் வாயிலாக வரும் ஹதீஸை நாம் ஏற்கனவே குறிப்பிட்டுள்ளோம்.<br />\r\n<br />\r\nஸூர் (எக்காளம்) பற்றிய ஹதீஸில், அல்லாஹ் தனது படைப்புகள் அனைத்தின் ஆன்மாக்களையும் கைப்பற்றுவான் என்றும், அவனுடன் கூட்டாளிகளோ துணைகளோ இன்றி அவன் மட்டுமே தனித்திருப்பான் என்றும் கூறப்பட்டுள்ளது. பிறகு அவன், \"இன்றைய நாளில் ஆட்சி யாருடையது?\" என்று மூன்று முறை கேட்பான். பிறகு அவனே அதற்குப் பதிலளிப்பான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لِلَّهِ</span> <span class=\"quran-arabic-font text-success\">الْوَاحِدِ</span> <span class=\"quran-arabic-font text-success\">الْقَهَّارِ</span><br />\r\n<br />\r\n(ஏகனும் அடக்கி ஆள்பவனுமான அல்லாஹ்வுக்கே உரியது!) அதாவது, அனைத்தையும் அடக்கி ஆள்பவன் அவன் ஒருவன் மட்டுமே.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">الْيَوْمَ</span> <span class=\"quran-arabic-font text-success\">تُجْزَى</span> <span class=\"quran-arabic-font text-success\">كُلُّ</span> <span class=\"quran-arabic-font text-success\">نَفْسٍ</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">كَسَبَتْ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">ظُلْمَ</span> <span class=\"quran-arabic-font text-success\">الْيَوْمَ</span> <span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">سَرِيعُ</span> <span class=\"quran-arabic-font text-success\">الْحِسَابِ</span><br />\r\n<br />\r\n(இன்று ஒவ்வொரு ஆத்மாவுக்கும் அது சம்பாதித்ததற்குக் கூலி கொடுக்கப்படும். இன்று அநீதி எதுவுமில்லை; நிச்சயமாக அல்லாஹ் கணக்கெடுப்பதில் மிக விரைவானவன்.) தனது படைப்புகளுக்கு இடையே தீர்ப்பளிக்கும்போது அல்லாஹ் கடைபிடிக்கும் நீதியைப் பற்றி இங்கே அவன் கூறுகிறான்; நன்மையாக இருந்தாலும் சரி, தீமையாக இருந்தாலும் சரி, ஓர் அணுவளவு கூட அவன் அநீதி இழைக்க மாட்டான். ஒவ்வொரு நற்செயலுக்கும் பத்து மடங்கு நற்கூலியும், ஒவ்வொரு தீமைக்கும் அதற்குச் சமமான தண்டனையுமே வழங்குகிறான். அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">ظُلْمَ</span> <span class=\"quran-arabic-font text-success\">الْيَوْمَ</span><br />\r\n<br />\r\n(இன்று அநீதி எதுவுமில்லை.) ஸஹீஹ் முஸ்லிமில் அபூ தர் (ரழி) அவர்கள் வாயிலாக அறிவிக்கப்பட்டுள்ள ஒரு ஹதீஸில், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் அல்லாஹ் பின்வருமாறு கூறியதாகக் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">عِبَادِي</span> <span class=\"quran-arabic-font text-success\">إِنِّي</span> <span class=\"quran-arabic-font text-success\">حَرَّمْتُ</span> <span class=\"quran-arabic-font text-success\">الظُّلْمَ</span> <span class=\"quran-arabic-font text-success\">عَلى</span> <span class=\"quran-arabic-font text-success\">نَفْسِي</span> <span class=\"quran-arabic-font text-success\">وَجَعَلْتُهُ</span> <span class=\"quran-arabic-font text-success\">بَيْنَكُمْ</span> <span class=\"quran-arabic-font text-success\">مُحَرَّمًا</span> <span class=\"quran-arabic-font text-success\">فَلَا</span> <span class=\"quran-arabic-font text-success\">تَظَالَمُوا</span> <span class=\"quran-arabic-font text-success\">إلى</span> <span class=\"quran-arabic-font text-success\">أن</span> <span class=\"quran-arabic-font text-success\">قال</span> <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">عِبَادِي</span> <span class=\"quran-arabic-font text-success\">إِنَّمَا</span> <span class=\"quran-arabic-font text-success\">هِيَ</span> <span class=\"quran-arabic-font text-success\">أَعْمَالُكُمْ</span> <span class=\"quran-arabic-font text-success\">أُحْصِيهَا</span> <span class=\"quran-arabic-font text-success\">عَلَيْكُمْ</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">أُوَفِّيكُمْ</span> <span class=\"quran-arabic-font text-success\">إِيَّاهَا،</span> <span class=\"quran-arabic-font text-success\">فَمَنْ</span> <span class=\"quran-arabic-font text-success\">وَجَدَ</span> <span class=\"quran-arabic-font text-success\">خَيْرًا</span> <span class=\"quran-arabic-font text-success\">فَلْيَحْمَدِ</span> <span class=\"quran-arabic-font text-success\">اللهَ</span> <span class=\"quran-arabic-font text-success\">تَبَارَكَ</span> <span class=\"quran-arabic-font text-success\">وَتَعَالَى،</span> <span class=\"quran-arabic-font text-success\">وَمَنْ</span> <span class=\"quran-arabic-font text-success\">وَجَدَ</span> <span class=\"quran-arabic-font text-success\">غَيْرَ</span> <span class=\"quran-arabic-font text-success\">ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">فَلَا</span> <span class=\"quran-arabic-font text-success\">يَلُومَنَّ</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">نَفْسَه</span>»<br />\r\n<br />\r\n(\"எனது அடியார்களே! அநீதியை எனக்கு நானே தடுத்துக்கொண்டேன்; அதை உங்களுக்கிடையிலும் தடுக்கப்பட்டதாக ஆக்கிவிட்டேன். எனவே ஒருவருக்கொருவர் அநீதி இழைக்காதீர்கள்...\" மேலும் கூறினான்: \"எனது அடியார்களே! இவை உங்கள் செயல்களே; இவற்றை நான் உங்களுக்காகக் கணக்கிடுகிறேன். பிறகு அவற்றுக்கான கூலியை உங்களுக்கு முழுமையாக வழங்குவேன். எனவே நன்மையைக் காண்பவர் அல்லாஹ்வைப் புகழட்டும்; அது அல்லாத வேறு எதையேனும் காண்பவர் தன்னைத் தவிர வேறு யாரையும் குறை கூற வேண்டாம்.\")<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">سَرِيعُ</span> <span class=\"quran-arabic-font text-success\">الْحِسَابِ</span><br />\r\n<br />\r\n(நிச்சயமாக அல்லாஹ் கணக்கெடுப்பதில் மிக விரைவானவன்.) அதாவது, அவன் தனது படைப்புகள் அனைத்தையும் ஒரே ஒரு நபரிடம் கணக்கெடுப்பதைப் போல மிக எளிதாகக் கணக்கெடுப்பான். இது பின்வரும் வசனத்தைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مَّا</span> <span class=\"quran-arabic-font text-success\">خَلْقُكُمْ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">بَعْثُكُمْ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">كَنَفْسٍ</span> <span class=\"quran-arabic-font text-success\">وَاحِدَةٍ</span><br />\r\n<br />\r\n(உங்கள் அனைவரையும் படைப்பதும், மீண்டும் உயிர் கொடுத்து எழுப்புவதும் ஒரே ஒரு நபரைப் படைப்பது போலவும், உயிர் கொடுத்து எழுப்புவது போலவுமே தவிர வேறில்லை.) (31: 28).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَآ</span> <span class=\"quran-arabic-font text-success\">أَمْرُنَآ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">وَاحِدَةٌ</span> <span class=\"quran-arabic-font text-success\">كَلَمْحٍ</span> <span class=\"quran-arabic-font text-success\">بِالْبَصَرِ</span><br />\r\n<br />\r\n(நம்முடைய கட்டளை கண் இமைப்பதைப் போன்ற ஒரே ஒரு சொல்லே தவிர வேறில்லை.) (<a href=\"qurandisp.php?sura=54&ayah=50\" class=\"link\">54:50</a>)<br />\r\n<br />","text":"சந்திப்பு நாளைப் பற்றித் தன் அடியார்களை எச்சரிப்பதற்காக அல்லாஹ் வஹீயை (இறைச்செய்தியை) அனுப்புகிறான்\n\r\n\n\r\nرَفِيعُ الدَّرَجَاتِ ذُو الْعَرْشِ\n\r\n\n\r\n(அவன்) உயர் பதவிகளை உடையவன்; அர்ஷுக்குச் சொந்தக்காரன்.\n\r\n\n\r\nஅல்லாஹ் தனது வல்லமையையும் பெருமையையும் பற்றியும், அவனது மகத்தான அர்ஷ் ஒரு கூரையைப் போல அவனது படைப்புகள் அனைத்திற்கும் மேலாக உயர்த்தப்பட்டுள்ளது என்பதைப் பற்றியும் நமக்குக் கூறுகிறான். இது பின்வரும் வசனத்தைப் போன்றது:\n\r\n\n\r\nمِّنَ اللَّهِ ذِي الْمَعَارِجِ - تَعْرُجُ الْمَلَائِكَةُ وَالرُّوحُ إِلَيْهِ فِى يَوْمٍ كَانَ مِقْدَارُهُ خَمْسِينَ أَلْفَ سَنَةٍ\n\r\n\n\r\n(உயர்வழிகளின் உரிமையாளனான அல்லாஹ்விடமிருந்து (அது கிடைக்கிறது). வானவர்களும் ரூஹும் (ஜிப்ரீல் அலை) ஐம்பதாயிரம் ஆண்டுகள் அளவுள்ள ஒரு நாளில் அவன்பால் ஏறிச் செல்வார்கள்.) (70:3-4). அல்லாஹ் நாடினால், அர்ஷுக்கும் ஏழாவது பூமிக்கும் இடைப்பட்ட தூரம் குறித்து முந்தைய மற்றும் பிந்தைய அறிஞர்கள் கூறும் மிகவும் சரியான கருத்து எது என்பதைப் பற்றி கீழே விவாதிப்போம். அர்ஷ் சிவப்பு மாணிக்கங்களால் ஆனது என்று ஒன்றுக்கும் மேற்பட்ட அறிஞர்கள் கூறியுள்ளனர். அதன் இரண்டு மூலைகளுக்கு இடைப்பட்ட அகலம் ஐம்பதாயிரம் ஆண்டு காலப் பயண தூரமாகும்; ஏழாவது பூமிக்கு மேல் அதன் உயரம் ஐம்பதாயிரம் ஆண்டு காலப் பயண தூரமாகும்.\n\r\n\n\r\nيُلْقِى الرُّوحَ مِنْ أَمْرِهِ عَلَى مَن يَشَآءُ مِنْ عِبَادِهِ\n\r\n\n\r\n(அவன் தனது அடியார்களில் தான் நாடியவர் மீது தனது கட்டளையின் மூலம் வஹீயை (இறைச்செய்தியை) இறக்குகிறான்.) இது பின்வரும் வசனங்களைப் போன்றது:\n\r\n\n\r\nيُنَزِّلُ الْمَلَائِكَةَ بِالرُّوحِ مِنْ أَمْرِهِ عَلَى مَن يَشَآءُ مِنْ عِبَادِهِ أَنْ أَنْذِرُواْ أَنَّهُ لاَ إِلَـهَ إِلاَ أَنَاْ فَاتَّقُونِ\n\r\n\n\r\n(\"என்னைத் தவிர வேறு இறைவனில்லை; எனவே எனக்கே அஞ்சுங்கள் என்று எச்சரிக்கை செய்யுங்கள்\" என்று கூறி, தனது அடியார்களில் தான் நாடியவர் மீது தனது கட்டளையின் மூலம் ரூஹுடன் (வஹீயுடன்) வானவர்களை அவன் இறக்குகிறான்.) (16:2), மேலும்:\n\r\n\n\r\nوَإِنَّهُ لَتَنزِيلُ رَبِّ الْعَالَمِينَ - نَزَلَ بِهِ الرُّوحُ الْأَمِينُ - عَلَى قَلْبِكَ لِتَكُونَ مِنَ الْمُنْذِرِينَ\n\r\n\n\r\n(நிச்சயமாக இது அகிலங்களின் இறைவனால் இறக்கப்பட்டதாகும். இதனை நம்பிக்கைக்குரிய ரூஹ் (ஜிப்ரீல் அலை) உம்முடைய இதயத்தில் இறக்கினார்; நீர் எச்சரிப்பவர்களில் ஒருவராக இருப்பதற்காக.) (26:192-194). அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nلِيُنذِرَ يَوْمَ التَّلاَقِ\n\r\n\n\r\n(அவர் (மக்களை) சந்திப்பு நாளைப் பற்றி எச்சரிப்பதற்காக.) 'சந்திப்பு நாள்' (யவ்முத் தலாக்) என்பது மறுமை நாளின் பெயர்களில் ஒன்று என்றும், அதைக் கொண்டே அல்லாஹ் தனது அடியார்களை எச்சரிக்கிறான் என்றும் இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாக அலீ பின் அபீ தல்ஹா (ரழி) அவர்கள் அறிவிக்கிறார்கள். அந்த நாளில்தான் ஒவ்வொருவரும் தங்களது நன்மையான மற்றும் தீமையான செயல்களைப் பற்றித் தெரிந்துகொள்வார்கள்.\n\r\n\n\r\nيَوْمَ هُم بَارِزُونَ لاَ يَخْفَى عَلَى اللَّهِ مِنْهُمْ شَىْءٌ\n\r\n\n\r\n(அவர்கள் வெளிப்படும் நாளில், அவர்களிடமிருந்து எதுவும் அல்லாஹ்வுக்கு மறைந்திருக்காது.) அதாவது, அவர்களுக்குப் புகலிடமோ, நிழலோ அல்லது மறைப்போ எதுவுமின்றி அவர்கள் அனைவரும் திறந்த வெளியில் தோன்றுவார்கள் என்று பொருள். அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nيَوْمَ هُم بَارِزُونَ لاَ يَخْفَى عَلَى اللَّهِ مِنْهُمْ شَىْءٌ\n\r\n\n\r\n(அவர்கள் வெளிப்படும் நாளில், அவர்களிடமிருந்து எதுவும் அல்லாஹ்வுக்கு மறைந்திருக்காது.) அதாவது, அனைத்தும் அவனுக்குத் சமமாக (தெளிவாகத்) தெரிந்திருக்கும்.\n\r\n\n\r\nلِّمَنِ الْمُلْكُ الْيَوْمَ لِلَّهِ الْوَاحِدِ الْقَهَّارِ\n\r\n\n\r\n(இன்றைய நாளில் ஆட்சி யாருடையது? ஏகனும் அடக்கி ஆள்பவனுமான அல்லாஹ்வுக்கே உரியது!) அல்லாஹ் வானங்களையும் பூமியையும் தனது கையில் சுருட்டிக்கொண்டு:\n\r\n\n\r\n«أَنَا الْمَلِكُ، أَنَا الْجَبَّارُ، أَنَا الْمُتَكَبِّرُ، أَيْنَ مُلُوكُ الْأَرْضِ؟ أَيْنَ الْجَبَّارُونَ؟ أَيْنَ الْمُتَكَبِّرُونَ؟»\n\r\n\n\r\n(\"நானே அரசன், நானே அடக்குபவன், நானே பெருமைக்குரியவன்; பூமியின் அரசர்கள் எங்கே? அக்கிரமக்காரர்கள் எங்கே? பெருமையடித்தவர்கள் எங்கே?\") என்று கூறுவான் என இப்னு உமர் (ரழி) அவர்கள் வாயிலாக வரும் ஹதீஸை நாம் ஏற்கனவே குறிப்பிட்டுள்ளோம்.\n\r\n\n\r\nஸூர் (எக்காளம்) பற்றிய ஹதீஸில், அல்லாஹ் தனது படைப்புகள் அனைத்தின் ஆன்மாக்களையும் கைப்பற்றுவான் என்றும், அவனுடன் கூட்டாளிகளோ துணைகளோ இன்றி அவன் மட்டுமே தனித்திருப்பான் என்றும் கூறப்பட்டுள்ளது. பிறகு அவன், \"இன்றைய நாளில் ஆட்சி யாருடையது?\" என்று மூன்று முறை கேட்பான். பிறகு அவனே அதற்குப் பதிலளிப்பான்:\n\r\n\n\r\nلِلَّهِ الْوَاحِدِ الْقَهَّارِ\n\r\n\n\r\n(ஏகனும் அடக்கி ஆள்பவனுமான அல்லாஹ்வுக்கே உரியது!) அதாவது, அனைத்தையும் அடக்கி ஆள்பவன் அவன் ஒருவன் மட்டுமே.\n\r\n\n\r\nالْيَوْمَ تُجْزَى كُلُّ نَفْسٍ بِمَا كَسَبَتْ لاَ ظُلْمَ الْيَوْمَ إِنَّ اللَّهَ سَرِيعُ الْحِسَابِ\n\r\n\n\r\n(இன்று ஒவ்வொரு ஆத்மாவுக்கும் அது சம்பாதித்ததற்குக் கூலி கொடுக்கப்படும். இன்று அநீதி எதுவுமில்லை; நிச்சயமாக அல்லாஹ் கணக்கெடுப்பதில் மிக விரைவானவன்.) தனது படைப்புகளுக்கு இடையே தீர்ப்பளிக்கும்போது அல்லாஹ் கடைபிடிக்கும் நீதியைப் பற்றி இங்கே அவன் கூறுகிறான்; நன்மையாக இருந்தாலும் சரி, தீமையாக இருந்தாலும் சரி, ஓர் அணுவளவு கூட அவன் அநீதி இழைக்க மாட்டான். ஒவ்வொரு நற்செயலுக்கும் பத்து மடங்கு நற்கூலியும், ஒவ்வொரு தீமைக்கும் அதற்குச் சமமான தண்டனையுமே வழங்குகிறான். அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nلاَ ظُلْمَ الْيَوْمَ\n\r\n\n\r\n(இன்று அநீதி எதுவுமில்லை.) ஸஹீஹ் முஸ்லிமில் அபூ தர் (ரழி) அவர்கள் வாயிலாக அறிவிக்கப்பட்டுள்ள ஒரு ஹதீஸில், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் அல்லாஹ் பின்வருமாறு கூறியதாகக் கூறினார்கள்:\n\r\n\n\r\n«يَا عِبَادِي إِنِّي حَرَّمْتُ الظُّلْمَ عَلى نَفْسِي وَجَعَلْتُهُ بَيْنَكُمْ مُحَرَّمًا فَلَا تَظَالَمُوا إلى أن قال يَا عِبَادِي إِنَّمَا هِيَ أَعْمَالُكُمْ أُحْصِيهَا عَلَيْكُمْ ثُمَّ أُوَفِّيكُمْ إِيَّاهَا، فَمَنْ وَجَدَ خَيْرًا فَلْيَحْمَدِ اللهَ تَبَارَكَ وَتَعَالَى، وَمَنْ وَجَدَ غَيْرَ ذَلِكَ فَلَا يَلُومَنَّ إِلَّا نَفْسَه»\n\r\n\n\r\n(\"எனது அடியார்களே! அநீதியை எனக்கு நானே தடுத்துக்கொண்டேன்; அதை உங்களுக்கிடையிலும் தடுக்கப்பட்டதாக ஆக்கிவிட்டேன். எனவே ஒருவருக்கொருவர் அநீதி இழைக்காதீர்கள்...\" மேலும் கூறினான்: \"எனது அடியார்களே! இவை உங்கள் செயல்களே; இவற்றை நான் உங்களுக்காகக் கணக்கிடுகிறேன். பிறகு அவற்றுக்கான கூலியை உங்களுக்கு முழுமையாக வழங்குவேன். எனவே நன்மையைக் காண்பவர் அல்லாஹ்வைப் புகழட்டும்; அது அல்லாத வேறு எதையேனும் காண்பவர் தன்னைத் தவிர வேறு யாரையும் குறை கூற வேண்டாம்.\")\n\r\n\n\r\nإِنَّ اللَّهَ سَرِيعُ الْحِسَابِ\n\r\n\n\r\n(நிச்சயமாக அல்லாஹ் கணக்கெடுப்பதில் மிக விரைவானவன்.) அதாவது, அவன் தனது படைப்புகள் அனைத்தையும் ஒரே ஒரு நபரிடம் கணக்கெடுப்பதைப் போல மிக எளிதாகக் கணக்கெடுப்பான். இது பின்வரும் வசனத்தைப் போன்றது:\n\r\n\n\r\nمَّا خَلْقُكُمْ وَلاَ بَعْثُكُمْ إِلاَّ كَنَفْسٍ وَاحِدَةٍ\n\r\n\n\r\n(உங்கள் அனைவரையும் படைப்பதும், மீண்டும் உயிர் கொடுத்து எழுப்புவதும் ஒரே ஒரு நபரைப் படைப்பது போலவும், உயிர் கொடுத்து எழுப்புவது போலவுமே தவிர வேறில்லை.) (31: 28).\n\r\n\n\r\nوَمَآ أَمْرُنَآ إِلاَّ وَاحِدَةٌ كَلَمْحٍ بِالْبَصَرِ\n\r\n\n\r\n(நம்முடைய கட்டளை கண் இமைப்பதைப் போன்ற ஒரே ஒரு சொல்லே தவிர வேறில்லை.) (54:50)"},"18":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=40&ayah=20\" class=\"link\">40:20</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 40:20 ஐ பார்க்கவும்"},"19":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=40&ayah=20\" class=\"link\">40:20</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 40:20 ஐ பார்க்கவும்"},"20":{"html":"<strong>-மறுமை நாள் குறித்த எச்சரிக்கையும் அந்நாளில் அல்லாஹ்வின் தீர்ப்பும்</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَأَنذِرْهُمْ</span> <span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">الْآزِفَةِ﴿</span><br />\r\n'நெருங்கி வரும் நாள்' என்பது மறுமை நாளின் பெயர்களில் ஒன்றாகும். அது மிக அருகாமையில் இருப்பதால் அவ்வாறு அழைக்கப்படுகிறது. அல்லாஹ் கூறுவது போல்: <span class=\"quran-arabic-font text-success\">﴾أَزِفَتِ</span> <span class=\"quran-arabic-font text-success\">الْآزِفَةُ</span> - <span class=\"quran-arabic-font text-success\">لَيْسَ</span> <span class=\"quran-arabic-font text-success\">لَهَا</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">دُونِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">كَاشِفَةٌ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n(மறுமை நாள் நெருங்கிவிட்டது. அல்லாஹ்வைத் தவிர வேறு யாராலும் அதைத் தடுக்க முடியாது) (<a href=\"qurandisp.php?sura=53&ayah=57\" class=\"link\">53:57</a>-58) <span class=\"quran-arabic-font text-success\">﴾اقْتَرَبَتِ</span> <span class=\"quran-arabic-font text-success\">السَّاعَةُ</span> <span class=\"quran-arabic-font text-success\">وَانشَقَّ</span> <span class=\"quran-arabic-font text-success\">الْقَمَرُ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n(அந்த நேரம் நெருங்கிவிட்டது, மேலும் சந்திரன் பிளந்துவிட்டது) (<a href=\"qurandisp.php?sura=54&ayah=1\" class=\"link\">54:1</a>) <span class=\"quran-arabic-font text-success\">﴾اقْتَرَبَ</span> <span class=\"quran-arabic-font text-success\">لِلنَّاسِ</span> <span class=\"quran-arabic-font text-success\">حِسَابُهُمْ﴿</span><br />\r\n(மனிதர்களுக்கு அவர்களது கணக்கு விசாரணை நெருங்கிவிட்டது) (<a href=\"qurandisp.php?sura=21&ayah=1\" class=\"link\">21:1</a>), <span class=\"quran-arabic-font text-success\">﴾أَتَى</span> <span class=\"quran-arabic-font text-success\">أَمْرُ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">فَلاَ</span> <span class=\"quran-arabic-font text-success\">تَسْتَعْجِلُوهُ﴿</span><br />\r\n(அல்லாஹ்வின் கட்டளை (மறுமை) வந்தே தீரும், எனவே அதனை அவசரப்படுத்த முற்படாதீர்கள்) (<a href=\"qurandisp.php?sura=16&ayah=1\" class=\"link\">16:1</a>), <span class=\"quran-arabic-font text-success\">﴾فَلَمَّا</span> <span class=\"quran-arabic-font text-success\">رَأَوْهُ</span> <span class=\"quran-arabic-font text-success\">زُلْفَةً</span> <span class=\"quran-arabic-font text-success\">سِيئَتْ</span> <span class=\"quran-arabic-font text-success\">وُجُوهُ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">كَفَرُواْ﴿</span><br />\r\n(ஆனால், அவர்கள் அதனை (வேதனையை) மிக அருகில் காணும்போது, நிராகரிப்பவர்களின் முகங்கள் துக்கத்தாலும் கவலையாலும் விகாரமடைந்துவிடும்) (<a href=\"qurandisp.php?sura=67&ayah=27\" class=\"link\">67:27</a>), மற்றும் <span class=\"quran-arabic-font text-success\">﴾إِذِ</span> <span class=\"quran-arabic-font text-success\">الْقُلُوبُ</span> <span class=\"quran-arabic-font text-success\">لَدَى</span> <span class=\"quran-arabic-font text-success\">الْحَنَاجِرِ</span> <span class=\"quran-arabic-font text-success\">كَاظِمِينَ﴿</span><br />\r\n(இதயங்கள் தொண்டைக் குழிகளை அடைந்து, அவர்கள் துயரத்தை விழுங்கியவர்களாக (மௌனமாக) இருக்கும்போது.) கதாதா (ரழி) அவர்கள் கூறினார்கள்: \"அச்சத்தின் காரணமாக இதயங்கள் தொண்டையை எட்டும்போது, அவை வெளியேயும் வராது, பழைய இடத்திற்கும் திரும்பாது.\" இக்ரிமா (ரழி), அஸ்-ஸுத்தீ (ரழி) போன்றோரும் இதே கருத்தைக் கொண்டிருந்தனர்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾كَاظِمِينَ﴿</span><br />\r\n(காழிமீன்) என்றால் மௌனமாக இருப்பவர்கள் என்று பொருள். ஏனெனில், அவனது அனுமதியின்றி அன்று எவரும் பேச மாட்டார்கள்: <span class=\"quran-arabic-font text-success\">﴾يَوْمَ</span> <span class=\"quran-arabic-font text-success\">يَقُومُ</span> <span class=\"quran-arabic-font text-success\">الرُّوحُ</span> <span class=\"quran-arabic-font text-success\">وَالْمَلَائِكَةُ</span> <span class=\"quran-arabic-font text-success\">صَفّاً</span> <span class=\"quran-arabic-font text-success\">لاَّ</span> <span class=\"quran-arabic-font text-success\">يَتَكَلَّمُونَ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">أَذِنَ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">الرَّحْمَنُ</span> <span class=\"quran-arabic-font text-success\">وَقَالَ</span> <span class=\"quran-arabic-font text-success\">صَوَاباً</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n(அர்-ரூஹும் (ஜிப்ரீல் (அலை)) வானவர்களும் அணிவகுத்து நிற்கும் அந்நாளில், அளவற்ற அருளாளன் அனுமதித்தவரைத் தவிர எவரும் பேச மாட்டார்கள்; அவர் சரியானதையே கூறுவார்.) (<a href=\"qurandisp.php?sura=78&ayah=38\" class=\"link\">78:38</a>). இப்னு ஜுரைஜ் (ரழி) அவர்கள் கூறினார்கள்: <span class=\"quran-arabic-font text-success\">﴾كَاظِمِينَ﴿</span> (காழிமீன்) என்பதற்கு \"அழுபவர்கள்\" என்று பொருள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾مَا</span> <span class=\"quran-arabic-font text-success\">لِلظَّالِمِينَ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">حَمِيمٍ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">شَفِيعٍ</span> <span class=\"quran-arabic-font text-success\">يُطَاعُ﴿</span><br />\r\n(அநீதியாளர்களுக்கு உற்ற நண்பனோ, ஏற்கப்படத்தக்க பரிந்துரையாளனோ எவரும் இருக்க மாட்டார்கள்.) இதன் பொருள் என்னவெனில், அல்லாஹ்வுக்கு இணையாக மற்றவர்களை வணங்கி தமக்குத்தாமே அநீதி இழைத்துக் கொண்டவர்களுக்கு, உதவக்கூடிய உறவினர்களோ அல்லது பரிந்துரை செய்யக்கூடிய பரிந்துரையாளர்களோ எவரும் இருக்க மாட்டார்கள்; நன்மையை எதிர்பார்க்கும் அனைத்து வழிகளும் அவர்களுக்கு அடைக்கப்பட்டுவிடும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾يَعْلَمُ</span> <span class=\"quran-arabic-font text-success\">خَائِنَةَ</span> <span class=\"quran-arabic-font text-success\">الْأَعْيُنِ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">تُخْفِي</span> <span class=\"quran-arabic-font text-success\">الصُّدُورُ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n(கண்களின் துரோகத்தையும், உள்ளங்கள் மறைப்பவற்றையும் அவன் அறிகிறான்.) அல்லாஹ் தனது பரிபூரணமான ஞானத்தைப் பற்றி இங்கே குறிப்பிடுகிறான். சிறியது, பெரியது என அனைத்தும் அவனது அறிவுக்கு உட்பட்டது என்பதை மக்கள் உணர்ந்து, அவன் முன்னிலையில் உரிய வெட்க உணர்வோடு இருக்க வேண்டும் என்பதற்காகவே இவ்வாறு கூறுகிறான். அவன் தங்களைக் கண்காணிக்கிறான் என்பதையும், கண்கள் அப்பாவித்தனமாகத் தெரிந்தாலும் அதிலுள்ள வஞ்சகத்தை அவன் அறிவான் என்பதையும், உள்ளங்கள் எதை மறைக்கின்றன என்பதையும் அவர்கள் கவனத்தில் கொள்ள வேண்டும்.<br />\r\n<br />\r\nஅத்-தஹ்ஹாக் (ரழி) அவர்கள் கூறினார்கள்: <span class=\"quran-arabic-font text-success\">﴾خَائِنَةَ</span> <span class=\"quran-arabic-font text-success\">الْأَعْيُنِ﴿</span><br />\r\n(கண்களின் துரோகம்) என்பது, \"கண் ஜாடை செய்வதையும், ஒரு பொருளைப் பார்க்காமலேயே பார்த்ததாகக் கூறுவதையும் அல்லது பார்த்த பிறகும் பார்க்கவில்லை என்று கூறுவதையும் குறிக்கும்.\"<br />\r\n<br />\r\nஇப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்: \"ஒரு கண் ஏதேனும் ஒன்றை நோக்கும்போது, அது துரோகம் செய்யும் எண்ணத்தில் பார்க்கிறதா இல்லையா என்பதை அல்லாஹ் அறிகிறான்.\" முஜாஹித் (ரழி), கதாதா (ரழி) ஆகியோரும் இதே கருத்தைக் கொண்டிருந்தனர்.<br />\r\n<br />\r\nஇப்னு அப்பாஸ் (ரழி) அவர்கள் <span class=\"quran-arabic-font text-success\">﴾وَمَا</span> <span class=\"quran-arabic-font text-success\">تُخْفِي</span> <span class=\"quran-arabic-font text-success\">الصُّدُورُ﴿</span> (உள்ளங்கள் மறைப்பவை) என்ற வசனத்திற்கு விளக்கமளிக்கும்போது: \"உங்களுக்கு வாய்ப்பு கிடைத்தால் ஒரு பெண்ணுடன் விபச்சாரம் செய்வீர்களா இல்லையா என்பதை அவன் அறிவான்\" என்று கூறினார்கள்.<br />\r\n<br />\r\nஅஸ்-ஸுத்தீ (ரழி) அவர்கள் <span class=\"quran-arabic-font text-success\">﴾وَمَا</span> <span class=\"quran-arabic-font text-success\">تُخْفِي</span> <span class=\"quran-arabic-font text-success\">الصُّدُورُ﴿</span> (உள்ளங்கள் மறைப்பவை) என்பதற்கு \"மனதில் எழும் தீய எண்ணங்கள்\" என்று பொருள்படும் எனக் கூறினார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَاللَّهُ</span> <span class=\"quran-arabic-font text-success\">يَقْضِي</span> <span class=\"quran-arabic-font text-success\">بِالْحَقِّ﴿</span><br />\r\n(மேலும், அல்லாஹ் சத்தியத்தைக் கொண்டு தீர்ப்பளிக்கிறான்) என்றால், அவன் நீதியுடன் தீர்ப்பளிக்கிறான் என்று பொருள். அல்-அஃமஷ் (ரழி) அவர்கள், ஸயீத் பின் ஜுபைர் (ரழி) வழியாக இப்னு அப்பாஸ் (ரழி) அவர்களிடமிருந்து அறிவிப்பதாவது: \"நன்மை செய்தவர்களுக்கு நன்மையையும், தீமை செய்தவர்களுக்குத் தீமையையும் கூலியாக வழங்க அவன் ஆற்றல் உள்ளவன்\" என்பதே இந்த வசனத்தின் பொருளாகும்.<br />\r\n<br />\r\nநீக்கப்பட்டது: <span class=\"quran-arabic-font text-success\">﴾إِنَّ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">السَّمِيعُ</span> <span class=\"quran-arabic-font text-success\">الْبَصِيرُ﴿</span> (நிச்சயமாக அல்லாஹ்வே அனைத்தையும் செவியுறுபவனாகவும் பார்ப்பவனாகவும் இருக்கிறான்.) - இங்கு தவறாக இடம்பெற்றுள்ளது<br />\r\n<br />\r\nஇப்னு அப்பாஸ் (ரழி) அவர்கள் இவ்விதமே விளக்கம் அளித்துள்ளார்கள். இது பின்வரும் வசனத்தைப் போன்றது: <span class=\"quran-arabic-font text-success\">﴾لِيَجْزِىَ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">أَسَاءُواْ</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">عَمِلُواْ</span> <span class=\"quran-arabic-font text-success\">وَيَجْزِيَ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">أَحْسَنُواْ</span> <span class=\"quran-arabic-font text-success\">بِالْحُسْنَى﴿</span> (தீமை செய்தவர்களுக்கு அவர்கள் செய்தவற்றிற்கு ஏற்ப அவன் கூலி கொடுக்கவும், நன்மை செய்தவர்களுக்கு மிக அழகிய நன்மையைக் கொண்டு கூலி கொடுக்கவும் (இவ்வாறு செய்கிறான்).) (<a href=\"qurandisp.php?sura=53&ayah=31\" class=\"link\">53:31</a>).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَالَّذِينَ</span> <span class=\"quran-arabic-font text-success\">يَدْعُونَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">دُونِهِ﴿</span><br />\r\n(அவனையன்றி அவர்கள் யாரை அழைக்கிறார்களோ அவர்கள்...) என்பது சிலைகளையும் பொய்த் தெய்வங்களையும் குறிக்கிறது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾لَا</span> <span class=\"quran-arabic-font text-success\">يَقْضُونَ</span> <span class=\"quran-arabic-font text-success\">بِشَيْءٍ﴿</span><br />\r\n(எந்தவொரு தீர்ப்பையும் வழங்க மாட்டார்கள்.) அதாவது, அவற்றுக்கு எந்த அதிகாரமும் இல்லை, அவற்றால் எந்தத் தீர்ப்பும் வழங்க முடியாது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾إِنَّ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">السَّمِيعُ</span> <span class=\"quran-arabic-font text-success\">الْبَصِيرُ﴿</span><br />\r\n(நிச்சயமாக அல்லாஹ்வே அனைத்தையும் செவியுறுபவனாகவும் பார்ப்பவனாகவும் இருக்கிறான்.) அதாவது, அவன் தனது படைப்புகள் பேசுவதை எல்லாம் செவியுறுகிறான், அவர்களைப் பற்றி நன்கு அறிந்திருக்கிறான். தான் நாடியவர்களுக்கு நேர்வழி காட்டுகிறான், தான் நாடியவர்களை வழிகேட்டில் விடுகிறான். இவை அனைத்திலும் அவன் மிகச் சரியான நீதியுடன் தீர்ப்பளிக்கிறான்.<br />\r\n<br />","text":"-மறுமை நாள் குறித்த எச்சரிக்கையும் அந்நாளில் அல்லாஹ்வின் தீர்ப்பும்\n\r\n\n\r\n﴾وَأَنذِرْهُمْ يَوْمَ الْآزِفَةِ﴿\n\r\n'நெருங்கி வரும் நாள்' என்பது மறுமை நாளின் பெயர்களில் ஒன்றாகும். அது மிக அருகாமையில் இருப்பதால் அவ்வாறு அழைக்கப்படுகிறது. அல்லாஹ் கூறுவது போல்: ﴾أَزِفَتِ الْآزِفَةُ - لَيْسَ لَهَا مِن دُونِ اللَّهِ كَاشِفَةٌ ﴿\n\r\n(மறுமை நாள் நெருங்கிவிட்டது. அல்லாஹ்வைத் தவிர வேறு யாராலும் அதைத் தடுக்க முடியாது) (53:57-58) ﴾اقْتَرَبَتِ السَّاعَةُ وَانشَقَّ الْقَمَرُ ﴿\n\r\n(அந்த நேரம் நெருங்கிவிட்டது, மேலும் சந்திரன் பிளந்துவிட்டது) (54:1) ﴾اقْتَرَبَ لِلنَّاسِ حِسَابُهُمْ﴿\n\r\n(மனிதர்களுக்கு அவர்களது கணக்கு விசாரணை நெருங்கிவிட்டது) (21:1), ﴾أَتَى أَمْرُ اللَّهِ فَلاَ تَسْتَعْجِلُوهُ﴿\n\r\n(அல்லாஹ்வின் கட்டளை (மறுமை) வந்தே தீரும், எனவே அதனை அவசரப்படுத்த முற்படாதீர்கள்) (16:1), ﴾فَلَمَّا رَأَوْهُ زُلْفَةً سِيئَتْ وُجُوهُ الَّذِينَ كَفَرُواْ﴿\n\r\n(ஆனால், அவர்கள் அதனை (வேதனையை) மிக அருகில் காணும்போது, நிராகரிப்பவர்களின் முகங்கள் துக்கத்தாலும் கவலையாலும் விகாரமடைந்துவிடும்) (67:27), மற்றும் ﴾إِذِ الْقُلُوبُ لَدَى الْحَنَاجِرِ كَاظِمِينَ﴿\n\r\n(இதயங்கள் தொண்டைக் குழிகளை அடைந்து, அவர்கள் துயரத்தை விழுங்கியவர்களாக (மௌனமாக) இருக்கும்போது.) கதாதா (ரழி) அவர்கள் கூறினார்கள்: \"அச்சத்தின் காரணமாக இதயங்கள் தொண்டையை எட்டும்போது, அவை வெளியேயும் வராது, பழைய இடத்திற்கும் திரும்பாது.\" இக்ரிமா (ரழி), அஸ்-ஸுத்தீ (ரழி) போன்றோரும் இதே கருத்தைக் கொண்டிருந்தனர்.\n\r\n\n\r\n﴾كَاظِمِينَ﴿\n\r\n(காழிமீன்) என்றால் மௌனமாக இருப்பவர்கள் என்று பொருள். ஏனெனில், அவனது அனுமதியின்றி அன்று எவரும் பேச மாட்டார்கள்: ﴾يَوْمَ يَقُومُ الرُّوحُ وَالْمَلَائِكَةُ صَفّاً لاَّ يَتَكَلَّمُونَ إِلاَّ مَنْ أَذِنَ لَهُ الرَّحْمَنُ وَقَالَ صَوَاباً ﴿\n\r\n(அர்-ரூஹும் (ஜிப்ரீல் (அலை)) வானவர்களும் அணிவகுத்து நிற்கும் அந்நாளில், அளவற்ற அருளாளன் அனுமதித்தவரைத் தவிர எவரும் பேச மாட்டார்கள்; அவர் சரியானதையே கூறுவார்.) (78:38). இப்னு ஜுரைஜ் (ரழி) அவர்கள் கூறினார்கள்: ﴾كَاظِمِينَ﴿ (காழிமீன்) என்பதற்கு \"அழுபவர்கள்\" என்று பொருள்.\n\r\n\n\r\n﴾مَا لِلظَّالِمِينَ مِنْ حَمِيمٍ وَلاَ شَفِيعٍ يُطَاعُ﴿\n\r\n(அநீதியாளர்களுக்கு உற்ற நண்பனோ, ஏற்கப்படத்தக்க பரிந்துரையாளனோ எவரும் இருக்க மாட்டார்கள்.) இதன் பொருள் என்னவெனில், அல்லாஹ்வுக்கு இணையாக மற்றவர்களை வணங்கி தமக்குத்தாமே அநீதி இழைத்துக் கொண்டவர்களுக்கு, உதவக்கூடிய உறவினர்களோ அல்லது பரிந்துரை செய்யக்கூடிய பரிந்துரையாளர்களோ எவரும் இருக்க மாட்டார்கள்; நன்மையை எதிர்பார்க்கும் அனைத்து வழிகளும் அவர்களுக்கு அடைக்கப்பட்டுவிடும்.\n\r\n\n\r\n﴾يَعْلَمُ خَائِنَةَ الْأَعْيُنِ وَمَا تُخْفِي الصُّدُورُ ﴿\n\r\n(கண்களின் துரோகத்தையும், உள்ளங்கள் மறைப்பவற்றையும் அவன் அறிகிறான்.) அல்லாஹ் தனது பரிபூரணமான ஞானத்தைப் பற்றி இங்கே குறிப்பிடுகிறான். சிறியது, பெரியது என அனைத்தும் அவனது அறிவுக்கு உட்பட்டது என்பதை மக்கள் உணர்ந்து, அவன் முன்னிலையில் உரிய வெட்க உணர்வோடு இருக்க வேண்டும் என்பதற்காகவே இவ்வாறு கூறுகிறான். அவன் தங்களைக் கண்காணிக்கிறான் என்பதையும், கண்கள் அப்பாவித்தனமாகத் தெரிந்தாலும் அதிலுள்ள வஞ்சகத்தை அவன் அறிவான் என்பதையும், உள்ளங்கள் எதை மறைக்கின்றன என்பதையும் அவர்கள் கவனத்தில் கொள்ள வேண்டும்.\n\r\n\n\r\nஅத்-தஹ்ஹாக் (ரழி) அவர்கள் கூறினார்கள்: ﴾خَائِنَةَ الْأَعْيُنِ﴿\n\r\n(கண்களின் துரோகம்) என்பது, \"கண் ஜாடை செய்வதையும், ஒரு பொருளைப் பார்க்காமலேயே பார்த்ததாகக் கூறுவதையும் அல்லது பார்த்த பிறகும் பார்க்கவில்லை என்று கூறுவதையும் குறிக்கும்.\"\n\r\n\n\r\nஇப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்: \"ஒரு கண் ஏதேனும் ஒன்றை நோக்கும்போது, அது துரோகம் செய்யும் எண்ணத்தில் பார்க்கிறதா இல்லையா என்பதை அல்லாஹ் அறிகிறான்.\" முஜாஹித் (ரழி), கதாதா (ரழி) ஆகியோரும் இதே கருத்தைக் கொண்டிருந்தனர்.\n\r\n\n\r\nஇப்னு அப்பாஸ் (ரழி) அவர்கள் ﴾وَمَا تُخْفِي الصُّدُورُ﴿ (உள்ளங்கள் மறைப்பவை) என்ற வசனத்திற்கு விளக்கமளிக்கும்போது: \"உங்களுக்கு வாய்ப்பு கிடைத்தால் ஒரு பெண்ணுடன் விபச்சாரம் செய்வீர்களா இல்லையா என்பதை அவன் அறிவான்\" என்று கூறினார்கள்.\n\r\n\n\r\nஅஸ்-ஸுத்தீ (ரழி) அவர்கள் ﴾وَمَا تُخْفِي الصُّدُورُ﴿ (உள்ளங்கள் மறைப்பவை) என்பதற்கு \"மனதில் எழும் தீய எண்ணங்கள்\" என்று பொருள்படும் எனக் கூறினார்கள்.\n\r\n\n\r\n﴾وَاللَّهُ يَقْضِي بِالْحَقِّ﴿\n\r\n(மேலும், அல்லாஹ் சத்தியத்தைக் கொண்டு தீர்ப்பளிக்கிறான்) என்றால், அவன் நீதியுடன் தீர்ப்பளிக்கிறான் என்று பொருள். அல்-அஃமஷ் (ரழி) அவர்கள், ஸயீத் பின் ஜுபைர் (ரழி) வழியாக இப்னு அப்பாஸ் (ரழி) அவர்களிடமிருந்து அறிவிப்பதாவது: \"நன்மை செய்தவர்களுக்கு நன்மையையும், தீமை செய்தவர்களுக்குத் தீமையையும் கூலியாக வழங்க அவன் ஆற்றல் உள்ளவன்\" என்பதே இந்த வசனத்தின் பொருளாகும்.\n\r\n\n\r\nநீக்கப்பட்டது: ﴾إِنَّ اللَّهَ هُوَ السَّمِيعُ الْبَصِيرُ﴿ (நிச்சயமாக அல்லாஹ்வே அனைத்தையும் செவியுறுபவனாகவும் பார்ப்பவனாகவும் இருக்கிறான்.) - இங்கு தவறாக இடம்பெற்றுள்ளது\n\r\n\n\r\nஇப்னு அப்பாஸ் (ரழி) அவர்கள் இவ்விதமே விளக்கம் அளித்துள்ளார்கள். இது பின்வரும் வசனத்தைப் போன்றது: ﴾لِيَجْزِىَ الَّذِينَ أَسَاءُواْ بِمَا عَمِلُواْ وَيَجْزِيَ الَّذِينَ أَحْسَنُواْ بِالْحُسْنَى﴿ (தீமை செய்தவர்களுக்கு அவர்கள் செய்தவற்றிற்கு ஏற்ப அவன் கூலி கொடுக்கவும், நன்மை செய்தவர்களுக்கு மிக அழகிய நன்மையைக் கொண்டு கூலி கொடுக்கவும் (இவ்வாறு செய்கிறான்).) (53:31).\n\r\n\n\r\n﴾وَالَّذِينَ يَدْعُونَ مِن دُونِهِ﴿\n\r\n(அவனையன்றி அவர்கள் யாரை அழைக்கிறார்களோ அவர்கள்...) என்பது சிலைகளையும் பொய்த் தெய்வங்களையும் குறிக்கிறது.\n\r\n\n\r\n﴾لَا يَقْضُونَ بِشَيْءٍ﴿\n\r\n(எந்தவொரு தீர்ப்பையும் வழங்க மாட்டார்கள்.) அதாவது, அவற்றுக்கு எந்த அதிகாரமும் இல்லை, அவற்றால் எந்தத் தீர்ப்பும் வழங்க முடியாது.\n\r\n\n\r\n﴾إِنَّ اللَّهَ هُوَ السَّمِيعُ الْبَصِيرُ﴿\n\r\n(நிச்சயமாக அல்லாஹ்வே அனைத்தையும் செவியுறுபவனாகவும் பார்ப்பவனாகவும் இருக்கிறான்.) அதாவது, அவன் தனது படைப்புகள் பேசுவதை எல்லாம் செவியுறுகிறான், அவர்களைப் பற்றி நன்கு அறிந்திருக்கிறான். தான் நாடியவர்களுக்கு நேர்வழி காட்டுகிறான், தான் நாடியவர்களை வழிகேட்டில் விடுகிறான். இவை அனைத்திலும் அவன் மிகச் சரியான நீதியுடன் தீர்ப்பளிக்கிறான்."},"21":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=40&ayah=22\" class=\"link\">40:22</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 40:22 ஐ பார்க்கவும்"},"22":{"html":"<strong>நிராகரிப்பாளர்களுக்கான கடுமையான தண்டனை</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾أَوَلَمْ</span> <span class=\"quran-arabic-font text-success\">يَسِيرُواْ﴿</span><br />\r\n<br />\r\n(அவர்கள் பூமியில் பயணம் செய்யவில்லையா?) அதாவது \"முஹம்மதே (ஸல்)! உமது தூதுத்துவத்தை நிராகரிக்கும் இந்த மக்கள்,\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فِي</span> <span class=\"quran-arabic-font text-success\">الْأَرْضِ</span> <span class=\"quran-arabic-font text-success\">فَيَنظُرُواْ</span> <span class=\"quran-arabic-font text-success\">كَيْفَ</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">عَاقِبَةُ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">كَانُواْ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">قَبْلِهِمْ﴿</span><br />\r\n<br />\r\n(பூமியில் பயணம் செய்து, தங்களுக்கு முன்னால் இருந்தவர்களின் முடிவு என்னவானது என்பதை அவர்கள் பார்க்கவில்லையா?) இதன் பொருள்: தங்களுக்கு அனுப்பப்பட்ட நபிமார்களை (அலை) நிராகரித்த கடந்த கால சமுதாயத்தினர் ஆவர். அவர்கள் குறைஷிகளை விட அதிக வலிமை வாய்ந்தவர்களாக இருந்தபோதிலும், அவர்கள் செய்த நிராகரிப்பின் காரணமாக அவர்கள் மீது அல்லாஹ்வின் தண்டனை இறங்கியது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾كَانُواْ</span> <span class=\"quran-arabic-font text-success\">هُمْ</span> <span class=\"quran-arabic-font text-success\">أَشَدَّ</span> <span class=\"quran-arabic-font text-success\">مِنْهُمْ</span> <span class=\"quran-arabic-font text-success\">قُوَّةً</span> <span class=\"quran-arabic-font text-success\">وَءَاثَاراً</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْأَرْضِ﴿</span><br />\r\n<br />\r\n(அவர்கள் இவர்களை விட அதிக பலம் கொண்டவர்களாகவும், மேலும் பூமியில் அவர்கள் விட்டுச் சென்ற அடையாளங்களையும் பார்க்கவில்லையா?) இதன் பொருள்: அவர்கள் பூமியில் விட்டுச் சென்ற கட்டிடங்கள், மாளிகைகள் மற்றும் குடியிருப்புகள் போன்ற அடையாளங்களாகும். தற்போதைய மக்களாகிய குறைஷிகளால் அத்தகையவற்றுக்கு இணையாக எதையும் செய்திட முடியாது. இது பின்வரும் வசனத்தைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَلَقَدْ</span> <span class=\"quran-arabic-font text-success\">مَكَّنَّاهُمْ</span> <span class=\"quran-arabic-font text-success\">فِيمَآ</span> <span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">مَّكَّنَّاكُمْ</span> <span class=\"quran-arabic-font text-success\">فِيهِ﴿</span><br />\r\n<br />\r\n(உங்களுக்கு நாம் வழங்காத வசதி வாய்ப்புகளை அவர்களுக்கு நாம் வழங்கி, அவர்களை உறுதிப்படுத்தியிருந்தோம்!) (<a href=\"qurandisp.php?sura=46&ayah=26\" class=\"link\">46:26</a>)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَأَثَارُواْ</span> <span class=\"quran-arabic-font text-success\">الْأَرْضَ</span> <span class=\"quran-arabic-font text-success\">وَعَمَرُوهَآ</span> <span class=\"quran-arabic-font text-success\">أَكْثَرَ</span> <span class=\"quran-arabic-font text-success\">مِمَّا</span> <span class=\"quran-arabic-font text-success\">عَمَرُوهَا﴿</span><br />\r\n<br />\r\n(மேலும், அவர்கள் பூமியைப் பண்படுத்தி, இவர்கள் செய்ததை விட அதிகமாக அதைப் பயிரிட்டும் செழிக்கவும் செய்தனர்) (<a href=\"qurandisp.php?sura=30&ayah=9\" class=\"link\">30:9</a>). <span class=\"quran-arabic-font text-success\">﴾فَأَخَذَهُمُ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">بِذُنُوبِهِمْ﴿</span> (எனவே, அவர்களுடைய பாவங்களின் காரணமாக அல்லாஹ் அவர்களைப் பிடித்துக் கொண்டான்.) இவ்வளவு பெரும் வலிமை கொண்டிருந்தும், அவர்கள் தங்கள் தூதர்களை நிராகரித்த பாவத்தின் காரணமாக அல்லாஹ் அவர்களைத் தண்டித்தான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَمَا</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">لَهُم</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">وَاقٍ﴿</span><br />\r\n<br />\r\n(அல்லாஹ்விடமிருந்து அவர்களைப் பாதுகாப்பவர் எவரும் இருக்கவில்லை.) இதன் பொருள்: அவர்களைப் பாதுகாக்கவோ அல்லது அல்லாஹ்வின் தண்டனையைத் தடுத்து நிறுத்தவோ எவராலும் முடியவில்லை. பின்னர், அல்லாஹ் அவர்களை ஏன் தண்டித்தான் என்பதற்கான காரணத்தையும் அவர்கள் செய்த பாவங்களையும் குறிப்பிடுகிறான். அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">بِأَنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">كَانَت</span> <span class=\"quran-arabic-font text-success\">تَّأْتِيهِمْ</span> <span class=\"quran-arabic-font text-success\">رُسُلُهُم</span> <span class=\"quran-arabic-font text-success\">بِالْبَيِّنَاتِ﴿</span><br />\r\n<br />\r\n(அது ஏனென்றால், அவர்களிடம் தெளிவான சான்றுகளுடன் அவர்களுடைய தூதர்கள் வந்தார்கள்.) அதாவது தெளிவான அத்தாட்சிகளுடனும் உறுதியான ஆதாரங்களுடனும் அவர்கள் வந்தனர்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَكَفَرُواْ﴿</span><br />\r\n<br />\r\n(ஆனால் அவர்கள் நிராகரித்தார்கள்.) இத்தனை அடையாளங்கள் வந்த பிறகும் அவர்கள் அந்தத் தூதுத்துவத்தை ஏற்க மறுத்து நிராகரித்தனர்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَأَخَذَهُمُ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ﴿</span><br />\r\n<br />\r\n(ஆகவே அல்லாஹ் அவர்களைப் பிடித்துக் கொண்டான்.) அதாவது அல்லாஹ் அவர்களை முழுமையாக அழித்துவிட்டான். இப்போதும் நிராகரிப்போருக்கு இத்தகையதொரு முடிவுதான் காத்திருக்கிறது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾إِنَّهُ</span> <span class=\"quran-arabic-font text-success\">قَوِىٌّ</span> <span class=\"quran-arabic-font text-success\">شَدِيدُ</span> <span class=\"quran-arabic-font text-success\">الْعِقَابِ﴿</span><br />\r\n<br />\r\n(நிச்சயமாக அவன் பேராற்றல் மிக்கவன்; தண்டிப்பதில் கடுமையானவன்.) அவன் மாபெரும் வல்லமையும் சக்தியும் கொண்டவன் என்பது இதன் பொருள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾شَدِيدُ</span> <span class=\"quran-arabic-font text-success\">الْعِقَابِ﴿</span><br />\r\n<br />\r\n(தண்டிப்பதில் கடுமையானவன்,) அவனது தண்டனை மிகவும் கடுமையானதும் வேதனையானதும் ஆகும். பாக்கியமிக்கவனும் உயர்ந்தவனுமான அல்லாஹ்விடம் அத்தகைய தண்டனையிலிருந்து நாம் பாதுகாப்புத் தேடுகிறோம்.<br />\r\n<br />","text":"நிராகரிப்பாளர்களுக்கான கடுமையான தண்டனை\n\r\n\n\r\n﴾أَوَلَمْ يَسِيرُواْ﴿\n\r\n\n\r\n(அவர்கள் பூமியில் பயணம் செய்யவில்லையா?) அதாவது \"முஹம்மதே (ஸல்)! உமது தூதுத்துவத்தை நிராகரிக்கும் இந்த மக்கள்,\"\n\r\n\n\r\n﴾فِي الْأَرْضِ فَيَنظُرُواْ كَيْفَ كَانَ عَاقِبَةُ الَّذِينَ كَانُواْ مِن قَبْلِهِمْ﴿\n\r\n\n\r\n(பூமியில் பயணம் செய்து, தங்களுக்கு முன்னால் இருந்தவர்களின் முடிவு என்னவானது என்பதை அவர்கள் பார்க்கவில்லையா?) இதன் பொருள்: தங்களுக்கு அனுப்பப்பட்ட நபிமார்களை (அலை) நிராகரித்த கடந்த கால சமுதாயத்தினர் ஆவர். அவர்கள் குறைஷிகளை விட அதிக வலிமை வாய்ந்தவர்களாக இருந்தபோதிலும், அவர்கள் செய்த நிராகரிப்பின் காரணமாக அவர்கள் மீது அல்லாஹ்வின் தண்டனை இறங்கியது.\n\r\n\n\r\n﴾كَانُواْ هُمْ أَشَدَّ مِنْهُمْ قُوَّةً وَءَاثَاراً فِي الْأَرْضِ﴿\n\r\n\n\r\n(அவர்கள் இவர்களை விட அதிக பலம் கொண்டவர்களாகவும், மேலும் பூமியில் அவர்கள் விட்டுச் சென்ற அடையாளங்களையும் பார்க்கவில்லையா?) இதன் பொருள்: அவர்கள் பூமியில் விட்டுச் சென்ற கட்டிடங்கள், மாளிகைகள் மற்றும் குடியிருப்புகள் போன்ற அடையாளங்களாகும். தற்போதைய மக்களாகிய குறைஷிகளால் அத்தகையவற்றுக்கு இணையாக எதையும் செய்திட முடியாது. இது பின்வரும் வசனத்தைப் போன்றது:\n\r\n\n\r\n﴾وَلَقَدْ مَكَّنَّاهُمْ فِيمَآ إِن مَّكَّنَّاكُمْ فِيهِ﴿\n\r\n\n\r\n(உங்களுக்கு நாம் வழங்காத வசதி வாய்ப்புகளை அவர்களுக்கு நாம் வழங்கி, அவர்களை உறுதிப்படுத்தியிருந்தோம்!) (46:26)\n\r\n\n\r\n﴾وَأَثَارُواْ الْأَرْضَ وَعَمَرُوهَآ أَكْثَرَ مِمَّا عَمَرُوهَا﴿\n\r\n\n\r\n(மேலும், அவர்கள் பூமியைப் பண்படுத்தி, இவர்கள் செய்ததை விட அதிகமாக அதைப் பயிரிட்டும் செழிக்கவும் செய்தனர்) (30:9). ﴾فَأَخَذَهُمُ اللَّهُ بِذُنُوبِهِمْ﴿ (எனவே, அவர்களுடைய பாவங்களின் காரணமாக அல்லாஹ் அவர்களைப் பிடித்துக் கொண்டான்.) இவ்வளவு பெரும் வலிமை கொண்டிருந்தும், அவர்கள் தங்கள் தூதர்களை நிராகரித்த பாவத்தின் காரணமாக அல்லாஹ் அவர்களைத் தண்டித்தான்.\n\r\n\n\r\n﴾وَمَا كَانَ لَهُم مِّنَ اللَّهِ مِن وَاقٍ﴿\n\r\n\n\r\n(அல்லாஹ்விடமிருந்து அவர்களைப் பாதுகாப்பவர் எவரும் இருக்கவில்லை.) இதன் பொருள்: அவர்களைப் பாதுகாக்கவோ அல்லது அல்லாஹ்வின் தண்டனையைத் தடுத்து நிறுத்தவோ எவராலும் முடியவில்லை. பின்னர், அல்லாஹ் அவர்களை ஏன் தண்டித்தான் என்பதற்கான காரணத்தையும் அவர்கள் செய்த பாவங்களையும் குறிப்பிடுகிறான். அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\n﴾ذَلِكَ بِأَنَّهُمْ كَانَت تَّأْتِيهِمْ رُسُلُهُم بِالْبَيِّنَاتِ﴿\n\r\n\n\r\n(அது ஏனென்றால், அவர்களிடம் தெளிவான சான்றுகளுடன் அவர்களுடைய தூதர்கள் வந்தார்கள்.) அதாவது தெளிவான அத்தாட்சிகளுடனும் உறுதியான ஆதாரங்களுடனும் அவர்கள் வந்தனர்.\n\r\n\n\r\n﴾فَكَفَرُواْ﴿\n\r\n\n\r\n(ஆனால் அவர்கள் நிராகரித்தார்கள்.) இத்தனை அடையாளங்கள் வந்த பிறகும் அவர்கள் அந்தத் தூதுத்துவத்தை ஏற்க மறுத்து நிராகரித்தனர்.\n\r\n\n\r\n﴾فَأَخَذَهُمُ اللَّهُ﴿\n\r\n\n\r\n(ஆகவே அல்லாஹ் அவர்களைப் பிடித்துக் கொண்டான்.) அதாவது அல்லாஹ் அவர்களை முழுமையாக அழித்துவிட்டான். இப்போதும் நிராகரிப்போருக்கு இத்தகையதொரு முடிவுதான் காத்திருக்கிறது.\n\r\n\n\r\n﴾إِنَّهُ قَوِىٌّ شَدِيدُ الْعِقَابِ﴿\n\r\n\n\r\n(நிச்சயமாக அவன் பேராற்றல் மிக்கவன்; தண்டிப்பதில் கடுமையானவன்.) அவன் மாபெரும் வல்லமையும் சக்தியும் கொண்டவன் என்பது இதன் பொருள்.\n\r\n\n\r\n﴾شَدِيدُ الْعِقَابِ﴿\n\r\n\n\r\n(தண்டிப்பதில் கடுமையானவன்,) அவனது தண்டனை மிகவும் கடுமையானதும் வேதனையானதும் ஆகும். பாக்கியமிக்கவனும் உயர்ந்தவனுமான அல்லாஹ்விடம் அத்தகைய தண்டனையிலிருந்து நாம் பாதுகாப்புத் தேடுகிறோம்."},"23":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=40&ayah=27\" class=\"link\">40:27</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 40:27 ஐ பார்க்கவும்"},"24":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=40&ayah=27\" class=\"link\">40:27</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 40:27 ஐ பார்க்கவும்"},"25":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=40&ayah=27\" class=\"link\">40:27</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 40:27 ஐ பார்க்கவும்"},"26":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=40&ayah=27\" class=\"link\">40:27</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 40:27 ஐ பார்க்கவும்"},"27":{"html":"<strong>மூஸா அலை மற்றும் ஃபிர்அவ்னின் கதை</strong><br />\r\n<br />\r\nஅல்லாஹ் தன் தூதர் முஹம்மது (ஸல்) அவர்களுக்கு, அவர்களது சமூகத்தார் அவரை நிராகரித்ததற்காக ஆறுதல் கூறுகிறான். மேலும், தெளிவான சான்றுகளுடனும் உறுதியான ஆதாரங்களுடனும் அல்லாஹ்வால் அனுப்பப்பட்ட மூஸா பின் இம்ரான் (அலை) அவர்களுக்கு நேர்ந்தது போலவே, இவ்வுலகிலும் மறுமையிலும் நல்ல முடிவுகளும் வெற்றியும் கிடைக்கும் என்ற நற்செய்தியை அவர்களுக்கு அளிக்கிறான். அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">بِآيَاتِنَا</span> <span class=\"quran-arabic-font text-success\">وَسُلْطَانٍ</span> <span class=\"quran-arabic-font text-success\">مُّبِينٍ</span><br />\r\n<br />\r\n(நம்முடைய அத்தாட்சிகளுடனும், தெளிவான அதிகாரத்துடனும்). 'அதிகாரம்' என்பது சான்று மற்றும் அத்தாட்சியைக் குறிக்கும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">فِرْعَوْنَ</span><br />\r\n<br />\r\n(ஃபிர்அவ்னிடம்), அவன் எகிப்திய கிப்தி (Copts) இன மக்களின் அரசனாக இருந்தான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَهَامَانَ</span><br />\r\n<br />\r\n(ஹாமான்), அவன் அவனது அமைச்சனாக இருந்தான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَقَارُونَ</span><br />\r\n<br />\r\n(மற்றும் காரூன்), அவன் அக்காலத்து மக்களிடையே மிகப் பெரிய செல்வந்தராகத் திகழ்ந்த வியாபாரி ஆவான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَقَالُواْ</span> <span class=\"quran-arabic-font text-success\">سَاحِرٌ</span> <span class=\"quran-arabic-font text-success\">كَذَّابٌ</span><br />\r\n<br />\r\n(ஆனால் அவர்கள் (அவரை): \"ஒரு சூனியக்காரர், பெரும் பொய்யர்!\" என்று கூறினர்) அதாவது, அவர்கள் அவரை நிராகரித்து, அவர் ஒரு சூனியக்காரர், ஒரு பைத்தியக்காரர் மற்றும் அல்லாஹ்வால் அனுப்பப்பட்டதாகப் பொய் சொல்லும் ஒரு மாயவித்தைக்காரர் என்று கருதினர். இது பின்வரும் வசனத்தைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">كَذَلِكَ</span> <span class=\"quran-arabic-font text-success\">مَآ</span> <span class=\"quran-arabic-font text-success\">أَتَى</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">قَبْلِهِمْ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">رَّسُولٍ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">قَالُواْ</span> <span class=\"quran-arabic-font text-success\">سَاحِرٌ</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">مَجْنُونٌ</span> - <span class=\"quran-arabic-font text-success\">أَتَوَاصَوْاْ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">بَلْ</span> <span class=\"quran-arabic-font text-success\">هُمْ</span> <span class=\"quran-arabic-font text-success\">قَوْمٌ</span> <span class=\"quran-arabic-font text-success\">طَاغُونَ</span><br />\r\n<br />\r\n(இவ்வாறே, இவர்களுக்கு முன் வாழ்ந்தவர்களிடமும் எந்தத் தூதர் வந்தாலும், அவர்கள் \"இவர் ஒரு சூனியக்காரர் அல்லது ஒரு பைத்தியக்காரர்!\" என்று கூறாமல் இருந்ததில்லை. இதனை ஒருவருக்கொருவர் அவர்கள் அறிவுறுத்திச் சென்றார்களா? இல்லை, அவர்களே வரம்பு மீறிய சமூகத்தினராக இருக்கின்றனர்!) (<a href=\"qurandisp.php?sura=51&ayah=52\" class=\"link\">51:52</a>-53)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَلَمَّا</span> <span class=\"quran-arabic-font text-success\">جَآءَهُمْ</span> <span class=\"quran-arabic-font text-success\">بِالْحَقِّ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">عِندِنَا</span><br />\r\n<br />\r\n(பின்னர், அவர் நம்மிடமிருந்து சத்தியத்தை அவர்களிடம் கொண்டு வந்தபோது,) அதாவது, அல்லாஹ் அவரை அவர்களிடம் அனுப்பியதற்கான உறுதியான ஆதாரத்தைக் கொண்டு வந்தபோது,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قَالُواْ</span> <span class=\"quran-arabic-font text-success\">اقْتُلُواْ</span> <span class=\"quran-arabic-font text-success\">أَبْنَآءَ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">ءَامَنُواْ</span> <span class=\"quran-arabic-font text-success\">مَعَهُ</span> <span class=\"quran-arabic-font text-success\">وَاسْتَحْيُواْ</span> <span class=\"quran-arabic-font text-success\">نِسَآءَهُمْ</span><br />\r\n<br />\r\n(அவர்கள் கூறினர்: \"அவருடன் ஈமான் கொண்டவர்களின் ஆண் மக்களைக் கொன்று விடுங்கள்; அவர்களின் பெண்களை வாழ விடுங்கள்;) இது இஸ்ரவேல் சந்ததிகளின் ஆண் குழந்தைகளைக் கொல்ல ஃபிர்அவ்ன் பிறப்பித்த இரண்டாவது கட்டளையாகும். முதல் கட்டளையானது, மூஸாவைப் போன்ற ஒரு மனிதர் தோன்றுவதற்கு எதிரான முன்னெச்சரிக்கை நடவடிக்கையாகவோ, அல்லது அந்த மக்களை இழிவுபடுத்தவோ, அவர்களின் எண்ணிக்கையைக் குறைக்கவோ அல்லது இவை அனைத்திற்காகவோ இருந்தது. ஆனால், இந்த இரண்டாவது கட்டளையோ, அந்த மக்களை மேலும் இழிவுபடுத்தி, அதன் மூலம் அவர்கள் மூஸா (அலை) அவர்களை ஒரு கெட்ட சகுனமாகக் கருத வேண்டும் என்பதற்காகவே பிறப்பிக்கப்பட்டது. அவர்கள் கூறினர்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أُوذِينَا</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">قَبْلِ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">تَأْتِيَنَا</span> <span class=\"quran-arabic-font text-success\">وَمِن</span> <span class=\"quran-arabic-font text-success\">بَعْدِ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">جِئْتَنَا</span> <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">عَسَى</span> <span class=\"quran-arabic-font text-success\">رَبُّكُمْ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">يُهْلِكَ</span> <span class=\"quran-arabic-font text-success\">عَدُوَّكُمْ</span> <span class=\"quran-arabic-font text-success\">وَيَسْتَخْلِفَكُمْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الاٌّرْضِ</span> <span class=\"quran-arabic-font text-success\">فَيَنظُرَ</span> <span class=\"quran-arabic-font text-success\">كَيْفَ</span> <span class=\"quran-arabic-font text-success\">تَعْمَلُونَ</span><br />\r\n<br />\r\n(\"நீர் எங்களிடம் வருவதற்கு முன்னரும், நீர் எங்களிடம் வந்த பின்னரும் நாங்கள் (இஸ்ரவேல் சந்ததிகள்) துன்புறுத்தப்பட்டோம்.\" அதற்கு அவர் கூறினார்: \"உங்கள் இறைவன் உங்கள் எதிரியை அழித்து, உங்களைப் பூமியில் வாரிசுகளாக ஆக்கிவிடக்கூடும். அதன் பின்னர் நீங்கள் எவ்வாறு செயல்படுகிறீர்கள் என்பதை அவன் கவனிப்பான்.\") (<a href=\"qurandisp.php?sura=7&ayah=129\" class=\"link\">7:129</a>). இது ஒன்றன்பின் ஒன்றாக வந்த கட்டளைகள் என்று கதாதா (ரஹ்) கூறினார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">كَيْدُ</span> <span class=\"quran-arabic-font text-success\">الْكَافِرِينَ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">ضَلَالٍ</span><br />\r\n<br />\r\n(ஆனால் நிராகரிப்பாளர்களின் சூழ்ச்சி வீணானதைத் தவிர வேறில்லை!) அதாவது, இஸ்ரவேல் சந்ததியினர் தங்களை விஞ்சிவிடக் கூடாது என்பதற்காக, அவர்களின் எண்ணிக்கையைக் குறைக்க அவர்கள் தீட்டிய திட்டங்களும் எண்ணங்களும் தோல்வியிலேயே முடிந்தன.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَقَالَ</span> <span class=\"quran-arabic-font text-success\">فِرْعَوْنُ</span> <span class=\"quran-arabic-font text-success\">ذَرُونِى</span> <span class=\"quran-arabic-font text-success\">أَقْتُلْ</span> <span class=\"quran-arabic-font text-success\">مُوسَى</span> <span class=\"quran-arabic-font text-success\">وَلْيَدْعُ</span> <span class=\"quran-arabic-font text-success\">رَبَّهُ</span><br />\r\n<br />\r\n(ஃபிர்அவ்ன் கூறினான்: \"மூஸாவைக் கொல்ல என்னை விடுங்கள், அவர் தன் இறைவனை அழைக்கட்டும்!...\") அல்லாஹ்வினால் சபிக்கப்பட்ட ஃபிர்அவ்ன், மூஸா (அலை) அவர்களைக் கொல்லத் தீர்மானித்தான். அதாவது, அவன் தன் மக்களிடம், \"உங்களுக்காக நான் அவரைக் கொன்றுவிடுகிறேன், என்னை விடுங்கள்\" என்று கூறினான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلْيَدْعُ</span> <span class=\"quran-arabic-font text-success\">رَبَّهُ</span><br />\r\n<br />\r\n(அவர் தன் இறைவனை அழைக்கட்டும்!) என்பது, \"அவர் யாரை அழைத்தாலும் எனக்குக் கவலையில்லை\" என்ற அவனது ஆணவமான முரட்டுத்தனத்தின் உச்சமாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنِّى</span> <span class=\"quran-arabic-font text-success\">أَخَافُ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">يُبَدِّلَ</span> <span class=\"quran-arabic-font text-success\">دِينَكُمْ</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">يُظْهِرَ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الاٌّرْضِ</span> <span class=\"quran-arabic-font text-success\">الْفَسَادَ</span><br />\r\n<br />\r\n(அவர் உங்கள் மார்க்கத்தை மாற்றிவிடுவார் அல்லது பூமியில் குழப்பத்தை ஏற்படுத்துவார் என்று நான் அஞ்சுகிறேன்!) அதாவது, மூஸா (அலை) தன் மக்களை வழிதவறச் செய்து, அவர்களின் பழக்கவழக்கங்களையும் கலாச்சாரத்தையும் மாற்றிவிடுவார் என்று ஃபிர்அவ்ன் பயந்தானாம். மூஸா தன் மக்களுக்கு என்ன செய்துவிடுவார் என்று ஃபிர்அவ்ன் கவலைப்படுவது போல் நடித்தான்! \"அவர் உங்கள் மார்க்கத்தை மாற்றிவிடுவார்; அல்லது பூமியில் குழப்பத்தை ஏற்படுத்துவார்\" என்பதே இதன் பொருள் என்று பெரும்பான்மையான அறிஞர்கள் கருதுகின்றனர்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَقَالَ</span> <span class=\"quran-arabic-font text-success\">مُوسَى</span> <span class=\"quran-arabic-font text-success\">إِنِّى</span> <span class=\"quran-arabic-font text-success\">عُذْتُ</span> <span class=\"quran-arabic-font text-success\">بِرَبِّى</span> <span class=\"quran-arabic-font text-success\">وَرَبِّكُم</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">كُلِّ</span> <span class=\"quran-arabic-font text-success\">مُتَكَبِّرٍ</span> <span class=\"quran-arabic-font text-success\">لاَّ</span> <span class=\"quran-arabic-font text-success\">يُؤْمِنُ</span> <span class=\"quran-arabic-font text-success\">بِيَوْمِ</span> <span class=\"quran-arabic-font text-success\">الْحِسَابِ</span><br />\r\n<br />\r\n(மூஸா கூறினார்: \"நிச்சயமாக, நான் என் இறைவனும் உங்கள் இறைவனுமாகிய அல்லாஹ்விடம், கணக்குத் தீர்க்கும் நாளை நம்பாத ஒவ்வொரு பெருமையடிப்பவனிடமிருந்தும் பாதுகாப்புத் தேடுகிறேன்!\") அதாவது, ஃபிர்அவ்ன் இவ்வாறு கூறியதைக் கேட்டபோது,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">ذَرُونِى</span> <span class=\"quran-arabic-font text-success\">أَقْتُلْ</span> <span class=\"quran-arabic-font text-success\">مُوسَى</span><br />\r\n<br />\r\n(மூஸாவைக் கொல்ல என்னை விடுங்கள்,) மூஸா (அலை) அவர்கள், \"அவனது தீங்கிலிருந்தும் அவனைப் போன்றவர்களின் தீங்கிலிருந்தும் நான் அல்லாஹ்விடம் அடைக்கலமும் பாதுகாப்பும் தேடுகிறேன்\" என்று கூறினார்கள். எனவே தான் அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنِّى</span> <span class=\"quran-arabic-font text-success\">عُذْتُ</span> <span class=\"quran-arabic-font text-success\">بِرَبِّى</span> <span class=\"quran-arabic-font text-success\">وَرَبِّكُم</span><br />\r\n<br />\r\n(நிச்சயமாக, நான் என் இறைவனும் உங்கள் இறைவனுமாகிய அல்லாஹ்விடம் பாதுகாப்புத் தேடுகிறேன்) -- யாரிடம் அந்த வார்த்தைகள் கூறப்பட்டதோ அவர்களை நோக்கி --<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">كُلِّ</span> <span class=\"quran-arabic-font text-success\">مُتَكَبِّرٍ</span><br />\r\n<br />\r\n(ஒவ்வொரு பெருமையடிப்பவனிடமிருந்தும்) அதாவது, ஒவ்வொரு தீயவனிடமிருந்தும்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لاَّ</span> <span class=\"quran-arabic-font text-success\">يُؤْمِنُ</span> <span class=\"quran-arabic-font text-success\">بِيَوْمِ</span> <span class=\"quran-arabic-font text-success\">الْحِسَابِ</span><br />\r\n<br />\r\n(கணக்குத் தீர்க்கும் நாளை நம்பாதவன்!) அபூ மூஸா (ரழி) அவர்கள் அறிவிக்கும் ஹதீஸில்: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் ஏதேனும் ஒரு கூட்டத்தைக் கண்டு அஞ்சினால் இவ்வாறு கூறுவார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">اللْهُمَّ</span> <span class=\"quran-arabic-font text-success\">إِنَّا</span> <span class=\"quran-arabic-font text-success\">نَعُوذُ</span> <span class=\"quran-arabic-font text-success\">بِكَ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">شُرُورِهِمْ،</span> <span class=\"quran-arabic-font text-success\">وَنَدْرَأُ</span> <span class=\"quran-arabic-font text-success\">بِكَ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">نُحُورِهِم</span>»<br />\r\n<br />\r\n(யா அல்லாஹ்! அவர்களின் தீங்குகளிலிருந்து உன்னிடம் நாங்கள் பாதுகாப்புத் தேடுகிறோம்; அவர்களை எதிர்ப்பதில் உன்னையே முன்னிறுத்துகிறோம்.) இதை அபூதாவூத் பதிவு செய்துள்ளார்.<br />\r\n<br />","text":"மூஸா அலை மற்றும் ஃபிர்அவ்னின் கதை\n\r\n\n\r\nஅல்லாஹ் தன் தூதர் முஹம்மது (ஸல்) அவர்களுக்கு, அவர்களது சமூகத்தார் அவரை நிராகரித்ததற்காக ஆறுதல் கூறுகிறான். மேலும், தெளிவான சான்றுகளுடனும் உறுதியான ஆதாரங்களுடனும் அல்லாஹ்வால் அனுப்பப்பட்ட மூஸா பின் இம்ரான் (அலை) அவர்களுக்கு நேர்ந்தது போலவே, இவ்வுலகிலும் மறுமையிலும் நல்ல முடிவுகளும் வெற்றியும் கிடைக்கும் என்ற நற்செய்தியை அவர்களுக்கு அளிக்கிறான். அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nبِآيَاتِنَا وَسُلْطَانٍ مُّبِينٍ\n\r\n\n\r\n(நம்முடைய அத்தாட்சிகளுடனும், தெளிவான அதிகாரத்துடனும்). 'அதிகாரம்' என்பது சான்று மற்றும் அத்தாட்சியைக் குறிக்கும்.\n\r\n\n\r\nإِلَى فِرْعَوْنَ\n\r\n\n\r\n(ஃபிர்அவ்னிடம்), அவன் எகிப்திய கிப்தி (Copts) இன மக்களின் அரசனாக இருந்தான்.\n\r\n\n\r\nوَهَامَانَ\n\r\n\n\r\n(ஹாமான்), அவன் அவனது அமைச்சனாக இருந்தான்.\n\r\n\n\r\nوَقَارُونَ\n\r\n\n\r\n(மற்றும் காரூன்), அவன் அக்காலத்து மக்களிடையே மிகப் பெரிய செல்வந்தராகத் திகழ்ந்த வியாபாரி ஆவான்.\n\r\n\n\r\nفَقَالُواْ سَاحِرٌ كَذَّابٌ\n\r\n\n\r\n(ஆனால் அவர்கள் (அவரை): \"ஒரு சூனியக்காரர், பெரும் பொய்யர்!\" என்று கூறினர்) அதாவது, அவர்கள் அவரை நிராகரித்து, அவர் ஒரு சூனியக்காரர், ஒரு பைத்தியக்காரர் மற்றும் அல்லாஹ்வால் அனுப்பப்பட்டதாகப் பொய் சொல்லும் ஒரு மாயவித்தைக்காரர் என்று கருதினர். இது பின்வரும் வசனத்தைப் போன்றது:\n\r\n\n\r\nكَذَلِكَ مَآ أَتَى الَّذِينَ مِن قَبْلِهِمْ مِّن رَّسُولٍ إِلاَّ قَالُواْ سَاحِرٌ أَوْ مَجْنُونٌ - أَتَوَاصَوْاْ بِهِ بَلْ هُمْ قَوْمٌ طَاغُونَ\n\r\n\n\r\n(இவ்வாறே, இவர்களுக்கு முன் வாழ்ந்தவர்களிடமும் எந்தத் தூதர் வந்தாலும், அவர்கள் \"இவர் ஒரு சூனியக்காரர் அல்லது ஒரு பைத்தியக்காரர்!\" என்று கூறாமல் இருந்ததில்லை. இதனை ஒருவருக்கொருவர் அவர்கள் அறிவுறுத்திச் சென்றார்களா? இல்லை, அவர்களே வரம்பு மீறிய சமூகத்தினராக இருக்கின்றனர்!) (51:52-53)\n\r\n\n\r\nفَلَمَّا جَآءَهُمْ بِالْحَقِّ مِنْ عِندِنَا\n\r\n\n\r\n(பின்னர், அவர் நம்மிடமிருந்து சத்தியத்தை அவர்களிடம் கொண்டு வந்தபோது,) அதாவது, அல்லாஹ் அவரை அவர்களிடம் அனுப்பியதற்கான உறுதியான ஆதாரத்தைக் கொண்டு வந்தபோது,\n\r\n\n\r\nقَالُواْ اقْتُلُواْ أَبْنَآءَ الَّذِينَ ءَامَنُواْ مَعَهُ وَاسْتَحْيُواْ نِسَآءَهُمْ\n\r\n\n\r\n(அவர்கள் கூறினர்: \"அவருடன் ஈமான் கொண்டவர்களின் ஆண் மக்களைக் கொன்று விடுங்கள்; அவர்களின் பெண்களை வாழ விடுங்கள்;) இது இஸ்ரவேல் சந்ததிகளின் ஆண் குழந்தைகளைக் கொல்ல ஃபிர்அவ்ன் பிறப்பித்த இரண்டாவது கட்டளையாகும். முதல் கட்டளையானது, மூஸாவைப் போன்ற ஒரு மனிதர் தோன்றுவதற்கு எதிரான முன்னெச்சரிக்கை நடவடிக்கையாகவோ, அல்லது அந்த மக்களை இழிவுபடுத்தவோ, அவர்களின் எண்ணிக்கையைக் குறைக்கவோ அல்லது இவை அனைத்திற்காகவோ இருந்தது. ஆனால், இந்த இரண்டாவது கட்டளையோ, அந்த மக்களை மேலும் இழிவுபடுத்தி, அதன் மூலம் அவர்கள் மூஸா (அலை) அவர்களை ஒரு கெட்ட சகுனமாகக் கருத வேண்டும் என்பதற்காகவே பிறப்பிக்கப்பட்டது. அவர்கள் கூறினர்:\n\r\n\n\r\nأُوذِينَا مِن قَبْلِ أَن تَأْتِيَنَا وَمِن بَعْدِ مَا جِئْتَنَا قَالَ عَسَى رَبُّكُمْ أَن يُهْلِكَ عَدُوَّكُمْ وَيَسْتَخْلِفَكُمْ فِى الاٌّرْضِ فَيَنظُرَ كَيْفَ تَعْمَلُونَ\n\r\n\n\r\n(\"நீர் எங்களிடம் வருவதற்கு முன்னரும், நீர் எங்களிடம் வந்த பின்னரும் நாங்கள் (இஸ்ரவேல் சந்ததிகள்) துன்புறுத்தப்பட்டோம்.\" அதற்கு அவர் கூறினார்: \"உங்கள் இறைவன் உங்கள் எதிரியை அழித்து, உங்களைப் பூமியில் வாரிசுகளாக ஆக்கிவிடக்கூடும். அதன் பின்னர் நீங்கள் எவ்வாறு செயல்படுகிறீர்கள் என்பதை அவன் கவனிப்பான்.\") (7:129). இது ஒன்றன்பின் ஒன்றாக வந்த கட்டளைகள் என்று கதாதா (ரஹ்) கூறினார்கள்.\n\r\n\n\r\nوَمَا كَيْدُ الْكَافِرِينَ إِلاَّ فِى ضَلَالٍ\n\r\n\n\r\n(ஆனால் நிராகரிப்பாளர்களின் சூழ்ச்சி வீணானதைத் தவிர வேறில்லை!) அதாவது, இஸ்ரவேல் சந்ததியினர் தங்களை விஞ்சிவிடக் கூடாது என்பதற்காக, அவர்களின் எண்ணிக்கையைக் குறைக்க அவர்கள் தீட்டிய திட்டங்களும் எண்ணங்களும் தோல்வியிலேயே முடிந்தன.\n\r\n\n\r\nوَقَالَ فِرْعَوْنُ ذَرُونِى أَقْتُلْ مُوسَى وَلْيَدْعُ رَبَّهُ\n\r\n\n\r\n(ஃபிர்அவ்ன் கூறினான்: \"மூஸாவைக் கொல்ல என்னை விடுங்கள், அவர் தன் இறைவனை அழைக்கட்டும்!...\") அல்லாஹ்வினால் சபிக்கப்பட்ட ஃபிர்அவ்ன், மூஸா (அலை) அவர்களைக் கொல்லத் தீர்மானித்தான். அதாவது, அவன் தன் மக்களிடம், \"உங்களுக்காக நான் அவரைக் கொன்றுவிடுகிறேன், என்னை விடுங்கள்\" என்று கூறினான்.\n\r\n\n\r\nوَلْيَدْعُ رَبَّهُ\n\r\n\n\r\n(அவர் தன் இறைவனை அழைக்கட்டும்!) என்பது, \"அவர் யாரை அழைத்தாலும் எனக்குக் கவலையில்லை\" என்ற அவனது ஆணவமான முரட்டுத்தனத்தின் உச்சமாகும்.\n\r\n\n\r\nإِنِّى أَخَافُ أَن يُبَدِّلَ دِينَكُمْ أَوْ أَن يُظْهِرَ فِى الاٌّرْضِ الْفَسَادَ\n\r\n\n\r\n(அவர் உங்கள் மார்க்கத்தை மாற்றிவிடுவார் அல்லது பூமியில் குழப்பத்தை ஏற்படுத்துவார் என்று நான் அஞ்சுகிறேன்!) அதாவது, மூஸா (அலை) தன் மக்களை வழிதவறச் செய்து, அவர்களின் பழக்கவழக்கங்களையும் கலாச்சாரத்தையும் மாற்றிவிடுவார் என்று ஃபிர்அவ்ன் பயந்தானாம். மூஸா தன் மக்களுக்கு என்ன செய்துவிடுவார் என்று ஃபிர்அவ்ன் கவலைப்படுவது போல் நடித்தான்! \"அவர் உங்கள் மார்க்கத்தை மாற்றிவிடுவார்; அல்லது பூமியில் குழப்பத்தை ஏற்படுத்துவார்\" என்பதே இதன் பொருள் என்று பெரும்பான்மையான அறிஞர்கள் கருதுகின்றனர்.\n\r\n\n\r\nوَقَالَ مُوسَى إِنِّى عُذْتُ بِرَبِّى وَرَبِّكُم مِّن كُلِّ مُتَكَبِّرٍ لاَّ يُؤْمِنُ بِيَوْمِ الْحِسَابِ\n\r\n\n\r\n(மூஸா கூறினார்: \"நிச்சயமாக, நான் என் இறைவனும் உங்கள் இறைவனுமாகிய அல்லாஹ்விடம், கணக்குத் தீர்க்கும் நாளை நம்பாத ஒவ்வொரு பெருமையடிப்பவனிடமிருந்தும் பாதுகாப்புத் தேடுகிறேன்!\") அதாவது, ஃபிர்அவ்ன் இவ்வாறு கூறியதைக் கேட்டபோது,\n\r\n\n\r\nذَرُونِى أَقْتُلْ مُوسَى\n\r\n\n\r\n(மூஸாவைக் கொல்ல என்னை விடுங்கள்,) மூஸா (அலை) அவர்கள், \"அவனது தீங்கிலிருந்தும் அவனைப் போன்றவர்களின் தீங்கிலிருந்தும் நான் அல்லாஹ்விடம் அடைக்கலமும் பாதுகாப்பும் தேடுகிறேன்\" என்று கூறினார்கள். எனவே தான் அவர்கள் கூறினார்கள்:\n\r\n\n\r\nإِنِّى عُذْتُ بِرَبِّى وَرَبِّكُم\n\r\n\n\r\n(நிச்சயமாக, நான் என் இறைவனும் உங்கள் இறைவனுமாகிய அல்லாஹ்விடம் பாதுகாப்புத் தேடுகிறேன்) -- யாரிடம் அந்த வார்த்தைகள் கூறப்பட்டதோ அவர்களை நோக்கி --\n\r\n\n\r\nمِّن كُلِّ مُتَكَبِّرٍ\n\r\n\n\r\n(ஒவ்வொரு பெருமையடிப்பவனிடமிருந்தும்) அதாவது, ஒவ்வொரு தீயவனிடமிருந்தும்,\n\r\n\n\r\nلاَّ يُؤْمِنُ بِيَوْمِ الْحِسَابِ\n\r\n\n\r\n(கணக்குத் தீர்க்கும் நாளை நம்பாதவன்!) அபூ மூஸா (ரழி) அவர்கள் அறிவிக்கும் ஹதீஸில்: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் ஏதேனும் ஒரு கூட்டத்தைக் கண்டு அஞ்சினால் இவ்வாறு கூறுவார்கள்:\n\r\n\n\r\n«اللْهُمَّ إِنَّا نَعُوذُ بِكَ مِنْ شُرُورِهِمْ، وَنَدْرَأُ بِكَ فِي نُحُورِهِم»\n\r\n\n\r\n(யா அல்லாஹ்! அவர்களின் தீங்குகளிலிருந்து உன்னிடம் நாங்கள் பாதுகாப்புத் தேடுகிறோம்; அவர்களை எதிர்ப்பதில் உன்னையே முன்னிறுத்துகிறோம்.) இதை அபூதாவூத் பதிவு செய்துள்ளார்."},"28":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=40&ayah=29\" class=\"link\">40:29</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 40:29 ஐ பார்க்கவும்"},"29":{"html":"<strong>ஃபிர்அவ்னின் குடும்பத்தைச் சேர்ந்த முஃமினான ஒரு மனிதர் மூஸா (அலை) அவர்களுக்கு ஆதரவளித்தது</strong><br />\r\n<br />\r\nஇந்த இறைநம்பிக்கை கொண்ட (முஃமின்) மனிதர் ஃபிர்அவ்னின் குடும்பத்தைச் சேர்ந்த ஒரு கிப்தி (எகிப்தியர்) என்பதே பரவலாக அறியப்பட்ட கருத்தாகும். அஸ்-ஸுத்தி அவர்கள், இவர் ஃபிர்அவ்னின் தந்தையுடைய சகோதரரின் மகன் (பெரியப்பா அல்லது சித்தப்பா மகன்) என்று கூறினார்கள். மேலும், மூஸா (அலை) அவர்களுடன் தப்பித்துக் காப்பாற்றப்பட்டவர் இவரே என்றும் கூறப்படுகிறது. இப்னு ஜுரைஜ் அவர்கள் அறிவித்தார்கள்: இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்: \"ஃபிர்அவ்னின் குடும்பத்தைச் சேர்ந்தவர்களில் இந்த மனிதர், ஃபிர்அவ்னின் மனைவி மற்றும் பின்வருமாறு கூறியவரைத் தவிர வேறு எவரும் ஈமான் கொள்ளவில்லை:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَـمُوسَى</span> <span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">الْمَلأَ</span> <span class=\"quran-arabic-font text-success\">يَأْتَمِرُونَ</span> <span class=\"quran-arabic-font text-success\">بِكَ</span> <span class=\"quran-arabic-font text-success\">لِيَقْتُلُوكَ</span><br />\r\n<br />\r\n('மூஸாவே! நிச்சயமாக, தலைவர்கள் உம்மைக் கொல்வதற்காக உமக்கு எதிராகச் சதி செய்கிறார்கள்.')\" (<a href=\"qurandisp.php?sura=28&ayah=20\" class=\"link\">28:20</a>). இதனை இப்னு அபீ ஹாதிம் அவர்கள் பதிவு செய்துள்ளார்கள். இந்த மனிதர் தனது ஈமானை (இறைநம்பிக்கையை) தனது மக்களான எகிப்தியர்களிடமிருந்து மறைத்து வைத்திருந்தார். ஃபிர்அவ்ன் பின்வருமாறு கூறிய அந்த நாளைத் தவிர வேறு எப்போதும் அவர் அதனை வெளிப்படுத்தவில்லை:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">ذَرُونِى</span> <span class=\"quran-arabic-font text-success\">أَقْتُلْ</span> <span class=\"quran-arabic-font text-success\">مُوسَى</span><br />\r\n<br />\r\n(மூஸாவைக் கொல்ல என்னை விடுங்கள்). அப்போது அந்த மனிதர் அல்லாஹ்வுக்காகக் கோபம் கொண்டார். ஹதீஸில் கூறப்பட்டுள்ளபடி, அநீதியான ஆட்சியாளருக்கு முன்னால் நீதியான வார்த்தையைக் கூறுவதே ஜிஹாதில் சிறந்ததாகும். இந்த மனிதர் ஃபிர்அவ்னிடம் கூறிய வார்த்தைகளை விட இதற்குச் சிறந்த உதாரணம் வேறேதும் இருக்க முடியாது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَتَقْتُلُونَ</span> <span class=\"quran-arabic-font text-success\">رَجُلاً</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">يَقُولَ</span> <span class=\"quran-arabic-font text-success\">رَبِّىَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span><br />\r\n<br />\r\n('என் இறைவன் அல்லாஹ்' என்று கூறுவதற்காகவா ஒரு மனிதரை நீங்கள் கொல்கிறீர்கள்?)<br />\r\n<br />\r\nஇதே போன்றதொரு சம்பவத்தை இமாம் புகாரி அவர்கள் தமது ஸஹீஹில் உர்வா பின் அஸ்-ஸுபைர் (ரழி) அவர்களின் அறிவிப்பாகப் பதிவு செய்துள்ளார்கள். அவர் கூறினார்கள்: \"நான் அப்துல்லாஹ் பின் அம்ர் பின் அல்-ஆஸ் (ரழி) அவர்களிடம், 'அல்லாஹ்வின் தூதர் (ஸல்) அவர்களுக்கு முஷ்ரிக்குகள் செய்த மிகக் கொடிய காரியம் எது?' என்று கேட்டேன். அதற்கு அவர்கள் கூறினார்கள்: 'அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கஅபாவின் முற்றத்தில் தொழுது கொண்டிருந்தபோது, உக்பா பின் அபீ முஐத் வந்து அல்லாஹ்வின் தூதர் (ஸல்) அவர்களின் தோளைப் பிடித்து, அவர்களின் ஆடையைக் கழுத்தைச் சுற்றித் திருகி நெரிக்கத் தொடங்கினான். அப்போது அபூபக்ர் (ரழி) அவர்கள் வந்து உக்பாவின் தோளைப் பிடித்து, அவரை நபி (ஸல்) அவர்களிடமிருந்து தள்ளிவிட்டுப் பின்வருமாறு கூறினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَتَقْتُلُونَ</span> <span class=\"quran-arabic-font text-success\">رَجُلاً</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">يَقُولَ</span> <span class=\"quran-arabic-font text-success\">رَبِّىَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">وَقَدْ</span> <span class=\"quran-arabic-font text-success\">جَآءَكُمْ</span> <span class=\"quran-arabic-font text-success\">بِالْبَيِّنَـتِ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">رَّبِّكُمْ</span><br />\r\n<br />\r\n('என் இறைவன் அல்லாஹ்' என்று கூறுவதாலும், அவர் உங்கள் இறைவனிடமிருந்து தெளிவான சான்றுகளுடன் உங்களிடம் வந்திருப்பதாலும் ஒரு மனிதரை நீங்கள் கொல்கிறீர்களா?).\" இதனை புகாரி பதிவு செய்துள்ளார். அல்லாஹ்வின் கூற்றான:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَقَدْ</span> <span class=\"quran-arabic-font text-success\">جَآءَكُمْ</span> <span class=\"quran-arabic-font text-success\">بِالْبَيِّنَـتِ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">رَّبِّكُمْ</span><br />\r\n<br />\r\n(மேலும் அவர் உங்கள் இறைவனிடமிருந்து தெளிவான சான்றுகளுடன் உங்களிடம் வந்துள்ளார்) என்பதன் பொருள்: \"ஒரு மனிதர் 'என் இறைவன் அல்லாஹ்' என்று கூறி, தான் கூறுவது உண்மை என்பதற்கு ஆதாரங்களையும் கொண்டு வந்திருக்கும்போது அவரை நீங்கள் எப்படிக் கொல்ல முடியும்?\" என்பதாகும். பின்னர், வாதத்திற்காக அவர்களுடன் இணங்கிப் போய் அவர் கூறினார்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَإِن</span> <span class=\"quran-arabic-font text-success\">يَكُ</span> <span class=\"quran-arabic-font text-success\">كَـذِباً</span> <span class=\"quran-arabic-font text-success\">فَعَلَيْهِ</span> <span class=\"quran-arabic-font text-success\">كَذِبُهُ</span> <span class=\"quran-arabic-font text-success\">وَإِن</span> <span class=\"quran-arabic-font text-success\">يَكُ</span> <span class=\"quran-arabic-font text-success\">صَـدِقاً</span> <span class=\"quran-arabic-font text-success\">يُصِبْكُمْ</span> <span class=\"quran-arabic-font text-success\">بَعْضُ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">يَعِدُكُمْ</span><br />\r\n<br />\r\n(அவர் பொய்யராக இருந்தால், அவரது பொய்யின் பாவம் அவர் மீதே சேரும்; ஆனால் அவர் உண்மையாளராக இருந்தால், அவர் உங்களுக்கு எச்சரிக்கும் வேதனைகளில் சில உங்களை வந்தடையும்.) இதன் பொருள்: 'அவர் கூறுவதை நீங்கள் நம்பவில்லை என்றால், அவரைத் தொந்தரவு செய்யாமல் விட்டுவிடுவதுதான் அறிவார்ந்த செயலாகும். அவர் பொய் சொல்பவராக இருந்தால், அந்தப் பொய்யிற்காக அல்லாஹ் அவரை இவ்வுலகிலும் மறுமையிலும் தண்டிப்பான். ஆனால் அவர் உண்மையாளராக இருந்து, நீங்கள் அவருக்குத் தீங்கு விளைவித்தால், அவர் எச்சரிக்கும் சில வேதனைகள் உங்களையும் வந்து சேரும். ஏனெனில் அவருக்கு எதிராகச் செயல்பட்டால் இவ்வுலகிலும் மறுமையிலும் தண்டனை கிடைக்கும் என்று அவர் எச்சரிக்கிறார். ஒருவேளை உங்கள் விஷயத்தில் அவர் உண்மையாளராகவும் இருக்கலாம், எனவே அவரையும் அவரது மக்களையும் எவ்விதத் தீங்கும் செய்யாமல் விட்டுவிடுங்கள்.' மூஸா (அலை) அவர்கள் ஃபிர்அவ்னிடமும் அவனது மக்களிடமும் தங்களை நிம்மதியாக விட்டுவிடுமாறு கேட்டதை அல்லாஹ் நமக்குக் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَقَدْ</span> <span class=\"quran-arabic-font text-success\">فَتَنَّا</span> <span class=\"quran-arabic-font text-success\">قَبْلَهُمْ</span> <span class=\"quran-arabic-font text-success\">قَوْمَ</span> <span class=\"quran-arabic-font text-success\">فِرْعَوْنَ</span> <span class=\"quran-arabic-font text-success\">وَجَآءَهُمْ</span> <span class=\"quran-arabic-font text-success\">رَسُولٌ</span> <span class=\"quran-arabic-font text-success\">كَرِيمٌ</span> - <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">أَدُّواْ</span> <span class=\"quran-arabic-font text-success\">إِلَىَّ</span> <span class=\"quran-arabic-font text-success\">عِبَادَ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">إِنِّى</span> <span class=\"quran-arabic-font text-success\">لَكُمْ</span> <span class=\"quran-arabic-font text-success\">رَسُولٌ</span> <span class=\"quran-arabic-font text-success\">أَمِينٌ</span><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَأَن</span> <span class=\"quran-arabic-font text-success\">لاَّ</span> <span class=\"quran-arabic-font text-success\">تَعْلُواْ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">إِنِّى</span> <span class=\"quran-arabic-font text-success\">ءَاتِيكُمْ</span> <span class=\"quran-arabic-font text-success\">بِسُلْطَانٍ</span> <span class=\"quran-arabic-font text-success\">مُّبِينٍ</span> - <span class=\"quran-arabic-font text-success\">وَإِنِّى</span> <span class=\"quran-arabic-font text-success\">عُذْتُ</span> <span class=\"quran-arabic-font text-success\">بِرَبِّى</span> <span class=\"quran-arabic-font text-success\">وَرَبِّكُمْ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">تَرْجُمُونِ</span> - <span class=\"quran-arabic-font text-success\">وَإِن</span> <span class=\"quran-arabic-font text-success\">لَّمْ</span> <span class=\"quran-arabic-font text-success\">تُؤْمِنُواْ</span> <span class=\"quran-arabic-font text-success\">لِى</span> <span class=\"quran-arabic-font text-success\">فَاعْتَزِلُونِ</span><br />\r\n<br />\r\n(நிச்சயமாக நாம் இவர்களுக்கு முன்னரே ஃபிர்அவ்னின் மக்களைச் சோதித்தோம். கண்ணியமிக்க ஒரு தூதர் அவர்களிடம் வந்து, \"அல்லாஹ்வின் அடியார்களை என்னிடம் ஒப்படையுங்கள். நிச்சயமாக நான் உங்களுக்கு நம்பிக்கைக்குரிய தூதராவேன். அல்லாஹ்வுக்கு எதிராகப் பெருமை அடிக்காதீர்கள். நிச்சயமாக நான் உங்களிடம் தெளிவான ஆதாரத்தைக் கொண்டு வந்துள்ளேன். நீங்கள் என்னைக் கல்லெறிந்து கொல்லாதவாறு என் இறைவனும் உங்கள் இறைவனுமாகிய அல்லாஹ்விடம் நான் பாதுகாப்புத் தேடுகிறேன். நீங்கள் என் மீது நம்பிக்கை கொள்ளாவிட்டால், என்னைவிட்டு விலகிக் கொள்ளுங்கள் (என்னைத் தொந்தரவு செய்யாதீர்கள்)\" என்று கூறினார்.) (<a href=\"qurandisp.php?sura=44&ayah=17\" class=\"link\">44:17</a>-21).<br />\r\n<br />\r\nஅதேபோலவே, அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் குறைஷிகளிடம் தங்களைத் தொந்தரவு செய்யாமல் விட்டுவிடுமாறும், அல்லாஹ்வின் அடியார்களை அல்லாஹ்வின் பக்கம் அழைக்க அனுமதிக்குமாறும் கூறினார்கள். தமக்கும் அவர்களுக்கும் இடையிலான உறவுமுறைக்காகத் தமக்குத் தீங்கு செய்ய வேண்டாம் என்று அவர்கள் வேண்டினார்கள். அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قُل</span> <span class=\"quran-arabic-font text-success\">لاَّ</span> <span class=\"quran-arabic-font text-success\">أَسْـَلُكُمْ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span> <span class=\"quran-arabic-font text-success\">أَجْراً</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">الْمَوَدَّةَ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْقُرْبَى</span><br />\r\n<br />\r\n(கூறுவீராக: \"உறவினர்களிடம் அன்பு செலுத்துவதைத் தவிர, இதற்காக நான் உங்களிடம் யாதொரு கூலியையும் கேட்கவில்லை.\") (<a href=\"qurandisp.php?sura=42&ayah=23\" class=\"link\">42:23</a>). இதன் பொருள்: 'எனக்கும் உங்களுக்குமிடையிலான உறவின் காரணமாக எனக்குத் தீங்கு செய்யாதீர்கள்; எனது அழைப்பை மக்களிடம் எடுத்துரைக்க என்னை விடுங்கள்.' இதுவே அல்-ஹுதைபிய்யா உடன்படிக்கையின் அடிப்படையாக அமைந்தது. அது ஒரு தெளிவான வெற்றியாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَهْدِى</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">مُسْرِفٌ</span> <span class=\"quran-arabic-font text-success\">كَذَّابٌ</span><br />\r\n<br />\r\n(நிச்சயமாக, அல்லாஹ் வரம்பு மீறுபவனையும், பொய்யனையும் நேர்வழியில் செலுத்தமாட்டான்!) இதன் பொருள்: 'நீங்கள் கூறுவது போல் அல்லாஹ்விடமிருந்து வந்ததாகக் கூறும் இவர் பொய்யராக இருந்தால், இவரது பேச்சும் செயலும் முரண்பாடானதாக இருக்கும், அது அனைவருக்கும் எளிதில் தெரிந்துவிடும். ஆனால் இந்த மனிதரோ நேர்மையானவராக இருக்கிறார், அவரது பேச்சும் சீராக உள்ளது. அவர் பாவியாகவும் பொய்யராகவும் இருந்திருந்தால் அல்லாஹ் அவருக்கு நேர்வழி காட்டியிருக்க மாட்டான்; நீங்கள் காண்பது போல் அவரது வார்த்தைகளும் செயல்களும் அறிவார்ந்ததாகவும் சீராகவும் இருக்காது.' பின்னர் அந்த முஃமின் தனது மக்களுக்கு அல்லாஹ் வழங்கிய அருட்கொடைகளை அவர்கள் இழந்துவிடுவார்கள் என்றும், அல்லாஹ்வின் தண்டனை அவர்கள் மீது இறங்கும் என்றும் எச்சரித்தார்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَـقَوْمِ</span> <span class=\"quran-arabic-font text-success\">لَكُمُ</span> <span class=\"quran-arabic-font text-success\">الْمُلْكُ</span> <span class=\"quran-arabic-font text-success\">الْيَوْمَ</span> <span class=\"quran-arabic-font text-success\">ظَـهِرِينَ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الاٌّرْضِ</span><br />\r\n<br />\r\n(என் மக்களே! இன்று ஆட்சி உங்களுடையது; பூமியில் நீங்களே அதிகாரம் செலுத்துபவர்களாக இருக்கிறீர்கள்.) இதன் பொருள்: 'அல்லாஹ் இந்த ஆட்சியையும், அதிகாரத்தையும், வலிமையையும் உங்களுக்கு வழங்கி அருள்புரிந்துள்ளான். எனவே அவனுக்கு நன்றி செலுத்தி அவனது தூதரை ஈமான் கொள்வதன் மூலம் இந்த அருளைப் பேணுங்கள். அவனது தூதரை நீங்கள் நிராகரித்தால் அல்லாஹ்வின் தண்டனைக்கு அஞ்சுங்கள்.'<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَمَن</span> <span class=\"quran-arabic-font text-success\">يَنصُرُنَا</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">بَأْسِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">جَآءَنَا</span><br />\r\n<br />\r\n(அல்லாஹ்வின் வேதனை நமக்கேதும் வந்துவிட்டால், அதிலிருந்து நம்மைக் காப்பாற்றுபவர் யார்?) இதன் பொருள்: 'அல்லாஹ் நம்மைத் தண்டிக்க நாடினால், இந்த வீரர்களும் படைகளும் உங்களுக்கு எந்தப் பயனும் அளிக்காது, அல்லாஹ்வின் தண்டனையைத் தடுக்கவும் முடியாது.' ஃபிர்அவ்னை விட ஆட்சிப் பொறுப்பிற்குத் தகுதியான அந்த நேர்மையான மனிதரின் அறிவுரைக்கு பதிலளிக்கும் விதமாக ஃபிர்அவ்ன் தன் மக்களிடம் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مَآ</span> <span class=\"quran-arabic-font text-success\">أُرِيكُمْ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">مَآ</span> <span class=\"quran-arabic-font text-success\">أَرَى</span><br />\r\n<br />\r\n(நான் எதைக் காண்கிறேனோ அதைத் தவிர வேறெதையும் உங்களுக்கு நான் காட்டவில்லை.) இதன் பொருள்: 'எனக்கு எது நல்லது என்று தோன்றுகிறதோ அதையே உங்களுக்கு அறிவுறுத்துகிறேன்.' ஆனால் ஃபிர்அவ்ன் பொய்யுரைத்தான். மூஸா (அலை) அவர்கள் கொண்டு வந்த செய்தி உண்மை என்பதை அவன் உள்ளூர அறிந்தே இருந்தான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">لَقَدْ</span> <span class=\"quran-arabic-font text-success\">عَلِمْتَ</span> <span class=\"quran-arabic-font text-success\">مَآ</span> <span class=\"quran-arabic-font text-success\">أَنزَلَ</span> <span class=\"quran-arabic-font text-success\">هَـؤُلاءِ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">رَبُّ</span> <span class=\"quran-arabic-font text-success\">السَّمَـوَتِ</span> <span class=\"quran-arabic-font text-success\">وَالاٌّرْضِ</span> <span class=\"quran-arabic-font text-success\">بَصَآئِرَ</span><br />\r\n<br />\r\n(அதற்கு மூஸா, \"வானங்களுக்கும் பூமிக்கும் இறைவனான அல்லாஹ்வே இந்த அத்தாட்சிகளை அறிவொளியாக இறக்கினான் என்பதை நீ நிச்சயமாக அறிவாய்\" என்று கூறினார்.) (<a href=\"qurandisp.php?sura=17&ayah=102\" class=\"link\">17:102</a>)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَجَحَدُواْ</span> <span class=\"quran-arabic-font text-success\">بِهَا</span> <span class=\"quran-arabic-font text-success\">وَاسْتَيْقَنَتْهَآ</span> <span class=\"quran-arabic-font text-success\">أَنفُسُهُمْ</span> <span class=\"quran-arabic-font text-success\">ظُلْماً</span> <span class=\"quran-arabic-font text-success\">وَعُلُوّاً</span><br />\r\n<br />\r\n(அவர்கள் அநியாயமாகவும் பெருமையாகவும் அவற்றை (அந்த அத்தாட்சிகளை) மறுத்தார்கள். எனினும் அவர்களது உள்ளங்கள் அவற்றை உண்மை என உறுதியாக நம்பின.) (<a href=\"qurandisp.php?sura=27&ayah=14\" class=\"link\">27:14</a>)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مَآ</span> <span class=\"quran-arabic-font text-success\">أُرِيكُمْ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">مَآ</span> <span class=\"quran-arabic-font text-success\">أَرَى</span><br />\r\n<br />\r\n(நான் எதைக் காண்கிறேனோ அதைத் தவிர வேறெதையும் உங்களுக்கு நான் காட்டவில்லை.) - ஃபிர்அவ்ன் ஒரு பொய்யையும் இட்டுக்கட்டலையும் கூறினான். அவன் அல்லாஹ்விற்கும் அவனது தூதருக்கும் துரோகம் செய்தான்; தனது மக்களுக்குத் தவறான ஆலோசனை கூறி அவர்களை ஏமாற்றினான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَآ</span> <span class=\"quran-arabic-font text-success\">أَهْدِيكُمْ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">سَبِيلَ</span> <span class=\"quran-arabic-font text-success\">الرَّشَادِ</span><br />\r\n<br />\r\n(மேலும், நான் உங்களுக்கு நேர்வழியின் பக்கமே வழிகாட்டுகிறேன்!) இதன் பொருள்: 'உண்மைக்கும் நேர்மைக்கும் மட்டுமே நான் உங்களை அழைக்கிறேன்' என்பதாகும். இதுவும் ஒரு பொய்யே. ஆனால் அவனது மக்கள் அவனுக்குக் கீழ்ப்படிந்து அவனைப் பின்பற்றினார்கள். அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَاتَّبَعُواْ</span> <span class=\"quran-arabic-font text-success\">أَمْرَ</span> <span class=\"quran-arabic-font text-success\">فِرْعَوْنَ</span> <span class=\"quran-arabic-font text-success\">وَمَآ</span> <span class=\"quran-arabic-font text-success\">أَمْرُ</span> <span class=\"quran-arabic-font text-success\">فِرْعَوْنَ</span> <span class=\"quran-arabic-font text-success\">بِرَشِيدٍ</span><br />\r\n<br />\r\n(அவர்கள் ஃபிர்அவ்னின் கட்டளையைப் பின்பற்றினார்கள். ஆனால் ஃபிர்அவ்னின் கட்டளை நேர்வழி காட்டுவதாக இருக்கவில்லை.) (<a href=\"qurandisp.php?sura=11&ayah=97\" class=\"link\">11:97</a>).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَأَضَلَّ</span> <span class=\"quran-arabic-font text-success\">فِرْعَوْنُ</span> <span class=\"quran-arabic-font text-success\">قَوْمَهُ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">هَدَى</span><br />\r\n<br />\r\n(மேலும் ஃபிர்அவ்ன் தன் மக்களை வழிதவறச் செய்தான்; அவன் அவர்களுக்கு நேர்வழி காட்டவில்லை.) (<a href=\"qurandisp.php?sura=20&ayah=79\" class=\"link\">20:79</a>).<br />\r\n<br />\r\nஒரு ஹதீஸில் கூறப்பட்டுள்ளதாவது:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">إِمَام</span> <span class=\"quran-arabic-font text-success\">يَمُوتُ</span> <span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">يَمُوتُ</span> <span class=\"quran-arabic-font text-success\">وَهُوَ</span> <span class=\"quran-arabic-font text-success\">غَاشٌّ</span> <span class=\"quran-arabic-font text-success\">لِرَعِيَّتِهِ،</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">لَمْ</span> <span class=\"quran-arabic-font text-success\">يَرَحْ</span> <span class=\"quran-arabic-font text-success\">رَائِحَةَ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةِ،</span> <span class=\"quran-arabic-font text-success\">وَإِنَّ</span> <span class=\"quran-arabic-font text-success\">رِيحَهَا</span> <span class=\"quran-arabic-font text-success\">لَيُوجَدُ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">مَسِيرَةِ</span> <span class=\"quran-arabic-font text-success\">خَمْسِمِائَةِ</span> <span class=\"quran-arabic-font text-success\">عَام</span>»<br />\r\n<br />\r\n(\"தன் குடிமக்களை ஏமாற்றிய நிலையில் மரணிக்கும் எந்தவொரு தலைவரும் சொர்க்கத்தின் நறுமணத்தை நுகர மாட்டார். அதன் நறுமணமோ ஐநூறு ஆண்டு கால பயணத் தூரத்திலிருந்தே வீசக்கூடியதாகும்.\") அல்லாஹ்வே நேரான பாதைக்கு வழிகாட்டுபவன்.<br />\r\n<br />\r\n<br />\r\n<br />","text":"ஃபிர்அவ்னின் குடும்பத்தைச் சேர்ந்த முஃமினான ஒரு மனிதர் மூஸா (அலை) அவர்களுக்கு ஆதரவளித்தது\n\r\n\n\r\nஇந்த இறைநம்பிக்கை கொண்ட (முஃமின்) மனிதர் ஃபிர்அவ்னின் குடும்பத்தைச் சேர்ந்த ஒரு கிப்தி (எகிப்தியர்) என்பதே பரவலாக அறியப்பட்ட கருத்தாகும். அஸ்-ஸுத்தி அவர்கள், இவர் ஃபிர்அவ்னின் தந்தையுடைய சகோதரரின் மகன் (பெரியப்பா அல்லது சித்தப்பா மகன்) என்று கூறினார்கள். மேலும், மூஸா (அலை) அவர்களுடன் தப்பித்துக் காப்பாற்றப்பட்டவர் இவரே என்றும் கூறப்படுகிறது. இப்னு ஜுரைஜ் அவர்கள் அறிவித்தார்கள்: இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்: \"ஃபிர்அவ்னின் குடும்பத்தைச் சேர்ந்தவர்களில் இந்த மனிதர், ஃபிர்அவ்னின் மனைவி மற்றும் பின்வருமாறு கூறியவரைத் தவிர வேறு எவரும் ஈமான் கொள்ளவில்லை:\n\r\n\n\r\nيَـمُوسَى إِنَّ الْمَلأَ يَأْتَمِرُونَ بِكَ لِيَقْتُلُوكَ\n\r\n\n\r\n('மூஸாவே! நிச்சயமாக, தலைவர்கள் உம்மைக் கொல்வதற்காக உமக்கு எதிராகச் சதி செய்கிறார்கள்.')\" (28:20). இதனை இப்னு அபீ ஹாதிம் அவர்கள் பதிவு செய்துள்ளார்கள். இந்த மனிதர் தனது ஈமானை (இறைநம்பிக்கையை) தனது மக்களான எகிப்தியர்களிடமிருந்து மறைத்து வைத்திருந்தார். ஃபிர்அவ்ன் பின்வருமாறு கூறிய அந்த நாளைத் தவிர வேறு எப்போதும் அவர் அதனை வெளிப்படுத்தவில்லை:\n\r\n\n\r\nذَرُونِى أَقْتُلْ مُوسَى\n\r\n\n\r\n(மூஸாவைக் கொல்ல என்னை விடுங்கள்). அப்போது அந்த மனிதர் அல்லாஹ்வுக்காகக் கோபம் கொண்டார். ஹதீஸில் கூறப்பட்டுள்ளபடி, அநீதியான ஆட்சியாளருக்கு முன்னால் நீதியான வார்த்தையைக் கூறுவதே ஜிஹாதில் சிறந்ததாகும். இந்த மனிதர் ஃபிர்அவ்னிடம் கூறிய வார்த்தைகளை விட இதற்குச் சிறந்த உதாரணம் வேறேதும் இருக்க முடியாது:\n\r\n\n\r\nأَتَقْتُلُونَ رَجُلاً أَن يَقُولَ رَبِّىَ اللَّهُ\n\r\n\n\r\n('என் இறைவன் அல்லாஹ்' என்று கூறுவதற்காகவா ஒரு மனிதரை நீங்கள் கொல்கிறீர்கள்?)\n\r\n\n\r\nஇதே போன்றதொரு சம்பவத்தை இமாம் புகாரி அவர்கள் தமது ஸஹீஹில் உர்வா பின் அஸ்-ஸுபைர் (ரழி) அவர்களின் அறிவிப்பாகப் பதிவு செய்துள்ளார்கள். அவர் கூறினார்கள்: \"நான் அப்துல்லாஹ் பின் அம்ர் பின் அல்-ஆஸ் (ரழி) அவர்களிடம், 'அல்லாஹ்வின் தூதர் (ஸல்) அவர்களுக்கு முஷ்ரிக்குகள் செய்த மிகக் கொடிய காரியம் எது?' என்று கேட்டேன். அதற்கு அவர்கள் கூறினார்கள்: 'அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கஅபாவின் முற்றத்தில் தொழுது கொண்டிருந்தபோது, உக்பா பின் அபீ முஐத் வந்து அல்லாஹ்வின் தூதர் (ஸல்) அவர்களின் தோளைப் பிடித்து, அவர்களின் ஆடையைக் கழுத்தைச் சுற்றித் திருகி நெரிக்கத் தொடங்கினான். அப்போது அபூபக்ர் (ரழி) அவர்கள் வந்து உக்பாவின் தோளைப் பிடித்து, அவரை நபி (ஸல்) அவர்களிடமிருந்து தள்ளிவிட்டுப் பின்வருமாறு கூறினார்கள்:\n\r\n\n\r\nأَتَقْتُلُونَ رَجُلاً أَن يَقُولَ رَبِّىَ اللَّهُ وَقَدْ جَآءَكُمْ بِالْبَيِّنَـتِ مِن رَّبِّكُمْ\n\r\n\n\r\n('என் இறைவன் அல்லாஹ்' என்று கூறுவதாலும், அவர் உங்கள் இறைவனிடமிருந்து தெளிவான சான்றுகளுடன் உங்களிடம் வந்திருப்பதாலும் ஒரு மனிதரை நீங்கள் கொல்கிறீர்களா?).\" இதனை புகாரி பதிவு செய்துள்ளார். அல்லாஹ்வின் கூற்றான:\n\r\n\n\r\nوَقَدْ جَآءَكُمْ بِالْبَيِّنَـتِ مِن رَّبِّكُمْ\n\r\n\n\r\n(மேலும் அவர் உங்கள் இறைவனிடமிருந்து தெளிவான சான்றுகளுடன் உங்களிடம் வந்துள்ளார்) என்பதன் பொருள்: \"ஒரு மனிதர் 'என் இறைவன் அல்லாஹ்' என்று கூறி, தான் கூறுவது உண்மை என்பதற்கு ஆதாரங்களையும் கொண்டு வந்திருக்கும்போது அவரை நீங்கள் எப்படிக் கொல்ல முடியும்?\" என்பதாகும். பின்னர், வாதத்திற்காக அவர்களுடன் இணங்கிப் போய் அவர் கூறினார்:\n\r\n\n\r\nوَإِن يَكُ كَـذِباً فَعَلَيْهِ كَذِبُهُ وَإِن يَكُ صَـدِقاً يُصِبْكُمْ بَعْضُ الَّذِى يَعِدُكُمْ\n\r\n\n\r\n(அவர் பொய்யராக இருந்தால், அவரது பொய்யின் பாவம் அவர் மீதே சேரும்; ஆனால் அவர் உண்மையாளராக இருந்தால், அவர் உங்களுக்கு எச்சரிக்கும் வேதனைகளில் சில உங்களை வந்தடையும்.) இதன் பொருள்: 'அவர் கூறுவதை நீங்கள் நம்பவில்லை என்றால், அவரைத் தொந்தரவு செய்யாமல் விட்டுவிடுவதுதான் அறிவார்ந்த செயலாகும். அவர் பொய் சொல்பவராக இருந்தால், அந்தப் பொய்யிற்காக அல்லாஹ் அவரை இவ்வுலகிலும் மறுமையிலும் தண்டிப்பான். ஆனால் அவர் உண்மையாளராக இருந்து, நீங்கள் அவருக்குத் தீங்கு விளைவித்தால், அவர் எச்சரிக்கும் சில வேதனைகள் உங்களையும் வந்து சேரும். ஏனெனில் அவருக்கு எதிராகச் செயல்பட்டால் இவ்வுலகிலும் மறுமையிலும் தண்டனை கிடைக்கும் என்று அவர் எச்சரிக்கிறார். ஒருவேளை உங்கள் விஷயத்தில் அவர் உண்மையாளராகவும் இருக்கலாம், எனவே அவரையும் அவரது மக்களையும் எவ்விதத் தீங்கும் செய்யாமல் விட்டுவிடுங்கள்.' மூஸா (அலை) அவர்கள் ஃபிர்அவ்னிடமும் அவனது மக்களிடமும் தங்களை நிம்மதியாக விட்டுவிடுமாறு கேட்டதை அல்லாஹ் நமக்குக் கூறுகிறான்:\n\r\n\n\r\nوَلَقَدْ فَتَنَّا قَبْلَهُمْ قَوْمَ فِرْعَوْنَ وَجَآءَهُمْ رَسُولٌ كَرِيمٌ - أَنْ أَدُّواْ إِلَىَّ عِبَادَ اللَّهِ إِنِّى لَكُمْ رَسُولٌ أَمِينٌ\n\r\n\n\r\nوَأَن لاَّ تَعْلُواْ عَلَى اللَّهِ إِنِّى ءَاتِيكُمْ بِسُلْطَانٍ مُّبِينٍ - وَإِنِّى عُذْتُ بِرَبِّى وَرَبِّكُمْ أَن تَرْجُمُونِ - وَإِن لَّمْ تُؤْمِنُواْ لِى فَاعْتَزِلُونِ\n\r\n\n\r\n(நிச்சயமாக நாம் இவர்களுக்கு முன்னரே ஃபிர்அவ்னின் மக்களைச் சோதித்தோம். கண்ணியமிக்க ஒரு தூதர் அவர்களிடம் வந்து, \"அல்லாஹ்வின் அடியார்களை என்னிடம் ஒப்படையுங்கள். நிச்சயமாக நான் உங்களுக்கு நம்பிக்கைக்குரிய தூதராவேன். அல்லாஹ்வுக்கு எதிராகப் பெருமை அடிக்காதீர்கள். நிச்சயமாக நான் உங்களிடம் தெளிவான ஆதாரத்தைக் கொண்டு வந்துள்ளேன். நீங்கள் என்னைக் கல்லெறிந்து கொல்லாதவாறு என் இறைவனும் உங்கள் இறைவனுமாகிய அல்லாஹ்விடம் நான் பாதுகாப்புத் தேடுகிறேன். நீங்கள் என் மீது நம்பிக்கை கொள்ளாவிட்டால், என்னைவிட்டு விலகிக் கொள்ளுங்கள் (என்னைத் தொந்தரவு செய்யாதீர்கள்)\" என்று கூறினார்.) (44:17-21).\n\r\n\n\r\nஅதேபோலவே, அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் குறைஷிகளிடம் தங்களைத் தொந்தரவு செய்யாமல் விட்டுவிடுமாறும், அல்லாஹ்வின் அடியார்களை அல்லாஹ்வின் பக்கம் அழைக்க அனுமதிக்குமாறும் கூறினார்கள். தமக்கும் அவர்களுக்கும் இடையிலான உறவுமுறைக்காகத் தமக்குத் தீங்கு செய்ய வேண்டாம் என்று அவர்கள் வேண்டினார்கள். அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nقُل لاَّ أَسْـَلُكُمْ عَلَيْهِ أَجْراً إِلاَّ الْمَوَدَّةَ فِى الْقُرْبَى\n\r\n\n\r\n(கூறுவீராக: \"உறவினர்களிடம் அன்பு செலுத்துவதைத் தவிர, இதற்காக நான் உங்களிடம் யாதொரு கூலியையும் கேட்கவில்லை.\") (42:23). இதன் பொருள்: 'எனக்கும் உங்களுக்குமிடையிலான உறவின் காரணமாக எனக்குத் தீங்கு செய்யாதீர்கள்; எனது அழைப்பை மக்களிடம் எடுத்துரைக்க என்னை விடுங்கள்.' இதுவே அல்-ஹுதைபிய்யா உடன்படிக்கையின் அடிப்படையாக அமைந்தது. அது ஒரு தெளிவான வெற்றியாகும்.\n\r\n\n\r\nإِنَّ اللَّهَ لاَ يَهْدِى مَنْ هُوَ مُسْرِفٌ كَذَّابٌ\n\r\n\n\r\n(நிச்சயமாக, அல்லாஹ் வரம்பு மீறுபவனையும், பொய்யனையும் நேர்வழியில் செலுத்தமாட்டான்!) இதன் பொருள்: 'நீங்கள் கூறுவது போல் அல்லாஹ்விடமிருந்து வந்ததாகக் கூறும் இவர் பொய்யராக இருந்தால், இவரது பேச்சும் செயலும் முரண்பாடானதாக இருக்கும், அது அனைவருக்கும் எளிதில் தெரிந்துவிடும். ஆனால் இந்த மனிதரோ நேர்மையானவராக இருக்கிறார், அவரது பேச்சும் சீராக உள்ளது. அவர் பாவியாகவும் பொய்யராகவும் இருந்திருந்தால் அல்லாஹ் அவருக்கு நேர்வழி காட்டியிருக்க மாட்டான்; நீங்கள் காண்பது போல் அவரது வார்த்தைகளும் செயல்களும் அறிவார்ந்ததாகவும் சீராகவும் இருக்காது.' பின்னர் அந்த முஃமின் தனது மக்களுக்கு அல்லாஹ் வழங்கிய அருட்கொடைகளை அவர்கள் இழந்துவிடுவார்கள் என்றும், அல்லாஹ்வின் தண்டனை அவர்கள் மீது இறங்கும் என்றும் எச்சரித்தார்:\n\r\n\n\r\nيَـقَوْمِ لَكُمُ الْمُلْكُ الْيَوْمَ ظَـهِرِينَ فِى الاٌّرْضِ\n\r\n\n\r\n(என் மக்களே! இன்று ஆட்சி உங்களுடையது; பூமியில் நீங்களே அதிகாரம் செலுத்துபவர்களாக இருக்கிறீர்கள்.) இதன் பொருள்: 'அல்லாஹ் இந்த ஆட்சியையும், அதிகாரத்தையும், வலிமையையும் உங்களுக்கு வழங்கி அருள்புரிந்துள்ளான். எனவே அவனுக்கு நன்றி செலுத்தி அவனது தூதரை ஈமான் கொள்வதன் மூலம் இந்த அருளைப் பேணுங்கள். அவனது தூதரை நீங்கள் நிராகரித்தால் அல்லாஹ்வின் தண்டனைக்கு அஞ்சுங்கள்.'\n\r\n\n\r\nفَمَن يَنصُرُنَا مِن بَأْسِ اللَّهِ إِن جَآءَنَا\n\r\n\n\r\n(அல்லாஹ்வின் வேதனை நமக்கேதும் வந்துவிட்டால், அதிலிருந்து நம்மைக் காப்பாற்றுபவர் யார்?) இதன் பொருள்: 'அல்லாஹ் நம்மைத் தண்டிக்க நாடினால், இந்த வீரர்களும் படைகளும் உங்களுக்கு எந்தப் பயனும் அளிக்காது, அல்லாஹ்வின் தண்டனையைத் தடுக்கவும் முடியாது.' ஃபிர்அவ்னை விட ஆட்சிப் பொறுப்பிற்குத் தகுதியான அந்த நேர்மையான மனிதரின் அறிவுரைக்கு பதிலளிக்கும் விதமாக ஃபிர்அவ்ன் தன் மக்களிடம் கூறினான்:\n\r\n\n\r\nمَآ أُرِيكُمْ إِلاَّ مَآ أَرَى\n\r\n\n\r\n(நான் எதைக் காண்கிறேனோ அதைத் தவிர வேறெதையும் உங்களுக்கு நான் காட்டவில்லை.) இதன் பொருள்: 'எனக்கு எது நல்லது என்று தோன்றுகிறதோ அதையே உங்களுக்கு அறிவுறுத்துகிறேன்.' ஆனால் ஃபிர்அவ்ன் பொய்யுரைத்தான். மூஸா (அலை) அவர்கள் கொண்டு வந்த செய்தி உண்மை என்பதை அவன் உள்ளூர அறிந்தே இருந்தான்.\n\r\n\n\r\nقَالَ لَقَدْ عَلِمْتَ مَآ أَنزَلَ هَـؤُلاءِ إِلاَّ رَبُّ السَّمَـوَتِ وَالاٌّرْضِ بَصَآئِرَ\n\r\n\n\r\n(அதற்கு மூஸா, \"வானங்களுக்கும் பூமிக்கும் இறைவனான அல்லாஹ்வே இந்த அத்தாட்சிகளை அறிவொளியாக இறக்கினான் என்பதை நீ நிச்சயமாக அறிவாய்\" என்று கூறினார்.) (17:102)\n\r\n\n\r\nوَجَحَدُواْ بِهَا وَاسْتَيْقَنَتْهَآ أَنفُسُهُمْ ظُلْماً وَعُلُوّاً\n\r\n\n\r\n(அவர்கள் அநியாயமாகவும் பெருமையாகவும் அவற்றை (அந்த அத்தாட்சிகளை) மறுத்தார்கள். எனினும் அவர்களது உள்ளங்கள் அவற்றை உண்மை என உறுதியாக நம்பின.) (27:14)\n\r\n\n\r\nمَآ أُرِيكُمْ إِلاَّ مَآ أَرَى\n\r\n\n\r\n(நான் எதைக் காண்கிறேனோ அதைத் தவிர வேறெதையும் உங்களுக்கு நான் காட்டவில்லை.) - ஃபிர்அவ்ன் ஒரு பொய்யையும் இட்டுக்கட்டலையும் கூறினான். அவன் அல்லாஹ்விற்கும் அவனது தூதருக்கும் துரோகம் செய்தான்; தனது மக்களுக்குத் தவறான ஆலோசனை கூறி அவர்களை ஏமாற்றினான்.\n\r\n\n\r\nوَمَآ أَهْدِيكُمْ إِلاَّ سَبِيلَ الرَّشَادِ\n\r\n\n\r\n(மேலும், நான் உங்களுக்கு நேர்வழியின் பக்கமே வழிகாட்டுகிறேன்!) இதன் பொருள்: 'உண்மைக்கும் நேர்மைக்கும் மட்டுமே நான் உங்களை அழைக்கிறேன்' என்பதாகும். இதுவும் ஒரு பொய்யே. ஆனால் அவனது மக்கள் அவனுக்குக் கீழ்ப்படிந்து அவனைப் பின்பற்றினார்கள். அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nفَاتَّبَعُواْ أَمْرَ فِرْعَوْنَ وَمَآ أَمْرُ فِرْعَوْنَ بِرَشِيدٍ\n\r\n\n\r\n(அவர்கள் ஃபிர்அவ்னின் கட்டளையைப் பின்பற்றினார்கள். ஆனால் ஃபிர்அவ்னின் கட்டளை நேர்வழி காட்டுவதாக இருக்கவில்லை.) (11:97).\n\r\n\n\r\nوَأَضَلَّ فِرْعَوْنُ قَوْمَهُ وَمَا هَدَى\n\r\n\n\r\n(மேலும் ஃபிர்அவ்ன் தன் மக்களை வழிதவறச் செய்தான்; அவன் அவர்களுக்கு நேர்வழி காட்டவில்லை.) (20:79).\n\r\n\n\r\nஒரு ஹதீஸில் கூறப்பட்டுள்ளதாவது:\n\r\n\n\r\n«مَا مِنْ إِمَام يَمُوتُ يَوْمَ يَمُوتُ وَهُوَ غَاشٌّ لِرَعِيَّتِهِ، إِلَّا لَمْ يَرَحْ رَائِحَةَ الْجَنَّةِ، وَإِنَّ رِيحَهَا لَيُوجَدُ مِنْ مَسِيرَةِ خَمْسِمِائَةِ عَام»\n\r\n\n\r\n(\"தன் குடிமக்களை ஏமாற்றிய நிலையில் மரணிக்கும் எந்தவொரு தலைவரும் சொர்க்கத்தின் நறுமணத்தை நுகர மாட்டார். அதன் நறுமணமோ ஐநூறு ஆண்டு கால பயணத் தூரத்திலிருந்தே வீசக்கூடியதாகும்.\") அல்லாஹ்வே நேரான பாதைக்கு வழிகாட்டுபவன்."},"30":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=40&ayah=35\" class=\"link\">40:35</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 40:35 ஐ பார்க்கவும்"},"31":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=40&ayah=35\" class=\"link\">40:35</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 40:35 ஐ பார்க்கவும்"},"32":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=40&ayah=35\" class=\"link\">40:35</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 40:35 ஐ பார்க்கவும்"},"33":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=40&ayah=35\" class=\"link\">40:35</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 40:35 ஐ பார்க்கவும்"},"34":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=40&ayah=35\" class=\"link\">40:35</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 40:35 ஐ பார்க்கவும்"},"35":{"html":"<span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">قَوْمِ</span> <span class=\"quran-arabic-font text-success\">إِنِّى</span> <span class=\"quran-arabic-font text-success\">أَخَافُ</span> <span class=\"quran-arabic-font text-success\">عَلَيْكُمْ</span> <span class=\"quran-arabic-font text-success\">مِّثْلَ</span> <span class=\"quran-arabic-font text-success\">يَوْمِ</span> <span class=\"quran-arabic-font text-success\">الْأَحْزَابِ</span> - <span class=\"quran-arabic-font text-success\">مِثْلَ</span> <span class=\"quran-arabic-font text-success\">دَأْبِ</span> <span class=\"quran-arabic-font text-success\">قَوْمِ</span> <span class=\"quran-arabic-font text-success\">نُوحٍ</span> <span class=\"quran-arabic-font text-success\">وَعَادٍ</span> <span class=\"quran-arabic-font text-success\">وَثَمُودَ</span> <span class=\"quran-arabic-font text-success\">وَالَّذِينَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">بَعْدِهِمْ</span><br />\r\n(என் சமூகத்தாரே! (உங்களுக்கு முன்னிருந்த) கூட்டத்தினர் சந்தித்த (அழிவு) நாளைப் போன்றதொரு நிலை உங்களுக்கும் ஏற்படுமோ என்று நான் மெய்யாகவே அஞ்சுகிறேன்!) அதாவது, நூஹ் (அலை) அவர்களின் சமூகம், ஆத், ஸமூத் மற்றும் அவர்களுக்குப் பின் வந்த நிராகரித்த சமூகத்தினர் போன்ற அல்லாஹ்வின் தூதர்களைப் பொய்ப்பித்த முந்தைய சமுதாயத்தினருக்கு ஏற்பட்ட கதியைப் பற்றி அவர் குறிப்பிடுகிறார். அல்லாஹ்வின் வேதனை அவர்கள் மீது எவ்வாறு இறங்கியது என்பதையும், அதிலிருந்து அவர்களைக் காப்பாற்றவோ அல்லது அந்தத் தண்டனையைத் தடுக்கவோ எவருமே இருக்கவில்லை என்பதையும் இது குறிக்கிறது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">يُرِيدُ</span> <span class=\"quran-arabic-font text-success\">ظُلْماً</span> <span class=\"quran-arabic-font text-success\">لِّلْعِبَادِ</span><br />\r\n(மேலும் அல்லாஹ் (தன்) அடியார்களுக்கு எவ்வித அநீதியும் இழைக்க நாடுவதில்லை.) அதாவது, அவர்கள் செய்த பாவங்களுக்காகவும், அவனது தூதர்களை நிராகரித்துப் பொய்ப்பித்ததற்காகவுமே அல்லாஹ் அவர்களை அழித்தான். இது அவர்கள் விஷயத்தில் நிறைவேற்றப்பட்ட அவனது கட்டளையும் விதியுமாகும். பிறகு அவர் கூறினார்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَيَا</span> <span class=\"quran-arabic-font text-success\">قَوْمِ</span> <span class=\"quran-arabic-font text-success\">إِنِّى</span> <span class=\"quran-arabic-font text-success\">أَخَافُ</span> <span class=\"quran-arabic-font text-success\">عَلَيْكُمْ</span> <span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">التَّنَادِ</span><br />\r\n(மேலும் என் சமூகத்தாரே! ஒருவரையொருவர் அழைத்து அலறிக் கொள்ளும் (மறுமை) நாளைப் பற்றி நான் உங்களுக்கு அஞ்சுகிறேன்.) அதாவது, கியாமத் (உயிர்த்தெழுதல்) நாள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">تُوَلُّونَ</span> <span class=\"quran-arabic-font text-success\">مُدْبِرِينَ</span><br />\r\n(அந்நாளில் நீங்கள் புறங்காட்டி ஓடுவீர்கள்.) அதாவது, (வேதனையைக் கண்டு) அஞ்சி ஓடுவது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">كَلاَّ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">وَزَرَ</span> - <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">رَبِّكَ</span> <span class=\"quran-arabic-font text-success\">يَوْمَئِذٍ</span> <span class=\"quran-arabic-font text-success\">الْمُسْتَقَرُّ</span><br />\r\n(அவ்வாறு அன்று! தப்பிச் செல்ல இடமே இல்லை! அந்நாளில் உமது இறைவனிடமே தங்குமிடம் உண்டு.) (<a href=\"qurandisp.php?sura=75&ayah=11\" class=\"link\">75:11</a>-12) அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">لَكُمْ</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">عَاصِمٍ</span><br />\r\n(அல்லாஹ்விடமிருந்து உங்களைக் காப்பவர் எவருமில்லை.) அதாவது, 'அல்லாஹ்வின் தண்டனையிலிருந்தும் வேதனையிலிருந்தும் உங்களைப் பாதுகாக்க எவருமே இருக்கமாட்டார்கள்' என்பதாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَن</span> <span class=\"quran-arabic-font text-success\">يُضْلِلِ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">فَمَا</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">هَادٍ</span><br />\r\n(மேலும் அல்லாஹ் யாரை வழிதவறச் செய்கிறானோ, அவருக்கு வழிகாட்டுபவர் எவருமில்லை.) அதாவது, அல்லாஹ் யாரை வழிதவறச் செய்கிறானோ, அவருக்கு அவனைத் தவிர வேறு எவரும் நேர்வழி காட்ட முடியாது. அல்லாஹ்வின் கூற்று:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَقَدْ</span> <span class=\"quran-arabic-font text-success\">جَآءَكُـمْ</span> <span class=\"quran-arabic-font text-success\">يُوسُفُ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">قَبْلُ</span> <span class=\"quran-arabic-font text-success\">بِالْبَيِّنَـتِ</span><br />\r\n(நிச்சயமாக இதற்கு முன்னர் யூஸுஃப் (அலை) அவர்கள் தெளிவான சான்றுகளுடன் உங்களிடம் வந்தார்கள்,) இது எகிப்து மக்களைக் குறிக்கிறது. மூஸா (அலை) அவர்களுக்கு முந்தைய காலத்தில், அதாவது, யூஸுஃப் இப்னு யஃகூப் இப்னு இஸ்ஹாக் இப்னு இப்ராஹீம் (அலை) எனும் எகிப்து அரசாங்கத்தில் உயர் பதவியில் இருந்த யூஸுஃப் (அலை) அவர்களை அல்லாஹ் ஒரு தூதராக அவர்களிடம் அனுப்பினான். அவர்கள் நீதியுடன் மக்களை அல்லாஹ்வின் பக்கம் அழைத்த ஒரு தூதராக இருந்தார்கள். ஆனால், அல்லாஹ்வை வணங்கும் விஷயத்தில் மக்கள் அவருக்குக் கீழ்ப்படியவில்லை; மாறாக, அரசாங்கத்தில் அவர் வகித்த பதவி தொடர்பான உலக விவகாரங்களில் மட்டுமே அவருக்குக் கீழ்ப்படிந்தார்கள். அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَمَا</span> <span class=\"quran-arabic-font text-success\">زِلْتُمْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">شَكٍّ</span> <span class=\"quran-arabic-font text-success\">مِّمَّا</span> <span class=\"quran-arabic-font text-success\">جَآءَكُـمْ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">هَلَكَ</span> <span class=\"quran-arabic-font text-success\">قُلْتُمْ</span> <span class=\"quran-arabic-font text-success\">لَن</span> <span class=\"quran-arabic-font text-success\">يَبْعَثَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">بَعْدِهِ</span> <span class=\"quran-arabic-font text-success\">رَسُولاً</span><br />\r\n(அவர் உங்களுக்குக் கொண்டு வந்தவற்றில் நீங்கள் தொடர்ந்து சந்தேகம் கொண்டவர்களாகவே இருந்தீர்கள். இறுதியில் அவர் இறந்தபோது: 'அவருக்குப் பிறகு அல்லாஹ் எந்தத் தூதரையும் அனுப்பவே மாட்டான்' என்று கூறினீர்கள்.) அதாவது, 'நீங்கள் நம்பிக்கையிழந்து, உங்கள் வீணான ஆசையினால் இவ்வாறு கூறினீர்கள்.'<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لَن</span> <span class=\"quran-arabic-font text-success\">يَبْعَثَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">بَعْدِهِ</span> <span class=\"quran-arabic-font text-success\">رَسُولاً</span><br />\r\n('அவருக்குப் பிறகு அல்லாஹ் எந்தத் தூதரையும் அனுப்பவே மாட்டான்.') இது அவர்கள் இறைத்தூதர்களை நிராகரித்ததாலும் பொய்ப்பித்ததாலும் ஏற்பட்ட நிலையாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">كَذَلِكَ</span> <span class=\"quran-arabic-font text-success\">يُضِلُّ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">مُسْرِفٌ</span> <span class=\"quran-arabic-font text-success\">مُّرْتَابٌ</span><br />\r\n(இவ்வாறே வரம்பு மீறுபவரையும், சந்தேகம் கொள்பவரையும் அல்லாஹ் வழிதவறச் செய்கிறான்.) அதாவது, ஒருவனது பாவச் செயல்களாலும் அவனது உள்ளத்திலுள்ள சந்தேகங்களாலும் அல்லாஹ் ஒருவனை வழிதவறச் செய்யும்போது அவனது நிலை இவ்வாறே இருக்கும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">يُجَادِلُونَ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">آيَاتِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">بِغَيْرِ</span> <span class=\"quran-arabic-font text-success\">سُلْطَانٍ</span> <span class=\"quran-arabic-font text-success\">أَتَاهُمْ</span><br />\r\n(தங்களுக்குக் கிடைத்த எந்த ஆதாரமும் இன்றி அல்லாஹ்வின் வசனங்களில் தர்க்கம் செய்பவர்கள்,) அதாவது, பொய்யைக் கொண்டு உண்மையை மறுக்க முயல்பவர்கள் மற்றும் அல்லாஹ்விடமிருந்து எந்தவொரு அத்தாட்சியும் இன்றி அவனது சான்றுகளைப் பற்றி தர்க்கம் செய்பவர்களை அல்லாஹ் கடுமையாக வெறுக்கிறான். அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">كَبُرَ</span> <span class=\"quran-arabic-font text-success\">مَقْتاً</span> <span class=\"quran-arabic-font text-success\">عِندَ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">وَعِندَ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">ءَامَنُواْ</span><br />\r\n(இது அல்லாஹ்விடத்திலும் நம்பிக்கை கொண்டவர்களிடத்திலும் மிகவும் வெறுக்கத்தக்கதாகும்.) அதாவது, இறைநம்பிக்கையாளர்களும் இத்தகையவர்களை வெறுப்பார்கள். மேலும் இவ்வாறானவர்களின் இதயங்களில் அல்லாஹ் முத்திரையிட்டு விடுகிறான்; அதன் பிறகு அவர்களால் எவ்வித நன்மையையும் அங்கீகரிக்க முடியாது, தீமையைத் தீமை என்று கண்டிக்கவும் முடியாது. அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">كَذَلِكَ</span> <span class=\"quran-arabic-font text-success\">يَطْبَعُ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">كُـلِّ</span> <span class=\"quran-arabic-font text-success\">قَلْبِ</span> <span class=\"quran-arabic-font text-success\">مُتَكَبِّرٍ</span> <span class=\"quran-arabic-font text-success\">جَبَّارٍ</span><br />\r\n(இவ்வாறே, பெருமையடிக்கும் ஒவ்வொரு கொடுங்கோலனின் இதயத்தின் மீதும் அல்லாஹ் முத்திரையிடுகிறான்.) அதாவது, அவர்கள் சத்தியத்தைப் பின்பற்ற முடியாதவாறு முத்திரையிடுகிறான்.<br />\r\n<br />","text":"يَا قَوْمِ إِنِّى أَخَافُ عَلَيْكُمْ مِّثْلَ يَوْمِ الْأَحْزَابِ - مِثْلَ دَأْبِ قَوْمِ نُوحٍ وَعَادٍ وَثَمُودَ وَالَّذِينَ مِن بَعْدِهِمْ\n\r\n(என் சமூகத்தாரே! (உங்களுக்கு முன்னிருந்த) கூட்டத்தினர் சந்தித்த (அழிவு) நாளைப் போன்றதொரு நிலை உங்களுக்கும் ஏற்படுமோ என்று நான் மெய்யாகவே அஞ்சுகிறேன்!) அதாவது, நூஹ் (அலை) அவர்களின் சமூகம், ஆத், ஸமூத் மற்றும் அவர்களுக்குப் பின் வந்த நிராகரித்த சமூகத்தினர் போன்ற அல்லாஹ்வின் தூதர்களைப் பொய்ப்பித்த முந்தைய சமுதாயத்தினருக்கு ஏற்பட்ட கதியைப் பற்றி அவர் குறிப்பிடுகிறார். அல்லாஹ்வின் வேதனை அவர்கள் மீது எவ்வாறு இறங்கியது என்பதையும், அதிலிருந்து அவர்களைக் காப்பாற்றவோ அல்லது அந்தத் தண்டனையைத் தடுக்கவோ எவருமே இருக்கவில்லை என்பதையும் இது குறிக்கிறது.\n\r\n\n\r\nوَمَا اللَّهُ يُرِيدُ ظُلْماً لِّلْعِبَادِ\n\r\n(மேலும் அல்லாஹ் (தன்) அடியார்களுக்கு எவ்வித அநீதியும் இழைக்க நாடுவதில்லை.) அதாவது, அவர்கள் செய்த பாவங்களுக்காகவும், அவனது தூதர்களை நிராகரித்துப் பொய்ப்பித்ததற்காகவுமே அல்லாஹ் அவர்களை அழித்தான். இது அவர்கள் விஷயத்தில் நிறைவேற்றப்பட்ட அவனது கட்டளையும் விதியுமாகும். பிறகு அவர் கூறினார்:\n\r\n\n\r\nوَيَا قَوْمِ إِنِّى أَخَافُ عَلَيْكُمْ يَوْمَ التَّنَادِ\n\r\n(மேலும் என் சமூகத்தாரே! ஒருவரையொருவர் அழைத்து அலறிக் கொள்ளும் (மறுமை) நாளைப் பற்றி நான் உங்களுக்கு அஞ்சுகிறேன்.) அதாவது, கியாமத் (உயிர்த்தெழுதல்) நாள்.\n\r\n\n\r\nيَوْمَ تُوَلُّونَ مُدْبِرِينَ\n\r\n(அந்நாளில் நீங்கள் புறங்காட்டி ஓடுவீர்கள்.) அதாவது, (வேதனையைக் கண்டு) அஞ்சி ஓடுவது.\n\r\n\n\r\nكَلاَّ لاَ وَزَرَ - إِلَى رَبِّكَ يَوْمَئِذٍ الْمُسْتَقَرُّ\n\r\n(அவ்வாறு அன்று! தப்பிச் செல்ல இடமே இல்லை! அந்நாளில் உமது இறைவனிடமே தங்குமிடம் உண்டு.) (75:11-12) அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nمَا لَكُمْ مِّنَ اللَّهِ مِنْ عَاصِمٍ\n\r\n(அல்லாஹ்விடமிருந்து உங்களைக் காப்பவர் எவருமில்லை.) அதாவது, 'அல்லாஹ்வின் தண்டனையிலிருந்தும் வேதனையிலிருந்தும் உங்களைப் பாதுகாக்க எவருமே இருக்கமாட்டார்கள்' என்பதாகும்.\n\r\n\n\r\nوَمَن يُضْلِلِ اللَّهُ فَمَا لَهُ مِنْ هَادٍ\n\r\n(மேலும் அல்லாஹ் யாரை வழிதவறச் செய்கிறானோ, அவருக்கு வழிகாட்டுபவர் எவருமில்லை.) அதாவது, அல்லாஹ் யாரை வழிதவறச் செய்கிறானோ, அவருக்கு அவனைத் தவிர வேறு எவரும் நேர்வழி காட்ட முடியாது. அல்லாஹ்வின் கூற்று:\n\r\n\n\r\nوَلَقَدْ جَآءَكُـمْ يُوسُفُ مِن قَبْلُ بِالْبَيِّنَـتِ\n\r\n(நிச்சயமாக இதற்கு முன்னர் யூஸுஃப் (அலை) அவர்கள் தெளிவான சான்றுகளுடன் உங்களிடம் வந்தார்கள்,) இது எகிப்து மக்களைக் குறிக்கிறது. மூஸா (அலை) அவர்களுக்கு முந்தைய காலத்தில், அதாவது, யூஸுஃப் இப்னு யஃகூப் இப்னு இஸ்ஹாக் இப்னு இப்ராஹீம் (அலை) எனும் எகிப்து அரசாங்கத்தில் உயர் பதவியில் இருந்த யூஸுஃப் (அலை) அவர்களை அல்லாஹ் ஒரு தூதராக அவர்களிடம் அனுப்பினான். அவர்கள் நீதியுடன் மக்களை அல்லாஹ்வின் பக்கம் அழைத்த ஒரு தூதராக இருந்தார்கள். ஆனால், அல்லாஹ்வை வணங்கும் விஷயத்தில் மக்கள் அவருக்குக் கீழ்ப்படியவில்லை; மாறாக, அரசாங்கத்தில் அவர் வகித்த பதவி தொடர்பான உலக விவகாரங்களில் மட்டுமே அவருக்குக் கீழ்ப்படிந்தார்கள். அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nفَمَا زِلْتُمْ فِى شَكٍّ مِّمَّا جَآءَكُـمْ بِهِ حَتَّى إِذَا هَلَكَ قُلْتُمْ لَن يَبْعَثَ اللَّهُ مِن بَعْدِهِ رَسُولاً\n\r\n(அவர் உங்களுக்குக் கொண்டு வந்தவற்றில் நீங்கள் தொடர்ந்து சந்தேகம் கொண்டவர்களாகவே இருந்தீர்கள். இறுதியில் அவர் இறந்தபோது: 'அவருக்குப் பிறகு அல்லாஹ் எந்தத் தூதரையும் அனுப்பவே மாட்டான்' என்று கூறினீர்கள்.) அதாவது, 'நீங்கள் நம்பிக்கையிழந்து, உங்கள் வீணான ஆசையினால் இவ்வாறு கூறினீர்கள்.'\n\r\n\n\r\nلَن يَبْعَثَ اللَّهُ مِن بَعْدِهِ رَسُولاً\n\r\n('அவருக்குப் பிறகு அல்லாஹ் எந்தத் தூதரையும் அனுப்பவே மாட்டான்.') இது அவர்கள் இறைத்தூதர்களை நிராகரித்ததாலும் பொய்ப்பித்ததாலும் ஏற்பட்ட நிலையாகும்.\n\r\n\n\r\nكَذَلِكَ يُضِلُّ اللَّهُ مَنْ هُوَ مُسْرِفٌ مُّرْتَابٌ\n\r\n(இவ்வாறே வரம்பு மீறுபவரையும், சந்தேகம் கொள்பவரையும் அல்லாஹ் வழிதவறச் செய்கிறான்.) அதாவது, ஒருவனது பாவச் செயல்களாலும் அவனது உள்ளத்திலுள்ள சந்தேகங்களாலும் அல்லாஹ் ஒருவனை வழிதவறச் செய்யும்போது அவனது நிலை இவ்வாறே இருக்கும்.\n\r\n\n\r\nالَّذِينَ يُجَادِلُونَ فِي آيَاتِ اللَّهِ بِغَيْرِ سُلْطَانٍ أَتَاهُمْ\n\r\n(தங்களுக்குக் கிடைத்த எந்த ஆதாரமும் இன்றி அல்லாஹ்வின் வசனங்களில் தர்க்கம் செய்பவர்கள்,) அதாவது, பொய்யைக் கொண்டு உண்மையை மறுக்க முயல்பவர்கள் மற்றும் அல்லாஹ்விடமிருந்து எந்தவொரு அத்தாட்சியும் இன்றி அவனது சான்றுகளைப் பற்றி தர்க்கம் செய்பவர்களை அல்லாஹ் கடுமையாக வெறுக்கிறான். அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nكَبُرَ مَقْتاً عِندَ اللَّهِ وَعِندَ الَّذِينَ ءَامَنُواْ\n\r\n(இது அல்லாஹ்விடத்திலும் நம்பிக்கை கொண்டவர்களிடத்திலும் மிகவும் வெறுக்கத்தக்கதாகும்.) அதாவது, இறைநம்பிக்கையாளர்களும் இத்தகையவர்களை வெறுப்பார்கள். மேலும் இவ்வாறானவர்களின் இதயங்களில் அல்லாஹ் முத்திரையிட்டு விடுகிறான்; அதன் பிறகு அவர்களால் எவ்வித நன்மையையும் அங்கீகரிக்க முடியாது, தீமையைத் தீமை என்று கண்டிக்கவும் முடியாது. அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nكَذَلِكَ يَطْبَعُ اللَّهُ عَلَى كُـلِّ قَلْبِ مُتَكَبِّرٍ جَبَّارٍ\n\r\n(இவ்வாறே, பெருமையடிக்கும் ஒவ்வொரு கொடுங்கோலனின் இதயத்தின் மீதும் அல்லாஹ் முத்திரையிடுகிறான்.) அதாவது, அவர்கள் சத்தியத்தைப் பின்பற்ற முடியாதவாறு முத்திரையிடுகிறான்."},"36":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=40&ayah=37\" class=\"link\">40:37</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 40:37 ஐ பார்க்கவும்"},"37":{"html":"<strong>ஃபிர்அவ்ன் எவ்வாறு மூஸா (அலை) அவர்களின் இறைவனைக் கேலி செய்தான்</strong><br />\r\n<br />\r\nஃபிர்அவ்னின் அகங்காரமான மற்றும் பகைமை நிறைந்த எதிர்ப்பையும், அவன் மூஸா (அலை) அவர்களை நிராகரித்ததையும் பற்றி அல்லாஹ் நமக்குக் கூறுகிறான். அவன் தனது அமைச்சரான ஹாமானிடம் தனக்காக ஒரு கோபுரத்தை, அதாவது மிகவும் உயரமான, வலிமையான ஒரு கோட்டையைக் கட்டும்படி கட்டளையிட்டான். அல்லாஹ் கூறுவது போல், அவன் அதைச் சுட்ட களிமண்ணால் ஆன செங்கற்களைக் கொண்டு கட்டினான்:<span class=\"quran-arabic-font text-success\">﴾فَأَوْقِدْ</span> <span class=\"quran-arabic-font text-success\">لِى</span> <span class=\"quran-arabic-font text-success\">يَهَـمَـنُ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">الطِّينِ</span> <span class=\"quran-arabic-font text-success\">فَاجْعَل</span> <span class=\"quran-arabic-font text-success\">لِّى</span> <span class=\"quran-arabic-font text-success\">صَرْحاً﴿</span><br />\r\n<br />\r\n(ஹாமனே! எனக்காகக் களிமண்ணால் (செங்கற்களைச்) சுட்டு, எனக்கு ஒரு உயர்ந்த கோபுரத்தை அமைப்பீராக!) (<a href=\"qurandisp.php?sura=28&ayah=38\" class=\"link\">28:38</a>).<span class=\"quran-arabic-font text-success\">﴾لَعَلِّى</span> <span class=\"quran-arabic-font text-success\">أَبْلُغُ</span> <span class=\"quran-arabic-font text-success\">الْأَسْبَابَ</span> - <span class=\"quran-arabic-font text-success\">أَسْبَابَ</span> <span class=\"quran-arabic-font text-success\">السَّمَـوَتِ﴿</span><br />\r\n<br />\r\n(நான் அந்தப் பாதைகளை — வானங்களின் பாதைகளை — அடையும் பொருட்டு,) ஸஈத் பின் ஜுபைர் அவர்களும், அபூ ஸாலிஹ் அவர்களும் \"வானங்களின் வாசல்கள்\" என்று கூறினார்கள். அல்லது, வானங்களின் வழிகள் என்றும் கூறப்பட்டது.<span class=\"quran-arabic-font text-success\">﴾فَأَطَّلِعَ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">إِلَـهِ</span> <span class=\"quran-arabic-font text-success\">مُوسَى</span> <span class=\"quran-arabic-font text-success\">وَإِنِّى</span> <span class=\"quran-arabic-font text-success\">لَأَظُنُّهُ</span> <span class=\"quran-arabic-font text-success\">كَـذِباً﴿</span><br />\r\n<br />\r\n(மேலும் நான் மூஸா (அலை) அவர்களின் இறைவனைப் பார்க்க வேண்டும், ஆனால் நிச்சயமாக, நான் அவரை ஒரு பொய்யர் என்றே கருதுகிறேன்.) அவனது நிராகரிப்பு மற்றும் பிடிவாதத்தின் காரணமாக, அல்லாஹ் மூஸா (அலை) அவர்களைத் தூதராக அனுப்பியிருப்பதை அவன் நம்பவில்லை. அல்லாஹ் கூறுகிறான்:<span class=\"quran-arabic-font text-success\">﴾وَكَـذَلِكَ</span> <span class=\"quran-arabic-font text-success\">زُيِّنَ</span> <span class=\"quran-arabic-font text-success\">لِفِرْعَوْنَ</span> <span class=\"quran-arabic-font text-success\">سُوءُ</span> <span class=\"quran-arabic-font text-success\">عَمَلِهِ</span> <span class=\"quran-arabic-font text-success\">وَصُدَّ</span> <span class=\"quran-arabic-font text-success\">عَنِ</span> <span class=\"quran-arabic-font text-success\">السَّبِيلِ﴿</span><br />\r\n<br />\r\n(இவ்வாறாக ஃபிர்அவ்னுக்கு அவனது தீய செயல் அழகாகக் காட்டப்பட்டது, மேலும் அவன் (நேர்)வழியிலிருந்து தடுக்கப்பட்டான்;) அதாவது, அவன் தனது மக்களை ஏமாற்றவும், மூஸா (அலை) அவர்கள் பொய் சொல்கிறார்கள் என்பதைத் தன்னால் நிரூபிக்க முடியும் என்று அவர்களை எண்ண வைக்கவும் விரும்பி, கோபுரம் கட்டிய அந்தச் செயலைக் குறிக்கிறது. அல்லாஹ் கூறுகிறான்:<span class=\"quran-arabic-font text-success\">﴾وَمَا</span> <span class=\"quran-arabic-font text-success\">كَـيْدُ</span> <span class=\"quran-arabic-font text-success\">فِرْعَوْنَ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">تَبَابٍ﴿</span><br />\r\n<br />\r\n(மேலும் ஃபிர்அவ்னின் சதித்திட்டம் அழிவைத் தவிர வேறெதற்கும் வழிவகுக்கவில்லை.) இப்னு அப்பாஸ் (ரழி) அவர்களும் முஜாஹித் அவர்களும், \"இதன் பொருள் அழிவே அன்றி வேறில்லை\" என்று கூறினார்கள்.<br />\r\n<br />","text":"ஃபிர்அவ்ன் எவ்வாறு மூஸா (அலை) அவர்களின் இறைவனைக் கேலி செய்தான்\n\r\n\n\r\nஃபிர்அவ்னின் அகங்காரமான மற்றும் பகைமை நிறைந்த எதிர்ப்பையும், அவன் மூஸா (அலை) அவர்களை நிராகரித்ததையும் பற்றி அல்லாஹ் நமக்குக் கூறுகிறான். அவன் தனது அமைச்சரான ஹாமானிடம் தனக்காக ஒரு கோபுரத்தை, அதாவது மிகவும் உயரமான, வலிமையான ஒரு கோட்டையைக் கட்டும்படி கட்டளையிட்டான். அல்லாஹ் கூறுவது போல், அவன் அதைச் சுட்ட களிமண்ணால் ஆன செங்கற்களைக் கொண்டு கட்டினான்:﴾فَأَوْقِدْ لِى يَهَـمَـنُ عَلَى الطِّينِ فَاجْعَل لِّى صَرْحاً﴿\n\r\n\n\r\n(ஹாமனே! எனக்காகக் களிமண்ணால் (செங்கற்களைச்) சுட்டு, எனக்கு ஒரு உயர்ந்த கோபுரத்தை அமைப்பீராக!) (28:38).﴾لَعَلِّى أَبْلُغُ الْأَسْبَابَ - أَسْبَابَ السَّمَـوَتِ﴿\n\r\n\n\r\n(நான் அந்தப் பாதைகளை — வானங்களின் பாதைகளை — அடையும் பொருட்டு,) ஸஈத் பின் ஜுபைர் அவர்களும், அபூ ஸாலிஹ் அவர்களும் \"வானங்களின் வாசல்கள்\" என்று கூறினார்கள். அல்லது, வானங்களின் வழிகள் என்றும் கூறப்பட்டது.﴾فَأَطَّلِعَ إِلَى إِلَـهِ مُوسَى وَإِنِّى لَأَظُنُّهُ كَـذِباً﴿\n\r\n\n\r\n(மேலும் நான் மூஸா (அலை) அவர்களின் இறைவனைப் பார்க்க வேண்டும், ஆனால் நிச்சயமாக, நான் அவரை ஒரு பொய்யர் என்றே கருதுகிறேன்.) அவனது நிராகரிப்பு மற்றும் பிடிவாதத்தின் காரணமாக, அல்லாஹ் மூஸா (அலை) அவர்களைத் தூதராக அனுப்பியிருப்பதை அவன் நம்பவில்லை. அல்லாஹ் கூறுகிறான்:﴾وَكَـذَلِكَ زُيِّنَ لِفِرْعَوْنَ سُوءُ عَمَلِهِ وَصُدَّ عَنِ السَّبِيلِ﴿\n\r\n\n\r\n(இவ்வாறாக ஃபிர்அவ்னுக்கு அவனது தீய செயல் அழகாகக் காட்டப்பட்டது, மேலும் அவன் (நேர்)வழியிலிருந்து தடுக்கப்பட்டான்;) அதாவது, அவன் தனது மக்களை ஏமாற்றவும், மூஸா (அலை) அவர்கள் பொய் சொல்கிறார்கள் என்பதைத் தன்னால் நிரூபிக்க முடியும் என்று அவர்களை எண்ண வைக்கவும் விரும்பி, கோபுரம் கட்டிய அந்தச் செயலைக் குறிக்கிறது. அல்லாஹ் கூறுகிறான்:﴾وَمَا كَـيْدُ فِرْعَوْنَ إِلاَّ فِى تَبَابٍ﴿\n\r\n\n\r\n(மேலும் ஃபிர்அவ்னின் சதித்திட்டம் அழிவைத் தவிர வேறெதற்கும் வழிவகுக்கவில்லை.) இப்னு அப்பாஸ் (ரழி) அவர்களும் முஜாஹித் அவர்களும், \"இதன் பொருள் அழிவே அன்றி வேறில்லை\" என்று கூறினார்கள்."},"38":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=40&ayah=40\" class=\"link\">40:40</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 40:40 ஐ பார்க்கவும்"},"39":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=40&ayah=40\" class=\"link\">40:40</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 40:40 ஐ பார்க்கவும்"},"40":{"html":"<strong>ஃபிர்அவ்னின் குடும்பத்தைச் சேர்ந்த அந்த இறைநம்பிக்கையாளர் மேலும் கூறியவை</strong><br />\r\n<br />\r\nதமது வரம்புமீறலிலும் பாவங்களிலும் பிடிவாதமாக இருந்து, இவ்வுலக வாழ்க்கையை (மறுமையை விட) மேலாகக் கருதிய தமது மக்களிடம் இந்த இறைநம்பிக்கையாளர் கூறினார்கள்: <span class=\"quran-arabic-font text-success\">﴾يَا</span> <span class=\"quran-arabic-font text-success\">قَوْمِ</span> <span class=\"quran-arabic-font text-success\">اتَّبِعُونِ</span> <span class=\"quran-arabic-font text-success\">أَهْدِكُمْ</span> <span class=\"quran-arabic-font text-success\">سَبِيلَ</span> <span class=\"quran-arabic-font text-success\">الرَّشَادِ﴿</span><br />\r\n<br />\r\n(என் மக்களே! என்னைப் பின்பற்றுங்கள், நான் உங்களுக்கு நேர்வழிகாட்டுவேன்.) இது ஃபிர்அவ்னின் பின்வரும் பொய்யான வாதத்திற்கு நேர்மாற்றமாக அமைந்தது: <span class=\"quran-arabic-font text-success\">﴾وَمَا</span> <span class=\"quran-arabic-font text-success\">أَهْدِيكُمْ</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">سَبِيلَ</span> <span class=\"quran-arabic-font text-success\">الرَّشَادِ﴿</span><br />\r\n<br />\r\n(நான் உங்களுக்கு நேர்வழியைத் தவிர வேறொன்றையும் காட்டவில்லை.) பிறகு, மறுமையை விட அவர்கள் அதிகம் நேசித்த, அல்லாஹ்வின் தூதர் மூஸா (அலை) அவர்களை ஈமான் கொள்வதிலிருந்து அவர்களைத் தடுத்த இவ்வுலக வாழ்க்கையை அவர்கள் வெறுத்து ஒதுக்கும்படி செய்ய அவர் முயன்றார். அவர்கள் கூறினார்கள்: <span class=\"quran-arabic-font text-success\">﴾يَا</span> <span class=\"quran-arabic-font text-success\">قَوْمِ</span> <span class=\"quran-arabic-font text-success\">إِنَّمَا</span> <span class=\"quran-arabic-font text-success\">هَذِهِ</span> <span class=\"quran-arabic-font text-success\">الْحَيَاةُ</span> <span class=\"quran-arabic-font text-success\">الدُّنْيَا</span> <span class=\"quran-arabic-font text-success\">مَتَاعٌ﴿</span><br />\r\n<br />\r\n(என் மக்களே! நிச்சயமாக இவ்வுலக வாழ்க்கை ஒரு தற்காலிகப் பயன்பாடு மட்டுமே.) அதாவது, இது அற்பமானது, நிலையற்றது; விரைவில் இது அழிந்து மறைந்துவிடக்கூடியது. <span class=\"quran-arabic-font text-success\">﴾وَإِنَّ</span> <span class=\"quran-arabic-font text-success\">الْآخِرَةَ</span> <span class=\"quran-arabic-font text-success\">هِيَ</span> <span class=\"quran-arabic-font text-success\">دَارُ</span> <span class=\"quran-arabic-font text-success\">الْقَرَارِ﴿</span><br />\r\n<br />\r\n(நிச்சயமாக மறுமையே நிலையான தங்குமிடமாகும்.) அதாவது, அது ஒருபோதும் முடிவில்லாத, எவரும் அங்கிருந்து வெளியேறத் தேவையில்லாத இல்லமாகும்; அது சொர்க்கமாகவோ அல்லது நரகமாகவோ இருக்கும். அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾مَنْ</span> <span class=\"quran-arabic-font text-success\">عَمِلَ</span> <span class=\"quran-arabic-font text-success\">سَيِّئَةً</span> <span class=\"quran-arabic-font text-success\">فَلَا</span> <span class=\"quran-arabic-font text-success\">يُجْزَى</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">مِثْلَهَا﴿</span><br />\r\n<br />\r\n(எவர் தீமை செய்கிறாரோ, அவருக்கு அது போன்ற கூலியே தவிர வேறு எதுவும் வழங்கப்பட மாட்டாது;) அதாவது, அத்தீமைக்குச் சமமான ஒரு கூலியே வழங்கப்படும். <span class=\"quran-arabic-font text-success\">﴾وَمَنْ</span> <span class=\"quran-arabic-font text-success\">عَمِلَ</span> <span class=\"quran-arabic-font text-success\">صَالِحًا</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">ذَكَرٍ</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">أُنْثَى</span> <span class=\"quran-arabic-font text-success\">وَهُوَ</span> <span class=\"quran-arabic-font text-success\">مُؤْمِنٌ</span> <span class=\"quran-arabic-font text-success\">فَأُولَئِكَ</span> <span class=\"quran-arabic-font text-success\">يَدْخُلُونَ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةَ</span> <span class=\"quran-arabic-font text-success\">يُرْزَقُونَ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">بِغَيْرِ</span> <span class=\"quran-arabic-font text-success\">حِسَابٍ﴿</span><br />\r\n<br />\r\n(ஆணோ பெண்ணோ, எவர் இறைநம்பிக்கை கொண்டவராக இருந்து நற்செயல்களைச் செய்கிறாரோ, அவர்கள் சொர்க்கத்தில் நுழைவார்கள்; அங்கு அவர்களுக்குக் கணக்கின்றி வாழ்வாதாரம் வழங்கப்படும்.) அதாவது, அவர்களுக்கு வழங்கப்படும் நற்கூலியை எண்ணிக் கணக்கிட முடியாது; மாறாக அல்லாஹ் முடிவில்லாத பெரும் நற்கூலியை அவர்களுக்கு வழங்குவான்.<br />\r\n<br />","text":"ஃபிர்அவ்னின் குடும்பத்தைச் சேர்ந்த அந்த இறைநம்பிக்கையாளர் மேலும் கூறியவை\n\r\n\n\r\nதமது வரம்புமீறலிலும் பாவங்களிலும் பிடிவாதமாக இருந்து, இவ்வுலக வாழ்க்கையை (மறுமையை விட) மேலாகக் கருதிய தமது மக்களிடம் இந்த இறைநம்பிக்கையாளர் கூறினார்கள்: ﴾يَا قَوْمِ اتَّبِعُونِ أَهْدِكُمْ سَبِيلَ الرَّشَادِ﴿\n\r\n\n\r\n(என் மக்களே! என்னைப் பின்பற்றுங்கள், நான் உங்களுக்கு நேர்வழிகாட்டுவேன்.) இது ஃபிர்அவ்னின் பின்வரும் பொய்யான வாதத்திற்கு நேர்மாற்றமாக அமைந்தது: ﴾وَمَا أَهْدِيكُمْ إِلَّا سَبِيلَ الرَّشَادِ﴿\n\r\n\n\r\n(நான் உங்களுக்கு நேர்வழியைத் தவிர வேறொன்றையும் காட்டவில்லை.) பிறகு, மறுமையை விட அவர்கள் அதிகம் நேசித்த, அல்லாஹ்வின் தூதர் மூஸா (அலை) அவர்களை ஈமான் கொள்வதிலிருந்து அவர்களைத் தடுத்த இவ்வுலக வாழ்க்கையை அவர்கள் வெறுத்து ஒதுக்கும்படி செய்ய அவர் முயன்றார். அவர்கள் கூறினார்கள்: ﴾يَا قَوْمِ إِنَّمَا هَذِهِ الْحَيَاةُ الدُّنْيَا مَتَاعٌ﴿\n\r\n\n\r\n(என் மக்களே! நிச்சயமாக இவ்வுலக வாழ்க்கை ஒரு தற்காலிகப் பயன்பாடு மட்டுமே.) அதாவது, இது அற்பமானது, நிலையற்றது; விரைவில் இது அழிந்து மறைந்துவிடக்கூடியது. ﴾وَإِنَّ الْآخِرَةَ هِيَ دَارُ الْقَرَارِ﴿\n\r\n\n\r\n(நிச்சயமாக மறுமையே நிலையான தங்குமிடமாகும்.) அதாவது, அது ஒருபோதும் முடிவில்லாத, எவரும் அங்கிருந்து வெளியேறத் தேவையில்லாத இல்லமாகும்; அது சொர்க்கமாகவோ அல்லது நரகமாகவோ இருக்கும். அல்லாஹ் கூறுகிறான்: ﴾مَنْ عَمِلَ سَيِّئَةً فَلَا يُجْزَى إِلَّا مِثْلَهَا﴿\n\r\n\n\r\n(எவர் தீமை செய்கிறாரோ, அவருக்கு அது போன்ற கூலியே தவிர வேறு எதுவும் வழங்கப்பட மாட்டாது;) அதாவது, அத்தீமைக்குச் சமமான ஒரு கூலியே வழங்கப்படும். ﴾وَمَنْ عَمِلَ صَالِحًا مِّن ذَكَرٍ أَوْ أُنْثَى وَهُوَ مُؤْمِنٌ فَأُولَئِكَ يَدْخُلُونَ الْجَنَّةَ يُرْزَقُونَ فِيهَا بِغَيْرِ حِسَابٍ﴿\n\r\n\n\r\n(ஆணோ பெண்ணோ, எவர் இறைநம்பிக்கை கொண்டவராக இருந்து நற்செயல்களைச் செய்கிறாரோ, அவர்கள் சொர்க்கத்தில் நுழைவார்கள்; அங்கு அவர்களுக்குக் கணக்கின்றி வாழ்வாதாரம் வழங்கப்படும்.) அதாவது, அவர்களுக்கு வழங்கப்படும் நற்கூலியை எண்ணிக் கணக்கிட முடியாது; மாறாக அல்லாஹ் முடிவில்லாத பெரும் நற்கூலியை அவர்களுக்கு வழங்குவான்."},"41":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=40&ayah=46\" class=\"link\">40:46</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 40:46 ஐ பார்க்கவும்"},"42":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=40&ayah=46\" class=\"link\">40:46</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 40:46 ஐ பார்க்கவும்"},"43":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=40&ayah=46\" class=\"link\">40:46</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 40:46 ஐ பார்க்கவும்"},"44":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=40&ayah=46\" class=\"link\">40:46</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 40:46 ஐ பார்க்கவும்"},"45":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=40&ayah=46\" class=\"link\">40:46</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 40:46 ஐ பார்க்கவும்"},"46":{"html":"<strong>அந்த இறைநம்பிக்கையாளரின் வார்த்தைகளின் நிறைவும், இரு தரப்பாரின் இறுதி முடிவும்</strong><br />\r\n<br />\r\nஅந்த இறைநம்பிக்கையாளர் கூறினார்: \"நான் ஏன் உங்களை ஈடேற்றத்தின் பக்கம் அழைக்கிறேன்? அதுவோ இணை துணையற்ற அல்லாஹ் ஒருவனையே வணங்குவதும், அவன் அனுப்பிய அவனது தூதரை ஈமான் கொள்வதுமாகும்.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَيَـقَوْمِ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">لِى</span> <span class=\"quran-arabic-font text-success\">أَدْعُوكُمْ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">النَّجَاةِ</span> <span class=\"quran-arabic-font text-success\">وَتَدْعُونَنِى</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">النَّارِ</span> - <span class=\"quran-arabic-font text-success\">تَدْعُونَنِى</span> <span class=\"quran-arabic-font text-success\">لأَكْفُرَ</span> <span class=\"quran-arabic-font text-success\">بِاللَّهِ</span> <span class=\"quran-arabic-font text-success\">وَأُشْرِكَ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">لَيْسَ</span> <span class=\"quran-arabic-font text-success\">لِى</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">عِلْمٌ</span><br />\r\n<br />\r\n(நீங்களோ என்னை நரகத்தின் பக்கம் அழைக்கிறீர்கள்! நான் அல்லாஹ்வை நிராகரிக்கவும், எனக்கு அறிவில்லாதவற்றை அவனுக்கு இணையாக்கவும் என்னை அழைக்கிறீர்கள்;) அதாவது எந்தவொரு ஆதாரமுமின்றி அறியாமையின் அடிப்படையில் என்னை அழைக்கிறீர்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَأَنَاْ</span> <span class=\"quran-arabic-font text-success\">أَدْعُوكُمْ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">الْعَزِيزِ</span> <span class=\"quran-arabic-font text-success\">الْغَفَّارِ</span><br />\r\n<br />\r\n(நானோ உங்களை யாவற்றையும் மிகைத்தவனும், பெரும் மன்னிப்பாளனுமான அல்லாஹ்வின் பக்கம் அழைக்கிறேன்!) அதாவது அவனது மகத்தான வல்லமைக்கும் கண்ணியத்திற்கும் மத்தியிலும், அவனிடம் தவ்பா செய்து மீளுபவரின் பாவங்களை அவன் மன்னிக்கிறான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">جَرَمَ</span> <span class=\"quran-arabic-font text-success\">أَنَّمَا</span> <span class=\"quran-arabic-font text-success\">تَدْعُونَنِى</span> <span class=\"quran-arabic-font text-success\">إِلَيْهِ</span><br />\r\n<br />\r\n(நிச்சயமாக, நீங்கள் என்னை எதன் பக்கம் அழைக்கிறீர்களோ) இதற்கு \"உண்மையாகவே\" என்று பொருள் என அறிஞர்கள் கூறுகின்றனர். அஸ்-ஸுத்தி மற்றும் இப்னு ஜரீர் ஆகியோர் இக்கூற்றிற்கு \"நிச்சயமாக\" என்று பொருள் எனக் கூறினார்கள். அத்-தஹ்ஹாக் கூறுகையில்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">جَرَمَ</span><br />\r\n<br />\r\n(லா ஜரம) என்பதற்கு, \"இதில் பொய்க்கிடமில்லை\" என்று பொருள். அலீ பின் அபீ தல்ஹா மற்றும் இப்னு அப்பாஸ் (ரழி) கூறினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">جَرَمَ</span><br />\r\n<br />\r\n(லா ஜரம) என்பதற்கு, \"நிச்சயமாக, நீங்கள் என்னை அழைக்கக்கூடிய இந்தச் சிலைகளுக்கும் பொய்த் தெய்வங்களுக்கும்<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لَيْسَ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">دَعْوَةٌ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الدُّنْيَا</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الاٌّخِرَةِ</span><br />\r\n<br />\r\n(இவ்வுலகிலோ அல்லது மறுமையிலோ எவ்வித அதிகாரமும் இல்லை)\" என்று பொருள். முஜாஹித் கூறுகையில், \"அந்தச் சிலைகளிடம் எதுவுமே இல்லை\" என்றார். கத்தாதா கூறுகையில், \"இதன் பொருள், சிலைகளுக்கு எவ்வித நன்மையோ தீங்கோ செய்ய சக்தியில்லை\" என்றார். அஸ்-ஸுத்தி கூறுகையில், \"இவ்வுலகிலோ அல்லது மறுமையிலோ தம்மை அழைப்பவர்களுக்கு அவை பதில் தராது\" என்றார். இது பின்வரும் வசனத்தைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَنْ</span> <span class=\"quran-arabic-font text-success\">أَضَلُّ</span> <span class=\"quran-arabic-font text-success\">مِمَّن</span> <span class=\"quran-arabic-font text-success\">يَدْعُو</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">دُونِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">لاَّ</span> <span class=\"quran-arabic-font text-success\">يَسْتَجِيبُ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">يَوْمِ</span> <span class=\"quran-arabic-font text-success\">الْقِيَـمَةِ</span> <span class=\"quran-arabic-font text-success\">وَهُمْ</span> <span class=\"quran-arabic-font text-success\">عَن</span> <span class=\"quran-arabic-font text-success\">دُعَآئِهِمْ</span> <span class=\"quran-arabic-font text-success\">غَـفِلُونَ</span> - <span class=\"quran-arabic-font text-success\">وَإِذَا</span> <span class=\"quran-arabic-font text-success\">حُشِرَ</span> <span class=\"quran-arabic-font text-success\">النَّاسُ</span> <span class=\"quran-arabic-font text-success\">كَانُواْ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">أَعْدَآءً</span> <span class=\"quran-arabic-font text-success\">وَكَانُواْ</span> <span class=\"quran-arabic-font text-success\">بِعِبَادَتِهِمْ</span> <span class=\"quran-arabic-font text-success\">كَـفِرِينَ</span><br />\r\n<br />\r\n(மறுமை நாள் வரை தனக்கு பதிலளிக்காத, அல்லாஹ் அல்லாதவற்றை அழைப்பவனை விட மிக வழிதவறியவன் யார்? அவர்களோ இவர்களது அழைப்பைப் பற்றி அறியாதவர்களாக இருக்கின்றனர். மேலும் மக்கள் ஒன்று திரட்டப்படும்போது, அவர்கள் இவர்களுக்கு எதிரிகளாகி விடுவார்கள்; இவர்களது வணக்கத்தையும் நிராகரித்து விடுவார்கள்.) (<a href=\"qurandisp.php?sura=46&ayah=5\" class=\"link\">46:5</a>-6)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">تَدْعُوهُمْ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَسْمَعُواْ</span> <span class=\"quran-arabic-font text-success\">دُعَآءَكُمْ</span> <span class=\"quran-arabic-font text-success\">وَلَوْ</span> <span class=\"quran-arabic-font text-success\">سَمِعُواْ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">اسْتَجَابُواْ</span> <span class=\"quran-arabic-font text-success\">لَكُمْ</span><br />\r\n<br />\r\n(நீங்கள் அவர்களை அழைத்தால், அவர்கள் உங்கள் அழைப்பைக் கேட்க மாட்டார்கள்; அவர்கள் கேட்டாலும் உங்களுக்குப் பதில் அளிக்க மாட்டார்கள்.) (<a href=\"qurandisp.php?sura=35&ayah=14\" class=\"link\">35:14</a>).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَأَنَّ</span> <span class=\"quran-arabic-font text-success\">مَرَدَّنَآ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span><br />\r\n<br />\r\n(மேலும் நமது மீளுதல் அல்லாஹ்விடமே இருக்கிறது,) அதாவது மறுமையில் ஒவ்வொருவருக்கும் அவரவர் செயல்களுக்கு ஏற்ப அவன் கூலியளிப்பான் அல்லது தண்டிப்பான். அவன் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَأَنَّ</span> <span class=\"quran-arabic-font text-success\">الْمُسْرِفِينَ</span> <span class=\"quran-arabic-font text-success\">هُمْ</span> <span class=\"quran-arabic-font text-success\">أَصْحَـبُ</span> <span class=\"quran-arabic-font text-success\">النَّارِ</span><br />\r\n<br />\r\n(மேலும் வரம்பு மீறுபவர்களே நரகவாசிகள்!) அதாவது அல்லாஹ்வுக்கு இணை வைத்த பெரும் பாவத்தினால், அவர்கள் நரகில் நிரந்தரமாகத் தங்குவார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَسَتَذْكُرُونَ</span> <span class=\"quran-arabic-font text-success\">مَآ</span> <span class=\"quran-arabic-font text-success\">أَقُولُ</span> <span class=\"quran-arabic-font text-success\">لَكُـمْ</span><br />\r\n<br />\r\n(நான் உங்களுக்குச் சொல்வதை நீங்கள் விரைவில் நினைத்துப் பார்ப்பீர்கள்,) அதாவது 'நான் உங்களுக்கு எதை ஏவினேனோ, எதைத் தடுத்தேனோ மற்றும் நான் உங்களுக்கு வழங்கிய அறிவுரைகளின் உண்மையை நீங்கள் விரைவில் அறிந்துகொள்வீர்கள். கைசேதம் பலனளிக்காத நேரத்தில் நீங்கள் இதற்காக வருத்தப்படுவீர்கள்.'<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَأُفَوِّضُ</span> <span class=\"quran-arabic-font text-success\">أَمْرِى</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span><br />\r\n<br />\r\n(மேலும் எனது காரியத்தை நான் அல்லாஹ்விடமே ஒப்படைக்கிறேன்.) அதாவது, 'நான் அல்லாஹ்வின் மீதே முழு நம்பிக்கை (தவக்குல்) வைத்து அவனது உதவியைத் தேடுகிறேன்; உங்களை விட்டும் நான் முற்றிலுமாக ஒதுங்கிக்கொள்கிறேன்.'<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">بَصِيرٌ</span> <span class=\"quran-arabic-font text-success\">بِالْعِبَادِ</span><br />\r\n<br />\r\n(நிச்சயமாக அல்லாஹ் அடியார்களை உற்று நோக்குபவன்.) அதாவது அவன் அவர்களைப் பற்றி முற்றிலும் அறிந்தவன்; அவன் உயர்ந்தவனும் தூய்மையானவனுமாவான். அவன் தகுதியுள்ளவர்களுக்கு நேர்வழி காட்டுகிறான், வழிகேட்டிற்குத் தகுதியானவர்களை வழிகேட்டில் விடுகிறான். அவனிடமே முழுமையான ஆதாரமும், உன்னதமான ஞானமும், மகத்தான வல்லமையும் உள்ளன.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَوقَاهُ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">سَيِّئَاتِ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">مَكَـرُواْ</span><br />\r\n<br />\r\n(ஆகவே, அவர்கள் செய்த சதிச் செயல்களின் தீமைகளிலிருந்து அல்லாஹ் அவரைக் காப்பாற்றினான்,) அதாவது இவ்வுலகிலும் மறுமையிலும்; இவ்வுலகில் மூஸா (அலை) அவர்களுடன் சேர்த்து அல்லாஹ் அவரையும் காப்பாற்றினான், மறுமையில் அவரைச் சுவனத்தில் புகுத்துவான்.<br />\r\n<br />\r\n<strong>கப்ரின் வேதனைக்கான ஆதாரம்</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَحَاقَ</span> <span class=\"quran-arabic-font text-success\">بِآلِ</span> <span class=\"quran-arabic-font text-success\">فِرْعَوْنَ</span> <span class=\"quran-arabic-font text-success\">سُوءُ</span> <span class=\"quran-arabic-font text-success\">الْعَذَابِ</span><br />\r\n<br />\r\n(ஃபிர்அவ்னின் கூட்டத்தினரை ஒரு கொடிய வேதனை சூழ்ந்துகொண்டது.) இது அவர்கள் கடலில் மூழ்கடிக்கப்பட்டதைக் குறிக்கிறது. அதன் பிறகு அவர்கள் நரகிற்கு மாற்றப்பட்டனர். கியாமத் நாள் வரும் வரை அவர்களது ஆன்மாக்கள் காலையிலும் மாலையிலும் நரக நெருப்பின் முன் கொண்டு வரப்படுகின்றன. மறுமை நாள் வரும்போது, அவர்களின் ஆன்மாக்களும் உடல்களும் நரகில் மீண்டும் இணைக்கப்படும். அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَيَوْمَ</span> <span class=\"quran-arabic-font text-success\">تَقُومُ</span> <span class=\"quran-arabic-font text-success\">السَّاعَةُ</span> <span class=\"quran-arabic-font text-success\">أَدْخِلُواْ</span> <span class=\"quran-arabic-font text-success\">ءَالَ</span> <span class=\"quran-arabic-font text-success\">فِرْعَوْنَ</span> <span class=\"quran-arabic-font text-success\">أَشَدَّ</span> <span class=\"quran-arabic-font text-success\">الْعَذَابِ</span><br />\r\n<br />\r\n(மேலும் மறுமை நாள் வரும்போது, \"ஃபிர்அவ்னின் கூட்டத்தினரை மிகக் கடுமையான வேதனையில் புகுத்துங்கள்\" (என வானவர்களுக்குக் கூறப்படும்).) அதாவது மிகத் தீவிரமான வலியும் வேதனையும் அளிக்கப்படும். அல்-பர்ஸக் (மறுமைக்கு முந்தைய திரை) காலத்தில் கப்ரில் வேதனை இருக்கும் என்பதை நிரூபிக்க அஹ்லுஸ் ஸுன்னாவால் பயன்படுத்தப்படும் மிக முக்கியமான ஆதாரம் இந்த வசனமாகும். அது பின்வரும் சொற்றொடராகும்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">النَّارُ</span> <span class=\"quran-arabic-font text-success\">يُعْرَضُونَ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهَا</span> <span class=\"quran-arabic-font text-success\">غُدُوّاً</span> <span class=\"quran-arabic-font text-success\">وَعَشِيّاً</span><br />\r\n<br />\r\n(அந்த நெருப்பின் முன் அவர்கள் காலையிலும் மாலையிலும் கொண்டு வரப்படுகிறார்கள்). ஆனால் ஒரு கேள்வி எழுகிறது: இந்த வசனம் மக்காவில் இறக்கப்பட்டதாகும். ஆனால் கப்ரின் வேதனை பற்றி மதீனாவில் தான் நபியவர்களுக்குத் தெரிவிக்கப்பட்டது என்ற செய்தியுடன் இதை எப்படிப் பொருத்துவது? இமாம் அஹ்மத் அவர்கள் ஆயிஷா (ரழி) அவர்களிடமிருந்து பதிவு செய்கிறார்கள்: ஒரு யூதப் பெண் ஆயிஷா (ரழி) அவர்களுக்குப் பணிவிடை செய்து வந்தார். ஆயிஷா (ரழி) அவர்கள் அவருக்கு ஏதேனும் உபகாரம் செய்யும்போது, அந்தப் பெண் \"கப்ரின் வேதனையிலிருந்து அல்லாஹ் உங்களைக் காப்பாற்றுவானாக\" என்று கூறுவார். ஆயிஷா (ரழி) அவர்கள் கூறினார்கள்: \"பிறகு அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் உள்ளே வந்தார்கள். நான், 'அல்லாஹ்வின் தூதரே! மறுமை நாளைக்கு முன்னதாகவே கப்ரில் ஏதேனும் வேதனை இருக்குமா?' என்று கேட்டேன். அதற்கு அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">لَا،</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">زَعَمَ</span> <span class=\"quran-arabic-font text-success\">ذَلِكَ؟</span>»<br />\r\n<br />\r\n(இல்லை, அப்படி யார் சொன்னது?)\"<br />\r\n<br />\r\nநான் கூறினேன்: \"இந்த யூதப் பெண், நான் அவளுக்கு உபகாரம் செய்யும்போதெல்லாம், 'கப்ரின் வேதனையிலிருந்து அல்லாஹ் உங்களைக் காப்பாற்றுவானாக' என்று கூறுகிறாளே!\" அப்போது அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">كَذَبَتْ</span> <span class=\"quran-arabic-font text-success\">يَهُودُ</span> <span class=\"quran-arabic-font text-success\">وَهُمْ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">اللهِ</span> <span class=\"quran-arabic-font text-success\">أَكْذَبُ،</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">عَذَابَ</span> <span class=\"quran-arabic-font text-success\">دُونَ</span> <span class=\"quran-arabic-font text-success\">يَوْمِ</span> <span class=\"quran-arabic-font text-success\">الْقِيَامَة</span>»<br />\r\n<br />\r\n(யூதர்கள் பொய் சொல்கிறார்கள்; அவர்கள் அல்லாஹ்வின் மீதே பெரும் பொய்களைச் சொல்பவர்கள். மறுமை நாளைத் தவிர வேறு வேதனை இல்லை.)<br />\r\n<br />\r\nபின்னர் அல்லாஹ் நாடிய காலம் வரை அவர்கள் அமைதியாக இருந்தார்கள். ஒரு நாள் நண்பகலில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் தங்கள் ஆடையால் போர்த்தியபடி, கண்கள் சிவந்து, உரத்த குரலில் அழைத்துக் கொண்டு வெளியே வந்தார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">الْقَبْرُ</span> <span class=\"quran-arabic-font text-success\">كَقِطَع</span> <span class=\"quran-arabic-font text-success\">اللَّيْلِ</span> <span class=\"quran-arabic-font text-success\">الْمُظْلِمِ،</span> <span class=\"quran-arabic-font text-success\">أَيُّهَا</span> <span class=\"quran-arabic-font text-success\">النَّاسُ</span> <span class=\"quran-arabic-font text-success\">لَوْ</span> <span class=\"quran-arabic-font text-success\">تَعْلَمُونَ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">أَعْلَمُ</span> <span class=\"quran-arabic-font text-success\">لَبَكَيْتُمْ</span> <span class=\"quran-arabic-font text-success\">كَثِيرًا</span> <span class=\"quran-arabic-font text-success\">وَضَحِكْتُمْ</span> <span class=\"quran-arabic-font text-success\">قَلِيلًا،</span> <span class=\"quran-arabic-font text-success\">أَيُّهَا</span> <span class=\"quran-arabic-font text-success\">النَّاسُ،</span> <span class=\"quran-arabic-font text-success\">اسْتَعِيذُوا</span> <span class=\"quran-arabic-font text-success\">بِاللهِ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">عَذَابِ</span> <span class=\"quran-arabic-font text-success\">الْقَبْرِ،</span> <span class=\"quran-arabic-font text-success\">فَإِنَّ</span> <span class=\"quran-arabic-font text-success\">عَذَابَ</span> <span class=\"quran-arabic-font text-success\">الْقَبْرِ</span> <span class=\"quran-arabic-font text-success\">حَق</span>»<br />\r\n<br />\r\n(கப்ரு என்பது இருண்ட இரவின் ஒரு பகுதியைப் போன்றது! மக்களே, நான் அறிந்ததை நீங்கள் அறிந்திருந்தால், நீங்கள் அதிகம் அழுவீர்கள், குறைவாகவே சிரிப்பீர்கள். மக்களே! கப்ரின் வேதனையிலிருந்து அல்லாஹ்விடம் பாதுகாப்புத் தேடுங்கள்; ஏனெனில் கப்ரின் வேதனை என்பது உண்மையானது.)\"<br />\r\n<br />\r\nஇந்த அறிவிப்பாளர் தொடர் புகாரி மற்றும் முஸ்லிமின் நிபந்தனைகளுக்கு ஏற்ப ஸஹீஹானது (ஆயினும் அவர்கள் இதனைப் பதிவு செய்யவில்லை). 'இந்த வசனம் மக்காவில் இறக்கப்பட்டது, அது அல்-பர்ஸக் கால வேதனையைச் சுட்டிக்காட்டுகிறது என்பதும், நபியவர்கள் அதை மறுத்த செய்தியும் எவ்வாறு பொருந்தும்?' என்று கேட்கப்பட்டது. இதற்கான பதில்: இந்த வசனம் (ஃபிர்அவ்ன் மற்றும் அவனது கூட்டத்தாரின்) ஆன்மாக்கள் காலையிலும் மாலையிலும் நெருப்பின் முன் கொண்டு வரப்படுவதைக் குறிக்கிறது. அவர்களின் உடல்கள் கப்ரில் பாதிக்கப்படும் என்று இது நேரடியாகக் கூறவில்லை. எனவே இது அவர்களது ஆன்மாக்களுக்கு மட்டும் உரித்தானதாக இருக்கலாம். அல்-பர்ஸக்கில் அவர்களது உடல்களுக்கு ஏற்படும் பாதிப்பு மற்றும் வேதனையை உணரச் செய்வது பற்றிச் சில ஹதீஸ்களில் விளக்கப்பட்டுள்ளது.<br />\r\n<br />\r\nமேலும், இந்த வசனம் காஃபிர்களுக்கு (நிராகரிப்பாளர்களுக்கு) அல்-பர்ஸக்கில் ஏற்படும் தண்டனையை மட்டுமே குறிக்கிறது என்றும், விசுவாசிகள் (முஃமின்கள்) கப்ரில் தண்டிக்கப்படுவதை இது நேரடியாகக் குறிக்கவில்லை என்றும் கூறப்படுகிறது. இமாம் அஹ்மத் அவர்கள் ஆயிஷா (ரழி) அவர்களிடமிருந்து பதிவு செய்த ஒரு ஹதீஸில், நபியவர்கள் ஆயிஷா (ரழி) அவர்களிடம் நுழைந்த போது அங்கிருந்த ஒரு யூதப் பெண், \"நீங்கள் கப்ரில் சோதிக்கப்படுவீர்கள் என்று எனக்குச் சொல்லப்பட்டது\" என்று கூறினாள். அதற்கு அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கவலையோடு:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِنَّمَا</span> <span class=\"quran-arabic-font text-success\">يُفْتَنُ</span> <span class=\"quran-arabic-font text-success\">يَهُود</span>»<br />\r\n<br />\r\n(யூதர்கள் மட்டுமே அவ்வாறு சோதிக்கப்படுவார்கள்.) என்று கூறினார்கள்.<br />\r\n<br />\r\nஆயிஷா (ரழி) அவர்கள் கூறினார்கள்: \"சில இரவுகள் கடந்த பிறகு அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">أَلَا</span> <span class=\"quran-arabic-font text-success\">إِنَّكُمْ</span> <span class=\"quran-arabic-font text-success\">تُفْتَنُونَ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْقُبُور</span>»<br />\r\n<br />\r\n(அறிந்துகொள்ளுங்கள்! நிச்சயமாக நீங்களும் கப்ருகளில் சோதிக்கப்படுவீர்கள்.)\"<br />\r\n<br />\r\nஆயிஷா (ரழி) அவர்கள் கூறினார்கள்: \"அதற்குப் பிறகு அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கப்ரின் வேதனையிலிருந்து அல்லாஹ்விடம் பாதுகாப்புத் தேடுபவர்களாக இருந்தார்கள்.\" இது முஸ்லிமிலும் பதிவு செய்யப்பட்டுள்ளது. எனவே, இந்த வசனம் ஆன்மாக்கள் தண்டிக்கப்படுவதைக் குறிக்கலாம்; ஆனால் அது உடல்கள் பாதிக்கப்படுவதை அவசியப்படுத்தவில்லை. பின்னர் கப்ரின் வேதனை பற்றி அல்லாஹ் தனது தூதருக்கு வஹீ (இறைச்செய்தி)யாக அறிவித்தபோது, அவர்கள் அதிலிருந்து பாதுகாப்புத் தேடினார்கள். அல்லாஹ்வே நன்கு அறிந்தவன்.<br />\r\n<br />\r\nகப்ரின் வேதனை பற்றி ஏராளமான ஹதீஸ்கள் வந்துள்ளன. கத்தாதா இந்த வசனத்தைப் பற்றிக் கூறும்போது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">غُدُوّاً</span> <span class=\"quran-arabic-font text-success\">وَعَشِيّاً</span><br />\r\n<br />\r\n(காலையிலும் மாலையிலும்.): \"ஒவ்வொரு காலையிலும், ஒவ்வொரு மாலையிலும் இவ்வுலகம் இருக்கும் வரை அவர்களுக்கு இழிவுபடுத்தும் விதமாக 'ஃபிர்அவ்னின் மக்களே! இதுதான் உங்களது தங்குமிடம்' என்று கூறப்படும்.\" இப்னு ஜைத் கூறுகையில்: \"அவர்கள் இன்றும் அங்கே இருக்கிறார்கள். மறுமை வரும் வரை காலையிலும் மாலையிலும் நரக நெருப்பைக் காட்டப்படுகிறார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَيَوْمَ</span> <span class=\"quran-arabic-font text-success\">تَقُومُ</span> <span class=\"quran-arabic-font text-success\">السَّاعَةُ</span> <span class=\"quran-arabic-font text-success\">أَدْخِلُواْ</span> <span class=\"quran-arabic-font text-success\">ءَالَ</span> <span class=\"quran-arabic-font text-success\">فِرْعَوْنَ</span> <span class=\"quran-arabic-font text-success\">أَشَدَّ</span> <span class=\"quran-arabic-font text-success\">الْعَذَابِ</span><br />\r\n<br />\r\n(மேலும் மறுமை நாள் வரும்போது, 'ஃபிர்அவ்னின் கூட்டத்தினரை மிகக் கடுமையான வேதனையில் புகுத்துங்கள்' (எனக் கூறப்படும்).)\" ஃபிர்அவ்னின் கூட்டத்தார் எதையும் சிந்திக்காமல் பாறைகளிலும் மரங்களிலும் மோதி விழும் முட்டாள் ஒட்டகங்களைப் போன்றவர்கள்.<br />\r\n<br />\r\nஇமாம் அஹ்மத் அவர்கள், இப்னு உமர் (ரழி) அவர்கள் அறிவித்ததாகப் பதிவு செய்துள்ளனர்: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">أَحَدَكُمْ</span> <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">مَاتَ</span> <span class=\"quran-arabic-font text-success\">عُرِضَ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span> <span class=\"quran-arabic-font text-success\">مَقْعَدُهُ</span> <span class=\"quran-arabic-font text-success\">بِالْغَدَاةِ</span> <span class=\"quran-arabic-font text-success\">وَالْعَشِيِّ،</span> <span class=\"quran-arabic-font text-success\">إِنْ</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">أَهْلِ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةِ</span> <span class=\"quran-arabic-font text-success\">فَمِنْ</span> <span class=\"quran-arabic-font text-success\">أَهْلِ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةِ،</span> <span class=\"quran-arabic-font text-success\">وَإِنْ</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">أَهْلِ</span> <span class=\"quran-arabic-font text-success\">النَّارِ</span> <span class=\"quran-arabic-font text-success\">فَمِنْ</span> <span class=\"quran-arabic-font text-success\">أَهْلِ</span> <span class=\"quran-arabic-font text-success\">النَّارِ،</span> <span class=\"quran-arabic-font text-success\">فَيُقَالُ</span>: <span class=\"quran-arabic-font text-success\">هذَا</span> <span class=\"quran-arabic-font text-success\">مَقْعَدُكَ</span> <span class=\"quran-arabic-font text-success\">حَتْى</span> <span class=\"quran-arabic-font text-success\">يَبْعَثَكَ</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">عَزَّ</span> <span class=\"quran-arabic-font text-success\">وَجَلَّ</span> <span class=\"quran-arabic-font text-success\">إِلَيْهِ</span> <span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">الْقِيَامَة</span>»<br />\r\n<br />\r\n(உங்களில் ஒருவர் இறந்துவிட்டால், காலையிலும் மாலையிலும் அவருக்குச் சுவனம் அல்லது நரகத்தில் உள்ள அவரது இடம் காட்டப்படும்; அவர் சுவனவாசிகளாக இருந்தால் சுவனவாசிகளின் இடம், நரகவாசிகளாக இருந்தால் நரகவாசிகளின் இடம் காட்டப்படும். 'மறுமை நாளில் அல்லாஹ் உங்களை எழுப்பும் வரை இதுதான் உங்களது இடம்' என்று அவருக்குக் கூறப்படும்.)\"<br />\r\n<br />\r\nஇந்த ஹதீஸ் புகாரி மற்றும் முஸ்லிம் ஆகிய இரு நூல்களிலும் இடம்பெற்றுள்ளது.<br />\r\n<br />\r\n<br />\r\n<br />","text":"அந்த இறைநம்பிக்கையாளரின் வார்த்தைகளின் நிறைவும், இரு தரப்பாரின் இறுதி முடிவும்\n\r\n\n\r\nஅந்த இறைநம்பிக்கையாளர் கூறினார்: \"நான் ஏன் உங்களை ஈடேற்றத்தின் பக்கம் அழைக்கிறேன்? அதுவோ இணை துணையற்ற அல்லாஹ் ஒருவனையே வணங்குவதும், அவன் அனுப்பிய அவனது தூதரை ஈமான் கொள்வதுமாகும்.\"\n\r\n\n\r\nوَيَـقَوْمِ مَا لِى أَدْعُوكُمْ إِلَى النَّجَاةِ وَتَدْعُونَنِى إِلَى النَّارِ - تَدْعُونَنِى لأَكْفُرَ بِاللَّهِ وَأُشْرِكَ بِهِ مَا لَيْسَ لِى بِهِ عِلْمٌ\n\r\n\n\r\n(நீங்களோ என்னை நரகத்தின் பக்கம் அழைக்கிறீர்கள்! நான் அல்லாஹ்வை நிராகரிக்கவும், எனக்கு அறிவில்லாதவற்றை அவனுக்கு இணையாக்கவும் என்னை அழைக்கிறீர்கள்;) அதாவது எந்தவொரு ஆதாரமுமின்றி அறியாமையின் அடிப்படையில் என்னை அழைக்கிறீர்கள்.\n\r\n\n\r\nوَأَنَاْ أَدْعُوكُمْ إِلَى الْعَزِيزِ الْغَفَّارِ\n\r\n\n\r\n(நானோ உங்களை யாவற்றையும் மிகைத்தவனும், பெரும் மன்னிப்பாளனுமான அல்லாஹ்வின் பக்கம் அழைக்கிறேன்!) அதாவது அவனது மகத்தான வல்லமைக்கும் கண்ணியத்திற்கும் மத்தியிலும், அவனிடம் தவ்பா செய்து மீளுபவரின் பாவங்களை அவன் மன்னிக்கிறான்.\n\r\n\n\r\nلاَ جَرَمَ أَنَّمَا تَدْعُونَنِى إِلَيْهِ\n\r\n\n\r\n(நிச்சயமாக, நீங்கள் என்னை எதன் பக்கம் அழைக்கிறீர்களோ) இதற்கு \"உண்மையாகவே\" என்று பொருள் என அறிஞர்கள் கூறுகின்றனர். அஸ்-ஸுத்தி மற்றும் இப்னு ஜரீர் ஆகியோர் இக்கூற்றிற்கு \"நிச்சயமாக\" என்று பொருள் எனக் கூறினார்கள். அத்-தஹ்ஹாக் கூறுகையில்:\n\r\n\n\r\nلاَ جَرَمَ\n\r\n\n\r\n(லா ஜரம) என்பதற்கு, \"இதில் பொய்க்கிடமில்லை\" என்று பொருள். அலீ பின் அபீ தல்ஹா மற்றும் இப்னு அப்பாஸ் (ரழி) கூறினார்கள்:\n\r\n\n\r\nلاَ جَرَمَ\n\r\n\n\r\n(லா ஜரம) என்பதற்கு, \"நிச்சயமாக, நீங்கள் என்னை அழைக்கக்கூடிய இந்தச் சிலைகளுக்கும் பொய்த் தெய்வங்களுக்கும்\n\r\n\n\r\nلَيْسَ لَهُ دَعْوَةٌ فِى الدُّنْيَا وَلاَ فِى الاٌّخِرَةِ\n\r\n\n\r\n(இவ்வுலகிலோ அல்லது மறுமையிலோ எவ்வித அதிகாரமும் இல்லை)\" என்று பொருள். முஜாஹித் கூறுகையில், \"அந்தச் சிலைகளிடம் எதுவுமே இல்லை\" என்றார். கத்தாதா கூறுகையில், \"இதன் பொருள், சிலைகளுக்கு எவ்வித நன்மையோ தீங்கோ செய்ய சக்தியில்லை\" என்றார். அஸ்-ஸுத்தி கூறுகையில், \"இவ்வுலகிலோ அல்லது மறுமையிலோ தம்மை அழைப்பவர்களுக்கு அவை பதில் தராது\" என்றார். இது பின்வரும் வசனத்தைப் போன்றது:\n\r\n\n\r\nوَمَنْ أَضَلُّ مِمَّن يَدْعُو مِن دُونِ اللَّهِ مَن لاَّ يَسْتَجِيبُ لَهُ إِلَى يَوْمِ الْقِيَـمَةِ وَهُمْ عَن دُعَآئِهِمْ غَـفِلُونَ - وَإِذَا حُشِرَ النَّاسُ كَانُواْ لَهُمْ أَعْدَآءً وَكَانُواْ بِعِبَادَتِهِمْ كَـفِرِينَ\n\r\n\n\r\n(மறுமை நாள் வரை தனக்கு பதிலளிக்காத, அல்லாஹ் அல்லாதவற்றை அழைப்பவனை விட மிக வழிதவறியவன் யார்? அவர்களோ இவர்களது அழைப்பைப் பற்றி அறியாதவர்களாக இருக்கின்றனர். மேலும் மக்கள் ஒன்று திரட்டப்படும்போது, அவர்கள் இவர்களுக்கு எதிரிகளாகி விடுவார்கள்; இவர்களது வணக்கத்தையும் நிராகரித்து விடுவார்கள்.) (46:5-6)\n\r\n\n\r\nإِن تَدْعُوهُمْ لاَ يَسْمَعُواْ دُعَآءَكُمْ وَلَوْ سَمِعُواْ مَا اسْتَجَابُواْ لَكُمْ\n\r\n\n\r\n(நீங்கள் அவர்களை அழைத்தால், அவர்கள் உங்கள் அழைப்பைக் கேட்க மாட்டார்கள்; அவர்கள் கேட்டாலும் உங்களுக்குப் பதில் அளிக்க மாட்டார்கள்.) (35:14).\n\r\n\n\r\nوَأَنَّ مَرَدَّنَآ إِلَى اللَّهِ\n\r\n\n\r\n(மேலும் நமது மீளுதல் அல்லாஹ்விடமே இருக்கிறது,) அதாவது மறுமையில் ஒவ்வொருவருக்கும் அவரவர் செயல்களுக்கு ஏற்ப அவன் கூலியளிப்பான் அல்லது தண்டிப்பான். அவன் கூறுகிறான்:\n\r\n\n\r\nوَأَنَّ الْمُسْرِفِينَ هُمْ أَصْحَـبُ النَّارِ\n\r\n\n\r\n(மேலும் வரம்பு மீறுபவர்களே நரகவாசிகள்!) அதாவது அல்லாஹ்வுக்கு இணை வைத்த பெரும் பாவத்தினால், அவர்கள் நரகில் நிரந்தரமாகத் தங்குவார்கள்.\n\r\n\n\r\nفَسَتَذْكُرُونَ مَآ أَقُولُ لَكُـمْ\n\r\n\n\r\n(நான் உங்களுக்குச் சொல்வதை நீங்கள் விரைவில் நினைத்துப் பார்ப்பீர்கள்,) அதாவது 'நான் உங்களுக்கு எதை ஏவினேனோ, எதைத் தடுத்தேனோ மற்றும் நான் உங்களுக்கு வழங்கிய அறிவுரைகளின் உண்மையை நீங்கள் விரைவில் அறிந்துகொள்வீர்கள். கைசேதம் பலனளிக்காத நேரத்தில் நீங்கள் இதற்காக வருத்தப்படுவீர்கள்.'\n\r\n\n\r\nوَأُفَوِّضُ أَمْرِى إِلَى اللَّهِ\n\r\n\n\r\n(மேலும் எனது காரியத்தை நான் அல்லாஹ்விடமே ஒப்படைக்கிறேன்.) அதாவது, 'நான் அல்லாஹ்வின் மீதே முழு நம்பிக்கை (தவக்குல்) வைத்து அவனது உதவியைத் தேடுகிறேன்; உங்களை விட்டும் நான் முற்றிலுமாக ஒதுங்கிக்கொள்கிறேன்.'\n\r\n\n\r\nإِنَّ اللَّهَ بَصِيرٌ بِالْعِبَادِ\n\r\n\n\r\n(நிச்சயமாக அல்லாஹ் அடியார்களை உற்று நோக்குபவன்.) அதாவது அவன் அவர்களைப் பற்றி முற்றிலும் அறிந்தவன்; அவன் உயர்ந்தவனும் தூய்மையானவனுமாவான். அவன் தகுதியுள்ளவர்களுக்கு நேர்வழி காட்டுகிறான், வழிகேட்டிற்குத் தகுதியானவர்களை வழிகேட்டில் விடுகிறான். அவனிடமே முழுமையான ஆதாரமும், உன்னதமான ஞானமும், மகத்தான வல்லமையும் உள்ளன.\n\r\n\n\r\nفَوقَاهُ اللَّهُ سَيِّئَاتِ مَا مَكَـرُواْ\n\r\n\n\r\n(ஆகவே, அவர்கள் செய்த சதிச் செயல்களின் தீமைகளிலிருந்து அல்லாஹ் அவரைக் காப்பாற்றினான்,) அதாவது இவ்வுலகிலும் மறுமையிலும்; இவ்வுலகில் மூஸா (அலை) அவர்களுடன் சேர்த்து அல்லாஹ் அவரையும் காப்பாற்றினான், மறுமையில் அவரைச் சுவனத்தில் புகுத்துவான்.\n\r\n\n\r\nகப்ரின் வேதனைக்கான ஆதாரம்\n\r\n\n\r\nوَحَاقَ بِآلِ فِرْعَوْنَ سُوءُ الْعَذَابِ\n\r\n\n\r\n(ஃபிர்அவ்னின் கூட்டத்தினரை ஒரு கொடிய வேதனை சூழ்ந்துகொண்டது.) இது அவர்கள் கடலில் மூழ்கடிக்கப்பட்டதைக் குறிக்கிறது. அதன் பிறகு அவர்கள் நரகிற்கு மாற்றப்பட்டனர். கியாமத் நாள் வரும் வரை அவர்களது ஆன்மாக்கள் காலையிலும் மாலையிலும் நரக நெருப்பின் முன் கொண்டு வரப்படுகின்றன. மறுமை நாள் வரும்போது, அவர்களின் ஆன்மாக்களும் உடல்களும் நரகில் மீண்டும் இணைக்கப்படும். அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَيَوْمَ تَقُومُ السَّاعَةُ أَدْخِلُواْ ءَالَ فِرْعَوْنَ أَشَدَّ الْعَذَابِ\n\r\n\n\r\n(மேலும் மறுமை நாள் வரும்போது, \"ஃபிர்அவ்னின் கூட்டத்தினரை மிகக் கடுமையான வேதனையில் புகுத்துங்கள்\" (என வானவர்களுக்குக் கூறப்படும்).) அதாவது மிகத் தீவிரமான வலியும் வேதனையும் அளிக்கப்படும். அல்-பர்ஸக் (மறுமைக்கு முந்தைய திரை) காலத்தில் கப்ரில் வேதனை இருக்கும் என்பதை நிரூபிக்க அஹ்லுஸ் ஸுன்னாவால் பயன்படுத்தப்படும் மிக முக்கியமான ஆதாரம் இந்த வசனமாகும். அது பின்வரும் சொற்றொடராகும்:\n\r\n\n\r\nالنَّارُ يُعْرَضُونَ عَلَيْهَا غُدُوّاً وَعَشِيّاً\n\r\n\n\r\n(அந்த நெருப்பின் முன் அவர்கள் காலையிலும் மாலையிலும் கொண்டு வரப்படுகிறார்கள்). ஆனால் ஒரு கேள்வி எழுகிறது: இந்த வசனம் மக்காவில் இறக்கப்பட்டதாகும். ஆனால் கப்ரின் வேதனை பற்றி மதீனாவில் தான் நபியவர்களுக்குத் தெரிவிக்கப்பட்டது என்ற செய்தியுடன் இதை எப்படிப் பொருத்துவது? இமாம் அஹ்மத் அவர்கள் ஆயிஷா (ரழி) அவர்களிடமிருந்து பதிவு செய்கிறார்கள்: ஒரு யூதப் பெண் ஆயிஷா (ரழி) அவர்களுக்குப் பணிவிடை செய்து வந்தார். ஆயிஷா (ரழி) அவர்கள் அவருக்கு ஏதேனும் உபகாரம் செய்யும்போது, அந்தப் பெண் \"கப்ரின் வேதனையிலிருந்து அல்லாஹ் உங்களைக் காப்பாற்றுவானாக\" என்று கூறுவார். ஆயிஷா (ரழி) அவர்கள் கூறினார்கள்: \"பிறகு அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் உள்ளே வந்தார்கள். நான், 'அல்லாஹ்வின் தூதரே! மறுமை நாளைக்கு முன்னதாகவே கப்ரில் ஏதேனும் வேதனை இருக்குமா?' என்று கேட்டேன். அதற்கு அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«لَا، مَنْ زَعَمَ ذَلِكَ؟»\n\r\n\n\r\n(இல்லை, அப்படி யார் சொன்னது?)\"\n\r\n\n\r\nநான் கூறினேன்: \"இந்த யூதப் பெண், நான் அவளுக்கு உபகாரம் செய்யும்போதெல்லாம், 'கப்ரின் வேதனையிலிருந்து அல்லாஹ் உங்களைக் காப்பாற்றுவானாக' என்று கூறுகிறாளே!\" அப்போது அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«كَذَبَتْ يَهُودُ وَهُمْ عَلَى اللهِ أَكْذَبُ، لَا عَذَابَ دُونَ يَوْمِ الْقِيَامَة»\n\r\n\n\r\n(யூதர்கள் பொய் சொல்கிறார்கள்; அவர்கள் அல்லாஹ்வின் மீதே பெரும் பொய்களைச் சொல்பவர்கள். மறுமை நாளைத் தவிர வேறு வேதனை இல்லை.)\n\r\n\n\r\nபின்னர் அல்லாஹ் நாடிய காலம் வரை அவர்கள் அமைதியாக இருந்தார்கள். ஒரு நாள் நண்பகலில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் தங்கள் ஆடையால் போர்த்தியபடி, கண்கள் சிவந்து, உரத்த குரலில் அழைத்துக் கொண்டு வெளியே வந்தார்கள்:\n\r\n\n\r\n«الْقَبْرُ كَقِطَع اللَّيْلِ الْمُظْلِمِ، أَيُّهَا النَّاسُ لَوْ تَعْلَمُونَ مَا أَعْلَمُ لَبَكَيْتُمْ كَثِيرًا وَضَحِكْتُمْ قَلِيلًا، أَيُّهَا النَّاسُ، اسْتَعِيذُوا بِاللهِ مِنْ عَذَابِ الْقَبْرِ، فَإِنَّ عَذَابَ الْقَبْرِ حَق»\n\r\n\n\r\n(கப்ரு என்பது இருண்ட இரவின் ஒரு பகுதியைப் போன்றது! மக்களே, நான் அறிந்ததை நீங்கள் அறிந்திருந்தால், நீங்கள் அதிகம் அழுவீர்கள், குறைவாகவே சிரிப்பீர்கள். மக்களே! கப்ரின் வேதனையிலிருந்து அல்லாஹ்விடம் பாதுகாப்புத் தேடுங்கள்; ஏனெனில் கப்ரின் வேதனை என்பது உண்மையானது.)\"\n\r\n\n\r\nஇந்த அறிவிப்பாளர் தொடர் புகாரி மற்றும் முஸ்லிமின் நிபந்தனைகளுக்கு ஏற்ப ஸஹீஹானது (ஆயினும் அவர்கள் இதனைப் பதிவு செய்யவில்லை). 'இந்த வசனம் மக்காவில் இறக்கப்பட்டது, அது அல்-பர்ஸக் கால வேதனையைச் சுட்டிக்காட்டுகிறது என்பதும், நபியவர்கள் அதை மறுத்த செய்தியும் எவ்வாறு பொருந்தும்?' என்று கேட்கப்பட்டது. இதற்கான பதில்: இந்த வசனம் (ஃபிர்அவ்ன் மற்றும் அவனது கூட்டத்தாரின்) ஆன்மாக்கள் காலையிலும் மாலையிலும் நெருப்பின் முன் கொண்டு வரப்படுவதைக் குறிக்கிறது. அவர்களின் உடல்கள் கப்ரில் பாதிக்கப்படும் என்று இது நேரடியாகக் கூறவில்லை. எனவே இது அவர்களது ஆன்மாக்களுக்கு மட்டும் உரித்தானதாக இருக்கலாம். அல்-பர்ஸக்கில் அவர்களது உடல்களுக்கு ஏற்படும் பாதிப்பு மற்றும் வேதனையை உணரச் செய்வது பற்றிச் சில ஹதீஸ்களில் விளக்கப்பட்டுள்ளது.\n\r\n\n\r\nமேலும், இந்த வசனம் காஃபிர்களுக்கு (நிராகரிப்பாளர்களுக்கு) அல்-பர்ஸக்கில் ஏற்படும் தண்டனையை மட்டுமே குறிக்கிறது என்றும், விசுவாசிகள் (முஃமின்கள்) கப்ரில் தண்டிக்கப்படுவதை இது நேரடியாகக் குறிக்கவில்லை என்றும் கூறப்படுகிறது. இமாம் அஹ்மத் அவர்கள் ஆயிஷா (ரழி) அவர்களிடமிருந்து பதிவு செய்த ஒரு ஹதீஸில், நபியவர்கள் ஆயிஷா (ரழி) அவர்களிடம் நுழைந்த போது அங்கிருந்த ஒரு யூதப் பெண், \"நீங்கள் கப்ரில் சோதிக்கப்படுவீர்கள் என்று எனக்குச் சொல்லப்பட்டது\" என்று கூறினாள். அதற்கு அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கவலையோடு:\n\r\n\n\r\n«إِنَّمَا يُفْتَنُ يَهُود»\n\r\n\n\r\n(யூதர்கள் மட்டுமே அவ்வாறு சோதிக்கப்படுவார்கள்.) என்று கூறினார்கள்.\n\r\n\n\r\nஆயிஷா (ரழி) அவர்கள் கூறினார்கள்: \"சில இரவுகள் கடந்த பிறகு அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«أَلَا إِنَّكُمْ تُفْتَنُونَ فِي الْقُبُور»\n\r\n\n\r\n(அறிந்துகொள்ளுங்கள்! நிச்சயமாக நீங்களும் கப்ருகளில் சோதிக்கப்படுவீர்கள்.)\"\n\r\n\n\r\nஆயிஷா (ரழி) அவர்கள் கூறினார்கள்: \"அதற்குப் பிறகு அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கப்ரின் வேதனையிலிருந்து அல்லாஹ்விடம் பாதுகாப்புத் தேடுபவர்களாக இருந்தார்கள்.\" இது முஸ்லிமிலும் பதிவு செய்யப்பட்டுள்ளது. எனவே, இந்த வசனம் ஆன்மாக்கள் தண்டிக்கப்படுவதைக் குறிக்கலாம்; ஆனால் அது உடல்கள் பாதிக்கப்படுவதை அவசியப்படுத்தவில்லை. பின்னர் கப்ரின் வேதனை பற்றி அல்லாஹ் தனது தூதருக்கு வஹீ (இறைச்செய்தி)யாக அறிவித்தபோது, அவர்கள் அதிலிருந்து பாதுகாப்புத் தேடினார்கள். அல்லாஹ்வே நன்கு அறிந்தவன்.\n\r\n\n\r\nகப்ரின் வேதனை பற்றி ஏராளமான ஹதீஸ்கள் வந்துள்ளன. கத்தாதா இந்த வசனத்தைப் பற்றிக் கூறும்போது:\n\r\n\n\r\nغُدُوّاً وَعَشِيّاً\n\r\n\n\r\n(காலையிலும் மாலையிலும்.): \"ஒவ்வொரு காலையிலும், ஒவ்வொரு மாலையிலும் இவ்வுலகம் இருக்கும் வரை அவர்களுக்கு இழிவுபடுத்தும் விதமாக 'ஃபிர்அவ்னின் மக்களே! இதுதான் உங்களது தங்குமிடம்' என்று கூறப்படும்.\" இப்னு ஜைத் கூறுகையில்: \"அவர்கள் இன்றும் அங்கே இருக்கிறார்கள். மறுமை வரும் வரை காலையிலும் மாலையிலும் நரக நெருப்பைக் காட்டப்படுகிறார்கள்.\n\r\n\n\r\nوَيَوْمَ تَقُومُ السَّاعَةُ أَدْخِلُواْ ءَالَ فِرْعَوْنَ أَشَدَّ الْعَذَابِ\n\r\n\n\r\n(மேலும் மறுமை நாள் வரும்போது, 'ஃபிர்அவ்னின் கூட்டத்தினரை மிகக் கடுமையான வேதனையில் புகுத்துங்கள்' (எனக் கூறப்படும்).)\" ஃபிர்அவ்னின் கூட்டத்தார் எதையும் சிந்திக்காமல் பாறைகளிலும் மரங்களிலும் மோதி விழும் முட்டாள் ஒட்டகங்களைப் போன்றவர்கள்.\n\r\n\n\r\nஇமாம் அஹ்மத் அவர்கள், இப்னு உமர் (ரழி) அவர்கள் அறிவித்ததாகப் பதிவு செய்துள்ளனர்: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«إِنَّ أَحَدَكُمْ إِذَا مَاتَ عُرِضَ عَلَيْهِ مَقْعَدُهُ بِالْغَدَاةِ وَالْعَشِيِّ، إِنْ كَانَ مِنْ أَهْلِ الْجَنَّةِ فَمِنْ أَهْلِ الْجَنَّةِ، وَإِنْ كَانَ مِنْ أَهْلِ النَّارِ فَمِنْ أَهْلِ النَّارِ، فَيُقَالُ: هذَا مَقْعَدُكَ حَتْى يَبْعَثَكَ اللهُ عَزَّ وَجَلَّ إِلَيْهِ يَوْمَ الْقِيَامَة»\n\r\n\n\r\n(உங்களில் ஒருவர் இறந்துவிட்டால், காலையிலும் மாலையிலும் அவருக்குச் சுவனம் அல்லது நரகத்தில் உள்ள அவரது இடம் காட்டப்படும்; அவர் சுவனவாசிகளாக இருந்தால் சுவனவாசிகளின் இடம், நரகவாசிகளாக இருந்தால் நரகவாசிகளின் இடம் காட்டப்படும். 'மறுமை நாளில் அல்லாஹ் உங்களை எழுப்பும் வரை இதுதான் உங்களது இடம்' என்று அவருக்குக் கூறப்படும்.)\"\n\r\n\n\r\nஇந்த ஹதீஸ் புகாரி மற்றும் முஸ்லிம் ஆகிய இரு நூல்களிலும் இடம்பெற்றுள்ளது."},"47":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=40&ayah=50\" class=\"link\">40:50</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 40:50 ஐ பார்க்கவும்"},"48":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=40&ayah=50\" class=\"link\">40:50</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 40:50 ஐ பார்க்கவும்"},"49":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=40&ayah=50\" class=\"link\">40:50</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 40:50 ஐ பார்க்கவும்"},"50":{"html":"<strong>நரகவாசிகளின் தர்க்கம்</strong><br />\r\n<br />\r\nநரகவாசிகள் தங்களுக்குள் எவ்வாறு தர்க்கம் செய்து வாதிடுவார்கள் என்பதைப் பற்றி அல்லாஹ் நமக்குக் கூறுகிறான். ஃபிர்அவ்னும் அவனது மக்களும் அவர்களில் அடங்குவர். (அவர்களைப்) பின்தொடர்ந்த பலவீனமானவர்கள், தலைவர்களாகவும் எஜமானர்களாகவும் இருந்து பெருமையடித்தவர்களிடம் கூறுவார்கள்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾إِنَّا</span> <span class=\"quran-arabic-font text-success\">كُنَّا</span> <span class=\"quran-arabic-font text-success\">لَكُمْ</span> <span class=\"quran-arabic-font text-success\">تَبَعًا﴿</span><br />\r\n<br />\r\n(நிச்சயமாக, நாங்கள் உங்களைப் பின்தொடர்ந்தோம்,) அதாவது, \"இவ்வுலகில் நாங்கள் உங்களுக்குக் கீழ்ப்படிந்து, நிராகரிப்பு மற்றும் வழிகேட்டின் பால் நீங்கள் விடுத்த அழைப்பிற்குச் செவிசாய்த்தோம்\" (என்பதாகும்).<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَهَلْ</span> <span class=\"quran-arabic-font text-success\">أَنتُم</span> <span class=\"quran-arabic-font text-success\">مُّغْنُونَ</span> <span class=\"quran-arabic-font text-success\">عَنَّا</span> <span class=\"quran-arabic-font text-success\">نَصِيباً</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">النَّارِ﴿</span><br />\r\n<br />\r\n(எனவே இந்த நெருப்பில் ஒரு பகுதியை எங்களிலிருந்து நீங்கள் அகற்ற முடியுமா?) அதாவது, \"எங்கள் சுமையில் ஒரு பகுதியை நீங்கள் சுமந்து கொள்ள முடியுமா?\" (என்பதாகும்).<br />\r\n<span class=\"quran-arabic-font text-success\">﴾قَالَ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">اسْتَكْبَرُواْ</span> <span class=\"quran-arabic-font text-success\">إِنَّا</span> <span class=\"quran-arabic-font text-success\">كُلٌّ</span> <span class=\"quran-arabic-font text-success\">فِيهَآ﴿</span><br />\r\n<br />\r\n(பெருமையடித்தவர்கள் கூறுவார்கள்: \"நிச்சயமாக நாம் அனைவரும் இதில் (ஒன்றாகவே) இருக்கிறோம்!...\") அதாவது, \"நாங்கள் உங்களுடைய சுமையில் எதையும் சுமக்க மாட்டோம்; எங்களுக்கு அளிக்கப்பட்டுள்ள தண்டனையே நாங்கள் சுமக்க போதுமானதாக உள்ளது\" (என்பதாகும்).<br />\r\n<span class=\"quran-arabic-font text-success\">﴾إِنَّ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">قَدْ</span> <span class=\"quran-arabic-font text-success\">حَكَمَ</span> <span class=\"quran-arabic-font text-success\">بَيْنَ</span> <span class=\"quran-arabic-font text-success\">الْعِبَادِ﴿</span><br />\r\n<br />\r\n(நிச்சயமாக, அல்லாஹ் தன் அடியார்களுக்கு இடையே தீர்ப்பளித்துவிட்டான்!) அதாவது, \"நம்மில் ஒவ்வொருவரும் எதற்குத் தகுதியானவர்களோ அதற்கேற்ப அல்லாஹ் தண்டனையைப் பகிர்ந்து அளித்துவிட்டான்\" (என்பதாகும்). இது பின்வரும் வசனத்தைப் போன்றது:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾قَالَ</span> <span class=\"quran-arabic-font text-success\">لِكُلٍّ</span> <span class=\"quran-arabic-font text-success\">ضِعْفٌ</span> <span class=\"quran-arabic-font text-success\">وَلَـكِن</span> <span class=\"quran-arabic-font text-success\">لاَّ</span> <span class=\"quran-arabic-font text-success\">تَعْلَمُونَ﴿</span><br />\r\n<br />\r\n(அவன் கூறுவான்: \"ஒவ்வொருவருக்கும் இரட்டிப்பு (வேதனை) உண்டு, ஆனால் நீங்கள் அறியமாட்டீர்கள்.\") (<a href=\"qurandisp.php?sura=7&ayah=38\" class=\"link\">7:38</a>)<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَقَالَ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">النَّارِ</span> <span class=\"quran-arabic-font text-success\">لِخَزَنَةِ</span> <span class=\"quran-arabic-font text-success\">جَهَنَّمَ</span> <span class=\"quran-arabic-font text-success\">ادْعُواْ</span> <span class=\"quran-arabic-font text-success\">رَبَّكُمْ</span> <span class=\"quran-arabic-font text-success\">يُخَفِّفْ</span> <span class=\"quran-arabic-font text-success\">عَنَّا</span> <span class=\"quran-arabic-font text-success\">يَوْماً</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">الْعَذَابِ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(நெருப்பிலுள்ளவர்கள் நரகத்தின் காவலர்களிடம் (வானவர்களிடம்) கூறுவார்கள்: \"எங்களுக்கு ஒரு நாள் வேதனையை இலேசாக்குமாறு உங்கள் இறைவனிடம் பிரார்த்தியுங்கள்!\") அல்லாஹ் அவர்களுக்குப் பதிலளிக்க மாட்டான் என்பதையும் அவர்களின் பிரார்த்தனைக்குச் செவிசாய்க்க மாட்டான் என்பதையும் அவர்கள் அறிவார்கள். ஏனெனில் அவன் இவ்வாறு கூறினான்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾اخْسَئُواْ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">تُكَلِّمُونِ﴿</span><br />\r\n<br />\r\n(அதில் இழிவோடு கிடயுங்கள்! என்னிடம் பேசாதீர்கள்!) (<a href=\"qurandisp.php?sura=23&ayah=108\" class=\"link\">23:108</a>). எனவே, நரகவாசிகளைக் கண்காணிக்கும் சிறைக்காவலர்களைப் போன்ற நரகத்தின் காவலர்களிடம், ஒரே ஒரு நாளாவது தங்களுக்கு நெருப்பின் வேதனையை இலேசாக்குமாறு அல்லாஹ்விடம் பிரார்த்திக்குமாறு அவர்கள் வேண்டுவார்கள். ஆனால் நரகத்தின் காவலர்கள் அதனை மறுத்து அவர்களிடம் இவ்வாறு கேட்பார்கள்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾قَالُوا</span> <span class=\"quran-arabic-font text-success\">أَوَلَمْ</span> <span class=\"quran-arabic-font text-success\">تَكُ</span> <span class=\"quran-arabic-font text-success\">تَأْتِيكُمْ</span> <span class=\"quran-arabic-font text-success\">رُسُلُكُم</span> <span class=\"quran-arabic-font text-success\">بِالْبَيِّنَـتِ﴿</span><br />\r\n<br />\r\n(அவர்கள் கூறுவார்கள்: \"உங்களிடம் உங்களுடைய தூதர்கள் தெளிவான அத்தாட்சிகளுடன் வரவில்லையா?\") அதாவது, இவ்வுலகில் தூதர்களின் நாவுகள் வாயிலாக ஆதாரங்கள் நிலைநாட்டப்படவில்லையா? (என்பதாகும்).<br />\r\n<span class=\"quran-arabic-font text-success\">﴾قَالُواْ</span> <span class=\"quran-arabic-font text-success\">بَلَى</span> <span class=\"quran-arabic-font text-success\">قَالُواْ</span> <span class=\"quran-arabic-font text-success\">فَادْعُواْ﴿</span><br />\r\n<br />\r\n(அவர்கள், \"ஆம்\" என்பார்கள். (அதற்கு வானவர்கள்) \"அப்படியானால் நீங்களே பிரார்த்தியுங்கள்\" என்று கூறுவார்கள்.) இதன் பொருள்: \"உங்களை நீங்களே கவனித்துக் கொள்ளுங்கள். நாங்கள் உங்களுக்காகப் பிரார்த்திக்க மாட்டோம், உங்கள் கோரிக்கைக்குச் செவிசாய்க்கவும் மாட்டோம்; நீங்கள் ஈடேற்றம் பெறுவதை நாங்கள் விரும்பவில்லை, உங்களுக்கும் எங்களுக்கும் எந்தத் தொடர்பும் இல்லை. மேலும், நீங்கள் பிரார்த்தனை செய்தாலும் செய்யாவிட்டாலும் இரண்டுமே சமம்தான். ஏனெனில் அல்லாஹ் இதற்குப் பதிலளிக்க மாட்டான், அவன் உங்களுடைய வேதனையை இலேசாக்கவும் மாட்டான்\" என்று அவர்கள் கூறுவார்கள். நரகத்தின் காவலர்கள் இவ்வாறு கூறுவார்கள்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَمَا</span> <span class=\"quran-arabic-font text-success\">دُعَآءُ</span> <span class=\"quran-arabic-font text-success\">الْكَـفِرِينَ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">ضَلَـلٍ﴿</span><br />\r\n<br />\r\n(மேலும் நிராகரிப்பவர்களின் பிரார்த்தனை வீணானதே தவிர வேறில்லை!) அதாவது, அது ஏற்றுக்கொள்ளப்படாது அல்லது அதற்குப் பதில் அளிக்கப்படாது.<br />\r\n<br />","text":"நரகவாசிகளின் தர்க்கம்\n\r\n\n\r\nநரகவாசிகள் தங்களுக்குள் எவ்வாறு தர்க்கம் செய்து வாதிடுவார்கள் என்பதைப் பற்றி அல்லாஹ் நமக்குக் கூறுகிறான். ஃபிர்அவ்னும் அவனது மக்களும் அவர்களில் அடங்குவர். (அவர்களைப்) பின்தொடர்ந்த பலவீனமானவர்கள், தலைவர்களாகவும் எஜமானர்களாகவும் இருந்து பெருமையடித்தவர்களிடம் கூறுவார்கள்:\n\r\n﴾إِنَّا كُنَّا لَكُمْ تَبَعًا﴿\n\r\n\n\r\n(நிச்சயமாக, நாங்கள் உங்களைப் பின்தொடர்ந்தோம்,) அதாவது, \"இவ்வுலகில் நாங்கள் உங்களுக்குக் கீழ்ப்படிந்து, நிராகரிப்பு மற்றும் வழிகேட்டின் பால் நீங்கள் விடுத்த அழைப்பிற்குச் செவிசாய்த்தோம்\" (என்பதாகும்).\n\r\n﴾فَهَلْ أَنتُم مُّغْنُونَ عَنَّا نَصِيباً مِّنَ النَّارِ﴿\n\r\n\n\r\n(எனவே இந்த நெருப்பில் ஒரு பகுதியை எங்களிலிருந்து நீங்கள் அகற்ற முடியுமா?) அதாவது, \"எங்கள் சுமையில் ஒரு பகுதியை நீங்கள் சுமந்து கொள்ள முடியுமா?\" (என்பதாகும்).\n\r\n﴾قَالَ الَّذِينَ اسْتَكْبَرُواْ إِنَّا كُلٌّ فِيهَآ﴿\n\r\n\n\r\n(பெருமையடித்தவர்கள் கூறுவார்கள்: \"நிச்சயமாக நாம் அனைவரும் இதில் (ஒன்றாகவே) இருக்கிறோம்!...\") அதாவது, \"நாங்கள் உங்களுடைய சுமையில் எதையும் சுமக்க மாட்டோம்; எங்களுக்கு அளிக்கப்பட்டுள்ள தண்டனையே நாங்கள் சுமக்க போதுமானதாக உள்ளது\" (என்பதாகும்).\n\r\n﴾إِنَّ اللَّهَ قَدْ حَكَمَ بَيْنَ الْعِبَادِ﴿\n\r\n\n\r\n(நிச்சயமாக, அல்லாஹ் தன் அடியார்களுக்கு இடையே தீர்ப்பளித்துவிட்டான்!) அதாவது, \"நம்மில் ஒவ்வொருவரும் எதற்குத் தகுதியானவர்களோ அதற்கேற்ப அல்லாஹ் தண்டனையைப் பகிர்ந்து அளித்துவிட்டான்\" (என்பதாகும்). இது பின்வரும் வசனத்தைப் போன்றது:\n\r\n﴾قَالَ لِكُلٍّ ضِعْفٌ وَلَـكِن لاَّ تَعْلَمُونَ﴿\n\r\n\n\r\n(அவன் கூறுவான்: \"ஒவ்வொருவருக்கும் இரட்டிப்பு (வேதனை) உண்டு, ஆனால் நீங்கள் அறியமாட்டீர்கள்.\") (7:38)\n\r\n﴾وَقَالَ الَّذِينَ فِى النَّارِ لِخَزَنَةِ جَهَنَّمَ ادْعُواْ رَبَّكُمْ يُخَفِّفْ عَنَّا يَوْماً مِّنَ الْعَذَابِ ﴿\n\r\n\n\r\n(நெருப்பிலுள்ளவர்கள் நரகத்தின் காவலர்களிடம் (வானவர்களிடம்) கூறுவார்கள்: \"எங்களுக்கு ஒரு நாள் வேதனையை இலேசாக்குமாறு உங்கள் இறைவனிடம் பிரார்த்தியுங்கள்!\") அல்லாஹ் அவர்களுக்குப் பதிலளிக்க மாட்டான் என்பதையும் அவர்களின் பிரார்த்தனைக்குச் செவிசாய்க்க மாட்டான் என்பதையும் அவர்கள் அறிவார்கள். ஏனெனில் அவன் இவ்வாறு கூறினான்:\n\r\n﴾اخْسَئُواْ فِيهَا وَلاَ تُكَلِّمُونِ﴿\n\r\n\n\r\n(அதில் இழிவோடு கிடயுங்கள்! என்னிடம் பேசாதீர்கள்!) (23:108). எனவே, நரகவாசிகளைக் கண்காணிக்கும் சிறைக்காவலர்களைப் போன்ற நரகத்தின் காவலர்களிடம், ஒரே ஒரு நாளாவது தங்களுக்கு நெருப்பின் வேதனையை இலேசாக்குமாறு அல்லாஹ்விடம் பிரார்த்திக்குமாறு அவர்கள் வேண்டுவார்கள். ஆனால் நரகத்தின் காவலர்கள் அதனை மறுத்து அவர்களிடம் இவ்வாறு கேட்பார்கள்:\n\r\n﴾قَالُوا أَوَلَمْ تَكُ تَأْتِيكُمْ رُسُلُكُم بِالْبَيِّنَـتِ﴿\n\r\n\n\r\n(அவர்கள் கூறுவார்கள்: \"உங்களிடம் உங்களுடைய தூதர்கள் தெளிவான அத்தாட்சிகளுடன் வரவில்லையா?\") அதாவது, இவ்வுலகில் தூதர்களின் நாவுகள் வாயிலாக ஆதாரங்கள் நிலைநாட்டப்படவில்லையா? (என்பதாகும்).\n\r\n﴾قَالُواْ بَلَى قَالُواْ فَادْعُواْ﴿\n\r\n\n\r\n(அவர்கள், \"ஆம்\" என்பார்கள். (அதற்கு வானவர்கள்) \"அப்படியானால் நீங்களே பிரார்த்தியுங்கள்\" என்று கூறுவார்கள்.) இதன் பொருள்: \"உங்களை நீங்களே கவனித்துக் கொள்ளுங்கள். நாங்கள் உங்களுக்காகப் பிரார்த்திக்க மாட்டோம், உங்கள் கோரிக்கைக்குச் செவிசாய்க்கவும் மாட்டோம்; நீங்கள் ஈடேற்றம் பெறுவதை நாங்கள் விரும்பவில்லை, உங்களுக்கும் எங்களுக்கும் எந்தத் தொடர்பும் இல்லை. மேலும், நீங்கள் பிரார்த்தனை செய்தாலும் செய்யாவிட்டாலும் இரண்டுமே சமம்தான். ஏனெனில் அல்லாஹ் இதற்குப் பதிலளிக்க மாட்டான், அவன் உங்களுடைய வேதனையை இலேசாக்கவும் மாட்டான்\" என்று அவர்கள் கூறுவார்கள். நரகத்தின் காவலர்கள் இவ்வாறு கூறுவார்கள்:\n\r\n﴾وَمَا دُعَآءُ الْكَـفِرِينَ إِلاَّ فِى ضَلَـلٍ﴿\n\r\n\n\r\n(மேலும் நிராகரிப்பவர்களின் பிரார்த்தனை வீணானதே தவிர வேறில்லை!) அதாவது, அது ஏற்றுக்கொள்ளப்படாது அல்லது அதற்குப் பதில் அளிக்கப்படாது."},"51":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=40&ayah=56\" class=\"link\">40:56</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 40:56 ஐ பார்க்கவும்"},"52":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=40&ayah=56\" class=\"link\">40:56</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 40:56 ஐ பார்க்கவும்"},"53":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=40&ayah=56\" class=\"link\">40:56</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 40:56 ஐ பார்க்கவும்"},"54":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=40&ayah=56\" class=\"link\">40:56</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 40:56 ஐ பார்க்கவும்"},"55":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=40&ayah=56\" class=\"link\">40:56</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 40:56 ஐ பார்க்கவும்"},"56":{"html":"<strong>தூதர்கள் மற்றும் நம்பிக்கையாளர்களின் வெற்றி</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّا</span> <span class=\"quran-arabic-font text-success\">لَنَنصُرُ</span> <span class=\"quran-arabic-font text-success\">رُسُلَنَا</span> <span class=\"quran-arabic-font text-success\">وَالَّذِينَ</span> <span class=\"quran-arabic-font text-success\">ءَامَنُواْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْحَيَوةِ</span> <span class=\"quran-arabic-font text-success\">الدُّنْيَا</span><br />\r\n<br />\r\n(நிச்சயமாக, நாம் நமது தூதர்களுக்கும், இவ்வுலக வாழ்வில் ஈமான் கொண்டவர்களுக்கும் நிச்சயமாக உதவி செய்வோம்). அஸ்-ஸுத்தி கூறுகிறார், \"அல்லாஹ் ஒரு சமூகத்திற்கு ஒரு தூதரை அனுப்பி, அந்த மக்கள் அவரைக் கொன்றாலோ அல்லது சத்தியத்தின் பக்கம் மக்களை அழைக்கும் நம்பிக்கையாளர்களில் சிலரைக் கொன்றாலோ, அந்தத் தலைமுறை கடந்து சென்ற பிறகு, அவர்களது அழைப்பிற்கு ஆதரவளிப்பவரையும், இவ்வுலகிலேயே அவர்களுக்கு அக்கொடுமையைச் செய்தவர்களிடம் பழிவாங்குபவரையும் அல்லாஹ் அனுப்புகிறான். எனவே, நபிமார்களும் நம்பிக்கையாளர்களும் இவ்வுலகில் கொல்லப்படலாம், ஆனால் அவர்களின் அழைப்பு (தஃவா) இவ்வுலகில் மேலோங்கி நிற்கும்.\" அல்லாஹ் தனது தூதர் முஹம்மது (ஸல்) அவர்களுக்கும், அவர்களின் தோழர்களுக்கும் (ரழி), அவர்களை எதிர்த்தவர்கள், நிராகரித்தவர்கள் மற்றும் பகைமை பாராட்டியவர்கள் மீது வெற்றியை அளித்தான். அவன் தனது வார்த்தையையும் தனது மார்க்கத்தையும் மற்ற எல்லா மார்க்கங்களையும் விட மேலோங்கச் செய்தான். அவர்களைத் தனது சமூகத்தை விட்டு அல்-மதீனாவிற்கு ஹிஜ்ரத் செய்யுமாறு கட்டளையிட்டான்; அங்கு அவர்களுக்கு ஆதரவாளர்களையும் உதவியாளர்களையும் (அன்சாரிகளை) வழங்கினான். பிறகு, பத்ரு போரின் போது இணைவைப்பாளர்களுக்கு எதிராக அவர்களுக்கு அல்லாஹ் வெற்றியளித்தான். அவர்களை இழிவுபடுத்தி, அவர்களின் தலைவர்களைக் கொன்று, முக்கியப் பிரமுகர்களைக் கைதிகளாகப் பிடித்து, சங்கிலிகளால் பிணைத்து தமக்கு முன்னால் இழுத்து வரச் செய்தான். பிறகு, அவர்களிடமிருந்து ஈட்டுத்தொகையை (பிணைத்தொகை) ஏற்றுக்கொண்டு அவர்களுக்கு அவர்கள் (ஸல்) அருள் புரிந்தார்கள். அதற்குச் சிறிது காலத்திற்குப் பிறகு, அல்லாஹ் அவர்களை மக்காவை வெற்றி கொள்ளச் செய்தான். புனிதமும் மேன்மையும் மிக்க அல்-ஹரம் பூமியான தனது தாயகத்திற்குத் திரும்பியதில் அவர்கள் (ஸல்) மகிழ்ச்சி அடைந்தார்கள். அவர்கள் மூலமாக, அல்லாஹ் அந்த ஊரை அதன் நிராகரிப்பு மற்றும் ஷிர்க்கிலிருந்து (இணைவைப்பு) காப்பாற்றினான். பிறகு அல்லாஹ் அவர்களுக்கு யமனையும் வெற்றி கொள்ளச் செய்தான். அரேபிய தீபகற்பம் முழுவதும் அவர்களுக்குக் கீழ்ப்படிந்தது; மக்கள் கூட்டம் கூட்டமாக அல்லாஹ்வின் மார்க்கத்தில் நுழைந்தனர். பிறகு, அவர்களின் உயர் அந்தஸ்து மற்றும் கண்ணியத்தின் காரணமாக அல்லாஹ் அவர்களைத் தன்பால் (மரணத்தின் மூலம்) எடுத்துக் கொண்டான். மேலும், அவர்களின் தோழர்களை (ரழி) அவர்களுக்குப் பின் கலீஃபாக்களாக நியமித்தான். அவர்கள் முஹம்மது (ஸல்) அவர்களிடமிருந்து கற்ற மார்க்கத்தை மக்களுக்கு எடுத்துரைத்தார்கள்; மனிதகுலத்தை அல்லாஹ்வின் பக்கம் அழைத்தார்கள்; பல நாடுகள் மற்றும் நகரங்களைக் கைப்பற்றி மக்களின் இதயங்களைத் திறந்தார்கள். இறுதியில், முஹம்மது (ஸல்) அவர்களின் அழைப்பு கிழக்கு, மேற்கு என உலகம் முழுவதும் பரவியது. யுகமுடிவு நாள் வரும் வரை இந்த மார்க்கம் மேலோங்கி நிற்கும். அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّا</span> <span class=\"quran-arabic-font text-success\">لَنَنصُرُ</span> <span class=\"quran-arabic-font text-success\">رُسُلَنَا</span> <span class=\"quran-arabic-font text-success\">وَالَّذِينَ</span> <span class=\"quran-arabic-font text-success\">ءَامَنُواْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْحَيَوةِ</span> <span class=\"quran-arabic-font text-success\">الدُّنْيَا</span> <span class=\"quran-arabic-font text-success\">وَيَوْمَ</span> <span class=\"quran-arabic-font text-success\">يَقُومُ</span> <span class=\"quran-arabic-font text-success\">الأَشْهَادُ</span><br />\r\n<br />\r\n(நிச்சயமாக, நாம் நமது தூதர்களுக்கும், இவ்வுலக வாழ்வில் ஈமான் கொண்டவர்களுக்கும், சாட்சிகள் நிற்கக்கூடிய (மறுமை) நாளிலும் நிச்சயமாக உதவி செய்வோம்). அதாவது, மறுமை நாளில் கிடைக்கும் வெற்றி இன்னும் மகத்தானதாகவும் முழுமையானதாகவும் இருக்கும். முஜாஹித் கூறுகிறார், \"சாட்சிகள் என்பது வானவர்களைக் குறிக்கும்.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَنفَعُ</span> <span class=\"quran-arabic-font text-success\">الظَّالِمِينَ</span> <span class=\"quran-arabic-font text-success\">مَعْذِرَتُهُمْ</span><br />\r\n<br />\r\n(அந்நாளில் அநியாயக்காரர்களுக்கு அவர்களின் சாக்குப்போக்குகள் எந்தப் பயனையும் அளிக்காது.) என்பது இதையே குறிக்கிறது;<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَيَوْمَ</span> <span class=\"quran-arabic-font text-success\">يَقُومُ</span> <span class=\"quran-arabic-font text-success\">الأَشْهَادُ</span><br />\r\n<br />\r\n(...சாட்சிகள் நிற்கக்கூடிய நாள்.) மற்றவர்கள் இதனை பின்வரும் அர்த்தத்தில் ஓதுகிறார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَيَوْمَ</span> <span class=\"quran-arabic-font text-success\">يَقُومُ</span> <span class=\"quran-arabic-font text-success\">الْأَشْهَادُ</span> <span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَنفَعُ</span> <span class=\"quran-arabic-font text-success\">الظَّالِمِينَ</span><br />\r\n<br />\r\n(சாட்சிகள் நிற்கக்கூடிய அந்த நாள், அநியாயக்காரர்களுக்கு எவ்விதப் பயனும் அளிக்காத நாளாகும்.) இங்கு அநியாயக்காரர்கள் என்பது இணைவைப்பவர்களைக் குறிக்கும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مَعْذِرَتُهُمْ</span><br />\r\n<br />\r\n(அவர்களின் சாக்குப்போக்குகள்) அதாவது, அவர்களிடமிருந்து எந்தப் புகலிடமோ அல்லது ஈட்டுத்தொகையோ ஏற்றுக்கொள்ளப்படாது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَهُمُ</span> <span class=\"quran-arabic-font text-success\">الْلَّعْنَةُ</span><br />\r\n<br />\r\n(அவர்களுக்குச் சாபம் உண்டு,) அதாவது, அவர்கள் அல்லாஹ்வின் கருணையிலிருந்து வெகுதூரம் விரட்டப்படுவார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَهُمْ</span> <span class=\"quran-arabic-font text-success\">سُوءُ</span> <span class=\"quran-arabic-font text-success\">الدَّارِ</span><br />\r\n<br />\r\n(மேலும் அவர்களுக்கு மிக மோசமான தங்குமிடம் உண்டு.) அஸ்-ஸுத்தி கூறியது போல், இது நரக நெருப்பைக் குறிக்கும்; அது தங்குவதற்கு மிகக் கொடிய இடமாகும்.<br />\r\n<br />\r\n<strong>மூஸா (அலை) மற்றும் இஸ்ரவேலர்கள் வெற்றி பெற்றது போலவே தூதரும் நம்பிக்கையாளர்களும் வெற்றி பெறுவார்கள் என்பதற்கான அறிகுறி</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَقَدْ</span> <span class=\"quran-arabic-font text-success\">ءَاتَيْنَا</span> <span class=\"quran-arabic-font text-success\">مُوسَى</span> <span class=\"quran-arabic-font text-success\">الْهُدَى</span><br />\r\n<br />\r\n(நிச்சயமாக நாம் மூஸா (அலை) அவர்களுக்கு நேர்வழியை வழங்கினோம்.) அதாவது, அல்லாஹ் அவரை அனுப்பி வைத்த அந்த நேர்வழியும் ஒளியும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَأَوْرَثْنَا</span> <span class=\"quran-arabic-font text-success\">بَنِى</span> <span class=\"quran-arabic-font text-success\">إِسْرَءِيلَ</span> <span class=\"quran-arabic-font text-success\">الْكِتَابَ</span><br />\r\n<br />\r\n(மேலும் நாம் இஸ்ரவேலர்களை அந்த வேதத்திற்கு வாரிசுகளாக்கினோம்.) அதாவது, 'இறுதியில் அவர்களை நாம் வெற்றி பெறச் செய்தோம். அல்லாஹ்வுக்குக் கீழ்ப்படிவதிலும், அவனது தூதர் மூஸா (அலை) அவர்களைப் பின்பற்றுவதிலும் அவர்கள் பொறுமையைக் கடைப்பிடித்ததால், ஃபிர்அவ்னின் தேசத்திற்கும் அவன் சேர்த்த செல்வத்திற்கும் அவர்களை வாரிசுகளாக்கினோம்.' அவர்கள் வாரிசாகப் பெற்ற அந்த வேதம் 'தவ்ரா' ஆகும். அது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">هُدًى</span> <span class=\"quran-arabic-font text-success\">وَذِكْرَى</span> <span class=\"quran-arabic-font text-success\">لِأُولِي</span> <span class=\"quran-arabic-font text-success\">الْأَلْبَابِ</span><br />\r\n<br />\r\n(அறிவுடையோருக்கு நேர்வழியாகவும் நினைவூட்டலாகவும் இருந்தது.) அதாவது, சீரான மற்றும் நேர்மையான சிந்தனை கொண்டவர்களுக்கு.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَاصْبِرْ</span><br />\r\n<br />\r\n(எனவே பொறுமையுடன் இருப்பீராக) அதாவது, 'முஹம்மதே (ஸல்),'<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">وَعْدَ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">حَقٌّ</span><br />\r\n<br />\r\n(நிச்சயமாக, அல்லாஹ்வின் வாக்குறுதி உண்மையானது,) அதாவது, 'உமது போதனை மேலோங்கும் என்றும், இறுதி வெற்றி உமக்கும் உம்மைப் பின்பற்றுபவர்களுக்கும் கிடைக்கும் என்றும் நாம் வாக்குறுதி அளித்துள்ளோம். அல்லாஹ் தனது வாக்குறுதிகளை மீறுவதில்லை. நாம் உமக்குக் கூறியது முற்றிலும் உண்மையானது, அதில் எவ்வித சந்தேகமும் இல்லை.'<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَاسْتَغْفِـرْ</span> <span class=\"quran-arabic-font text-success\">لِذَنبِكَ</span><br />\r\n<br />\r\n(மேலும் உமது தவறுக்காகப் பாவமன்னிப்புத் தேடுவீராக,) இது உம்மத்தினர் பாவமன்னிப்புத் தேடுவதை ஊக்குவிப்பதாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَسَبِّحْ</span> <span class=\"quran-arabic-font text-success\">بِحَمْدِ</span> <span class=\"quran-arabic-font text-success\">رَبِّكَ</span> <span class=\"quran-arabic-font text-success\">بِالْعَشِىِّ</span><br />\r\n<br />\r\n(மேலும் மாலையிலும் (`அஷி) உமது இறைவனைப் புகழ்ந்து துதிப்பீராக) அதாவது, பகல் பொழுதின் இறுதியிலும் இரவின் தொடக்கத்திலும்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالإِبْكَارِ</span><br />\r\n<br />\r\n(மேலும் காலையிலும் (இப்கார்).) அதாவது, பகல் பொழுதின் தொடக்கத்திலும் இரவின் இறுதியிலும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">يُجَادِلُونَ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">آيَاتِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">بِغَيْرِ</span> <span class=\"quran-arabic-font text-success\">سُلْطَانٍ</span> <span class=\"quran-arabic-font text-success\">أَتَاهُمْ</span><br />\r\n<br />\r\n(நிச்சயமாக, தங்களிடம் எவ்வித ஆதாரமும் வராத நிலையில், அல்லாஹ்வின் வசனங்களைப் பற்றி தர்க்கம் செய்பவர்கள்,) அதாவது, அவர்கள் பொய்யைக் கொண்டு உண்மையையும், சந்தேகத்திற்குரிய வாதங்களைக் கொண்டு தெளிவான ஆதாரங்களையும் மறுக்க முற்படுகிறார்கள். அல்லாஹ்விடமிருந்து வந்த எந்தவொரு அத்தாட்சியும் அவர்களிடம் இல்லை.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">صُدُورِهِمْ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">كِبْرٌ</span> <span class=\"quran-arabic-font text-success\">مَّا</span> <span class=\"quran-arabic-font text-success\">هُم</span> <span class=\"quran-arabic-font text-success\">بِبَالِغِيهِ</span><br />\r\n<br />\r\n(அவர்களின் உள்ளங்களில் பெருமையைத் தவிர வேறொன்றுமில்லை. அவர்கள் அதை ஒருபோதும் அடையப் போவதில்லை.) அதாவது, சத்தியத்தைப் பின்பற்றுவதற்கும், அதைக் கொண்டு வந்தவருக்குப் பணிவதற்கும் அவர்கள் பெரும் கர்வம் கொள்கிறார்கள். ஆனால், சத்தியத்தை அடக்கிப் பொய்யை நிலைநிறுத்த அவர்கள் செய்யும் முயற்சிகள் தோல்வியடையும்; சத்தியமே மேலோங்கும், அவர்களின் எண்ணங்களும் லட்சியங்களும் தகர்க்கப்படும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَاسْتَعِذْ</span> <span class=\"quran-arabic-font text-success\">بِاللَّهِ</span><br />\r\n<br />\r\n(எனவே நீர் அல்லாஹ்விடம் பாதுகாப்புக் கோருவீராக.) அதாவது, இத்தகைய மக்களைப் போல் ஆவதிலிருந்து (பாதுகாப்புத் தேடுவீராக),<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّهُ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">السَّمِيعُ</span> <span class=\"quran-arabic-font text-success\">البَصِيرُ</span><br />\r\n<br />\r\n(நிச்சயமாக, அவன்தான் யாவற்றையும் செவியுறுபவன், யாவற்றையும் பார்ப்பவன்.) அல்லது, அல்லாஹ்விடமிருந்து எந்த ஆதாரமும் வராத நிலையிலும் அவனது வசனங்களைப் பற்றி தர்க்கம் செய்யும் இத்தகைய மனிதர்களிடமிருந்து அல்லாஹ்விடம் பாதுகாப்புக் கோருவீராக.<br />\r\n<br />","text":"தூதர்கள் மற்றும் நம்பிக்கையாளர்களின் வெற்றி\n\r\n\n\r\nإِنَّا لَنَنصُرُ رُسُلَنَا وَالَّذِينَ ءَامَنُواْ فِى الْحَيَوةِ الدُّنْيَا\n\r\n\n\r\n(நிச்சயமாக, நாம் நமது தூதர்களுக்கும், இவ்வுலக வாழ்வில் ஈமான் கொண்டவர்களுக்கும் நிச்சயமாக உதவி செய்வோம்). அஸ்-ஸுத்தி கூறுகிறார், \"அல்லாஹ் ஒரு சமூகத்திற்கு ஒரு தூதரை அனுப்பி, அந்த மக்கள் அவரைக் கொன்றாலோ அல்லது சத்தியத்தின் பக்கம் மக்களை அழைக்கும் நம்பிக்கையாளர்களில் சிலரைக் கொன்றாலோ, அந்தத் தலைமுறை கடந்து சென்ற பிறகு, அவர்களது அழைப்பிற்கு ஆதரவளிப்பவரையும், இவ்வுலகிலேயே அவர்களுக்கு அக்கொடுமையைச் செய்தவர்களிடம் பழிவாங்குபவரையும் அல்லாஹ் அனுப்புகிறான். எனவே, நபிமார்களும் நம்பிக்கையாளர்களும் இவ்வுலகில் கொல்லப்படலாம், ஆனால் அவர்களின் அழைப்பு (தஃவா) இவ்வுலகில் மேலோங்கி நிற்கும்.\" அல்லாஹ் தனது தூதர் முஹம்மது (ஸல்) அவர்களுக்கும், அவர்களின் தோழர்களுக்கும் (ரழி), அவர்களை எதிர்த்தவர்கள், நிராகரித்தவர்கள் மற்றும் பகைமை பாராட்டியவர்கள் மீது வெற்றியை அளித்தான். அவன் தனது வார்த்தையையும் தனது மார்க்கத்தையும் மற்ற எல்லா மார்க்கங்களையும் விட மேலோங்கச் செய்தான். அவர்களைத் தனது சமூகத்தை விட்டு அல்-மதீனாவிற்கு ஹிஜ்ரத் செய்யுமாறு கட்டளையிட்டான்; அங்கு அவர்களுக்கு ஆதரவாளர்களையும் உதவியாளர்களையும் (அன்சாரிகளை) வழங்கினான். பிறகு, பத்ரு போரின் போது இணைவைப்பாளர்களுக்கு எதிராக அவர்களுக்கு அல்லாஹ் வெற்றியளித்தான். அவர்களை இழிவுபடுத்தி, அவர்களின் தலைவர்களைக் கொன்று, முக்கியப் பிரமுகர்களைக் கைதிகளாகப் பிடித்து, சங்கிலிகளால் பிணைத்து தமக்கு முன்னால் இழுத்து வரச் செய்தான். பிறகு, அவர்களிடமிருந்து ஈட்டுத்தொகையை (பிணைத்தொகை) ஏற்றுக்கொண்டு அவர்களுக்கு அவர்கள் (ஸல்) அருள் புரிந்தார்கள். அதற்குச் சிறிது காலத்திற்குப் பிறகு, அல்லாஹ் அவர்களை மக்காவை வெற்றி கொள்ளச் செய்தான். புனிதமும் மேன்மையும் மிக்க அல்-ஹரம் பூமியான தனது தாயகத்திற்குத் திரும்பியதில் அவர்கள் (ஸல்) மகிழ்ச்சி அடைந்தார்கள். அவர்கள் மூலமாக, அல்லாஹ் அந்த ஊரை அதன் நிராகரிப்பு மற்றும் ஷிர்க்கிலிருந்து (இணைவைப்பு) காப்பாற்றினான். பிறகு அல்லாஹ் அவர்களுக்கு யமனையும் வெற்றி கொள்ளச் செய்தான். அரேபிய தீபகற்பம் முழுவதும் அவர்களுக்குக் கீழ்ப்படிந்தது; மக்கள் கூட்டம் கூட்டமாக அல்லாஹ்வின் மார்க்கத்தில் நுழைந்தனர். பிறகு, அவர்களின் உயர் அந்தஸ்து மற்றும் கண்ணியத்தின் காரணமாக அல்லாஹ் அவர்களைத் தன்பால் (மரணத்தின் மூலம்) எடுத்துக் கொண்டான். மேலும், அவர்களின் தோழர்களை (ரழி) அவர்களுக்குப் பின் கலீஃபாக்களாக நியமித்தான். அவர்கள் முஹம்மது (ஸல்) அவர்களிடமிருந்து கற்ற மார்க்கத்தை மக்களுக்கு எடுத்துரைத்தார்கள்; மனிதகுலத்தை அல்லாஹ்வின் பக்கம் அழைத்தார்கள்; பல நாடுகள் மற்றும் நகரங்களைக் கைப்பற்றி மக்களின் இதயங்களைத் திறந்தார்கள். இறுதியில், முஹம்மது (ஸல்) அவர்களின் அழைப்பு கிழக்கு, மேற்கு என உலகம் முழுவதும் பரவியது. யுகமுடிவு நாள் வரும் வரை இந்த மார்க்கம் மேலோங்கி நிற்கும். அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nإِنَّا لَنَنصُرُ رُسُلَنَا وَالَّذِينَ ءَامَنُواْ فِى الْحَيَوةِ الدُّنْيَا وَيَوْمَ يَقُومُ الأَشْهَادُ\n\r\n\n\r\n(நிச்சயமாக, நாம் நமது தூதர்களுக்கும், இவ்வுலக வாழ்வில் ஈமான் கொண்டவர்களுக்கும், சாட்சிகள் நிற்கக்கூடிய (மறுமை) நாளிலும் நிச்சயமாக உதவி செய்வோம்). அதாவது, மறுமை நாளில் கிடைக்கும் வெற்றி இன்னும் மகத்தானதாகவும் முழுமையானதாகவும் இருக்கும். முஜாஹித் கூறுகிறார், \"சாட்சிகள் என்பது வானவர்களைக் குறிக்கும்.\"\n\r\n\n\r\nيَوْمَ لاَ يَنفَعُ الظَّالِمِينَ مَعْذِرَتُهُمْ\n\r\n\n\r\n(அந்நாளில் அநியாயக்காரர்களுக்கு அவர்களின் சாக்குப்போக்குகள் எந்தப் பயனையும் அளிக்காது.) என்பது இதையே குறிக்கிறது;\n\r\n\n\r\nوَيَوْمَ يَقُومُ الأَشْهَادُ\n\r\n\n\r\n(...சாட்சிகள் நிற்கக்கூடிய நாள்.) மற்றவர்கள் இதனை பின்வரும் அர்த்தத்தில் ஓதுகிறார்கள்:\n\r\n\n\r\nوَيَوْمَ يَقُومُ الْأَشْهَادُ يَوْمَ لاَ يَنفَعُ الظَّالِمِينَ\n\r\n\n\r\n(சாட்சிகள் நிற்கக்கூடிய அந்த நாள், அநியாயக்காரர்களுக்கு எவ்விதப் பயனும் அளிக்காத நாளாகும்.) இங்கு அநியாயக்காரர்கள் என்பது இணைவைப்பவர்களைக் குறிக்கும்.\n\r\n\n\r\nمَعْذِرَتُهُمْ\n\r\n\n\r\n(அவர்களின் சாக்குப்போக்குகள்) அதாவது, அவர்களிடமிருந்து எந்தப் புகலிடமோ அல்லது ஈட்டுத்தொகையோ ஏற்றுக்கொள்ளப்படாது.\n\r\n\n\r\nوَلَهُمُ الْلَّعْنَةُ\n\r\n\n\r\n(அவர்களுக்குச் சாபம் உண்டு,) அதாவது, அவர்கள் அல்லாஹ்வின் கருணையிலிருந்து வெகுதூரம் விரட்டப்படுவார்கள்.\n\r\n\n\r\nوَلَهُمْ سُوءُ الدَّارِ\n\r\n\n\r\n(மேலும் அவர்களுக்கு மிக மோசமான தங்குமிடம் உண்டு.) அஸ்-ஸுத்தி கூறியது போல், இது நரக நெருப்பைக் குறிக்கும்; அது தங்குவதற்கு மிகக் கொடிய இடமாகும்.\n\r\n\n\r\nமூஸா (அலை) மற்றும் இஸ்ரவேலர்கள் வெற்றி பெற்றது போலவே தூதரும் நம்பிக்கையாளர்களும் வெற்றி பெறுவார்கள் என்பதற்கான அறிகுறி\n\r\n\n\r\nوَلَقَدْ ءَاتَيْنَا مُوسَى الْهُدَى\n\r\n\n\r\n(நிச்சயமாக நாம் மூஸா (அலை) அவர்களுக்கு நேர்வழியை வழங்கினோம்.) அதாவது, அல்லாஹ் அவரை அனுப்பி வைத்த அந்த நேர்வழியும் ஒளியும்.\n\r\n\n\r\nوَأَوْرَثْنَا بَنِى إِسْرَءِيلَ الْكِتَابَ\n\r\n\n\r\n(மேலும் நாம் இஸ்ரவேலர்களை அந்த வேதத்திற்கு வாரிசுகளாக்கினோம்.) அதாவது, 'இறுதியில் அவர்களை நாம் வெற்றி பெறச் செய்தோம். அல்லாஹ்வுக்குக் கீழ்ப்படிவதிலும், அவனது தூதர் மூஸா (அலை) அவர்களைப் பின்பற்றுவதிலும் அவர்கள் பொறுமையைக் கடைப்பிடித்ததால், ஃபிர்அவ்னின் தேசத்திற்கும் அவன் சேர்த்த செல்வத்திற்கும் அவர்களை வாரிசுகளாக்கினோம்.' அவர்கள் வாரிசாகப் பெற்ற அந்த வேதம் 'தவ்ரா' ஆகும். அது:\n\r\n\n\r\nهُدًى وَذِكْرَى لِأُولِي الْأَلْبَابِ\n\r\n\n\r\n(அறிவுடையோருக்கு நேர்வழியாகவும் நினைவூட்டலாகவும் இருந்தது.) அதாவது, சீரான மற்றும் நேர்மையான சிந்தனை கொண்டவர்களுக்கு.\n\r\n\n\r\nفَاصْبِرْ\n\r\n\n\r\n(எனவே பொறுமையுடன் இருப்பீராக) அதாவது, 'முஹம்மதே (ஸல்),'\n\r\n\n\r\nإِنَّ وَعْدَ اللَّهِ حَقٌّ\n\r\n\n\r\n(நிச்சயமாக, அல்லாஹ்வின் வாக்குறுதி உண்மையானது,) அதாவது, 'உமது போதனை மேலோங்கும் என்றும், இறுதி வெற்றி உமக்கும் உம்மைப் பின்பற்றுபவர்களுக்கும் கிடைக்கும் என்றும் நாம் வாக்குறுதி அளித்துள்ளோம். அல்லாஹ் தனது வாக்குறுதிகளை மீறுவதில்லை. நாம் உமக்குக் கூறியது முற்றிலும் உண்மையானது, அதில் எவ்வித சந்தேகமும் இல்லை.'\n\r\n\n\r\nوَاسْتَغْفِـرْ لِذَنبِكَ\n\r\n\n\r\n(மேலும் உமது தவறுக்காகப் பாவமன்னிப்புத் தேடுவீராக,) இது உம்மத்தினர் பாவமன்னிப்புத் தேடுவதை ஊக்குவிப்பதாகும்.\n\r\n\n\r\nوَسَبِّحْ بِحَمْدِ رَبِّكَ بِالْعَشِىِّ\n\r\n\n\r\n(மேலும் மாலையிலும் (`அஷி) உமது இறைவனைப் புகழ்ந்து துதிப்பீராக) அதாவது, பகல் பொழுதின் இறுதியிலும் இரவின் தொடக்கத்திலும்,\n\r\n\n\r\nوَالإِبْكَارِ\n\r\n\n\r\n(மேலும் காலையிலும் (இப்கார்).) அதாவது, பகல் பொழுதின் தொடக்கத்திலும் இரவின் இறுதியிலும்.\n\r\n\n\r\nإِنَّ الَّذِينَ يُجَادِلُونَ فِي آيَاتِ اللَّهِ بِغَيْرِ سُلْطَانٍ أَتَاهُمْ\n\r\n\n\r\n(நிச்சயமாக, தங்களிடம் எவ்வித ஆதாரமும் வராத நிலையில், அல்லாஹ்வின் வசனங்களைப் பற்றி தர்க்கம் செய்பவர்கள்,) அதாவது, அவர்கள் பொய்யைக் கொண்டு உண்மையையும், சந்தேகத்திற்குரிய வாதங்களைக் கொண்டு தெளிவான ஆதாரங்களையும் மறுக்க முற்படுகிறார்கள். அல்லாஹ்விடமிருந்து வந்த எந்தவொரு அத்தாட்சியும் அவர்களிடம் இல்லை.\n\r\n\n\r\nإِن فِى صُدُورِهِمْ إِلاَّ كِبْرٌ مَّا هُم بِبَالِغِيهِ\n\r\n\n\r\n(அவர்களின் உள்ளங்களில் பெருமையைத் தவிர வேறொன்றுமில்லை. அவர்கள் அதை ஒருபோதும் அடையப் போவதில்லை.) அதாவது, சத்தியத்தைப் பின்பற்றுவதற்கும், அதைக் கொண்டு வந்தவருக்குப் பணிவதற்கும் அவர்கள் பெரும் கர்வம் கொள்கிறார்கள். ஆனால், சத்தியத்தை அடக்கிப் பொய்யை நிலைநிறுத்த அவர்கள் செய்யும் முயற்சிகள் தோல்வியடையும்; சத்தியமே மேலோங்கும், அவர்களின் எண்ணங்களும் லட்சியங்களும் தகர்க்கப்படும்.\n\r\n\n\r\nفَاسْتَعِذْ بِاللَّهِ\n\r\n\n\r\n(எனவே நீர் அல்லாஹ்விடம் பாதுகாப்புக் கோருவீராக.) அதாவது, இத்தகைய மக்களைப் போல் ஆவதிலிருந்து (பாதுகாப்புத் தேடுவீராக),\n\r\n\n\r\nإِنَّهُ هُوَ السَّمِيعُ البَصِيرُ\n\r\n\n\r\n(நிச்சயமாக, அவன்தான் யாவற்றையும் செவியுறுபவன், யாவற்றையும் பார்ப்பவன்.) அல்லது, அல்லாஹ்விடமிருந்து எந்த ஆதாரமும் வராத நிலையிலும் அவனது வசனங்களைப் பற்றி தர்க்கம் செய்யும் இத்தகைய மனிதர்களிடமிருந்து அல்லாஹ்விடம் பாதுகாப்புக் கோருவீராக."},"57":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=40&ayah=59\" class=\"link\">40:59</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 40:59 ஐ பார்க்கவும்"},"58":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=40&ayah=59\" class=\"link\">40:59</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 40:59 ஐ பார்க்கவும்"},"59":{"html":"<strong>மரணத்திற்குப் பிறகான வாழ்க்கை</strong><br />\r\n<br />\r\nமறுமை நாளில் அல்லாஹ் தனது படைப்புகளை மீண்டும் உயிர் கொடுத்து எழுப்புவான் என்று நமக்குக் கூறுகிறான். அது அவனுக்கு மிகவும் எளிதானது; ஏனெனில் அவனே வானங்களையும் பூமியையும் படைத்தான். மனிதர்களை முதல் முறையாகப் படைப்பதையும், மீண்டும் அவர்களைப் படைப்பதையும் விட, வானங்களையும் பூமியையும் படைப்பதே மிகப் பெரிய காரியமாகும். அதைச் செய்ய ஆற்றல் பெற்றவன், அதைவிட எளிய எதனையும் செய்ய ஆற்றல் பெற்றவன் ஆவான். அல்லாஹ் கூறுவது போல:<span class=\"quran-arabic-font text-success\">﴾أَوَلَمْ</span> <span class=\"quran-arabic-font text-success\">يَرَوْا</span> <span class=\"quran-arabic-font text-success\">أَنَّ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">الَّذِي</span> <span class=\"quran-arabic-font text-success\">خَلَقَ</span> <span class=\"quran-arabic-font text-success\">السَّمَاوَاتِ</span> <span class=\"quran-arabic-font text-success\">وَالْأَرْضَ</span> <span class=\"quran-arabic-font text-success\">وَلَمْ</span> <span class=\"quran-arabic-font text-success\">يَعْيَ</span> <span class=\"quran-arabic-font text-success\">بِخَلْقِهِنَّ</span> <span class=\"quran-arabic-font text-success\">بِقَادِرٍ</span> <span class=\"quran-arabic-font text-success\">عَلَىٰ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">يُحْيِيَ</span> <span class=\"quran-arabic-font text-success\">الْمَوْتَىٰ</span> <span class=\"quran-arabic-font text-success\">ۚ</span> <span class=\"quran-arabic-font text-success\">بَلَىٰ</span> <span class=\"quran-arabic-font text-success\">إِنَّهُ</span> <span class=\"quran-arabic-font text-success\">عَلَىٰ</span> <span class=\"quran-arabic-font text-success\">كُلِّ</span> <span class=\"quran-arabic-font text-success\">شَيْءٍ</span> <span class=\"quran-arabic-font text-success\">قَدِيرٌ﴿</span><br />\r\n<br />\r\n(வானங்களையும் பூமியையும் படைத்து, அவற்றைப் படைத்ததில் எவ்விதச் சோர்வும் அடையாத அல்லாஹ், மரித்தவர்களை உயிர் கொடுத்து எழுப்ப ஆற்றலுடையவன் என்பதை அவர்கள் பார்க்கவில்லையா? ஆம், நிச்சயமாக அவன் அனைத்துப் பொருட்களின் மீதும் பேராற்றல் உடையவன்.) (<a href=\"qurandisp.php?sura=46&ayah=33\" class=\"link\">46:33</a>) மேலும் அல்லாஹ் இங்கு கூறுகிறான்:<span class=\"quran-arabic-font text-success\">﴾لَخَلْقُ</span> <span class=\"quran-arabic-font text-success\">السَّمَاوَاتِ</span> <span class=\"quran-arabic-font text-success\">وَالْأَرْضِ</span> <span class=\"quran-arabic-font text-success\">أَكْبَرُ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">خَلْقِ</span> <span class=\"quran-arabic-font text-success\">النَّاسِ</span> <span class=\"quran-arabic-font text-success\">وَلَٰكِنَّ</span> <span class=\"quran-arabic-font text-success\">أَكْثَرَ</span> <span class=\"quran-arabic-font text-success\">النَّاسِ</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">يَعْلَمُونَ﴿</span><br />\r\n<br />\r\n(நிச்சயமாக வானங்களையும் பூமியையும் படைப்பது, மனிதர்களைப் படைப்பதை விட மிகப் பெரியதாகும்; எனினும், மனிதர்களில் பெரும்பாலோர் இதனை அறியமாட்டார்கள்.) எனவே அவர்கள் இந்தச் சான்றைப் பற்றிச் சிந்திப்பதோ அல்லது ஆராய்வதோ இல்லை. அதேபோல், அரேபியர்களில் பலர் அல்லாஹ்வே வானங்களையும் பூமியையும் படைத்தான் என்பதை ஒப்புக்கொண்டார்கள்; ஆனால், அவர்கள் மறுமை நாளில் மீண்டும் உயிர்ப்பிக்கப்படுவதை மறுத்து நிராகரித்தார்கள். எதை அவர்கள் மறுத்தார்களோ, அதைவிடப் பெரிய ஒரு விஷயத்தை அவர்கள் ஏற்கனவே ஒப்புக்கொண்டிருந்தார்கள். பின்னர் அல்லாஹ் கூறுகிறான்:<span class=\"quran-arabic-font text-success\">﴾وَمَا</span> <span class=\"quran-arabic-font text-success\">يَسْتَوِي</span> <span class=\"quran-arabic-font text-success\">الْأَعْمَىٰ</span> <span class=\"quran-arabic-font text-success\">وَالْبَصِيرُ</span> <span class=\"quran-arabic-font text-success\">وَالَّذِينَ</span> <span class=\"quran-arabic-font text-success\">آمَنُوا</span> <span class=\"quran-arabic-font text-success\">وَعَمِلُوا</span> <span class=\"quran-arabic-font text-success\">الصَّالِحَاتِ</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">الْمُسِيءُ</span> <span class=\"quran-arabic-font text-success\">ۚ</span> <span class=\"quran-arabic-font text-success\">قَلِيلًا</span> <span class=\"quran-arabic-font text-success\">مَّا</span> <span class=\"quran-arabic-font text-success\">تَتَذَكَّرُونَ﴿</span><br />\r\n<br />\r\n(பார்வையற்றவரும் பார்வையுடையவரும் சமமாக மாட்டார்கள். அவ்வாறே, ஈமான் கொண்டு நற்செயல்கள் புரிபவர்களும் தீமை செய்பவர்களும் சமமாக மாட்டார்கள். நீங்கள் மிகக் குறைவாகவே படிப்பினை பெறுகிறீர்கள்!) எதனையும் பார்க்க முடியாத ஒரு பார்வையற்றவரும், தனது பார்வை எட்டும் வரை அனைத்தையும் பார்க்கக்கூடிய ஒரு பார்வையுடையவரும் சமமானவர்கள் அல்ல; அவர்களுக்கு இடையே மிகப்பெரிய வித்தியாசம் உள்ளது. அதேபோன்றுதான், நேர்மையான முஃமின்களும் (நம்பிக்கையாளர்களும்) ஒழுக்கக்கேடான நிராகரிப்பாளர்களும் சமமாக மாட்டார்கள்.<span class=\"quran-arabic-font text-success\">﴾قَلِيـلاً</span> <span class=\"quran-arabic-font text-success\">مَّا</span> <span class=\"quran-arabic-font text-success\">تَتَذَكَّرُونَ﴿</span><br />\r\n<br />\r\n(நீங்கள் மிகக் குறைவாகவே படிப்பினை பெறுகிறீர்கள்!) இதன் பொருள், மக்களில் பெரும்பாலோர் மிகக் குறைவாகவே சிந்திக்கிறார்கள் என்பதாகும்.<span class=\"quran-arabic-font text-success\">﴾إِنَّ</span> <span class=\"quran-arabic-font text-success\">السَّاعَةَ</span> <span class=\"quran-arabic-font text-success\">لَآتِيَةٌ﴿</span><br />\r\n<br />\r\n(நிச்சயமாக மறுமை நாள் வந்தே தீரும்.) இதன் பொருள், அது நிச்சயமாக நிகழ்ந்தே தீரும் என்பதாகும்.<span class=\"quran-arabic-font text-success\">﴾لَا</span> <span class=\"quran-arabic-font text-success\">رَيْبَ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">وَلَٰكِنَّ</span> <span class=\"quran-arabic-font text-success\">أَكْثَرَ</span> <span class=\"quran-arabic-font text-success\">النَّاسِ</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">يُؤْمِنُونَ﴿</span><br />\r\n<br />\r\n(அதில் எவ்விதச் சந்தேகமும் இல்லை; எனினும் மனிதர்களில் பெரும்பாலோர் நம்புவதில்லை.) அதாவது, அவர்கள் அதனை நம்புவதில்லை, சொல்லப்போனால் அதன் இருப்பு குறித்தே அவர்கள் முற்றிலும் சந்தேகப்படுகிறார்கள்.<br />\r\n<br />\r\n<br />\r\n<br />","text":"மரணத்திற்குப் பிறகான வாழ்க்கை\n\r\n\n\r\nமறுமை நாளில் அல்லாஹ் தனது படைப்புகளை மீண்டும் உயிர் கொடுத்து எழுப்புவான் என்று நமக்குக் கூறுகிறான். அது அவனுக்கு மிகவும் எளிதானது; ஏனெனில் அவனே வானங்களையும் பூமியையும் படைத்தான். மனிதர்களை முதல் முறையாகப் படைப்பதையும், மீண்டும் அவர்களைப் படைப்பதையும் விட, வானங்களையும் பூமியையும் படைப்பதே மிகப் பெரிய காரியமாகும். அதைச் செய்ய ஆற்றல் பெற்றவன், அதைவிட எளிய எதனையும் செய்ய ஆற்றல் பெற்றவன் ஆவான். அல்லாஹ் கூறுவது போல:﴾أَوَلَمْ يَرَوْا أَنَّ اللَّهَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ وَلَمْ يَعْيَ بِخَلْقِهِنَّ بِقَادِرٍ عَلَىٰ أَن يُحْيِيَ الْمَوْتَىٰ ۚ بَلَىٰ إِنَّهُ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ﴿\n\r\n\n\r\n(வானங்களையும் பூமியையும் படைத்து, அவற்றைப் படைத்ததில் எவ்விதச் சோர்வும் அடையாத அல்லாஹ், மரித்தவர்களை உயிர் கொடுத்து எழுப்ப ஆற்றலுடையவன் என்பதை அவர்கள் பார்க்கவில்லையா? ஆம், நிச்சயமாக அவன் அனைத்துப் பொருட்களின் மீதும் பேராற்றல் உடையவன்.) (46:33) மேலும் அல்லாஹ் இங்கு கூறுகிறான்:﴾لَخَلْقُ السَّمَاوَاتِ وَالْأَرْضِ أَكْبَرُ مِنْ خَلْقِ النَّاسِ وَلَٰكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ﴿\n\r\n\n\r\n(நிச்சயமாக வானங்களையும் பூமியையும் படைப்பது, மனிதர்களைப் படைப்பதை விட மிகப் பெரியதாகும்; எனினும், மனிதர்களில் பெரும்பாலோர் இதனை அறியமாட்டார்கள்.) எனவே அவர்கள் இந்தச் சான்றைப் பற்றிச் சிந்திப்பதோ அல்லது ஆராய்வதோ இல்லை. அதேபோல், அரேபியர்களில் பலர் அல்லாஹ்வே வானங்களையும் பூமியையும் படைத்தான் என்பதை ஒப்புக்கொண்டார்கள்; ஆனால், அவர்கள் மறுமை நாளில் மீண்டும் உயிர்ப்பிக்கப்படுவதை மறுத்து நிராகரித்தார்கள். எதை அவர்கள் மறுத்தார்களோ, அதைவிடப் பெரிய ஒரு விஷயத்தை அவர்கள் ஏற்கனவே ஒப்புக்கொண்டிருந்தார்கள். பின்னர் அல்லாஹ் கூறுகிறான்:﴾وَمَا يَسْتَوِي الْأَعْمَىٰ وَالْبَصِيرُ وَالَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَلَا الْمُسِيءُ ۚ قَلِيلًا مَّا تَتَذَكَّرُونَ﴿\n\r\n\n\r\n(பார்வையற்றவரும் பார்வையுடையவரும் சமமாக மாட்டார்கள். அவ்வாறே, ஈமான் கொண்டு நற்செயல்கள் புரிபவர்களும் தீமை செய்பவர்களும் சமமாக மாட்டார்கள். நீங்கள் மிகக் குறைவாகவே படிப்பினை பெறுகிறீர்கள்!) எதனையும் பார்க்க முடியாத ஒரு பார்வையற்றவரும், தனது பார்வை எட்டும் வரை அனைத்தையும் பார்க்கக்கூடிய ஒரு பார்வையுடையவரும் சமமானவர்கள் அல்ல; அவர்களுக்கு இடையே மிகப்பெரிய வித்தியாசம் உள்ளது. அதேபோன்றுதான், நேர்மையான முஃமின்களும் (நம்பிக்கையாளர்களும்) ஒழுக்கக்கேடான நிராகரிப்பாளர்களும் சமமாக மாட்டார்கள்.﴾قَلِيـلاً مَّا تَتَذَكَّرُونَ﴿\n\r\n\n\r\n(நீங்கள் மிகக் குறைவாகவே படிப்பினை பெறுகிறீர்கள்!) இதன் பொருள், மக்களில் பெரும்பாலோர் மிகக் குறைவாகவே சிந்திக்கிறார்கள் என்பதாகும்.﴾إِنَّ السَّاعَةَ لَآتِيَةٌ﴿\n\r\n\n\r\n(நிச்சயமாக மறுமை நாள் வந்தே தீரும்.) இதன் பொருள், அது நிச்சயமாக நிகழ்ந்தே தீரும் என்பதாகும்.﴾لَا رَيْبَ فِيهَا وَلَٰكِنَّ أَكْثَرَ النَّاسِ لَا يُؤْمِنُونَ﴿\n\r\n\n\r\n(அதில் எவ்விதச் சந்தேகமும் இல்லை; எனினும் மனிதர்களில் பெரும்பாலோர் நம்புவதில்லை.) அதாவது, அவர்கள் அதனை நம்புவதில்லை, சொல்லப்போனால் அதன் இருப்பு குறித்தே அவர்கள் முற்றிலும் சந்தேகப்படுகிறார்கள்."},"60":{"html":"<strong>அல்லாஹ்வின் அருளாலும் கிருபையாலும் அவனைப் பிரார்த்திக்குமாறு விடப்பட்ட கட்டளை</strong><br />\r\n<br />\r\nஅல்லாஹ் தனது அடியார்களைத் தன்னிடம் பிரார்த்தனை செய்யுமாறு ஊக்குவிக்கிறான், மேலும் அதற்குப் பதிலளிப்பதாகவும் அவன் உறுதியளிக்கிறான். சுஃப்யான் அஸ்-ஸவ்ரீ அவர்கள் கூறுவது வழக்கம்: \"உன்னிடம் கேட்பவர்களை அதிகம் நேசிப்பவனே, உன்னிடம் கேட்காதவர்களிடம் அதிகம் கோபப்படுபவனே, என் இறைவனே! உன்னைத் தவிர வேறு எவரும் இத்தகையவர் அல்ல.\" இதனை இப்னு அபீ ஹாதிம் அவர்கள் பதிவு செய்துள்ளார்கள்.<br />\r\n<br />\r\nஅதேபோல் ஒரு கவிஞர் கூறினார்: \"அல்லாஹ் தன்னிடம் கேட்கப்படாவிட்டால் கோபப்படுகிறான், ஆனால் ஆதமுடைய மகனோ (மனிதன்) தன்னிடம் கேட்கப்பட்டால் கோபப்படுகிறான்.\"<br />\r\n<br />\r\nகதாதா அவர்கள் கூறினார்கள்: \"இந்த உம்மத்திற்கு, இதற்கு முன்னால் வாழ்ந்த நபிமார்களுக்கு மட்டுமே வழங்கப்பட்ட மூன்று சிறப்பம்சங்கள் வழங்கப்பட்டுள்ளன என்று கஃபுல் அஹ்பார் அவர்கள் கூறினார்கள். அல்லாஹ் ஒரு நபியை அனுப்பியபோது அவரிடம், 'நீர் உமது சமூகத்திற்கு சாட்சியாக இருக்கிறீர்' என்று கூறினான். ஆனால் நீங்கள் ஒட்டுமொத்த மனிதகுலத்திற்கும் சாட்சிகளாக ஆக்கப்பட்டுள்ளீர்கள். நபிமார்களிடம் தனித்தனியாக, 'மார்க்கத்தில் அல்லாஹ் உங்கள் மீது எந்தச் சிரமத்தையும் ஏற்படுத்தவில்லை' என்று கூறப்பட்டது. ஆனால் இந்த உம்மத் முழுவதையும் நோக்கி அவன் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">جَعَلَ</span> <span class=\"quran-arabic-font text-success\">عَلَيْكُمْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الدِّينِ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">حَرَجٍ</span><br />\r\n<br />\r\n(மேலும் மார்க்கத்தில் அவன் உங்கள் மீது எத்தகைய சிரமத்தையும் ஏற்படுத்தவில்லை) (<a href=\"qurandisp.php?sura=22&ayah=78\" class=\"link\">22:78</a>). மேலும் நபிமார்களிடம் தனித்தனியாக, 'என்னிடம் பிரார்த்தனை செய்யுங்கள், நான் உங்களுக்குப் பதிலளிப்பேன்' என்று கூறப்பட்டது. ஆனால் இந்த உம்மத்திடம் பொதுவாகவே கூறப்பட்டுள்ளது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">ادْعُونِى</span> <span class=\"quran-arabic-font text-success\">أَسْتَجِبْ</span> <span class=\"quran-arabic-font text-success\">لَكُمْ</span><br />\r\n<br />\r\n(என்னிடம் பிரார்த்தனை செய்யுங்கள், நான் உங்களுக்குப் பதிலளிப்பேன்).\" இதனை இப்னு அபீ ஹாதிம் அவர்கள் பதிவு செய்துள்ளார்கள்.<br />\r\n<br />\r\nஇமாம் அஹ்மத் அவர்கள் பதிவு செய்துள்ளார்கள்: அந்நுஃமான் பின் பஷீர் (ரழி) அவர்கள் அறிவிக்கிறார்கள், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">الدُّعَاءَ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">الْعِبَادَة</span>»<br />\r\n<br />\r\n\"(நிச்சயமாகப் பிரார்த்தனை என்பதே வணக்கமாகும்).\" பிறகு அவர்கள் இந்த வசனத்தை ஓதினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَقَالَ</span> <span class=\"quran-arabic-font text-success\">رَبُّكُمُ</span> <span class=\"quran-arabic-font text-success\">ادْعُونِى</span> <span class=\"quran-arabic-font text-success\">أَسْتَجِبْ</span> <span class=\"quran-arabic-font text-success\">لَكُمْ</span> <span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">يَسْتَكْبِرُونَ</span> <span class=\"quran-arabic-font text-success\">عَنْ</span> <span class=\"quran-arabic-font text-success\">عِبَادَتِى</span> <span class=\"quran-arabic-font text-success\">سَيَدْخُلُونَ</span> <span class=\"quran-arabic-font text-success\">جَهَنَّمَ</span> <span class=\"quran-arabic-font text-success\">دَاخِرِينَ</span><br />\r\n<br />\r\n(உங்கள் இறைவன் கூறுகிறான்: \"என்னிடம் பிரார்த்தனை செய்யுங்கள், நான் உங்களுக்குப் பதிலளிக்கிறேன். நிச்சயமாக, எனது வணக்கத்தைப் புறக்கணித்துப் பெருமையடிப்பவர்கள் இழிவடைந்தவர்களாக நரகில் நுழைவார்கள்!\"). இதனை சுனன் நூலாசிரியர்களான அத்திர்மிதி, அந்நஸாஈ, இப்னு மாஜா, இப்னு அபீ ஹாதிம் மற்றும் இப்னு ஜரீர் ஆகியோரும் பதிவு செய்துள்ளனர். இமாம் அத்திர்மிதி அவர்கள் இது \"ஹஸன் ஸஹீஹ்\" என்று குறிப்பிட்டுள்ளார். அபூதாவூத், அத்திர்மிதி, அந்நஸாஈ மற்றும் இப்னு ஜரீர் ஆகியோரால் வேறு அறிவிப்பாளர் தொடர் மூலமாகவும் இது பதிவு செய்யப்பட்டுள்ளது.<br />\r\n<br />\r\nஇமாம் அஹ்மத் அவர்கள் அபூஹுரைரா (ரழி) அவர்கள் வாயிலாகப் பதிவு செய்துள்ளார்கள்: நபி (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">لَمْ</span> <span class=\"quran-arabic-font text-success\">يَدْعُ</span> <span class=\"quran-arabic-font text-success\">اللهَ</span> <span class=\"quran-arabic-font text-success\">عَزَّ</span> <span class=\"quran-arabic-font text-success\">وَجَلَّ</span> <span class=\"quran-arabic-font text-success\">يَغْضَبْ</span> <span class=\"quran-arabic-font text-success\">عَلَيْه</span>»<br />\r\n<br />\r\n\"(யார் அல்லாஹ்விடம் கேட்கவில்லையோ, அவன் மீது அல்லாஹ் கோபப்படுகிறான்).\" இதனை இப்னு மாஜாவும் பதிவு செய்துள்ளார்.<br />\r\n<br />\r\nஅல்லாஹ்வின் கூற்றான:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">يَسْتَكْبِرُونَ</span> <span class=\"quran-arabic-font text-success\">عَنْ</span> <span class=\"quran-arabic-font text-success\">عِبَادَتِى</span><br />\r\n<br />\r\n(நிச்சயமாக, எனது வணக்கத்தைப் புறக்கணித்துப் பெருமையடிப்பவர்கள்) என்பதன் பொருள், 'என்னிடம் பிரார்த்தனை செய்வதற்கும், என்னை ஒருவன் என ஏற்று வணங்குவதற்கும் பெருமை கொள்கிறவர்கள்' என்பதாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">سَيَدْخُلُونَ</span> <span class=\"quran-arabic-font text-success\">جَهَنَّمَ</span> <span class=\"quran-arabic-font text-success\">دَاخِرِينَ</span><br />\r\n<br />\r\n(அவர்கள் இழிவடைந்தவர்களாக நரகில் நுழைவார்கள்!) என்பதன் பொருள், அவர்கள் சிறுமையுடனும் இழிவாகவும் அங்கு நுழைவார்கள் என்பதாகும்.<br />\r\n<br />\r\nஇமாம் அஹ்மத் அவர்கள், அம்ர் பின் ஷுஐப் அவர்கள் தனது தந்தை வழியாகவும், அவர் தனது பாட்டனார் வழியாகவும் அறிவிப்பதாகப் பதிவு செய்துள்ளார்கள், நபி (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">يُحْشَرُ</span> <span class=\"quran-arabic-font text-success\">الْمُتَكَبِّرُونَ</span> <span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">الْقِيَامَةِ</span> <span class=\"quran-arabic-font text-success\">أَمْثَالَ</span> <span class=\"quran-arabic-font text-success\">الذَّرِّ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">صُوَرِ</span> <span class=\"quran-arabic-font text-success\">النَّاسِ،</span> <span class=\"quran-arabic-font text-success\">يَعْلُوهُمْ</span> <span class=\"quran-arabic-font text-success\">كُلُّ</span> <span class=\"quran-arabic-font text-success\">شَيْءٍ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الصَّغَارِ،</span> <span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">يَدْخُلُوا</span> <span class=\"quran-arabic-font text-success\">سِجْنًا</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">جَهَنَّمَ</span> <span class=\"quran-arabic-font text-success\">يُقَالُ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span>: <span class=\"quran-arabic-font text-success\">بُولَسُ،</span> <span class=\"quran-arabic-font text-success\">تَعْلُوهُمْ</span> <span class=\"quran-arabic-font text-success\">نَارُ</span> <span class=\"quran-arabic-font text-success\">الْأَنْيَارِ،</span> <span class=\"quran-arabic-font text-success\">يُسْقَوْنَ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">طِينَةِ</span> <span class=\"quran-arabic-font text-success\">الْخَبَالِ،</span> <span class=\"quran-arabic-font text-success\">عُصَارَةِ</span> <span class=\"quran-arabic-font text-success\">أَهْلِ</span> <span class=\"quran-arabic-font text-success\">النَّار</span>»<br />\r\n<br />\r\n\"(மறுமை நாளில் பெருமையடித்தவர்கள் எறும்புகளைப் போன்ற சிறிய உருவத்தில் ஆனால் மனிதத் தோற்றத்தில் ஒன்றுதிரட்டப்படுவார்கள். இழிவினால் எல்லாப் பொருட்களும் அவர்களுக்கு மேலிருக்கும். இறுதியில் அவர்கள் நரகத்திலுள்ள 'பூலஸ்' எனப்படும் சிறைச்சாலையில் நுழைவார்கள். நெருப்புகளுக்கெல்லாம் மேலான நெருப்பு அவர்களைச் சூழ்ந்துகொள்ளும். அவர்களுக்கு நரகவாசிகளின் உடலில் இருந்து வடியும் 'தீனத்துல் கபால்' (சீழ் மற்றும் கழிவுகள்) குடிக்கக் கொடுக்கப்படும்).\" இதை இமாம் அத்திர்மிதி அவர்களும் பதிவு செய்துள்ளார்கள்.<br />\r\n<br />","text":"அல்லாஹ்வின் அருளாலும் கிருபையாலும் அவனைப் பிரார்த்திக்குமாறு விடப்பட்ட கட்டளை\n\r\n\n\r\nஅல்லாஹ் தனது அடியார்களைத் தன்னிடம் பிரார்த்தனை செய்யுமாறு ஊக்குவிக்கிறான், மேலும் அதற்குப் பதிலளிப்பதாகவும் அவன் உறுதியளிக்கிறான். சுஃப்யான் அஸ்-ஸவ்ரீ அவர்கள் கூறுவது வழக்கம்: \"உன்னிடம் கேட்பவர்களை அதிகம் நேசிப்பவனே, உன்னிடம் கேட்காதவர்களிடம் அதிகம் கோபப்படுபவனே, என் இறைவனே! உன்னைத் தவிர வேறு எவரும் இத்தகையவர் அல்ல.\" இதனை இப்னு அபீ ஹாதிம் அவர்கள் பதிவு செய்துள்ளார்கள்.\n\r\n\n\r\nஅதேபோல் ஒரு கவிஞர் கூறினார்: \"அல்லாஹ் தன்னிடம் கேட்கப்படாவிட்டால் கோபப்படுகிறான், ஆனால் ஆதமுடைய மகனோ (மனிதன்) தன்னிடம் கேட்கப்பட்டால் கோபப்படுகிறான்.\"\n\r\n\n\r\nகதாதா அவர்கள் கூறினார்கள்: \"இந்த உம்மத்திற்கு, இதற்கு முன்னால் வாழ்ந்த நபிமார்களுக்கு மட்டுமே வழங்கப்பட்ட மூன்று சிறப்பம்சங்கள் வழங்கப்பட்டுள்ளன என்று கஃபுல் அஹ்பார் அவர்கள் கூறினார்கள். அல்லாஹ் ஒரு நபியை அனுப்பியபோது அவரிடம், 'நீர் உமது சமூகத்திற்கு சாட்சியாக இருக்கிறீர்' என்று கூறினான். ஆனால் நீங்கள் ஒட்டுமொத்த மனிதகுலத்திற்கும் சாட்சிகளாக ஆக்கப்பட்டுள்ளீர்கள். நபிமார்களிடம் தனித்தனியாக, 'மார்க்கத்தில் அல்லாஹ் உங்கள் மீது எந்தச் சிரமத்தையும் ஏற்படுத்தவில்லை' என்று கூறப்பட்டது. ஆனால் இந்த உம்மத் முழுவதையும் நோக்கி அவன் கூறுகிறான்:\n\r\n\n\r\nوَمَا جَعَلَ عَلَيْكُمْ فِى الدِّينِ مِنْ حَرَجٍ\n\r\n\n\r\n(மேலும் மார்க்கத்தில் அவன் உங்கள் மீது எத்தகைய சிரமத்தையும் ஏற்படுத்தவில்லை) (22:78). மேலும் நபிமார்களிடம் தனித்தனியாக, 'என்னிடம் பிரார்த்தனை செய்யுங்கள், நான் உங்களுக்குப் பதிலளிப்பேன்' என்று கூறப்பட்டது. ஆனால் இந்த உம்மத்திடம் பொதுவாகவே கூறப்பட்டுள்ளது:\n\r\n\n\r\nادْعُونِى أَسْتَجِبْ لَكُمْ\n\r\n\n\r\n(என்னிடம் பிரார்த்தனை செய்யுங்கள், நான் உங்களுக்குப் பதிலளிப்பேன்).\" இதனை இப்னு அபீ ஹாதிம் அவர்கள் பதிவு செய்துள்ளார்கள்.\n\r\n\n\r\nஇமாம் அஹ்மத் அவர்கள் பதிவு செய்துள்ளார்கள்: அந்நுஃமான் பின் பஷீர் (ரழி) அவர்கள் அறிவிக்கிறார்கள், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«إِنَّ الدُّعَاءَ هُوَ الْعِبَادَة»\n\r\n\n\r\n\"(நிச்சயமாகப் பிரார்த்தனை என்பதே வணக்கமாகும்).\" பிறகு அவர்கள் இந்த வசனத்தை ஓதினார்கள்:\n\r\n\n\r\nوَقَالَ رَبُّكُمُ ادْعُونِى أَسْتَجِبْ لَكُمْ إِنَّ الَّذِينَ يَسْتَكْبِرُونَ عَنْ عِبَادَتِى سَيَدْخُلُونَ جَهَنَّمَ دَاخِرِينَ\n\r\n\n\r\n(உங்கள் இறைவன் கூறுகிறான்: \"என்னிடம் பிரார்த்தனை செய்யுங்கள், நான் உங்களுக்குப் பதிலளிக்கிறேன். நிச்சயமாக, எனது வணக்கத்தைப் புறக்கணித்துப் பெருமையடிப்பவர்கள் இழிவடைந்தவர்களாக நரகில் நுழைவார்கள்!\"). இதனை சுனன் நூலாசிரியர்களான அத்திர்மிதி, அந்நஸாஈ, இப்னு மாஜா, இப்னு அபீ ஹாதிம் மற்றும் இப்னு ஜரீர் ஆகியோரும் பதிவு செய்துள்ளனர். இமாம் அத்திர்மிதி அவர்கள் இது \"ஹஸன் ஸஹீஹ்\" என்று குறிப்பிட்டுள்ளார். அபூதாவூத், அத்திர்மிதி, அந்நஸாஈ மற்றும் இப்னு ஜரீர் ஆகியோரால் வேறு அறிவிப்பாளர் தொடர் மூலமாகவும் இது பதிவு செய்யப்பட்டுள்ளது.\n\r\n\n\r\nஇமாம் அஹ்மத் அவர்கள் அபூஹுரைரா (ரழி) அவர்கள் வாயிலாகப் பதிவு செய்துள்ளார்கள்: நபி (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«مَنْ لَمْ يَدْعُ اللهَ عَزَّ وَجَلَّ يَغْضَبْ عَلَيْه»\n\r\n\n\r\n\"(யார் அல்லாஹ்விடம் கேட்கவில்லையோ, அவன் மீது அல்லாஹ் கோபப்படுகிறான்).\" இதனை இப்னு மாஜாவும் பதிவு செய்துள்ளார்.\n\r\n\n\r\nஅல்லாஹ்வின் கூற்றான:\n\r\n\n\r\nإِنَّ الَّذِينَ يَسْتَكْبِرُونَ عَنْ عِبَادَتِى\n\r\n\n\r\n(நிச்சயமாக, எனது வணக்கத்தைப் புறக்கணித்துப் பெருமையடிப்பவர்கள்) என்பதன் பொருள், 'என்னிடம் பிரார்த்தனை செய்வதற்கும், என்னை ஒருவன் என ஏற்று வணங்குவதற்கும் பெருமை கொள்கிறவர்கள்' என்பதாகும்.\n\r\n\n\r\nسَيَدْخُلُونَ جَهَنَّمَ دَاخِرِينَ\n\r\n\n\r\n(அவர்கள் இழிவடைந்தவர்களாக நரகில் நுழைவார்கள்!) என்பதன் பொருள், அவர்கள் சிறுமையுடனும் இழிவாகவும் அங்கு நுழைவார்கள் என்பதாகும்.\n\r\n\n\r\nஇமாம் அஹ்மத் அவர்கள், அம்ர் பின் ஷுஐப் அவர்கள் தனது தந்தை வழியாகவும், அவர் தனது பாட்டனார் வழியாகவும் அறிவிப்பதாகப் பதிவு செய்துள்ளார்கள், நபி (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«يُحْشَرُ الْمُتَكَبِّرُونَ يَوْمَ الْقِيَامَةِ أَمْثَالَ الذَّرِّ فِي صُوَرِ النَّاسِ، يَعْلُوهُمْ كُلُّ شَيْءٍ مِنَ الصَّغَارِ، حَتَّى يَدْخُلُوا سِجْنًا فِي جَهَنَّمَ يُقَالُ لَهُ: بُولَسُ، تَعْلُوهُمْ نَارُ الْأَنْيَارِ، يُسْقَوْنَ مِنْ طِينَةِ الْخَبَالِ، عُصَارَةِ أَهْلِ النَّار»\n\r\n\n\r\n\"(மறுமை நாளில் பெருமையடித்தவர்கள் எறும்புகளைப் போன்ற சிறிய உருவத்தில் ஆனால் மனிதத் தோற்றத்தில் ஒன்றுதிரட்டப்படுவார்கள். இழிவினால் எல்லாப் பொருட்களும் அவர்களுக்கு மேலிருக்கும். இறுதியில் அவர்கள் நரகத்திலுள்ள 'பூலஸ்' எனப்படும் சிறைச்சாலையில் நுழைவார்கள். நெருப்புகளுக்கெல்லாம் மேலான நெருப்பு அவர்களைச் சூழ்ந்துகொள்ளும். அவர்களுக்கு நரகவாசிகளின் உடலில் இருந்து வடியும் 'தீனத்துல் கபால்' (சீழ் மற்றும் கழிவுகள்) குடிக்கக் கொடுக்கப்படும்).\" இதை இமாம் அத்திர்மிதி அவர்களும் பதிவு செய்துள்ளார்கள்."},"61":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=40&ayah=65\" class=\"link\">40:65</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 40:65 ஐ பார்க்கவும்"},"62":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=40&ayah=65\" class=\"link\">40:65</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 40:65 ஐ பார்க்கவும்"},"63":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=40&ayah=65\" class=\"link\">40:65</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 40:65 ஐ பார்க்கவும்"},"64":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=40&ayah=65\" class=\"link\">40:65</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 40:65 ஐ பார்க்கவும்"},"65":{"html":"<strong>அல்லாஹ்வின் வல்லமை மற்றும் ஏகத்துவத்தின் அத்தாட்சிகள்</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">جَعَـلَ</span> <span class=\"quran-arabic-font text-success\">لَكُـمُ</span> <span class=\"quran-arabic-font text-success\">الَّيْلَ</span> <span class=\"quran-arabic-font text-success\">لِتَسْكُنُواْ</span> <span class=\"quran-arabic-font text-success\">فِيهِ</span> <span class=\"quran-arabic-font text-success\">وَالنَّهَارَ</span> <span class=\"quran-arabic-font text-success\">مُبْصِراً</span><br />\r\n<br />\r\n(அல்லாஹ்வே உங்களுக்காக இரவை, நீங்கள் அதில் ஓய்வெடுப்பதற்காகவும்; பகலை (பொருட்களைப்) பார்க்கக் கூடியதாகவும் ஆக்கினான்.)<br />\r\n<br />\r\nஅல்லாஹ் தன் படைப்புகளுக்குத் தான் வழங்கிய அருட்கொடைகளை நினைவூட்டுகிறான். பகலில் அவர்கள் தங்கள் வாழ்வாதாரத்திற்காகச் செய்யும் பணிகளிலிருந்து ஓய்வெடுத்துக் கொள்ள அவர்களுக்கு அவன் இரவை வழங்கியுள்ளான். அவர்கள் தங்கள் பயணங்களை மேற்கொள்ளவும், வியாபாரங்களில் ஈடுபடவும் ஏதுவாக ஒளியுடன் கூடிய பகலை அவர்களுக்கு வழங்கினான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">لَذُو</span> <span class=\"quran-arabic-font text-success\">فَضْلٍ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">النَّاسِ</span> <span class=\"quran-arabic-font text-success\">وَلَـكِنَّ</span> <span class=\"quran-arabic-font text-success\">أَكْثَرَ</span> <span class=\"quran-arabic-font text-success\">النَّاسِ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَشْكُرُونَ</span><br />\r\n<br />\r\n(நிச்சயமாக, அல்லாஹ் மனிதர்களின் மீது பெரும் அருளுடையவன்; எனினும், மனிதர்களில் பெரும்பாலோர் நன்றி செலுத்துவதில்லை.) அதாவது, அல்லாஹ் தங்களுக்கு வழங்கிய அருட்கொடைகளுக்காக அவர்கள் நன்றி தெரிவிப்பதில்லை. பின்னர் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">ذَلِكُـمُ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">رَبُّـكُمْ</span> <span class=\"quran-arabic-font text-success\">خَالِقُ</span> <span class=\"quran-arabic-font text-success\">كُـلِّ</span> <span class=\"quran-arabic-font text-success\">شَىْءٍ</span> <span class=\"quran-arabic-font text-success\">لاَّ</span> <span class=\"quran-arabic-font text-success\">إِلَـهَ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span><br />\r\n<br />\r\n(அவன்தான் உங்கள் இறைவனாகிய அல்லாஹ்; அனைத்தையும் படைத்தவன். அவனைத் தவிர வணக்கத்திற்குரியவன் வேறு யாருமில்லை.) அதாவது, இவை அனைத்தையும் செய்பவன் அல்லாஹ்வே; அவன் தனித்தவன், இணையற்றவன், அனைத்தையும் படைத்தவன். அவனைத் தவிர வேறு இறைவனோ அல்லது இரட்சகனோ இல்லை.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَأَنَّى</span> <span class=\"quran-arabic-font text-success\">تُؤْفَكُونَ</span><br />\r\n<br />\r\n(அவ்வாறிருக்க, நீங்கள் எவ்வாறு (உண்மையை விட்டுத்) திருப்பப்படுகிறீர்கள்?) அதாவது, 'எதையும் படைக்க முடியாத, மனிதர்களால் செதுக்கப்பட்ட சிலைகளை நீங்கள் எவ்வாறு வணங்க முடியும்?' என்று கேட்கிறான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">كَذَلِكَ</span> <span class=\"quran-arabic-font text-success\">يُؤْفَكُ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">كَانُواْ</span> <span class=\"quran-arabic-font text-success\">بِـَايَـتِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">يَجْحَدُونَ</span><br />\r\n<br />\r\n(இவ்வாறே, அல்லாஹ்வின் வசனங்களை மறுத்து வந்தவர்கள் (உண்மையை விட்டுத்) திருப்பப்பட்டார்கள்.) அதாவது, இந்த குரைஷிகள் அல்லாஹ்வைத் தவிர மற்றவர்களை வணங்கி வழிதவறிப் போனது போலவே, அவர்களுக்கு முன் வாழ்ந்தவர்களும் எவ்வித ஆதாரமும் இன்றி, அறியாமை மற்றும் இச்சைகளின் அடிப்படையில் இறைவசனங்களை நிராகரித்து மற்றவர்களை வணங்கினார்கள். அவர்கள் அல்லாஹ்வின் அத்தாட்சிகளையும் சான்றுகளையும் மறுத்தார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">جَعَـلَ</span> <span class=\"quran-arabic-font text-success\">لَكُـمُ</span> <span class=\"quran-arabic-font text-success\">الْأَرْضَ</span> <span class=\"quran-arabic-font text-success\">قَـرَاراً</span><br />\r\n<br />\r\n(அல்லாஹ்வே உங்களுக்காகப் பூமியை ஒரு தங்குமிடமாக ஆக்கினான்.) அதாவது, 'அவன் அதனை உங்களுக்கு நிலையானதாகவும், விரிப்பாகவும் ஆக்கினான். நீங்கள் அதில் வசிப்பதற்கும், பயணம் செய்வதற்கும் வசதியாக அதனை அமைத்தான். அது உங்களோடு சேர்ந்து குலுங்காதவாறு மலைகளைக் கொண்டு அதனை அவன் உறுதிப்படுத்தினான்.'<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالسَّمَآءَ</span> <span class=\"quran-arabic-font text-success\">بِنَآءً</span><br />\r\n<br />\r\n(மேலும் வானத்தை ஒரு மேற்கூரையாக (ஆக்கினான்).) அதாவது, உலகத்தைப் பாதுகாக்கும் ஒரு கூரையாக அதனை ஆக்கினான். இது குறித்து அல்லாஹ் கூறும்போது: \"(வானத்தை) பாதுகாக்கப்பட்ட ஒரு முகடாகவும் அமைத்தோம். எனினும் அவர்கள், அதிலுள்ள அத்தாட்சிகளைப் புறக்கணிப்பர்களாகவே இருக்கின்றனர்.\" (<a href=\"qurandisp.php?sura=21&ayah=32\" class=\"link\">21:32</a>) என்று கூறினான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَصَوَّرَكُمْ</span> <span class=\"quran-arabic-font text-success\">فَأَحْسَنَ</span> <span class=\"quran-arabic-font text-success\">صُوَرَكُمْ</span><br />\r\n<br />\r\n(மேலும் உங்களுக்கு உருவம் கொடுத்து, உங்கள் உருவங்களை அழகாக்கினான்.) அதாவது, அவன் உங்களை மிகச் சிறந்த, முழுமையான வடிவில் படைத்தான். (<span class=\"quran-arabic-font text-success\">فَتَبَارَكَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">أَحْسَنُ</span> <span class=\"quran-arabic-font text-success\">الْخَالِقِينَ</span>) \"படைப்பாளர்களில் மிகவும் அழகானவனான அல்லாஹ் பாக்கியம் மிக்கவன்\" (<a href=\"qurandisp.php?sura=23&ayah=14\" class=\"link\">23:14</a>) என்று அல்லாஹ் கூறியிருப்பதைப் போல.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَرَزَقَكُم</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">الطَّيِّبَاتِ</span><br />\r\n<br />\r\n(மேலும் தூய்மையானவற்றிலிருந்து உங்களுக்கு உணவளித்தான்.) அதாவது, இவ்வுலகில் தூய்மையான உணவு மற்றும் பானங்களை வழங்கினான். வசிப்பிடம், அதில் வசிப்பவர்கள் மற்றும் அவர்களுக்கான வாழ்வாதாரம் ஆகிய அனைத்தையும் படைத்தவன் அல்லாஹ்வே என்பதை அவன் தெளிவுபடுத்துகிறான். அவனே படைப்பாளனும் உணவளிப்பவனுமாவான். இதனை ஸூரத்துல் பகராவில் அல்லாஹ் பின்வருமாறு கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَـأَيُّهَا</span> <span class=\"quran-arabic-font text-success\">النَّاسُ</span> <span class=\"quran-arabic-font text-success\">اعْبُدُواْ</span> <span class=\"quran-arabic-font text-success\">رَبَّكُمُ</span> <span class=\"quran-arabic-font text-success\">الَّذِىْ</span> <span class=\"quran-arabic-font text-success\">خَلَقَكُمْ</span> <span class=\"quran-arabic-font text-success\">وَالَّذِينَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">قَبْلِكُمْ</span> <span class=\"quran-arabic-font text-success\">لَعَلَّكُمْ</span> <span class=\"quran-arabic-font text-success\">تَتَّقُونَ</span> - <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">جَعَلَ</span> <span class=\"quran-arabic-font text-success\">لَكُمُ</span> <span class=\"quran-arabic-font text-success\">الْأَرْضَ</span> <span class=\"quran-arabic-font text-success\">فِرَاشاً</span> <span class=\"quran-arabic-font text-success\">وَالسَّمَآءَ</span> <span class=\"quran-arabic-font text-success\">بِنَآءً</span> <span class=\"quran-arabic-font text-success\">وَأَنزَلَ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">السَّمَآءِ</span> <span class=\"quran-arabic-font text-success\">مَآءً</span> <span class=\"quran-arabic-font text-success\">فَأَخْرَجَ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الثَّمَرَتِ</span> <span class=\"quran-arabic-font text-success\">رِزْقاً</span> <span class=\"quran-arabic-font text-success\">لَّكُمْ</span> <span class=\"quran-arabic-font text-success\">فَلاَ</span> <span class=\"quran-arabic-font text-success\">تَجْعَلُواْ</span> <span class=\"quran-arabic-font text-success\">للَّهِ</span> <span class=\"quran-arabic-font text-success\">أَندَاداً</span> <span class=\"quran-arabic-font text-success\">وَأَنتُمْ</span> <span class=\"quran-arabic-font text-success\">تَعْلَمُونَ</span><br />\r\n<br />\r\n(மனிதர்களே! உங்களையும் உங்களுக்கு முன்னிருந்தவர்களையும் படைத்த உங்கள் இறைவனை வணங்குங்கள்; அதனால் நீங்கள் தக்வா (இறையச்சம்) உடையவர்களாகலாம். அவனே உங்களுக்காகப் பூமியை ஒரு விரிப்பாகவும், வானத்தை ஒரு மேற்கூரையாகவும் ஆக்கினான்; மேலும் வானத்திலிருந்து மழையை இறக்கி, அதன் மூலம் உங்களுக்கு உணவாகக் கனிகளை வெளிப்படுத்தினான். எனவே, நீங்கள் அறிந்து கொண்டே அல்லாஹ்வுக்கு இணைகளை ஏற்படுத்தாதீர்கள்.) (<a href=\"qurandisp.php?sura=2&ayah=21\" class=\"link\">2:21</a>-22) இவை அனைத்தையும் படைத்ததைக் குறிப்பிட்ட பிறகு அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">ذَلِكُمُ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">رَبُّكُـمْ</span> <span class=\"quran-arabic-font text-success\">فَتَـبَـرَكَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">رَبُّ</span> <span class=\"quran-arabic-font text-success\">الْعَـلَمِينَ</span><br />\r\n<br />\r\n(அவன்தான் உங்கள் இறைவனாகிய அல்லாஹ்; அகிலங்களின் இறைவனாகிய அல்லாஹ் மிகவும் பாக்கியம் மிக்கவன்.) அதாவது, அகிலங்களின் இறைவனாகிய அல்லாஹ் மிக உயர்ந்தவன், தூய்மையானவன் மற்றும் போற்றுதலுக்குரியவன்.<br />\r\n<br />\r\nபின்னர் அவன் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">الْحَىُّ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">إِلَـهَ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span><br />\r\n<br />\r\n(அவன் என்றென்றும் உயிரோடு இருப்பவன்; அவனைத் தவிர வணக்கத்திற்குரியவன் வேறு யாருமில்லை.) அதாவது, அவன் ஆரம்பமும் முடிவும் இல்லாதவன்; என்றும் நிலையானவன். (<span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">الأَوَّلُ</span> <span class=\"quran-arabic-font text-success\">وَالآخِرُ</span> <span class=\"quran-arabic-font text-success\">وَالظَّـهِرُ</span> <span class=\"quran-arabic-font text-success\">وَالْبَاطِنُ</span>) அவனே முதலாவதும் கடைசியானவனும், வெளிப்படையானவனும் மறைவானவனுமாவான். (<a href=\"qurandisp.php?sura=57&ayah=3\" class=\"link\">57:3</a>)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">إِلَـهَ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span><br />\r\n<br />\r\n(அவனைத் தவிர வணக்கத்திற்குரியவன் வேறு யாருமில்லை.) அதாவது, அவனுக்கு இணையானவரோ அல்லது நிகரானவரோ எவருமில்லை.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَـادْعُوهُ</span> <span class=\"quran-arabic-font text-success\">مُخْلِصِينَ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">الدِّينَ</span> <span class=\"quran-arabic-font text-success\">الْحَمْدُ</span> <span class=\"quran-arabic-font text-success\">للَّهِ</span> <span class=\"quran-arabic-font text-success\">رَبِّ</span> <span class=\"quran-arabic-font text-success\">الْعَالَمِينَ</span><br />\r\n<br />\r\n(எனவே, வணக்கத்தை அவனுக்கே தூய்மையாக்கியவர்களாக அவனை நீங்கள் பிரார்த்தியுங்கள். அகிலங்களின் இறைவனாகிய அல்லாஹ்வுக்கே புகழனைத்தும்.) அதாவது, அவனைத் தவிர வேறு இறைவன் இல்லை என்று சாட்சியமளித்து அவனது ஏகத்துவத்தை உறுதிப்படுத்துங்கள். அகிலங்களின் இறைவனாகிய அல்லாஹ்வுக்கே புகழனைத்தும். இமாம் அஹ்மத் அவர்கள் பதிவு செய்துள்ளார்கள்: யஃலா பின் ஷத்தாத் கூறினார்: நான் முஆவியா(ரலி) அவர்களிடம் வந்தேன். அப்போது அப்துல்லாஹ் பின் அஸ்-ஸுபைர் (ரழி) அவர்கள் இருந்தார்கள். நபி(ஸல்) அவர்கள் ஒவ்வொரு தொழுகையை முடித்த பிறகும் பின்வருமாறு கூறுவார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">إِلهَ</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">وَحْدَهُ</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">شَرِيكَ</span> <span class=\"quran-arabic-font text-success\">لَهُ،لَهُ</span> <span class=\"quran-arabic-font text-success\">الْمُلْكُ</span> <span class=\"quran-arabic-font text-success\">وَلَهُ</span> <span class=\"quran-arabic-font text-success\">الْحَمْدُ،</span> <span class=\"quran-arabic-font text-success\">وَهُوَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">كُلِّ</span> <span class=\"quran-arabic-font text-success\">شَيْءٍ</span> <span class=\"quran-arabic-font text-success\">قَدِيرٌ،</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">حَوْلَ</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">قُوَّةَ</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">بِاللهِ،</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">إِلهَ</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">اللهُ،</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">نَعْبُدُ</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">إِيَّاهُ،</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">النِّعْمَةُ</span> <span class=\"quran-arabic-font text-success\">وَلَهُ</span> <span class=\"quran-arabic-font text-success\">الْفَضْلُ</span> <span class=\"quran-arabic-font text-success\">وَلَهُ</span> <span class=\"quran-arabic-font text-success\">الثَّنَاءُ</span> <span class=\"quran-arabic-font text-success\">الْحَسَنُ،</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">إِلهَ</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">مُخْلِصِينَ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">الدِّينَ</span> <span class=\"quran-arabic-font text-success\">وَلَوْ</span> <span class=\"quran-arabic-font text-success\">كَرِهَ</span> <span class=\"quran-arabic-font text-success\">الْكَافِرُون</span>»<br />\r\n<br />\r\n(அல்லாஹ்வைத் தவிர வணக்கத்திற்குரியவன் வேறு யாருமில்லை, அவன் தனித்தவன், அவனுக்கு இணையேதுமில்லை. அவனுக்கே ஆட்சியும் புகழும் உரியன. அவன் அனைத்துப் பொருட்கள் மீதும் பேராற்றல் கொண்டவன். அல்லாஹ்வின் உதவியின்றி (பாவங்களிலிருந்து) விலகவோ (நன்மைகள் செய்ய) சக்தியோ இல்லை. அல்லாஹ்வைத் தவிர வணக்கத்திற்குரியவன் வேறு யாருமில்லை. அவனைத் தவிர வேறு எவரையும் நாங்கள் வணங்கமாட்டோம். அவனுக்கே அருட்கொடைகளும் சிறப்பும் அழகிய புகழும் உரியன. அல்லாஹ்வைத் தவிர வணக்கத்திற்குரியவன் வேறு யாருமில்லை. நிராகரிப்பாளர்கள் வெறுத்த போதிலும், நாங்கள் அவனுக்கே மார்க்கத்தைத் தூய்மையாக்குகிறோம்.)<br />\r\n<br />\r\nஅவர் (அப்துல்லாஹ் பின் அஸ்-ஸுபைர் (ரழி)) கூறினார்: \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் ஒவ்வொரு தொழுகைக்குப் பிறகும் இந்த தஹ்லீலை இவ்வாறு கூறி வந்தார்கள்.\" இதே போன்ற செய்தி முஸ்லிம், அபூ தாவூத் மற்றும் அந்-நஸாயீ ஆகிய நூல்களிலும் இடம்பெற்றுள்ளது.<br />\r\n<br />","text":"அல்லாஹ்வின் வல்லமை மற்றும் ஏகத்துவத்தின் அத்தாட்சிகள்\n\r\n\n\r\nاللَّهُ الَّذِى جَعَـلَ لَكُـمُ الَّيْلَ لِتَسْكُنُواْ فِيهِ وَالنَّهَارَ مُبْصِراً\n\r\n\n\r\n(அல்லாஹ்வே உங்களுக்காக இரவை, நீங்கள் அதில் ஓய்வெடுப்பதற்காகவும்; பகலை (பொருட்களைப்) பார்க்கக் கூடியதாகவும் ஆக்கினான்.)\n\r\n\n\r\nஅல்லாஹ் தன் படைப்புகளுக்குத் தான் வழங்கிய அருட்கொடைகளை நினைவூட்டுகிறான். பகலில் அவர்கள் தங்கள் வாழ்வாதாரத்திற்காகச் செய்யும் பணிகளிலிருந்து ஓய்வெடுத்துக் கொள்ள அவர்களுக்கு அவன் இரவை வழங்கியுள்ளான். அவர்கள் தங்கள் பயணங்களை மேற்கொள்ளவும், வியாபாரங்களில் ஈடுபடவும் ஏதுவாக ஒளியுடன் கூடிய பகலை அவர்களுக்கு வழங்கினான்.\n\r\n\n\r\nإِنَّ اللَّهَ لَذُو فَضْلٍ عَلَى النَّاسِ وَلَـكِنَّ أَكْثَرَ النَّاسِ لاَ يَشْكُرُونَ\n\r\n\n\r\n(நிச்சயமாக, அல்லாஹ் மனிதர்களின் மீது பெரும் அருளுடையவன்; எனினும், மனிதர்களில் பெரும்பாலோர் நன்றி செலுத்துவதில்லை.) அதாவது, அல்லாஹ் தங்களுக்கு வழங்கிய அருட்கொடைகளுக்காக அவர்கள் நன்றி தெரிவிப்பதில்லை. பின்னர் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nذَلِكُـمُ اللَّهُ رَبُّـكُمْ خَالِقُ كُـلِّ شَىْءٍ لاَّ إِلَـهَ إِلاَّ هُوَ\n\r\n\n\r\n(அவன்தான் உங்கள் இறைவனாகிய அல்லாஹ்; அனைத்தையும் படைத்தவன். அவனைத் தவிர வணக்கத்திற்குரியவன் வேறு யாருமில்லை.) அதாவது, இவை அனைத்தையும் செய்பவன் அல்லாஹ்வே; அவன் தனித்தவன், இணையற்றவன், அனைத்தையும் படைத்தவன். அவனைத் தவிர வேறு இறைவனோ அல்லது இரட்சகனோ இல்லை.\n\r\n\n\r\nفَأَنَّى تُؤْفَكُونَ\n\r\n\n\r\n(அவ்வாறிருக்க, நீங்கள் எவ்வாறு (உண்மையை விட்டுத்) திருப்பப்படுகிறீர்கள்?) அதாவது, 'எதையும் படைக்க முடியாத, மனிதர்களால் செதுக்கப்பட்ட சிலைகளை நீங்கள் எவ்வாறு வணங்க முடியும்?' என்று கேட்கிறான்.\n\r\n\n\r\nكَذَلِكَ يُؤْفَكُ الَّذِينَ كَانُواْ بِـَايَـتِ اللَّهِ يَجْحَدُونَ\n\r\n\n\r\n(இவ்வாறே, அல்லாஹ்வின் வசனங்களை மறுத்து வந்தவர்கள் (உண்மையை விட்டுத்) திருப்பப்பட்டார்கள்.) அதாவது, இந்த குரைஷிகள் அல்லாஹ்வைத் தவிர மற்றவர்களை வணங்கி வழிதவறிப் போனது போலவே, அவர்களுக்கு முன் வாழ்ந்தவர்களும் எவ்வித ஆதாரமும் இன்றி, அறியாமை மற்றும் இச்சைகளின் அடிப்படையில் இறைவசனங்களை நிராகரித்து மற்றவர்களை வணங்கினார்கள். அவர்கள் அல்லாஹ்வின் அத்தாட்சிகளையும் சான்றுகளையும் மறுத்தார்கள்.\n\r\n\n\r\nاللَّهُ الَّذِى جَعَـلَ لَكُـمُ الْأَرْضَ قَـرَاراً\n\r\n\n\r\n(அல்லாஹ்வே உங்களுக்காகப் பூமியை ஒரு தங்குமிடமாக ஆக்கினான்.) அதாவது, 'அவன் அதனை உங்களுக்கு நிலையானதாகவும், விரிப்பாகவும் ஆக்கினான். நீங்கள் அதில் வசிப்பதற்கும், பயணம் செய்வதற்கும் வசதியாக அதனை அமைத்தான். அது உங்களோடு சேர்ந்து குலுங்காதவாறு மலைகளைக் கொண்டு அதனை அவன் உறுதிப்படுத்தினான்.'\n\r\n\n\r\nوَالسَّمَآءَ بِنَآءً\n\r\n\n\r\n(மேலும் வானத்தை ஒரு மேற்கூரையாக (ஆக்கினான்).) அதாவது, உலகத்தைப் பாதுகாக்கும் ஒரு கூரையாக அதனை ஆக்கினான். இது குறித்து அல்லாஹ் கூறும்போது: \"(வானத்தை) பாதுகாக்கப்பட்ட ஒரு முகடாகவும் அமைத்தோம். எனினும் அவர்கள், அதிலுள்ள அத்தாட்சிகளைப் புறக்கணிப்பர்களாகவே இருக்கின்றனர்.\" (21:32) என்று கூறினான்.\n\r\n\n\r\nوَصَوَّرَكُمْ فَأَحْسَنَ صُوَرَكُمْ\n\r\n\n\r\n(மேலும் உங்களுக்கு உருவம் கொடுத்து, உங்கள் உருவங்களை அழகாக்கினான்.) அதாவது, அவன் உங்களை மிகச் சிறந்த, முழுமையான வடிவில் படைத்தான். (فَتَبَارَكَ اللَّهُ أَحْسَنُ الْخَالِقِينَ) \"படைப்பாளர்களில் மிகவும் அழகானவனான அல்லாஹ் பாக்கியம் மிக்கவன்\" (23:14) என்று அல்லாஹ் கூறியிருப்பதைப் போல.\n\r\n\n\r\nوَرَزَقَكُم مِّنَ الطَّيِّبَاتِ\n\r\n\n\r\n(மேலும் தூய்மையானவற்றிலிருந்து உங்களுக்கு உணவளித்தான்.) அதாவது, இவ்வுலகில் தூய்மையான உணவு மற்றும் பானங்களை வழங்கினான். வசிப்பிடம், அதில் வசிப்பவர்கள் மற்றும் அவர்களுக்கான வாழ்வாதாரம் ஆகிய அனைத்தையும் படைத்தவன் அல்லாஹ்வே என்பதை அவன் தெளிவுபடுத்துகிறான். அவனே படைப்பாளனும் உணவளிப்பவனுமாவான். இதனை ஸூரத்துல் பகராவில் அல்லாஹ் பின்வருமாறு கூறுகிறான்:\n\r\n\n\r\nيَـأَيُّهَا النَّاسُ اعْبُدُواْ رَبَّكُمُ الَّذِىْ خَلَقَكُمْ وَالَّذِينَ مِن قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ - الَّذِى جَعَلَ لَكُمُ الْأَرْضَ فِرَاشاً وَالسَّمَآءَ بِنَآءً وَأَنزَلَ مِنَ السَّمَآءِ مَآءً فَأَخْرَجَ بِهِ مِنَ الثَّمَرَتِ رِزْقاً لَّكُمْ فَلاَ تَجْعَلُواْ للَّهِ أَندَاداً وَأَنتُمْ تَعْلَمُونَ\n\r\n\n\r\n(மனிதர்களே! உங்களையும் உங்களுக்கு முன்னிருந்தவர்களையும் படைத்த உங்கள் இறைவனை வணங்குங்கள்; அதனால் நீங்கள் தக்வா (இறையச்சம்) உடையவர்களாகலாம். அவனே உங்களுக்காகப் பூமியை ஒரு விரிப்பாகவும், வானத்தை ஒரு மேற்கூரையாகவும் ஆக்கினான்; மேலும் வானத்திலிருந்து மழையை இறக்கி, அதன் மூலம் உங்களுக்கு உணவாகக் கனிகளை வெளிப்படுத்தினான். எனவே, நீங்கள் அறிந்து கொண்டே அல்லாஹ்வுக்கு இணைகளை ஏற்படுத்தாதீர்கள்.) (2:21-22) இவை அனைத்தையும் படைத்ததைக் குறிப்பிட்ட பிறகு அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nذَلِكُمُ اللَّهُ رَبُّكُـمْ فَتَـبَـرَكَ اللَّهُ رَبُّ الْعَـلَمِينَ\n\r\n\n\r\n(அவன்தான் உங்கள் இறைவனாகிய அல்லாஹ்; அகிலங்களின் இறைவனாகிய அல்லாஹ் மிகவும் பாக்கியம் மிக்கவன்.) அதாவது, அகிலங்களின் இறைவனாகிய அல்லாஹ் மிக உயர்ந்தவன், தூய்மையானவன் மற்றும் போற்றுதலுக்குரியவன்.\n\r\n\n\r\nபின்னர் அவன் கூறுகிறான்:\n\r\n\n\r\nهُوَ الْحَىُّ لاَ إِلَـهَ إِلاَّ هُوَ\n\r\n\n\r\n(அவன் என்றென்றும் உயிரோடு இருப்பவன்; அவனைத் தவிர வணக்கத்திற்குரியவன் வேறு யாருமில்லை.) அதாவது, அவன் ஆரம்பமும் முடிவும் இல்லாதவன்; என்றும் நிலையானவன். (هُوَ الأَوَّلُ وَالآخِرُ وَالظَّـهِرُ وَالْبَاطِنُ) அவனே முதலாவதும் கடைசியானவனும், வெளிப்படையானவனும் மறைவானவனுமாவான். (57:3)\n\r\n\n\r\nلاَ إِلَـهَ إِلاَّ هُوَ\n\r\n\n\r\n(அவனைத் தவிர வணக்கத்திற்குரியவன் வேறு யாருமில்லை.) அதாவது, அவனுக்கு இணையானவரோ அல்லது நிகரானவரோ எவருமில்லை.\n\r\n\n\r\nفَـادْعُوهُ مُخْلِصِينَ لَهُ الدِّينَ الْحَمْدُ للَّهِ رَبِّ الْعَالَمِينَ\n\r\n\n\r\n(எனவே, வணக்கத்தை அவனுக்கே தூய்மையாக்கியவர்களாக அவனை நீங்கள் பிரார்த்தியுங்கள். அகிலங்களின் இறைவனாகிய அல்லாஹ்வுக்கே புகழனைத்தும்.) அதாவது, அவனைத் தவிர வேறு இறைவன் இல்லை என்று சாட்சியமளித்து அவனது ஏகத்துவத்தை உறுதிப்படுத்துங்கள். அகிலங்களின் இறைவனாகிய அல்லாஹ்வுக்கே புகழனைத்தும். இமாம் அஹ்மத் அவர்கள் பதிவு செய்துள்ளார்கள்: யஃலா பின் ஷத்தாத் கூறினார்: நான் முஆவியா(ரலி) அவர்களிடம் வந்தேன். அப்போது அப்துல்லாஹ் பின் அஸ்-ஸுபைர் (ரழி) அவர்கள் இருந்தார்கள். நபி(ஸல்) அவர்கள் ஒவ்வொரு தொழுகையை முடித்த பிறகும் பின்வருமாறு கூறுவார்கள்:\n\r\n\n\r\n«لَا إِلهَ إِلَّا اللهُ وَحْدَهُ لَا شَرِيكَ لَهُ،لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللهِ، لَا إِلهَ إِلَّا اللهُ، وَلَا نَعْبُدُ إِلَّا إِيَّاهُ، لَهُ النِّعْمَةُ وَلَهُ الْفَضْلُ وَلَهُ الثَّنَاءُ الْحَسَنُ، لَا إِلهَ إِلَّا اللهُ مُخْلِصِينَ لَهُ الدِّينَ وَلَوْ كَرِهَ الْكَافِرُون»\n\r\n\n\r\n(அல்லாஹ்வைத் தவிர வணக்கத்திற்குரியவன் வேறு யாருமில்லை, அவன் தனித்தவன், அவனுக்கு இணையேதுமில்லை. அவனுக்கே ஆட்சியும் புகழும் உரியன. அவன் அனைத்துப் பொருட்கள் மீதும் பேராற்றல் கொண்டவன். அல்லாஹ்வின் உதவியின்றி (பாவங்களிலிருந்து) விலகவோ (நன்மைகள் செய்ய) சக்தியோ இல்லை. அல்லாஹ்வைத் தவிர வணக்கத்திற்குரியவன் வேறு யாருமில்லை. அவனைத் தவிர வேறு எவரையும் நாங்கள் வணங்கமாட்டோம். அவனுக்கே அருட்கொடைகளும் சிறப்பும் அழகிய புகழும் உரியன. அல்லாஹ்வைத் தவிர வணக்கத்திற்குரியவன் வேறு யாருமில்லை. நிராகரிப்பாளர்கள் வெறுத்த போதிலும், நாங்கள் அவனுக்கே மார்க்கத்தைத் தூய்மையாக்குகிறோம்.)\n\r\n\n\r\nஅவர் (அப்துல்லாஹ் பின் அஸ்-ஸுபைர் (ரழி)) கூறினார்: \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் ஒவ்வொரு தொழுகைக்குப் பிறகும் இந்த தஹ்லீலை இவ்வாறு கூறி வந்தார்கள்.\" இதே போன்ற செய்தி முஸ்லிம், அபூ தாவூத் மற்றும் அந்-நஸாயீ ஆகிய நூல்களிலும் இடம்பெற்றுள்ளது."},"66":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=40&ayah=68\" class=\"link\">40:68</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 40:68 ஐ பார்க்கவும்"},"67":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=40&ayah=68\" class=\"link\">40:68</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 40:68 ஐ பார்க்கவும்"},"68":{"html":"<strong>ஷிர்க் (இணைவைத்தல்) விலக்கப்படுதல், தவ்ஹீதுக்கான (ஏகத்துவம்) கட்டளை மற்றும் அதற்கான ஆதாரங்கள்</strong><br />\r\n<br />\r\nஅல்லாஹ் கூறுகிறான், \"முஹம்மதே (ஸல்)! அல்லாஹ்வைத் தவிர, இந்த சிலைகளையும் போலித் தெய்வங்களையும் வணங்குவதை அல்லாஹ் இவர்களுக்குத் தடை செய்கிறான் என்று இந்த இணைவைப்பாளர்களிடம் கூறுவீராக.\" தன்னைத் தவிர வேறு எவரும் வணக்கத்திற்குத் தகுதியானவர் இல்லை என்பதை அல்லாஹ் விளக்குகிறான். அவன் கூறுகிறான்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾هُوَ</span> <span class=\"quran-arabic-font text-success\">الَّذِي</span> <span class=\"quran-arabic-font text-success\">خَلَقَكُمْ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">تُرَابٍ</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">نُّطْفَةٍ</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">عَلَقَةٍ</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">يُخْرِجُكُمْ</span> <span class=\"quran-arabic-font text-success\">طِفْلاً</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">لِتَـبْلُغُواْ</span> <span class=\"quran-arabic-font text-success\">أَشُدَّكُـمْ</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">لِتَكُـونُواْ</span> <span class=\"quran-arabic-font text-success\">شُيُوخاً﴿</span><br />\r\n<br />\r\n(அவன்தான் உங்களை மண்ணிலிருந்தும், பின்னர் ஒரு விந்துத் துளியிலிருந்தும் (நுத்ஃபா), பின்னர் ஒரு இரத்தக் கட்டியிலிருந்தும் படைத்தான். பின்னர் உங்களைக் குழந்தையாக வெளிப்படுத்துகிறான். பின்னர் நீங்கள் உங்கள் முழு வலிமையை அடையும் வரை (வளரச் செய்கிறான்); அதன் பிறகு நீங்கள் முதியவர்களாகிறீர்கள்.) அதாவது, எவ்வித கூட்டாளியோ இணையோ இன்றி, அவன் ஒருவன் மட்டுமே உங்களை இந்தப் பல்வேறு நிலைகளைக் கடக்கச் செய்கிறான். இது அவனது கட்டளை, நாட்டம் மற்றும் விதியின்படியே நிகழ்கிறது.<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَمِنكُمْ</span> <span class=\"quran-arabic-font text-success\">مَّن</span> <span class=\"quran-arabic-font text-success\">يُتَوَفَّى</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">قَبْلُ﴿</span><br />\r\n<br />\r\n(உங்களில் சிலர் அதற்கு முன்னரே இறந்துவிடுகின்றனர்) அதாவது, முழுமையாக உருவாகி இவ்வுலகிற்கு வருவதற்கு முன்னரே (கருவிலேயே) இறந்துவிடுகின்றனர்; அதாவது தாய்க்கு கருச்சிதைவு ஏற்படுகிறது. இன்னும் சிலர் குழந்தைப் பருவத்திலோ, வாலிபத்திலோ அல்லது முதுமையை அடைவதற்கு முன்னரோ இறந்துவிடுகின்றனர். அல்லாஹ் கூறுவது போல்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾لِّنُبَيِّنَ</span> <span class=\"quran-arabic-font text-success\">لَكُمْ</span> <span class=\"quran-arabic-font text-success\">وَنُقِرُّ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْأَرْحَامِ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">نَشَآءُ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">أَجَلٍ</span> <span class=\"quran-arabic-font text-success\">مُّسَمًّى﴿</span><br />\r\n<br />\r\n(உங்களுக்குத் தெளிவுபடுத்துவதற்காகவே (இவ்வாறு செய்கிறோம்). மேலும், நாம் நாடியவற்றைக் குறிப்பிட்ட காலம் வரை கருவறைகளில் நிலைபெறச் செய்கிறோம்) (<a href=\"qurandisp.php?sura=22&ayah=5\" class=\"link\">22:5</a>).<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَلِتَبْلُغُواْ</span> <span class=\"quran-arabic-font text-success\">أَجَلاً</span> <span class=\"quran-arabic-font text-success\">مُّسَمًّى</span> <span class=\"quran-arabic-font text-success\">وَلَعَلَّـكُمْ</span> <span class=\"quran-arabic-font text-success\">تَعْقِلُونَ﴿</span><br />\r\n<br />\r\n(மேலும் நீங்கள் ஒரு குறிப்பிட்ட தவணையை அடைவதற்காகவும், நீங்கள் சிந்தித்துப் புரிந்து கொள்வதற்காகவும் (இவ்வாறு செய்கிறான்).) இப்னு ஜுரைஜ் கூறினார்கள், \"நீங்கள் மறுமை நாளை நினைவுகூருவதற்காக.\" பின்னர் அல்லாஹ் கூறுகிறான்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾هُوَ</span> <span class=\"quran-arabic-font text-success\">الَّذِي</span> <span class=\"quran-arabic-font text-success\">يُحْيِي</span> <span class=\"quran-arabic-font text-success\">وَيُمِيتُ﴿</span><br />\r\n<br />\r\n(அவன்தான் உயிர் கொடுக்கிறான், இன்னும் அவனே மரணிக்கச் செய்கிறான்.) அதாவது, இதனைச் செய்பவன் அவன் ஒருவன் மட்டுமே. அவனைத் தவிர வேறு எவராலும் இதைச் செய்ய முடியாது.<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَإِذَا</span> <span class=\"quran-arabic-font text-success\">قَضَى</span> <span class=\"quran-arabic-font text-success\">أَمْراً</span> <span class=\"quran-arabic-font text-success\">فَإِنَّمَا</span> <span class=\"quran-arabic-font text-success\">يَقُولُ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">كُن</span> <span class=\"quran-arabic-font text-success\">فَيَكُونُ﴿</span><br />\r\n<br />\r\n(அவன் ஒரு காரியத்தைத் தீர்மானித்தால், அதனிடம் \"ஆகு\" என்றுதான் கூறுகிறான்; உடனே அது ஆகிவிடுகிறது.) அதாவது, அவனது கட்டளையை எவராலும் எதிர்க்கவோ தடுக்கவோ முடியாது. அவன் நாடியது நிச்சயமாக நடந்தே தீரும்.<br />\r\n<br />","text":"ஷிர்க் (இணைவைத்தல்) விலக்கப்படுதல், தவ்ஹீதுக்கான (ஏகத்துவம்) கட்டளை மற்றும் அதற்கான ஆதாரங்கள்\n\r\n\n\r\nஅல்லாஹ் கூறுகிறான், \"முஹம்மதே (ஸல்)! அல்லாஹ்வைத் தவிர, இந்த சிலைகளையும் போலித் தெய்வங்களையும் வணங்குவதை அல்லாஹ் இவர்களுக்குத் தடை செய்கிறான் என்று இந்த இணைவைப்பாளர்களிடம் கூறுவீராக.\" தன்னைத் தவிர வேறு எவரும் வணக்கத்திற்குத் தகுதியானவர் இல்லை என்பதை அல்லாஹ் விளக்குகிறான். அவன் கூறுகிறான்:\n\r\n﴾هُوَ الَّذِي خَلَقَكُمْ مِّن تُرَابٍ ثُمَّ مِن نُّطْفَةٍ ثُمَّ مِنْ عَلَقَةٍ ثُمَّ يُخْرِجُكُمْ طِفْلاً ثُمَّ لِتَـبْلُغُواْ أَشُدَّكُـمْ ثُمَّ لِتَكُـونُواْ شُيُوخاً﴿\n\r\n\n\r\n(அவன்தான் உங்களை மண்ணிலிருந்தும், பின்னர் ஒரு விந்துத் துளியிலிருந்தும் (நுத்ஃபா), பின்னர் ஒரு இரத்தக் கட்டியிலிருந்தும் படைத்தான். பின்னர் உங்களைக் குழந்தையாக வெளிப்படுத்துகிறான். பின்னர் நீங்கள் உங்கள் முழு வலிமையை அடையும் வரை (வளரச் செய்கிறான்); அதன் பிறகு நீங்கள் முதியவர்களாகிறீர்கள்.) அதாவது, எவ்வித கூட்டாளியோ இணையோ இன்றி, அவன் ஒருவன் மட்டுமே உங்களை இந்தப் பல்வேறு நிலைகளைக் கடக்கச் செய்கிறான். இது அவனது கட்டளை, நாட்டம் மற்றும் விதியின்படியே நிகழ்கிறது.\n\r\n﴾وَمِنكُمْ مَّن يُتَوَفَّى مِن قَبْلُ﴿\n\r\n\n\r\n(உங்களில் சிலர் அதற்கு முன்னரே இறந்துவிடுகின்றனர்) அதாவது, முழுமையாக உருவாகி இவ்வுலகிற்கு வருவதற்கு முன்னரே (கருவிலேயே) இறந்துவிடுகின்றனர்; அதாவது தாய்க்கு கருச்சிதைவு ஏற்படுகிறது. இன்னும் சிலர் குழந்தைப் பருவத்திலோ, வாலிபத்திலோ அல்லது முதுமையை அடைவதற்கு முன்னரோ இறந்துவிடுகின்றனர். அல்லாஹ் கூறுவது போல்:\n\r\n﴾لِّنُبَيِّنَ لَكُمْ وَنُقِرُّ فِي الْأَرْحَامِ مَا نَشَآءُ إِلَى أَجَلٍ مُّسَمًّى﴿\n\r\n\n\r\n(உங்களுக்குத் தெளிவுபடுத்துவதற்காகவே (இவ்வாறு செய்கிறோம்). மேலும், நாம் நாடியவற்றைக் குறிப்பிட்ட காலம் வரை கருவறைகளில் நிலைபெறச் செய்கிறோம்) (22:5).\n\r\n﴾وَلِتَبْلُغُواْ أَجَلاً مُّسَمًّى وَلَعَلَّـكُمْ تَعْقِلُونَ﴿\n\r\n\n\r\n(மேலும் நீங்கள் ஒரு குறிப்பிட்ட தவணையை அடைவதற்காகவும், நீங்கள் சிந்தித்துப் புரிந்து கொள்வதற்காகவும் (இவ்வாறு செய்கிறான்).) இப்னு ஜுரைஜ் கூறினார்கள், \"நீங்கள் மறுமை நாளை நினைவுகூருவதற்காக.\" பின்னர் அல்லாஹ் கூறுகிறான்:\n\r\n﴾هُوَ الَّذِي يُحْيِي وَيُمِيتُ﴿\n\r\n\n\r\n(அவன்தான் உயிர் கொடுக்கிறான், இன்னும் அவனே மரணிக்கச் செய்கிறான்.) அதாவது, இதனைச் செய்பவன் அவன் ஒருவன் மட்டுமே. அவனைத் தவிர வேறு எவராலும் இதைச் செய்ய முடியாது.\n\r\n﴾فَإِذَا قَضَى أَمْراً فَإِنَّمَا يَقُولُ لَهُ كُن فَيَكُونُ﴿\n\r\n\n\r\n(அவன் ஒரு காரியத்தைத் தீர்மானித்தால், அதனிடம் \"ஆகு\" என்றுதான் கூறுகிறான்; உடனே அது ஆகிவிடுகிறது.) அதாவது, அவனது கட்டளையை எவராலும் எதிர்க்கவோ தடுக்கவோ முடியாது. அவன் நாடியது நிச்சயமாக நடந்தே தீரும்."},"69":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=40&ayah=76\" class=\"link\">40:76</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 40:76 ஐ பார்க்கவும்"},"70":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=40&ayah=76\" class=\"link\">40:76</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 40:76 ஐ பார்க்கவும்"},"71":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=40&ayah=76\" class=\"link\">40:76</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 40:76 ஐ பார்க்கவும்"},"72":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=40&ayah=76\" class=\"link\">40:76</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 40:76 ஐ பார்க்கவும்"},"73":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=40&ayah=76\" class=\"link\">40:76</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 40:76 ஐ பார்க்கவும்"},"74":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=40&ayah=76\" class=\"link\">40:76</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 40:76 ஐ பார்க்கவும்"},"75":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=40&ayah=76\" class=\"link\">40:76</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 40:76 ஐ பார்க்கவும்"},"76":{"html":"<strong>அல்லாஹ்வின் வசனங்களை மறுத்து தர்க்கம் செய்பவர்களின் முடிவு</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾أَلَمْ</span> <span class=\"quran-arabic-font text-success\">تَرَ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">يُجَـدِلُونَ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">ءَايَـتِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">أَنَّى</span> <span class=\"quran-arabic-font text-success\">يُصْرَفُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\nஅல்லாஹ் கூறுகிறான்: 'முஹம்மத் (ஸல்) அவர்களே! அல்லாஹ்வின் வசனங்களை மறுத்து, பொய்யைக் கொண்டு சத்தியத்தை எதிர்க்கத் துணிபவர்களைப் பார்த்து நீங்கள் ஆச்சரியப்படவில்லையா? அவர்களது புத்தி உண்மையிலிருந்து எவ்வாறு திசைதிருப்பப்பட்டு, அவர்கள் வழிகெடுக்கப்படுகிறார்கள் (என்பதைக் கவனியுங்கள்).' <span class=\"quran-arabic-font text-success\">﴾الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">كَذَّبُواْ</span> <span class=\"quran-arabic-font text-success\">بِالْكِـتَـبِ</span> <span class=\"quran-arabic-font text-success\">وَبِمَآ</span> <span class=\"quran-arabic-font text-success\">أَرْسَلْنَا</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">رُسُلَنَا﴿</span><br />\r\n<br />\r\n(எவர்கள் இந்த வேதத்தையும், நம்முடைய தூதர்களுடன் நாம் எதை அனுப்பினோமோ அதையும் பொய்ப்பிக்கிறார்களோ -) அதாவது, நேர்வழியையும் தெளிவான அத்தாட்சிகளையும் (அவர்கள் மறுக்கிறார்கள்). <span class=\"quran-arabic-font text-success\">﴾فَسَوْفَ</span> <span class=\"quran-arabic-font text-success\">يَعْلَمُونَ﴿</span><br />\r\n<br />\r\n(அவர்கள் விரைவில் அறிந்து கொள்வார்கள்.) இது இத்தகைய மக்களுக்கு இறைவனிடமிருந்து விடுக்கப்படும் ஒரு கடுமையான எச்சரிக்கையும் தெளிவான அச்சுறுத்தலுமாகும். இது பின்வரும் வசனத்தைப் போன்றது: <span class=\"quran-arabic-font text-success\">﴾وَيْلٌ</span> <span class=\"quran-arabic-font text-success\">يَوْمَئِذٍ</span> <span class=\"quran-arabic-font text-success\">لِّلْمُكَذِّبِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அந்நாளில் (உண்மையைப்) பொய்ப்பிப்பவர்களுக்குக் கேடுதான்!) (<a href=\"qurandisp.php?sura=77&ayah=15\" class=\"link\">77:15</a>) <span class=\"quran-arabic-font text-success\">﴾إِذِ</span> <span class=\"quran-arabic-font text-success\">الاٌّغْلَـلُ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">أَعْنَـقِهِمْ</span> <span class=\"quran-arabic-font text-success\">والسَّلَـسِلُ﴿</span><br />\r\n<br />\r\n(அவர்களுடைய கழுத்துகளில் இரும்பு விலங்குகள் மாட்டப்பட்டு, சங்கிலிகளால் அவர்கள் பிணைக்கப்படும் போது.) அதாவது, அந்தச் சங்கிலிகள் இரும்பு விலங்குகளுடன் இணைக்கப்பட்டிருக்கும். நரகத்தின் காவலர்கள் அவர்களைக் குப்புறக் கவிழ்த்து, சில நேரங்களில் கொதிக்கும் நீருக்கும், சில நேரங்களில் நரக நெருப்புக்கும் இழுத்துச் செல்வார்கள். அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾يُسْحَبُونَ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْحَمِيمِ</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">النَّارِ</span> <span class=\"quran-arabic-font text-success\">يُسْجَرُونَ﴿</span><br />\r\n<br />\r\n(அவர்கள் கொதிக்கும் நீரில் இழுத்துச் செல்லப்படுவார்கள்; பின்னர் நரக நெருப்பில் அவர்கள் எரிக்கப்படுவார்கள்.) இது பின்வரும் வசனங்களைப் போன்றது: <span class=\"quran-arabic-font text-success\">﴾هَـذِهِ</span> <span class=\"quran-arabic-font text-success\">جَهَنَّمُ</span> <span class=\"quran-arabic-font text-success\">الَّتِى</span> <span class=\"quran-arabic-font text-success\">يُكَذِّبُ</span> <span class=\"quran-arabic-font text-success\">بِهَا</span> <span class=\"quran-arabic-font text-success\">الْمُجْرِمُونَ</span> - <span class=\"quran-arabic-font text-success\">يَطُوفُونَ</span> <span class=\"quran-arabic-font text-success\">بَيْنَهَا</span> <span class=\"quran-arabic-font text-success\">وَبَيْنَ</span> <span class=\"quran-arabic-font text-success\">حَمِيمٍ</span> <span class=\"quran-arabic-font text-success\">ءَانٍ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(“குற்றவாளிகள் எதைப் பொய்ப்பித்தார்களோ அந்த நரகம் இதுதான்.” அதற்கும், கொதித்துக் கொண்டிருக்கும் நீருக்கும் இடையே அவர்கள் சுற்றி வருவார்கள்.) (<a href=\"qurandisp.php?sura=55&ayah=43\" class=\"link\">55:43</a>-44). அவர்கள் ஸக்கூம் (நரகத்தின் கசப்பான மரம்) உண்பார்கள் என்றும், ஹமீம் (கொதிக்கும் நீர்) குடிப்பார்கள் என்றும் விவரித்த பிறகு அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾ثُمَّ</span> <span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">مَرْجِعَهُمْ</span> <span class=\"quran-arabic-font text-success\">لإِلَى</span> <span class=\"quran-arabic-font text-success\">الْجَحِيمِ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(பிறகு நிச்சயமாக, அவர்கள் மீளுமிடம் நரகத்தின் கொழுந்துவிட்டெரியும் நெருப்பின் பக்கமேயாகும்.) (<a href=\"qurandisp.php?sura=37&ayah=68\" class=\"link\">37:68</a>). மேலும் அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾وَأَصْحَـبُ</span> <span class=\"quran-arabic-font text-success\">الشِّمَالِ</span> <span class=\"quran-arabic-font text-success\">مَآ</span> <span class=\"quran-arabic-font text-success\">أَصْحَـبُ</span> <span class=\"quran-arabic-font text-success\">الشِّمَالِ</span> - <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">سَمُومٍ</span> <span class=\"quran-arabic-font text-success\">وَحَمِيمٍ</span> - <span class=\"quran-arabic-font text-success\">وَظِلٍّ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">يَحْمُومٍ</span> - <span class=\"quran-arabic-font text-success\">لاَّ</span> <span class=\"quran-arabic-font text-success\">بَارِدٍ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">كَرِيمٍ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(இடது புறத்துக்காரர்கள் - அந்த இடது புறத்துக்காரர்கள் எவ்வளவு (துரதிர்ஷ்டசாலிகள்)! அவர்கள் கடுமையான வெப்பக் காற்றிலும், கொதிக்கும் நீரிலும், கரும்புகை நிழலிலும் இருப்பார்கள். (அந்த நிழலோ) குளிர்ச்சியானதும் அல்ல; கண்ணியமானதும் அல்ல.) <span class=\"quran-arabic-font text-success\">﴾ثُمَّ</span> <span class=\"quran-arabic-font text-success\">إِنَّكُمْ</span> <span class=\"quran-arabic-font text-success\">أَيُّهَا</span> <span class=\"quran-arabic-font text-success\">الضَّآلُّونَ</span> <span class=\"quran-arabic-font text-success\">الْمُكَذِّبُونَ</span> - <span class=\"quran-arabic-font text-success\">لآكِلُونَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">شَجَرٍ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">زَقُّومٍ</span> - <span class=\"quran-arabic-font text-success\">فَمَالِئُونَ</span> <span class=\"quran-arabic-font text-success\">مِنْهَا</span> <span class=\"quran-arabic-font text-success\">الْبُطُونَ</span> - <span class=\"quran-arabic-font text-success\">فَشَارِبُونَ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْحَمِيمِ</span> - <span class=\"quran-arabic-font text-success\">فَشَارِبُونَ</span> <span class=\"quran-arabic-font text-success\">شُرْبَ</span> <span class=\"quran-arabic-font text-success\">الْهِيمِ</span> - <span class=\"quran-arabic-font text-success\">هَـذَا</span> <span class=\"quran-arabic-font text-success\">نُزُلُهُمْ</span> <span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">الدِّينِ</span> <span class=\"quran-arabic-font text-success\">﴿</span> வரை,<br />\r\n<br />\r\n(பிறகு, வழிதவறியவர்களே! (மறுமையைப்) பொய்ப்பிப்பவர்களே! நீங்கள் நிச்சயமாக ஸக்கூம் மரத்திலிருந்து உண்பீர்கள். அதைக் கொண்டு உங்கள் வயிறுகளை நிரப்புவீர்கள். அதன் மேல் கொதிக்கும் நீரைக் குடிப்பீர்கள். தாகம் கொண்ட ஒட்டகங்கள் குடிப்பதைப் போல் குடிப்பீர்கள். கூலி கொடுக்கப்படும் (மறுமை) நாளில் இதுவே அவர்களுக்கு அளிக்கப்படும் விருந்தாகும்.) (56: 41-44, 51-56) <span class=\"quran-arabic-font text-success\">﴾إِنَّ</span> <span class=\"quran-arabic-font text-success\">شَجَرَةَ</span> <span class=\"quran-arabic-font text-success\">الزَّقُّومِ</span> - <span class=\"quran-arabic-font text-success\">طَعَامُ</span> <span class=\"quran-arabic-font text-success\">الاٌّثِيمِ</span> - <span class=\"quran-arabic-font text-success\">كَالْمُهْلِ</span> <span class=\"quran-arabic-font text-success\">يَغْلِى</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْبُطُونِ</span> - <span class=\"quran-arabic-font text-success\">كَغَلْىِ</span> <span class=\"quran-arabic-font text-success\">الْحَمِيمِ</span> - <span class=\"quran-arabic-font text-success\">خُذُوهُ</span> <span class=\"quran-arabic-font text-success\">فَاعْتِلُوهُ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">سَوَآءِ</span> <span class=\"quran-arabic-font text-success\">الْجَحِيمِ</span> - <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">صُبُّواْ</span> <span class=\"quran-arabic-font text-success\">فَوْقَ</span> <span class=\"quran-arabic-font text-success\">رَأْسِهِ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">عَذَابِ</span> <span class=\"quran-arabic-font text-success\">الْحَمِيمِ</span> - <span class=\"quran-arabic-font text-success\">ذُقْ</span> <span class=\"quran-arabic-font text-success\">إِنَّكَ</span> <span class=\"quran-arabic-font text-success\">أَنتَ</span> <span class=\"quran-arabic-font text-success\">الْعَزِيزُ</span> <span class=\"quran-arabic-font text-success\">الْكَرِيمُ</span> - <span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">هَـذَا</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">كُنتُمْ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">تَمْتَرُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(நிச்சயமாக ஸக்கூம் மரம் பாவிகளின் உணவாகும். அது உருக்கப்பட்ட செம்பு போல் வயிறுகளில் கொதிக்கும். கொதிக்கும் நீர் கொதிப்பதைப் போல. (வானவர்களிடம் கூறப்படும்:) \"அவனைப் பிடித்து நரகத்தின் மையப்பகுதிக்கு இழுத்துச் செல்லுங்கள். பின்னர் அவனது தலையின் மேல் கொதிக்கும் நீரை ஊற்றி வேதனைப்படுத்துங்கள். (இதை) நீ சுவைத்துப் பார்! நிச்சயமாக நீ (உன்னையே) வலிமைமிக்கவனாகவும் கண்ணியமானவனாகவும் அல்லவா (நினைத்துக் கொண்டிருந்தாய்)! நிச்சயமாக எதைப் பற்றி நீங்கள் சந்தேகித்துக் கொண்டிருந்தீர்களோ, அது இதுவே!\") (<a href=\"qurandisp.php?sura=44&ayah=43\" class=\"link\">44:43</a>-50). அதாவது, அவர்களைக் கண்டிப்பதற்கும் ஏளனம் செய்வதற்கும் இவ்வாறு கூறப்படும். <span class=\"quran-arabic-font text-success\">﴾ثُمَّ</span> <span class=\"quran-arabic-font text-success\">قِيلَ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">أَيْنَ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">كُنتُمْ</span> <span class=\"quran-arabic-font text-success\">تُشْرِكُونَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">دُونِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ﴿</span><br />\r\n<br />\r\n(பிறகு அவர்களிடம் கேட்கப்படும்: \"அல்லாஹ்வையன்றி நீங்கள் எவற்றை இணைவைத்துக் கொண்டிருந்தீர்களோ அவை எங்கே?\") அதாவது, \"அல்லாஹ்வைத் தவிர்த்து நீங்கள் வணங்கி வந்த அந்தச் சிலைகள் எங்கே? இன்று அவை உங்களுக்கு உதவ முடியுமா?\" என்று அவர்களிடம் கேட்கப்படும். <span class=\"quran-arabic-font text-success\">﴾قَـالُواْ</span> <span class=\"quran-arabic-font text-success\">ضَـلُّواْ</span> <span class=\"quran-arabic-font text-success\">عَنَّا﴿</span><br />\r\n<br />\r\n(அதற்கு அவர்கள், \"அவை எங்களை விட்டு மறைந்துவிட்டன\" என்று கூறுவார்கள்.) அதாவது, \"அவை எங்களை விட்டுப் போய்விட்டன; அவற்றால் எங்களுக்கு எந்த நன்மையும் செய்ய முடியாது\" (என்று கூறுவார்கள்). <span class=\"quran-arabic-font text-success\">﴾بَل</span> <span class=\"quran-arabic-font text-success\">لَّمْ</span> <span class=\"quran-arabic-font text-success\">نَكُنْ</span> <span class=\"quran-arabic-font text-success\">نَّدْعُواْ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">قَبْلُ</span> <span class=\"quran-arabic-font text-success\">شَيْئاً﴿</span><br />\r\n<br />\r\n(\"இல்லை! இதற்கு முன்னர் நாம் எதையுமே அழைத்துக் (வணங்கிக்) கொண்டிருக்கவில்லை\" (என்று கூறுவார்கள்).) அதாவது, தாங்கள் அவற்றை வணங்கியதையே அவர்கள் மறுப்பார்கள். இது பின்வரும் வசனத்தைப் போன்றது: <span class=\"quran-arabic-font text-success\">﴾ثُمَّ</span> <span class=\"quran-arabic-font text-success\">لَمْ</span> <span class=\"quran-arabic-font text-success\">تَكُنْ</span> <span class=\"quran-arabic-font text-success\">فِتْنَتُهُمْ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">قَالُواْ</span> <span class=\"quran-arabic-font text-success\">وَاللَّهِ</span> <span class=\"quran-arabic-font text-success\">رَبِّنَا</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">كُنَّا</span> <span class=\"quran-arabic-font text-success\">مُشْرِكِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(பிறகு, \"எங்கள் இறைவனாகிய அல்லாஹ்வின் மீது சத்தியமாக! நாங்கள் இணைவைப்பவர்களாக இருக்கவில்லை\" என்று கூறுவதைத் தவிர அவர்களுக்கு வேறு எந்தச் சாக்குப்போக்கும் இருக்காது.) (<a href=\"qurandisp.php?sura=6&ayah=23\" class=\"link\">6:23</a>). அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾كَذَلِكَ</span> <span class=\"quran-arabic-font text-success\">يُضِلُّ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">الْكَـفِرِينَ﴿</span><br />\r\n<br />\r\n(இவ்வாறே அல்லாஹ் நிராகரிப்பாளர்களை வழிகேட்டில் விடுகிறான்.) <span class=\"quran-arabic-font text-success\">﴾ذَلِكُمْ</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">كُنتُمْ</span> <span class=\"quran-arabic-font text-success\">تَفْرَحُونَ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الاٌّرْضِ</span> <span class=\"quran-arabic-font text-success\">بِغَيْرِ</span> <span class=\"quran-arabic-font text-success\">الْحَقِّ</span> <span class=\"quran-arabic-font text-success\">وَبِمَا</span> <span class=\"quran-arabic-font text-success\">كُنتُمْ</span> <span class=\"quran-arabic-font text-success\">تَمْرَحُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(பூமியில் எவ்வித நியாயமுமின்றி நீங்கள் களிப்படைந்து கொண்டிருந்ததாலும், நீங்கள் மமதையுடன் திரிந்து கொண்டிருந்ததாலும் உங்களுக்கு இந்த நிலை ஏற்பட்டது.) அதாவது வானவர்கள் அவர்களிடம் கூறுவார்கள்: \"நீங்கள் இப்போது அனுபவிக்கும் இந்த வேதனையானது, பூமியில் எவ்வித நியாயமுமின்றி நீங்கள் வரம்பு மீறி நடந்ததற்கும், வீண் பெருமை கொண்டதற்கும் உரிய கூலியாகும்.\" <span class=\"quran-arabic-font text-success\">﴾ادْخُلُواْ</span> <span class=\"quran-arabic-font text-success\">أَبْوَبَ</span> <span class=\"quran-arabic-font text-success\">جَهَنَّمَ</span> <span class=\"quran-arabic-font text-success\">خَـلِدِينَ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">فَبِئْسَ</span> <span class=\"quran-arabic-font text-success\">مَثْوَى</span> <span class=\"quran-arabic-font text-success\">الْمُتَكَبِّرِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அதில் நிரந்தரமாகத் தங்குவதற்காக நரகத்தின் வாசல்களுக்குள் நுழையுங்கள். பெருமை கொண்டவர்களின் தங்குமிடம் மிகக் கெட்டது!) அதாவது, அல்லாஹ்வின் வசனங்களை ஆணவத்துடன் புறக்கணித்து, அவனது சான்றுகளையும் ஆதாரங்களையும் ஏற்க மறுத்தவர்களுக்கு, அவமானமும் கடுமையான தண்டனையும் நிறைந்த அந்த இறுதி தங்குமிடம் எவ்வளவு மோசமானது! அல்லாஹ்வே மிக அறிந்தவன்.<br />\r\n<br />\r\n<br />\r\n<br />","text":"அல்லாஹ்வின் வசனங்களை மறுத்து தர்க்கம் செய்பவர்களின் முடிவு\n\r\n\n\r\n﴾أَلَمْ تَرَ إِلَى الَّذِينَ يُجَـدِلُونَ فِى ءَايَـتِ اللَّهِ أَنَّى يُصْرَفُونَ ﴿\n\r\n\n\r\nஅல்லாஹ் கூறுகிறான்: 'முஹம்மத் (ஸல்) அவர்களே! அல்லாஹ்வின் வசனங்களை மறுத்து, பொய்யைக் கொண்டு சத்தியத்தை எதிர்க்கத் துணிபவர்களைப் பார்த்து நீங்கள் ஆச்சரியப்படவில்லையா? அவர்களது புத்தி உண்மையிலிருந்து எவ்வாறு திசைதிருப்பப்பட்டு, அவர்கள் வழிகெடுக்கப்படுகிறார்கள் (என்பதைக் கவனியுங்கள்).' ﴾الَّذِينَ كَذَّبُواْ بِالْكِـتَـبِ وَبِمَآ أَرْسَلْنَا بِهِ رُسُلَنَا﴿\n\r\n\n\r\n(எவர்கள் இந்த வேதத்தையும், நம்முடைய தூதர்களுடன் நாம் எதை அனுப்பினோமோ அதையும் பொய்ப்பிக்கிறார்களோ -) அதாவது, நேர்வழியையும் தெளிவான அத்தாட்சிகளையும் (அவர்கள் மறுக்கிறார்கள்). ﴾فَسَوْفَ يَعْلَمُونَ﴿\n\r\n\n\r\n(அவர்கள் விரைவில் அறிந்து கொள்வார்கள்.) இது இத்தகைய மக்களுக்கு இறைவனிடமிருந்து விடுக்கப்படும் ஒரு கடுமையான எச்சரிக்கையும் தெளிவான அச்சுறுத்தலுமாகும். இது பின்வரும் வசனத்தைப் போன்றது: ﴾وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ ﴿\n\r\n\n\r\n(அந்நாளில் (உண்மையைப்) பொய்ப்பிப்பவர்களுக்குக் கேடுதான்!) (77:15) ﴾إِذِ الاٌّغْلَـلُ فِى أَعْنَـقِهِمْ والسَّلَـسِلُ﴿\n\r\n\n\r\n(அவர்களுடைய கழுத்துகளில் இரும்பு விலங்குகள் மாட்டப்பட்டு, சங்கிலிகளால் அவர்கள் பிணைக்கப்படும் போது.) அதாவது, அந்தச் சங்கிலிகள் இரும்பு விலங்குகளுடன் இணைக்கப்பட்டிருக்கும். நரகத்தின் காவலர்கள் அவர்களைக் குப்புறக் கவிழ்த்து, சில நேரங்களில் கொதிக்கும் நீருக்கும், சில நேரங்களில் நரக நெருப்புக்கும் இழுத்துச் செல்வார்கள். அல்லாஹ் கூறுகிறான்: ﴾يُسْحَبُونَ فِى الْحَمِيمِ ثُمَّ فِى النَّارِ يُسْجَرُونَ﴿\n\r\n\n\r\n(அவர்கள் கொதிக்கும் நீரில் இழுத்துச் செல்லப்படுவார்கள்; பின்னர் நரக நெருப்பில் அவர்கள் எரிக்கப்படுவார்கள்.) இது பின்வரும் வசனங்களைப் போன்றது: ﴾هَـذِهِ جَهَنَّمُ الَّتِى يُكَذِّبُ بِهَا الْمُجْرِمُونَ - يَطُوفُونَ بَيْنَهَا وَبَيْنَ حَمِيمٍ ءَانٍ ﴿\n\r\n\n\r\n(“குற்றவாளிகள் எதைப் பொய்ப்பித்தார்களோ அந்த நரகம் இதுதான்.” அதற்கும், கொதித்துக் கொண்டிருக்கும் நீருக்கும் இடையே அவர்கள் சுற்றி வருவார்கள்.) (55:43-44). அவர்கள் ஸக்கூம் (நரகத்தின் கசப்பான மரம்) உண்பார்கள் என்றும், ஹமீம் (கொதிக்கும் நீர்) குடிப்பார்கள் என்றும் விவரித்த பிறகு அல்லாஹ் கூறுகிறான்: ﴾ثُمَّ إِنَّ مَرْجِعَهُمْ لإِلَى الْجَحِيمِ ﴿\n\r\n\n\r\n(பிறகு நிச்சயமாக, அவர்கள் மீளுமிடம் நரகத்தின் கொழுந்துவிட்டெரியும் நெருப்பின் பக்கமேயாகும்.) (37:68). மேலும் அல்லாஹ் கூறுகிறான்: ﴾وَأَصْحَـبُ الشِّمَالِ مَآ أَصْحَـبُ الشِّمَالِ - فِى سَمُومٍ وَحَمِيمٍ - وَظِلٍّ مِّن يَحْمُومٍ - لاَّ بَارِدٍ وَلاَ كَرِيمٍ ﴿\n\r\n\n\r\n(இடது புறத்துக்காரர்கள் - அந்த இடது புறத்துக்காரர்கள் எவ்வளவு (துரதிர்ஷ்டசாலிகள்)! அவர்கள் கடுமையான வெப்பக் காற்றிலும், கொதிக்கும் நீரிலும், கரும்புகை நிழலிலும் இருப்பார்கள். (அந்த நிழலோ) குளிர்ச்சியானதும் அல்ல; கண்ணியமானதும் அல்ல.) ﴾ثُمَّ إِنَّكُمْ أَيُّهَا الضَّآلُّونَ الْمُكَذِّبُونَ - لآكِلُونَ مِن شَجَرٍ مِّن زَقُّومٍ - فَمَالِئُونَ مِنْهَا الْبُطُونَ - فَشَارِبُونَ عَلَيْهِ مِنَ الْحَمِيمِ - فَشَارِبُونَ شُرْبَ الْهِيمِ - هَـذَا نُزُلُهُمْ يَوْمَ الدِّينِ ﴿ வரை,\n\r\n\n\r\n(பிறகு, வழிதவறியவர்களே! (மறுமையைப்) பொய்ப்பிப்பவர்களே! நீங்கள் நிச்சயமாக ஸக்கூம் மரத்திலிருந்து உண்பீர்கள். அதைக் கொண்டு உங்கள் வயிறுகளை நிரப்புவீர்கள். அதன் மேல் கொதிக்கும் நீரைக் குடிப்பீர்கள். தாகம் கொண்ட ஒட்டகங்கள் குடிப்பதைப் போல் குடிப்பீர்கள். கூலி கொடுக்கப்படும் (மறுமை) நாளில் இதுவே அவர்களுக்கு அளிக்கப்படும் விருந்தாகும்.) (56: 41-44, 51-56) ﴾إِنَّ شَجَرَةَ الزَّقُّومِ - طَعَامُ الاٌّثِيمِ - كَالْمُهْلِ يَغْلِى فِى الْبُطُونِ - كَغَلْىِ الْحَمِيمِ - خُذُوهُ فَاعْتِلُوهُ إِلَى سَوَآءِ الْجَحِيمِ - ثُمَّ صُبُّواْ فَوْقَ رَأْسِهِ مِنْ عَذَابِ الْحَمِيمِ - ذُقْ إِنَّكَ أَنتَ الْعَزِيزُ الْكَرِيمُ - إِنَّ هَـذَا مَا كُنتُمْ بِهِ تَمْتَرُونَ ﴿\n\r\n\n\r\n(நிச்சயமாக ஸக்கூம் மரம் பாவிகளின் உணவாகும். அது உருக்கப்பட்ட செம்பு போல் வயிறுகளில் கொதிக்கும். கொதிக்கும் நீர் கொதிப்பதைப் போல. (வானவர்களிடம் கூறப்படும்:) \"அவனைப் பிடித்து நரகத்தின் மையப்பகுதிக்கு இழுத்துச் செல்லுங்கள். பின்னர் அவனது தலையின் மேல் கொதிக்கும் நீரை ஊற்றி வேதனைப்படுத்துங்கள். (இதை) நீ சுவைத்துப் பார்! நிச்சயமாக நீ (உன்னையே) வலிமைமிக்கவனாகவும் கண்ணியமானவனாகவும் அல்லவா (நினைத்துக் கொண்டிருந்தாய்)! நிச்சயமாக எதைப் பற்றி நீங்கள் சந்தேகித்துக் கொண்டிருந்தீர்களோ, அது இதுவே!\") (44:43-50). அதாவது, அவர்களைக் கண்டிப்பதற்கும் ஏளனம் செய்வதற்கும் இவ்வாறு கூறப்படும். ﴾ثُمَّ قِيلَ لَهُمْ أَيْنَ مَا كُنتُمْ تُشْرِكُونَ مِن دُونِ اللَّهِ﴿\n\r\n\n\r\n(பிறகு அவர்களிடம் கேட்கப்படும்: \"அல்லாஹ்வையன்றி நீங்கள் எவற்றை இணைவைத்துக் கொண்டிருந்தீர்களோ அவை எங்கே?\") அதாவது, \"அல்லாஹ்வைத் தவிர்த்து நீங்கள் வணங்கி வந்த அந்தச் சிலைகள் எங்கே? இன்று அவை உங்களுக்கு உதவ முடியுமா?\" என்று அவர்களிடம் கேட்கப்படும். ﴾قَـالُواْ ضَـلُّواْ عَنَّا﴿\n\r\n\n\r\n(அதற்கு அவர்கள், \"அவை எங்களை விட்டு மறைந்துவிட்டன\" என்று கூறுவார்கள்.) அதாவது, \"அவை எங்களை விட்டுப் போய்விட்டன; அவற்றால் எங்களுக்கு எந்த நன்மையும் செய்ய முடியாது\" (என்று கூறுவார்கள்). ﴾بَل لَّمْ نَكُنْ نَّدْعُواْ مِن قَبْلُ شَيْئاً﴿\n\r\n\n\r\n(\"இல்லை! இதற்கு முன்னர் நாம் எதையுமே அழைத்துக் (வணங்கிக்) கொண்டிருக்கவில்லை\" (என்று கூறுவார்கள்).) அதாவது, தாங்கள் அவற்றை வணங்கியதையே அவர்கள் மறுப்பார்கள். இது பின்வரும் வசனத்தைப் போன்றது: ﴾ثُمَّ لَمْ تَكُنْ فِتْنَتُهُمْ إِلاَّ أَن قَالُواْ وَاللَّهِ رَبِّنَا مَا كُنَّا مُشْرِكِينَ ﴿\n\r\n\n\r\n(பிறகு, \"எங்கள் இறைவனாகிய அல்லாஹ்வின் மீது சத்தியமாக! நாங்கள் இணைவைப்பவர்களாக இருக்கவில்லை\" என்று கூறுவதைத் தவிர அவர்களுக்கு வேறு எந்தச் சாக்குப்போக்கும் இருக்காது.) (6:23). அல்லாஹ் கூறுகிறான்: ﴾كَذَلِكَ يُضِلُّ اللَّهُ الْكَـفِرِينَ﴿\n\r\n\n\r\n(இவ்வாறே அல்லாஹ் நிராகரிப்பாளர்களை வழிகேட்டில் விடுகிறான்.) ﴾ذَلِكُمْ بِمَا كُنتُمْ تَفْرَحُونَ فِى الاٌّرْضِ بِغَيْرِ الْحَقِّ وَبِمَا كُنتُمْ تَمْرَحُونَ ﴿\n\r\n\n\r\n(பூமியில் எவ்வித நியாயமுமின்றி நீங்கள் களிப்படைந்து கொண்டிருந்ததாலும், நீங்கள் மமதையுடன் திரிந்து கொண்டிருந்ததாலும் உங்களுக்கு இந்த நிலை ஏற்பட்டது.) அதாவது வானவர்கள் அவர்களிடம் கூறுவார்கள்: \"நீங்கள் இப்போது அனுபவிக்கும் இந்த வேதனையானது, பூமியில் எவ்வித நியாயமுமின்றி நீங்கள் வரம்பு மீறி நடந்ததற்கும், வீண் பெருமை கொண்டதற்கும் உரிய கூலியாகும்.\" ﴾ادْخُلُواْ أَبْوَبَ جَهَنَّمَ خَـلِدِينَ فِيهَا فَبِئْسَ مَثْوَى الْمُتَكَبِّرِينَ ﴿\n\r\n\n\r\n(அதில் நிரந்தரமாகத் தங்குவதற்காக நரகத்தின் வாசல்களுக்குள் நுழையுங்கள். பெருமை கொண்டவர்களின் தங்குமிடம் மிகக் கெட்டது!) அதாவது, அல்லாஹ்வின் வசனங்களை ஆணவத்துடன் புறக்கணித்து, அவனது சான்றுகளையும் ஆதாரங்களையும் ஏற்க மறுத்தவர்களுக்கு, அவமானமும் கடுமையான தண்டனையும் நிறைந்த அந்த இறுதி தங்குமிடம் எவ்வளவு மோசமானது! அல்லாஹ்வே மிக அறிந்தவன்."},"77":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=40&ayah=78\" class=\"link\">40:78</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 40:78 ஐ பார்க்கவும்"},"78":{"html":"<strong>பொறுமையைக் கடைப்பிடிக்குமாறு கட்டளையும், வெற்றியின் நற்செய்தியும்</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴿فَاصْبِرْ</span> <span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">وَعْدَ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">حَقٌّ﴾</span><br />\r\n<br />\r\nதன்னை நிராகரிப்பவர்களின் செயல்களைப் பொறுமையுடன் சகித்துக் கொள்ளுமாறு அல்லாஹ் தன் தூதருக்கு (ஸல்) இங்கு கட்டளையிடுகிறான்: \"அல்லாஹ் உமக்கு அளித்த வாக்குறுதியை நிச்சயமாக நிறைவேற்றுவான். நீங்கள் வெற்றியடைந்து உங்கள் மக்கள் மீது ஆதிக்கம் செலுத்துவீர்கள். நீங்களும் உங்களைப் பின்பற்றுபவர்களும் இவ்வுலகிலும் மறுமையிலும் வெற்றி பெறுவீர்கள்.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴿فَإِمَّا</span> <span class=\"quran-arabic-font text-success\">نُرِيَنَّكَ</span> <span class=\"quran-arabic-font text-success\">بَعْضَ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">نَعِدُهُمْ﴾</span><br />\r\n<br />\r\n(அவர்களுக்கு நாம் வாக்களித்தவற்றில் சிலவற்றை நாம் உமக்குக் காட்டினாலும்,) இதன் பொருள் இவ்வுலகிலேயே (அவர்களுக்குரிய தண்டனையைக் காட்டுவோம்) என்பதாகும். அல்லாஹ் அவ்வாறே செய்தும் காட்டினான்; பத்ருப் போரின்போது கொல்லப்பட்ட குறைஷித் தலைவர்களும் பிரமுகர்களும் இழிவுபடுத்தப்பட்டதைக் கண்டு அல்லாஹ் அவர்களுக்கு மகிழ்ச்சியை அளித்தான். பின்னர், நபி (ஸல்) அவர்களின் வாழ்நாளிலேயே மக்காவையும் ஒட்டுமொத்த அரேபிய தீபகற்பத்தையும் அல்லாஹ் அவர்களுக்கு வெற்றியாக அளித்தான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴿أَوْ</span> <span class=\"quran-arabic-font text-success\">نَتَوَفَّيَنَّكَ</span> <span class=\"quran-arabic-font text-success\">فَإِلَيْنَا</span> <span class=\"quran-arabic-font text-success\">يُرْجَعُونَ﴾</span><br />\r\n<br />\r\n(அல்லது நாம் உம்மை மரணிக்கச் செய்தாலும், அவர்கள் அனைவரும் நம்மிடமே திரும்பக் கொண்டுவரப்படுவார்கள்.) இதன் பொருள்: 'மறுமையில் அவர்களுக்குக் கடுமையான தண்டனையை நாம் வழங்குவோம்' என்பதாகும். பிறகு, அல்லாஹ் தன் நபிக்கு (ஸல்) ஆறுதல் கூறும் விதமாக இவ்வாறு கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴿وَلَقَدْ</span> <span class=\"quran-arabic-font text-success\">أَرْسَلْنَا</span> <span class=\"quran-arabic-font text-success\">رُسُلاً</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">قَبْلِكَ</span> <span class=\"quran-arabic-font text-success\">مِنْهُم</span> <span class=\"quran-arabic-font text-success\">مَّن</span> <span class=\"quran-arabic-font text-success\">قَصَصْنَا</span> <span class=\"quran-arabic-font text-success\">عَلَيْكَ﴾</span><br />\r\n<br />\r\n(நிச்சயமாக உமக்கு முன்னரும் நாம் தூதர்களை அனுப்பினோம்; அவர்களில் சிலரது வரலாற்றை உமக்கு நாம் கூறியிருக்கிறோம்.) ஸூரத்துந் நிஸாவிலும் அல்லாஹ் இதைக் குறிப்பிடுகிறான். அதாவது, 'தூதர்களில் சிலருடைய வரலாறுகளையும், அவர்களை அவர்களது மக்கள் எவ்வாறு நிராகரித்தார்கள் என்பதையும் நாம் வஹீ (இறைச்செய்தி)யாக அறிவித்துள்ளோம்; ஆனால் இறுதியாகத் தூதர்களே வெற்றி பெற்றார்கள்'.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴿وَمِنْهُم</span> <span class=\"quran-arabic-font text-success\">مَّن</span> <span class=\"quran-arabic-font text-success\">لَّمْ</span> <span class=\"quran-arabic-font text-success\">نَقْصُصْ</span> <span class=\"quran-arabic-font text-success\">عَلَيْكَ﴾</span><br />\r\n<br />\r\n(இன்னும் சிலரது வரலாற்றை உமக்கு நாம் கூறவில்லை.) வரலாறுகள் கூறப்பட்டவர்களை விடக் கூறப்படாதவர்களின் எண்ணிக்கை மிக மிக அதிகமாகும். இது ஸூரத்துந் நிஸாவில் கூறப்பட்டுள்ளது. அல்லாஹ்வுக்கே புகழும் அருளும் உரித்தாகட்டும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴿وَمَا</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">لِرَسُولٍ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">يَأْتِيَ</span> <span class=\"quran-arabic-font text-success\">بِآيَةٍ</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">بِإِذْنِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ﴾</span><br />\r\n<br />\r\n(அல்லாஹ்வின் அனுமதியின்றி எந்தவொரு தூதரும் எந்த ஓர் அத்தாட்சியையும் கொண்டு வருவதற்கு அதிகாரம் இல்லை.) அதாவது, எந்த ஒரு நபியும் தான் கொண்டு வந்த செய்தியின் உண்மைத் தன்மைக்கு அத்தாட்சியாக அற்புதங்களை நிகழ்த்த அல்லாஹ் அனுமதித்தால் ஒழிய, தானாக அவற்றைச் செய்ய இயலாது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴿فَإِذَا</span> <span class=\"quran-arabic-font text-success\">جَاءَ</span> <span class=\"quran-arabic-font text-success\">أَمْرُ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ﴾</span><br />\r\n<br />\r\n(ஆனால், அல்லாஹ்வின் கட்டளை வரும்போது,) அதாவது, நிராகரிப்பாளர்கள் மீது இறங்கும் அவனது தண்டனையும் பழிவாங்குதலுமாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴿قُضِيَ</span> <span class=\"quran-arabic-font text-success\">بِالْحَقِّ﴾</span><br />\r\n<br />\r\n(அப்பொழுது சத்தியத்தைக் கொண்டு தீர்ப்பளிக்கப்படும்.) அதன் மூலம் விசுவாசிகள் காப்பாற்றப்படுவார்கள்; நிராகரிப்பாளர்கள் அழிக்கப்படுவார்கள். அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴿وَخَسِرَ</span> <span class=\"quran-arabic-font text-success\">هُنَالِكَ</span> <span class=\"quran-arabic-font text-success\">الْمُبْطِلُونَ﴾</span><br />\r\n<br />\r\n(அந்நேரத்தில் அசத்தியவாதிகள் நஷ்டமடைவார்கள்.)<br />\r\n<br />","text":"பொறுமையைக் கடைப்பிடிக்குமாறு கட்டளையும், வெற்றியின் நற்செய்தியும்\n\r\n\n\r\n﴿فَاصْبِرْ إِنَّ وَعْدَ اللَّهِ حَقٌّ﴾\n\r\n\n\r\nதன்னை நிராகரிப்பவர்களின் செயல்களைப் பொறுமையுடன் சகித்துக் கொள்ளுமாறு அல்லாஹ் தன் தூதருக்கு (ஸல்) இங்கு கட்டளையிடுகிறான்: \"அல்லாஹ் உமக்கு அளித்த வாக்குறுதியை நிச்சயமாக நிறைவேற்றுவான். நீங்கள் வெற்றியடைந்து உங்கள் மக்கள் மீது ஆதிக்கம் செலுத்துவீர்கள். நீங்களும் உங்களைப் பின்பற்றுபவர்களும் இவ்வுலகிலும் மறுமையிலும் வெற்றி பெறுவீர்கள்.\"\n\r\n\n\r\n﴿فَإِمَّا نُرِيَنَّكَ بَعْضَ الَّذِى نَعِدُهُمْ﴾\n\r\n\n\r\n(அவர்களுக்கு நாம் வாக்களித்தவற்றில் சிலவற்றை நாம் உமக்குக் காட்டினாலும்,) இதன் பொருள் இவ்வுலகிலேயே (அவர்களுக்குரிய தண்டனையைக் காட்டுவோம்) என்பதாகும். அல்லாஹ் அவ்வாறே செய்தும் காட்டினான்; பத்ருப் போரின்போது கொல்லப்பட்ட குறைஷித் தலைவர்களும் பிரமுகர்களும் இழிவுபடுத்தப்பட்டதைக் கண்டு அல்லாஹ் அவர்களுக்கு மகிழ்ச்சியை அளித்தான். பின்னர், நபி (ஸல்) அவர்களின் வாழ்நாளிலேயே மக்காவையும் ஒட்டுமொத்த அரேபிய தீபகற்பத்தையும் அல்லாஹ் அவர்களுக்கு வெற்றியாக அளித்தான்.\n\r\n\n\r\n﴿أَوْ نَتَوَفَّيَنَّكَ فَإِلَيْنَا يُرْجَعُونَ﴾\n\r\n\n\r\n(அல்லது நாம் உம்மை மரணிக்கச் செய்தாலும், அவர்கள் அனைவரும் நம்மிடமே திரும்பக் கொண்டுவரப்படுவார்கள்.) இதன் பொருள்: 'மறுமையில் அவர்களுக்குக் கடுமையான தண்டனையை நாம் வழங்குவோம்' என்பதாகும். பிறகு, அல்லாஹ் தன் நபிக்கு (ஸல்) ஆறுதல் கூறும் விதமாக இவ்வாறு கூறுகிறான்:\n\r\n\n\r\n﴿وَلَقَدْ أَرْسَلْنَا رُسُلاً مِّن قَبْلِكَ مِنْهُم مَّن قَصَصْنَا عَلَيْكَ﴾\n\r\n\n\r\n(நிச்சயமாக உமக்கு முன்னரும் நாம் தூதர்களை அனுப்பினோம்; அவர்களில் சிலரது வரலாற்றை உமக்கு நாம் கூறியிருக்கிறோம்.) ஸூரத்துந் நிஸாவிலும் அல்லாஹ் இதைக் குறிப்பிடுகிறான். அதாவது, 'தூதர்களில் சிலருடைய வரலாறுகளையும், அவர்களை அவர்களது மக்கள் எவ்வாறு நிராகரித்தார்கள் என்பதையும் நாம் வஹீ (இறைச்செய்தி)யாக அறிவித்துள்ளோம்; ஆனால் இறுதியாகத் தூதர்களே வெற்றி பெற்றார்கள்'.\n\r\n\n\r\n﴿وَمِنْهُم مَّن لَّمْ نَقْصُصْ عَلَيْكَ﴾\n\r\n\n\r\n(இன்னும் சிலரது வரலாற்றை உமக்கு நாம் கூறவில்லை.) வரலாறுகள் கூறப்பட்டவர்களை விடக் கூறப்படாதவர்களின் எண்ணிக்கை மிக மிக அதிகமாகும். இது ஸூரத்துந் நிஸாவில் கூறப்பட்டுள்ளது. அல்லாஹ்வுக்கே புகழும் அருளும் உரித்தாகட்டும்.\n\r\n\n\r\n﴿وَمَا كَانَ لِرَسُولٍ أَن يَأْتِيَ بِآيَةٍ إِلَّا بِإِذْنِ اللَّهِ﴾\n\r\n\n\r\n(அல்லாஹ்வின் அனுமதியின்றி எந்தவொரு தூதரும் எந்த ஓர் அத்தாட்சியையும் கொண்டு வருவதற்கு அதிகாரம் இல்லை.) அதாவது, எந்த ஒரு நபியும் தான் கொண்டு வந்த செய்தியின் உண்மைத் தன்மைக்கு அத்தாட்சியாக அற்புதங்களை நிகழ்த்த அல்லாஹ் அனுமதித்தால் ஒழிய, தானாக அவற்றைச் செய்ய இயலாது.\n\r\n\n\r\n﴿فَإِذَا جَاءَ أَمْرُ اللَّهِ﴾\n\r\n\n\r\n(ஆனால், அல்லாஹ்வின் கட்டளை வரும்போது,) அதாவது, நிராகரிப்பாளர்கள் மீது இறங்கும் அவனது தண்டனையும் பழிவாங்குதலுமாகும்.\n\r\n\n\r\n﴿قُضِيَ بِالْحَقِّ﴾\n\r\n\n\r\n(அப்பொழுது சத்தியத்தைக் கொண்டு தீர்ப்பளிக்கப்படும்.) அதன் மூலம் விசுவாசிகள் காப்பாற்றப்படுவார்கள்; நிராகரிப்பாளர்கள் அழிக்கப்படுவார்கள். அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\n﴿وَخَسِرَ هُنَالِكَ الْمُبْطِلُونَ﴾\n\r\n\n\r\n(அந்நேரத்தில் அசத்தியவாதிகள் நஷ்டமடைவார்கள்.)"},"79":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=40&ayah=81\" class=\"link\">40:81</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 40:81 ஐ பார்க்கவும்"},"80":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=40&ayah=81\" class=\"link\">40:81</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 40:81 ஐ பார்க்கவும்"},"81":{"html":"<strong>கால்நடைகளும் அல்லாஹ்வின் அருட்கொடையும் அவனுடைய அத்தாட்சியுமாகும்</strong><br />\r\n<br />\r\nஅல்லாஹ் தன் அடியார்களுக்கு 'அல்-அன்ஆம்' (கால்நடைகளை) படைத்ததன் மூலம் அவன் செய்த அருட்கொடைகளை அவர்களுக்கு நினைவூட்டுகிறான். இது ஒட்டகங்கள், மாடுகள் மற்றும் ஆடுகளைக் குறிக்கிறது; அவற்றில் சிலவற்றை அவர்கள் சவாரி செய்யவும், சிலவற்றை உணவாக உட்கொள்ளவும் செய்கின்றனர். ஒட்டகங்கள் சவாரி செய்யவும் அல்லது உண்ணவும் பயன்படுகின்றன; அவற்றின் பால் பருகப்படுகிறது. மேலும், தொலைதூரப் பயணங்களின் போது கனமான சுமைகளைச் சுமந்து செல்லவும் அவை பயன்படுகின்றன. மாடுகள் உண்ணப்படுகின்றன, அவற்றின் பாலும் பருகப்படுகிறது; அவை நிலத்தை உழுவதற்கும் பயன்படுத்தப்படுகின்றன. ஆடுகள் உண்ணப்படுகின்றன, அவற்றின் பாலும் பருகப்படுகிறது. நாம் ஏற்கனவே ஸூரத்துல் அன்ஆம் மற்றும் ஸூரத்துன் நஹ்ல் போன்றவற்றில் விளக்கியுள்ளபடி, இந்த விலங்குகள் அனைத்தின் ரோமங்கள் மற்றும் கம்பளிகள் கூடாரங்கள், ஆடைகள் மற்றும் வீட்டு உபயோகப் பொருட்கள் தயாரிக்கப் பயன்படுத்தப்படுகின்றன. இங்கே அல்லாஹ் கூறுகிறான்:<br />\r\n<span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">الَّذِي</span> <span class=\"quran-arabic-font text-success\">جَعَلَ</span> <span class=\"quran-arabic-font text-success\">لَكُمُ</span> <span class=\"quran-arabic-font text-success\">الْأَنْعَامَ</span> <span class=\"quran-arabic-font text-success\">لِتَرْكَبُوا</span> <span class=\"quran-arabic-font text-success\">مِنْهَا</span> <span class=\"quran-arabic-font text-success\">وَمِنْهَا</span> <span class=\"quran-arabic-font text-success\">تَأْكُلُونَ</span> - <span class=\"quran-arabic-font text-success\">وَلَكُمْ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">مَنَافِعُ</span> <span class=\"quran-arabic-font text-success\">وَلِتَبْلُغُوا</span> <span class=\"quran-arabic-font text-success\">عَلَيْهَا</span> <span class=\"quran-arabic-font text-success\">حَاجَةً</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">صُدُورِكُمْ</span> <span class=\"quran-arabic-font text-success\">وَعَلَيْهَا</span> <span class=\"quran-arabic-font text-success\">وَعَلَى</span> <span class=\"quran-arabic-font text-success\">الْفُلْكِ</span> <span class=\"quran-arabic-font text-success\">تُحْمَلُونَ</span><br />\r\n<br />\r\n(அல்லாஹ்வே உங்களுக்காகக் கால்நடைகளை உண்டாக்கினான்; அவற்றில் சிலவற்றின் மீது நீங்கள் சவாரி செய்யவும், சிலவற்றை நீங்கள் உண்ணவும் செய்கிறீர்கள். இன்னும் அவற்றில் உங்களுக்கு (வேறு பல) பயன்களும் உள்ளன. உங்கள் உள்ளங்களில் உள்ள ஒரு தேவையை அவற்றின் மூலம் நீங்கள் எய்துவதற்காகவும் (அவன் அவற்றை உண்டாக்கினான்); அவற்றின் மீதும், கப்பல்களின் மீதும் நீங்கள் சுமந்து செல்லப்படுகிறீர்கள்.)<br />\r\n<span class=\"quran-arabic-font text-success\">وَيُرِيكُمْ</span> <span class=\"quran-arabic-font text-success\">آيَاتِهِ</span><br />\r\n<br />\r\n(மேலும் அவன் தனது அத்தாட்சிகளை (ஆயத்களை) உங்களுக்குக் காட்டுகிறான்.) இதன் பொருள், 'வான எல்லைகளிலும் உங்களுக்குள்ளேயும் உள்ள அவனது சான்றுகளும் ஆதாரங்களுமாகும்' என்பதாகும்.<br />\r\n<span class=\"quran-arabic-font text-success\">فَأَيَّ</span> <span class=\"quran-arabic-font text-success\">آيَاتِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">تُنكِرُونَ</span><br />\r\n<br />\r\n(அப்படியாயின், அல்லாஹ்வின் அத்தாட்சிகளில் எதனை நீங்கள் மறுப்பீர்கள்?) இதன் பொருள், நீங்கள் பிடிவாதக்காரர்களாகவும் அகந்தை கொண்டவர்களாகவும் இருந்தால் தவிர, அவனது அத்தாட்சிகளையும் சான்றுகளையும் உங்களால் மறுக்க முடியாது என்பதாகும்.<br />\r\n<span class=\"quran-arabic-font text-success\">أَفَلَمْ</span> <span class=\"quran-arabic-font text-success\">يَسِيرُوا</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْأَرْضِ</span> <span class=\"quran-arabic-font text-success\">فَيَنظُرُوا</span> <span class=\"quran-arabic-font text-success\">كَيْفَ</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">عَاقِبَةُ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">قَبْلِهِمْ</span> <span class=\"quran-arabic-font text-success\">كَانُوا</span> <span class=\"quran-arabic-font text-success\">أَكْثَرَ</span> <span class=\"quran-arabic-font text-success\">مِنْهُمْ</span> <span class=\"quran-arabic-font text-success\">وَأَشَدَّ</span> <span class=\"quran-arabic-font text-success\">قُوَّةً</span> <span class=\"quran-arabic-font text-success\">وَآثَاراً</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْأَرْضِ</span> <span class=\"quran-arabic-font text-success\">فَمَا</span> <span class=\"quran-arabic-font text-success\">أَغْنَى</span> <span class=\"quran-arabic-font text-success\">عَنْهُم</span> <span class=\"quran-arabic-font text-success\">مَّا</span> <span class=\"quran-arabic-font text-success\">كَانُوا</span> <span class=\"quran-arabic-font text-success\">يَكْسِبُونَ</span> - <span class=\"quran-arabic-font text-success\">فَلَمَّا</span> <span class=\"quran-arabic-font text-success\">جَاءَتْهُمْ</span> <span class=\"quran-arabic-font text-success\">رُسُلُهُم</span> <span class=\"quran-arabic-font text-success\">بِالْبَيِّنَاتِ</span> <span class=\"quran-arabic-font text-success\">فَرِحُوا</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">عِندَهُمْ</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">الْعِلْمِ</span> <span class=\"quran-arabic-font text-success\">وَحَاقَ</span> <span class=\"quran-arabic-font text-success\">بِهِم</span> <span class=\"quran-arabic-font text-success\">مَّا</span> <span class=\"quran-arabic-font text-success\">كَانُوا</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">يَسْتَهْزِئُونَ</span> - <span class=\"quran-arabic-font text-success\">فَلَمَّا</span> <span class=\"quran-arabic-font text-success\">رَأَوْا</span> <span class=\"quran-arabic-font text-success\">بَأْسَنَا</span> <span class=\"quran-arabic-font text-success\">قَالُوا</span> <span class=\"quran-arabic-font text-success\">آمَنَّا</span> <span class=\"quran-arabic-font text-success\">بِاللَّهِ</span> <span class=\"quran-arabic-font text-success\">وَحْدَهُ</span> <span class=\"quran-arabic-font text-success\">وَكَفَرْنَا</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">كُنَّا</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">مُشْرِكِينَ</span><br />\r\n<br />\r\n<br />\r\n<br />","text":"கால்நடைகளும் அல்லாஹ்வின் அருட்கொடையும் அவனுடைய அத்தாட்சியுமாகும்\n\r\n\n\r\nஅல்லாஹ் தன் அடியார்களுக்கு 'அல்-அன்ஆம்' (கால்நடைகளை) படைத்ததன் மூலம் அவன் செய்த அருட்கொடைகளை அவர்களுக்கு நினைவூட்டுகிறான். இது ஒட்டகங்கள், மாடுகள் மற்றும் ஆடுகளைக் குறிக்கிறது; அவற்றில் சிலவற்றை அவர்கள் சவாரி செய்யவும், சிலவற்றை உணவாக உட்கொள்ளவும் செய்கின்றனர். ஒட்டகங்கள் சவாரி செய்யவும் அல்லது உண்ணவும் பயன்படுகின்றன; அவற்றின் பால் பருகப்படுகிறது. மேலும், தொலைதூரப் பயணங்களின் போது கனமான சுமைகளைச் சுமந்து செல்லவும் அவை பயன்படுகின்றன. மாடுகள் உண்ணப்படுகின்றன, அவற்றின் பாலும் பருகப்படுகிறது; அவை நிலத்தை உழுவதற்கும் பயன்படுத்தப்படுகின்றன. ஆடுகள் உண்ணப்படுகின்றன, அவற்றின் பாலும் பருகப்படுகிறது. நாம் ஏற்கனவே ஸூரத்துல் அன்ஆம் மற்றும் ஸூரத்துன் நஹ்ல் போன்றவற்றில் விளக்கியுள்ளபடி, இந்த விலங்குகள் அனைத்தின் ரோமங்கள் மற்றும் கம்பளிகள் கூடாரங்கள், ஆடைகள் மற்றும் வீட்டு உபயோகப் பொருட்கள் தயாரிக்கப் பயன்படுத்தப்படுகின்றன. இங்கே அல்லாஹ் கூறுகிறான்:\n\r\nاللَّهُ الَّذِي جَعَلَ لَكُمُ الْأَنْعَامَ لِتَرْكَبُوا مِنْهَا وَمِنْهَا تَأْكُلُونَ - وَلَكُمْ فِيهَا مَنَافِعُ وَلِتَبْلُغُوا عَلَيْهَا حَاجَةً فِي صُدُورِكُمْ وَعَلَيْهَا وَعَلَى الْفُلْكِ تُحْمَلُونَ\n\r\n\n\r\n(அல்லாஹ்வே உங்களுக்காகக் கால்நடைகளை உண்டாக்கினான்; அவற்றில் சிலவற்றின் மீது நீங்கள் சவாரி செய்யவும், சிலவற்றை நீங்கள் உண்ணவும் செய்கிறீர்கள். இன்னும் அவற்றில் உங்களுக்கு (வேறு பல) பயன்களும் உள்ளன. உங்கள் உள்ளங்களில் உள்ள ஒரு தேவையை அவற்றின் மூலம் நீங்கள் எய்துவதற்காகவும் (அவன் அவற்றை உண்டாக்கினான்); அவற்றின் மீதும், கப்பல்களின் மீதும் நீங்கள் சுமந்து செல்லப்படுகிறீர்கள்.)\n\r\nوَيُرِيكُمْ آيَاتِهِ\n\r\n\n\r\n(மேலும் அவன் தனது அத்தாட்சிகளை (ஆயத்களை) உங்களுக்குக் காட்டுகிறான்.) இதன் பொருள், 'வான எல்லைகளிலும் உங்களுக்குள்ளேயும் உள்ள அவனது சான்றுகளும் ஆதாரங்களுமாகும்' என்பதாகும்.\n\r\nفَأَيَّ آيَاتِ اللَّهِ تُنكِرُونَ\n\r\n\n\r\n(அப்படியாயின், அல்லாஹ்வின் அத்தாட்சிகளில் எதனை நீங்கள் மறுப்பீர்கள்?) இதன் பொருள், நீங்கள் பிடிவாதக்காரர்களாகவும் அகந்தை கொண்டவர்களாகவும் இருந்தால் தவிர, அவனது அத்தாட்சிகளையும் சான்றுகளையும் உங்களால் மறுக்க முடியாது என்பதாகும்.\n\r\nأَفَلَمْ يَسِيرُوا فِي الْأَرْضِ فَيَنظُرُوا كَيْفَ كَانَ عَاقِبَةُ الَّذِينَ مِن قَبْلِهِمْ كَانُوا أَكْثَرَ مِنْهُمْ وَأَشَدَّ قُوَّةً وَآثَاراً فِي الْأَرْضِ فَمَا أَغْنَى عَنْهُم مَّا كَانُوا يَكْسِبُونَ - فَلَمَّا جَاءَتْهُمْ رُسُلُهُم بِالْبَيِّنَاتِ فَرِحُوا بِمَا عِندَهُمْ مِّنَ الْعِلْمِ وَحَاقَ بِهِم مَّا كَانُوا بِهِ يَسْتَهْزِئُونَ - فَلَمَّا رَأَوْا بَأْسَنَا قَالُوا آمَنَّا بِاللَّهِ وَحْدَهُ وَكَفَرْنَا بِمَا كُنَّا بِهِ مُشْرِكِينَ"},"82":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=40&ayah=85\" class=\"link\">40:85</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 40:85 ஐ பார்க்கவும்"},"83":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=40&ayah=85\" class=\"link\">40:85</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 40:85 ஐ பார்க்கவும்"},"84":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=40&ayah=85\" class=\"link\">40:85</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 40:85 ஐ பார்க்கவும்"},"85":{"html":"<strong>முன்னோர்களுக்கு நேர்ந்தவற்றிலிருந்து பெற வேண்டிய பாடம்</strong><br />\r\n<br />\r\nபண்டைய காலங்களில் தங்களது தூதர்களை நிராகரித்த சமூகங்களைப் பற்றி அல்லாஹ் நமக்குக் கூறுகிறான். அவர்கள் மிகுந்த வலிமையுடன் இருந்தபோதிலும், அவர்கள் அனுபவித்த கடுமையான தண்டனையையும், அவர்கள் பூமியில் விட்டுச் சென்ற அடையாளங்களையும், அவர்கள் திரட்டிய பெரும் செல்வங்களையும் அவன் குறிப்பிடுகிறான். அவையெதுவும் அவர்களுக்குச் சிறிதும் பலனளிக்கவில்லை; அல்லாஹ்வின் தண்டனையிலிருந்து அவர்களைக் காப்பாற்றவும் முடியவில்லை. ஏனென்றால், தூதர்கள் அவர்களிடம் தெளிவான அத்தாட்சிகளையும் உறுதியான சான்றுகளையும் கொண்டு வந்தபோது, அவர்கள் அவற்றை அலட்சியப்படுத்தினர். மாறாக, தங்களிடம் இருந்த (உலகார்ந்த) அறிவைக் கொண்டே அவர்கள் திருப்தியடைந்தனர் அல்லது அவ்வாறு வாதிட்டனர்; மேலும் தூதர்கள் கொண்டு வந்தவை தங்களுக்குத் தேவையில்லை என்றும் கூறினர். முஜாஹித் (ரஹ்) அவர்கள் கூறினார்கள்: \"அவர்களை விட எங்களுக்கு நன்றாகத் தெரியும், நாங்கள் மீண்டும் உயிர்ப்பிக்கப்பட மாட்டோம், தண்டிக்கப்படவும் மாட்டோம் என்று அவர்கள் கூறினார்கள்.\" அஸ்-ஸுத்தி (ரஹ்) அவர்கள் கூறினார்கள்: \"தங்களது அறியாமையால், அவர்கள் பெற்றிருந்த (உலக) அறிவைக் கண்டு அவர்கள் மமதை கொண்டனர். எனவே, அவர்களால் தப்பிக்கவோ தற்காத்துக் கொள்ளவோ முடியாத தண்டனையை அல்லாஹ் அவர்கள் மீது இறக்கினான்.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَحَاقَ</span> <span class=\"quran-arabic-font text-success\">بِهِم﴿</span><br />\r\n(மேலும் அவர்களைச் சூழ்ந்து கொண்டது.) என்பதன் பொருள், அவர்களை முழுமையாக வளைத்துக் கொண்டது என்பதாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾مَا</span> <span class=\"quran-arabic-font text-success\">كَانُواْ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">يَسْتَهْزِءُونَ﴿</span><br />\r\n(அவர்கள் எதைப் பரிகசித்துக் கொண்டிருந்தார்களோ அது,) என்பதன் பொருள், அவர்கள் எதை நம்ப மறுத்து, அது ஒருபோதும் நிகழாது என்று கூறினார்களோ அந்தத் தண்டனையாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَلَمَّا</span> <span class=\"quran-arabic-font text-success\">رَأَوْاْ</span> <span class=\"quran-arabic-font text-success\">بَأْسَنَا﴿</span><br />\r\n(ஆகவே, நமது தண்டனையை அவர்கள் கண்டபோது,) என்பதன் பொருள், தங்களுக்கு வரவிருந்த தண்டனையை அவர்கள் தங்கள் கண்களால் நேரில் கண்டபோது, இவ்வாறு கூறினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾قَالُواْ</span> <span class=\"quran-arabic-font text-success\">ءَامَنَّا</span> <span class=\"quran-arabic-font text-success\">بِاللَّهِ</span> <span class=\"quran-arabic-font text-success\">وَحْدَهُ</span> <span class=\"quran-arabic-font text-success\">وَكَـفَرْنَا</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">كُنَّا</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">مُشْرِكِينَ﴿</span><br />\r\n(அல்லாஹ் ஒருவனையே நாங்கள் நம்புகிறோம், அவனுக்கு இணையாக நாங்கள் கருதியவற்றை நிராகரிக்கிறோம்.) என்பதன் பொருள், அவர்கள் அல்லாஹ் ஒருவனே என்பதை உறுதிப்படுத்தி, போலி தெய்வங்களை மறுத்தார்கள். ஆனால், புகலிடம் தேடுவது பலனளிக்காத நேரத்தில் இது நிகழ்ந்தது. இது ஃபிர்அவ்ன் மூழ்கும் போது கூறியதைப் போன்றதாகும்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾ءَامَنتُ</span> <span class=\"quran-arabic-font text-success\">أَنَّهُ</span> <span class=\"quran-arabic-font text-success\">لا</span> <span class=\"quran-arabic-font text-success\">إِلِـهَ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">ءَامَنَتْ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">بَنُو</span> <span class=\"quran-arabic-font text-success\">إِسْرَائِيلَ</span> <span class=\"quran-arabic-font text-success\">وَأَنَاْ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْمُسْلِمِينَ﴿</span><br />\r\n(இஸ்ராயீலின் மக்கள் எவனை நம்புகிறார்களோ, அவனைத் தவிர வணக்கத்திற்குரியவன் வேறு யாருமில்லை என்று நான் நம்புகிறேன், மேலும் நான் முஸ்லிம்களில் ஒருவனாக இருக்கிறேன்.) (<a href=\"qurandisp.php?sura=10&ayah=90\" class=\"link\">10:90</a>). ஆனால் அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾آلْآنَ</span> <span class=\"quran-arabic-font text-success\">وَقَدْ</span> <span class=\"quran-arabic-font text-success\">عَصَيْتَ</span> <span class=\"quran-arabic-font text-success\">قَبْلُ</span> <span class=\"quran-arabic-font text-success\">وَكُنتَ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْمُفْسِدِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n(இப்போதுதானா (நீ நம்புகிறாய்)? இதற்கு முன்பு நீ மாறு செய்தாய், மேலும் நீ குழப்பம் செய்பவர்களில் ஒருவனாக இருந்தாய்.) (<a href=\"qurandisp.php?sura=10&ayah=91\" class=\"link\">10:91</a>). அதாவது, அல்லாஹ் அவனிடமிருந்து இதனை ஏற்றுக்கொள்ளவில்லை. ஏனெனில், அவன் தனது தூதர் மூஸா (அலை) அவர்களின் பிரார்த்தனைக்கு ஏற்கனவே பதிலளித்திருந்தான். அவர் (மூஸா (அலை)) இவ்வாறு பிரார்த்தித்திருந்தார்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَاشْدُدْ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">قُلُوبِهِمْ</span> <span class=\"quran-arabic-font text-success\">فَلاَ</span> <span class=\"quran-arabic-font text-success\">يُؤْمِنُواْ</span> <span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">يَرَوُاْ</span> <span class=\"quran-arabic-font text-success\">الْعَذَابَ</span> <span class=\"quran-arabic-font text-success\">الْأَلِيمَ﴿</span><br />\r\n(மேலும் அவர்களின் இதயங்களைக் கடினமாக்குவாயாக, அதனால் அவர்கள் வேதனையான தண்டனையைக் காணும் வரை அவர்கள் ஈமான் கொள்ள மாட்டார்கள்.) (<a href=\"qurandisp.php?sura=10&ayah=88\" class=\"link\">10:88</a>). அல்லாஹ் இங்கே கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَلَمْ</span> <span class=\"quran-arabic-font text-success\">يَكُ</span> <span class=\"quran-arabic-font text-success\">يَنفَعُهُمْ</span> <span class=\"quran-arabic-font text-success\">إِيمَـنُهُمْ</span> <span class=\"quran-arabic-font text-success\">لَمَّا</span> <span class=\"quran-arabic-font text-success\">رَأَوْاْ</span> <span class=\"quran-arabic-font text-success\">بَأْسَنَا</span> <span class=\"quran-arabic-font text-success\">سُنَّةَ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">الَّتِى</span> <span class=\"quran-arabic-font text-success\">قَدْ</span> <span class=\"quran-arabic-font text-success\">خَلَتْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">عِبَادِهِ﴿</span><br />\r\n(அப்பொழுது, நமது தண்டனையை அவர்கள் கண்டபோது அவர்களது நம்பிக்கை அவர்களுக்குப் பயனளிக்கவில்லை. (இது போன்றே) தனது அடியார்கள் விஷயத்தில் அல்லாஹ் கையாண்டு வரும் வழிமுறையாக இருந்துள்ளது.) என்பதன் பொருள், தண்டனையை நேரில் கண்ட பிறகு மட்டுமே பாவமன்னிப்புக் கேட்கும் எவரிடமிருந்தும் அதனை ஏற்றுக் கொள்ளாதது அல்லாஹ்வின் சட்டமாகும். ஹதீஸில் இவ்வாறு வந்துள்ளது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾</span>«<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">اللهَ</span> <span class=\"quran-arabic-font text-success\">تَعَالَى</span> <span class=\"quran-arabic-font text-success\">يَقْبَلُ</span> <span class=\"quran-arabic-font text-success\">تَوْبَةَ</span> <span class=\"quran-arabic-font text-success\">الْعَبْدِ</span> <span class=\"quran-arabic-font text-success\">مَالَمْ</span> <span class=\"quran-arabic-font text-success\">يُغَرْغِر</span>»<span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n(அல்லாஹ் தனது அடியானின் தவ்பாவை (பாவமன்னிப்பை), அவனது உயிர் தொண்டைக்குழியை அடைந்து மரண அவஸ்தை ஏற்படும் வரை ஏற்றுக் கொள்கிறான்.) மரணத்தின் போது உயிர் தொண்டையை அடைந்து, மரணமடைபவர் வானவரை நேரில் காணத் தொடங்கிவிட்டால், அதற்குப் பிறகு அவரால் பாவமன்னிப்புக் கேட்க முடியாது. அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَخَسِرَ</span> <span class=\"quran-arabic-font text-success\">هُنَالِكَ</span> <span class=\"quran-arabic-font text-success\">الْكَـفِرُونَ﴿</span><br />\r\n(மேலும் அங்கே நிராகரிப்பாளர்கள் முற்றிலும் நஷ்டமடைந்தனர்.)<br />\r\n<br />\r\nஇத்துடன் ஸூரா ஃகாஃபிரின் தஃப்ஸீர் நிறைவுற்றது. எல்லாப் புகழும் நன்றியும் அல்லாஹ்வுக்கே உரித்தாகட்டும்.<br />\r\n<br />","text":"முன்னோர்களுக்கு நேர்ந்தவற்றிலிருந்து பெற வேண்டிய பாடம்\n\r\n\n\r\nபண்டைய காலங்களில் தங்களது தூதர்களை நிராகரித்த சமூகங்களைப் பற்றி அல்லாஹ் நமக்குக் கூறுகிறான். அவர்கள் மிகுந்த வலிமையுடன் இருந்தபோதிலும், அவர்கள் அனுபவித்த கடுமையான தண்டனையையும், அவர்கள் பூமியில் விட்டுச் சென்ற அடையாளங்களையும், அவர்கள் திரட்டிய பெரும் செல்வங்களையும் அவன் குறிப்பிடுகிறான். அவையெதுவும் அவர்களுக்குச் சிறிதும் பலனளிக்கவில்லை; அல்லாஹ்வின் தண்டனையிலிருந்து அவர்களைக் காப்பாற்றவும் முடியவில்லை. ஏனென்றால், தூதர்கள் அவர்களிடம் தெளிவான அத்தாட்சிகளையும் உறுதியான சான்றுகளையும் கொண்டு வந்தபோது, அவர்கள் அவற்றை அலட்சியப்படுத்தினர். மாறாக, தங்களிடம் இருந்த (உலகார்ந்த) அறிவைக் கொண்டே அவர்கள் திருப்தியடைந்தனர் அல்லது அவ்வாறு வாதிட்டனர்; மேலும் தூதர்கள் கொண்டு வந்தவை தங்களுக்குத் தேவையில்லை என்றும் கூறினர். முஜாஹித் (ரஹ்) அவர்கள் கூறினார்கள்: \"அவர்களை விட எங்களுக்கு நன்றாகத் தெரியும், நாங்கள் மீண்டும் உயிர்ப்பிக்கப்பட மாட்டோம், தண்டிக்கப்படவும் மாட்டோம் என்று அவர்கள் கூறினார்கள்.\" அஸ்-ஸுத்தி (ரஹ்) அவர்கள் கூறினார்கள்: \"தங்களது அறியாமையால், அவர்கள் பெற்றிருந்த (உலக) அறிவைக் கண்டு அவர்கள் மமதை கொண்டனர். எனவே, அவர்களால் தப்பிக்கவோ தற்காத்துக் கொள்ளவோ முடியாத தண்டனையை அல்லாஹ் அவர்கள் மீது இறக்கினான்.\"\n\r\n\n\r\n﴾وَحَاقَ بِهِم﴿\n\r\n(மேலும் அவர்களைச் சூழ்ந்து கொண்டது.) என்பதன் பொருள், அவர்களை முழுமையாக வளைத்துக் கொண்டது என்பதாகும்.\n\r\n\n\r\n﴾مَا كَانُواْ بِهِ يَسْتَهْزِءُونَ﴿\n\r\n(அவர்கள் எதைப் பரிகசித்துக் கொண்டிருந்தார்களோ அது,) என்பதன் பொருள், அவர்கள் எதை நம்ப மறுத்து, அது ஒருபோதும் நிகழாது என்று கூறினார்களோ அந்தத் தண்டனையாகும்.\n\r\n\n\r\n﴾فَلَمَّا رَأَوْاْ بَأْسَنَا﴿\n\r\n(ஆகவே, நமது தண்டனையை அவர்கள் கண்டபோது,) என்பதன் பொருள், தங்களுக்கு வரவிருந்த தண்டனையை அவர்கள் தங்கள் கண்களால் நேரில் கண்டபோது, இவ்வாறு கூறினார்கள்:\n\r\n\n\r\n﴾قَالُواْ ءَامَنَّا بِاللَّهِ وَحْدَهُ وَكَـفَرْنَا بِمَا كُنَّا بِهِ مُشْرِكِينَ﴿\n\r\n(அல்லாஹ் ஒருவனையே நாங்கள் நம்புகிறோம், அவனுக்கு இணையாக நாங்கள் கருதியவற்றை நிராகரிக்கிறோம்.) என்பதன் பொருள், அவர்கள் அல்லாஹ் ஒருவனே என்பதை உறுதிப்படுத்தி, போலி தெய்வங்களை மறுத்தார்கள். ஆனால், புகலிடம் தேடுவது பலனளிக்காத நேரத்தில் இது நிகழ்ந்தது. இது ஃபிர்அவ்ன் மூழ்கும் போது கூறியதைப் போன்றதாகும்:\n\r\n\n\r\n﴾ءَامَنتُ أَنَّهُ لا إِلِـهَ إِلاَّ الَّذِى ءَامَنَتْ بِهِ بَنُو إِسْرَائِيلَ وَأَنَاْ مِنَ الْمُسْلِمِينَ﴿\n\r\n(இஸ்ராயீலின் மக்கள் எவனை நம்புகிறார்களோ, அவனைத் தவிர வணக்கத்திற்குரியவன் வேறு யாருமில்லை என்று நான் நம்புகிறேன், மேலும் நான் முஸ்லிம்களில் ஒருவனாக இருக்கிறேன்.) (10:90). ஆனால் அல்லாஹ் கூறினான்:\n\r\n\n\r\n﴾آلْآنَ وَقَدْ عَصَيْتَ قَبْلُ وَكُنتَ مِنَ الْمُفْسِدِينَ ﴿\n\r\n(இப்போதுதானா (நீ நம்புகிறாய்)? இதற்கு முன்பு நீ மாறு செய்தாய், மேலும் நீ குழப்பம் செய்பவர்களில் ஒருவனாக இருந்தாய்.) (10:91). அதாவது, அல்லாஹ் அவனிடமிருந்து இதனை ஏற்றுக்கொள்ளவில்லை. ஏனெனில், அவன் தனது தூதர் மூஸா (அலை) அவர்களின் பிரார்த்தனைக்கு ஏற்கனவே பதிலளித்திருந்தான். அவர் (மூஸா (அலை)) இவ்வாறு பிரார்த்தித்திருந்தார்:\n\r\n\n\r\n﴾وَاشْدُدْ عَلَى قُلُوبِهِمْ فَلاَ يُؤْمِنُواْ حَتَّى يَرَوُاْ الْعَذَابَ الْأَلِيمَ﴿\n\r\n(மேலும் அவர்களின் இதயங்களைக் கடினமாக்குவாயாக, அதனால் அவர்கள் வேதனையான தண்டனையைக் காணும் வரை அவர்கள் ஈமான் கொள்ள மாட்டார்கள்.) (10:88). அல்லாஹ் இங்கே கூறுகிறான்:\n\r\n\n\r\n﴾فَلَمْ يَكُ يَنفَعُهُمْ إِيمَـنُهُمْ لَمَّا رَأَوْاْ بَأْسَنَا سُنَّةَ اللَّهِ الَّتِى قَدْ خَلَتْ فِى عِبَادِهِ﴿\n\r\n(அப்பொழுது, நமது தண்டனையை அவர்கள் கண்டபோது அவர்களது நம்பிக்கை அவர்களுக்குப் பயனளிக்கவில்லை. (இது போன்றே) தனது அடியார்கள் விஷயத்தில் அல்லாஹ் கையாண்டு வரும் வழிமுறையாக இருந்துள்ளது.) என்பதன் பொருள், தண்டனையை நேரில் கண்ட பிறகு மட்டுமே பாவமன்னிப்புக் கேட்கும் எவரிடமிருந்தும் அதனை ஏற்றுக் கொள்ளாதது அல்லாஹ்வின் சட்டமாகும். ஹதீஸில் இவ்வாறு வந்துள்ளது:\n\r\n\n\r\n﴾«إِنَّ اللهَ تَعَالَى يَقْبَلُ تَوْبَةَ الْعَبْدِ مَالَمْ يُغَرْغِر»﴿\n\r\n(அல்லாஹ் தனது அடியானின் தவ்பாவை (பாவமன்னிப்பை), அவனது உயிர் தொண்டைக்குழியை அடைந்து மரண அவஸ்தை ஏற்படும் வரை ஏற்றுக் கொள்கிறான்.) மரணத்தின் போது உயிர் தொண்டையை அடைந்து, மரணமடைபவர் வானவரை நேரில் காணத் தொடங்கிவிட்டால், அதற்குப் பிறகு அவரால் பாவமன்னிப்புக் கேட்க முடியாது. அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\n﴾وَخَسِرَ هُنَالِكَ الْكَـفِرُونَ﴿\n\r\n(மேலும் அங்கே நிராகரிப்பாளர்கள் முற்றிலும் நஷ்டமடைந்தனர்.)\n\r\n\n\r\nஇத்துடன் ஸூரா ஃகாஃபிரின் தஃப்ஸீர் நிறைவுற்றது. எல்லாப் புகழும் நன்றியும் அல்லாஹ்வுக்கே உரித்தாகட்டும்."}}};})(self);
